var DCATS_CSP_STYLE_MAP = {
  display: { "none": "none", "block": "block", "flex": "flex", "grid": "grid" },
  color: {
    "#888": "888", "#b07800": "b07800", "#c0392b": "c0392b",
    "#e24b4a": "e24b4a", "#d33": "d33", "#64748b": "64748b",
    "#1a8c3e": "1a8c3e", "#667085": "667085", "#f5a623": "f5a623",
    "#27ae60": "27ae60"
  },
  background: {
    "#eee": "eee", "#e24b4a": "e24b4a", "#f5a623": "f5a623",
    "#27ae60": "27ae60", "#1a8c3e": "1a8c3e"
  },
  width: { "0%": "0", "20%": "20", "40%": "40", "60%": "60", "80%": "80", "100%": "100" }
};

function setCspStyle(element, property, value) {
  if (!element) return;
  var attribute = "data-dcats-" + property;
  var normalized = String(value == null ? "" : value).trim().toLowerCase();
  if (!normalized) {
    element.removeAttribute(attribute);
    return;
  }
  var token = DCATS_CSP_STYLE_MAP[property] && DCATS_CSP_STYLE_MAP[property][normalized];
  if (!token) {
    console.warn("Unsupported CSP style value", property, normalized);
    element.removeAttribute(attribute);
    return;
  }
  element.setAttribute(attribute, token);
}

function ecPriceHistoryColorClass(type, provider) {
  var key = String(type || "other") + "|" + String(provider || "");
  var classes = {"rebuilt|rakuten":"ec-history-rebuilt-rakuten","rebuilt|yahoo_shopping":"ec-history-rebuilt-yahoo-shopping","rebuilt|yahoo_auction":"ec-history-rebuilt-yahoo-auction","new|rakuten":"ec-history-new-rakuten","new|yahoo_shopping":"ec-history-new-yahoo-shopping","new|yahoo_auction":"ec-history-new-yahoo-auction","used|rakuten":"ec-history-used-rakuten","used|yahoo_shopping":"ec-history-used-yahoo-shopping","used|yahoo_auction":"ec-history-used-yahoo-auction"};
  return classes[key] || classes[String(type || "other") + "|rakuten"] || "ec-history-default";
}

