function productLegacyPartId(p) {
  if (!p) return null;
  var id = p.legacy_part_id || p.part_id || null;
  var n = parseInt(id, 10);
  return isNaN(n) ? null : n;
}
function productSlCacheKeys(p) {
  var keys = [];
  var dkd = productDkdId(p);
  if (dkd) keys.push("dkd:" + String(dkd));
  var legacyId = productLegacyPartId(p);
  if (legacyId) keys.push(String(legacyId));
  return keys.filter(function(key, idx, arr) { return key && arr.indexOf(key) === idx; });
}
function productSlPresence(p) {
  if (!p) return false;
  if (p.has_sl_part || p.has_sl || p.sl_part_count > 0 || p.sl_count > 0) return true;
  return productSlCacheKeys(p).some(function(key) {
    return !!(slPresenceMap[key] || slPresenceCache[key]);
  });
}

async function fetchActiveSlLinkedDkdIds(maxRows) {
  maxRows = maxRows || 10000;
  var result = [];
  var seen = {};
  var r = await sb.from("core_product_sl_links")
    .select("dkd_shohin_id")
    .eq("status", "active")
    .not("dkd_shohin_id", "is", null)
    .limit(maxRows);
  if (r.error) {
    console.warn("active SL linked product lookup failed", r.error);
    return result;
  }
  (r.data || []).forEach(function(row) {
    var id = parseInt(row.dkd_shohin_id, 10);
    if (isNaN(id) || seen[id]) return;
    seen[id] = true;
    result.push(id);
  });
  return result;
}
function slPartLabelsForProduct(p) {
  var labels = [];
  productSlCacheKeys(p).forEach(function(key) {
    (slPartsMap[key] || slPartsCache[key] || []).forEach(function(label) {
      if (label && labels.indexOf(label) < 0) labels.push(label);
    });
  });
  return labels;
}
function clearSlLinkCachesForDkdIds(dkdIds) {
  (dkdIds || []).forEach(function(id) {
    var n = parseInt(id, 10);
    if (isNaN(n)) return;
    var key = "dkd:" + String(n);
    delete slPresenceMap[key];
    delete slPresenceCache[key];
    delete slPartsMap[key];
    delete slPartsCache[key];
    delete supplierPriceRowsCache[key];
  });
}
