// =============================================
// 翻訳ヘルパー
//
// t(key)          → currentLangの翻訳を返す。なければenにフォールバック、それもなければkeyをそのまま返す。
// tf(key, vars)   → プレースホルダ {name} 等を vars の値で置換する。
//                   例: tf("greeting", {name:"山本"}) → "ようこそ、山本 さん"
// applyI18n()     → data-i18n / data-i18n-ph 属性を持つ全要素のテキストを更新する。
// applyLanguage() → 言語切り替えの本体。UIを更新しSupabaseに設定を保存する。
// =============================================
function t(key) {
  var dict = TRANSLATIONS[currentLang] || null;
  // tl は null の場合があるので en にフォールバックする
  if (!dict) dict = TRANSLATIONS["en"];
  var val = dict ? dict[key] : null;
  if (val == null) val = (TRANSLATIONS["en"] || {})[key];
  return val != null ? val : key;
}

function tf(key, vars) {
  var str = t(key);
  if (vars) {
    Object.keys(vars).forEach(function(k) {
      str = str.replace(new RegExp("\\{" + k + "\\}", "g"), vars[k]);
    });
  }
  return str;
}

// HTMLのdata-i18n属性を持つ要素を一括更新する
function applyI18n() {
  document.querySelectorAll(".app-version").forEach(function(el) {
    el.textContent = APP_VERSION;
  });
  document.querySelectorAll("[data-i18n]").forEach(function(el) {
    var key = el.dataset.i18n;
    var val = t(key);
    // HTMLエンティティを含む可能性があるためinnerHTMLで設定する
    if (el.tagName === "INPUT" || el.tagName === "BUTTON" || el.tagName === "SPAN" || el.tagName === "P" || el.tagName === "H2") {
      el.innerHTML = val;
    } else {
      el.innerHTML = val;
    }
  });
  document.querySelectorAll("[data-i18n-ph]").forEach(function(el) {
    el.placeholder = t(el.dataset.i18nPh);
  });
  document.querySelectorAll("[data-i18n-aria-label]").forEach(function(el) {
    el.setAttribute("aria-label", t(el.dataset.i18nAriaLabel));
  });
  refreshCategorySelectLabels();
  applySpecFormCategory();
  renderComponentReverseVehicleMakerOptions();
}

// 全ての言語切り替えボタンのactiveクラスを更新する
function updateLangSwitchers(lang) {
  document.querySelectorAll(".lang-btn, .lang-btn-login").forEach(function(btn) {
    btn.classList.toggle("active", btn.dataset.lang === lang);
  });
}

// 言語を切り替えてUIを更新し、ログイン中ならSupabaseに保存する
async function applyLanguage(lang) {
  // tl は翻訳辞書が null なので en として扱う
  currentLang = (TRANSLATIONS[lang] !== undefined) ? lang : "en";

  // localStorageにも保存（ログイン前のデフォルト設定として使う）
  try { localStorage.setItem("dcats_lang", lang); } catch(e) {}

  // 静的要素を更新する
  applyI18n();
  updateLangSwitchers(lang);

  // 動的コンテンツを再描画する
  componentCatalogNameCandidateCache = {};
  componentCatalogNameCandidateLabelMap = {};
  componentCatalogNameCandidateKindMap = {};
  componentCatalogNameCandidateMetaMap = {};
  componentCatalogNameCandidateMasterMap = {};
  renderMenu();
  renderCustomerPortal();
  if (isScreenActive("customer-users")) renderCustomerManagedUsers();
  if (isScreenActive("customer-shipping")) {
    populateShippingPrefectureSelects();
    populateShippingCarrierSelects();
    populateShippingDetailSelects();
    renderCustomerShippingRates();
  }
  if (isScreenActive("shipping-rate-mgmt")) {
    populateShippingPrefectureSelects();
    populateShippingCarrierSelects();
    populateShippingDetailSelects();
    renderShippingRateMgmt();
  }
  renderCustomerCatalogShell();
  if (isScreenActive("customer-catalog")) {
    await populateCustomerCatalogCategories();
    renderCustomerCatalogList();
    if (customerCatalogSelectedProduct) await openCustomerCatalogProduct(customerCatalogSelectedProduct, { autoSelect: true });
  }
  if (dataLoaded) { renderCategoryChips(); render(); }
  renderProductionFilterChips();
  renderProductionCategoryFilterOptions();
  if (currentProduct) { renderPanelStatic(); }
  renderComponentAddPanel();
  renderAssemblyComponentRows();
  updateAllHeaders();
  if (isScreenActive("product-kind-stock-mgmt")) {
    configureProductKindStockMode(productKindStockMode);
    await populateProductKindStockCategoryOptions();
    if (productKindStockRows.length) renderProductKindStockMgmt();
    else renderProductKindStockEmpty();
  }
  if (isScreenActive("manufacturing-cost-mgmt")) {
    await populateManufacturingCostCategoryOptions();
    renderManufacturingCostCategoryCoreCosts();
    renderManufacturingCostSavedListOptions();
    if (manufacturingCostRows.length) renderManufacturingCostRows();
    else renderManufacturingCostEmpty();
  }
  if (isScreenActive("finished-label-mgmt")) {
    setFinishedLabelPrintMode(finishedLabelPrintMode);
    renderFinishedLabelCategoryOptions();
    renderFinishedLabelResults();
    renderFinishedLabelSelectedSummary(finishedLabelSelectedProduct);
    renderFinishedLabelVariantOptions(finishedLabelVariants);
    renderFinishedLabelComponents();
    renderFinishedLabelHistory();
    renderFinishedLabelIssuedResult(finishedLabelLastIssuedRecord);
    updateFinishedLabelQrPayload();
  }
  if (isScreenActive("kikan-mgmt")) await loadKikanMgmt();
  if (document.getElementById("kikan-form-overlay") && document.getElementById("kikan-form-overlay").classList.contains("show")) {
    document.getElementById("kikan-form-title").textContent = kikanFormGroupId ? tf("kikan_group_member_add_title", { id: kikanFormGroupId }) : t("kikan_group_new_title");
  }
  if (document.getElementById("vehicle-info-overlay") && document.getElementById("vehicle-info-overlay").classList.contains("show")) {
    openVehicleApplicationsDialog(currentVehicleApplicationRows || [], currentProduct);
  }
  if (document.getElementById("ec-price-history-overlay") && document.getElementById("ec-price-history-overlay").classList.contains("show") && ecPriceHistoryState) {
    renderEcPriceHistoryContent();
  }

  // ログイン中ならSupabaseのprofileにも保存する
  if (currentUser && userProfile) {
    userProfile.language = lang;
    await sb.from("profiles").update({ language: lang }).eq("id", currentUser.id);
  }
}

// =============================================
// 自動ログアウト（8時間無操作で自動的にログアウト）
// =============================================
function markAppUpdateActivity() {
  appUpdateLastActivityAt = Date.now();
}

function appVersionNumber(version) {
  var m = String(version || "").match(/v?(\d+)\.(\d+)\.(\d+)/i);
  if (!m) return 0;
  return parseInt(m[1], 10) * 1000000 + parseInt(m[2], 10) * 1000 + parseInt(m[3], 10);
}

function activeAppScreenName() {
  var el = document.querySelector(".screen.active");
  if (!el || !el.id) return "";
  return el.id.replace(/^screen-/, "");
}

function captureAppRestoreState(reason) {
  var screen = activeAppScreenName();
  var state = {
    reason: reason || "refresh",
    version: APP_VERSION,
    ts: Date.now(),
    screen: screen,
    lang: currentLang
  };
  function captureSearchState() {
    var qEl = document.getElementById("q");
    var portalContext = activeCustomerPortalContext();
    state.screen = "search";
    state.q = qEl ? qEl.value : "";
    state.filter = currentFilter || "all";
    state.selectedDkdId = currentProduct ? productDkdId(currentProduct) : "";
    state.limit = productSearchLimit || SEARCH_INITIAL_LIMIT;
    state.customerPortalMode = !!(customerPortalSearchActive || isCustomerViewer());
    state.customerPortalCustomerId = portalContext && portalContext.sales_customer_id ? portalContext.sales_customer_id : "";
  }
  function captureProductionState() {
    var pqEl = document.getElementById("production-q");
    var yearEl = document.getElementById("production-year-filter");
    state.screen = "production-search";
    state.q = pqEl ? pqEl.value : "";
    state.filter = productionFilter || "all";
    state.productionCategory = productionCategoryFilter || "all";
    state.selectedDkdId = currentProductionRow ? productDkdId(currentProductionRow) : (currentProduct ? productDkdId(currentProduct) : "");
    state.limit = productionSearchLimit || SEARCH_INITIAL_LIMIT;
    state.year = yearEl ? yearEl.value : "";
  }
  function captureCustomerCatalogState() {
    var qEl = document.getElementById("customer-catalog-q");
    var categoryEl = document.getElementById("customer-catalog-category");
    var portalContext = activeCustomerPortalContext();
    state.screen = "customer-catalog";
    state.q = qEl ? qEl.value : "";
    state.customerCategory = categoryEl ? categoryEl.value : "all";
    state.selectedDkdId = customerCatalogSelectedProduct ? productDkdId(customerCatalogSelectedProduct) : "";
    state.customerPortalCustomerId = portalContext && portalContext.sales_customer_id ? portalContext.sales_customer_id : "";
  }
  if (screen === "customer-catalog") {
    captureCustomerCatalogState();
  } else if (screen === "search") {
    captureSearchState();
  } else if (screen === "production-search") {
    captureProductionState();
  } else if (screen === "components" && currentProduct) {
    if (componentReturnScreen === "production-search") captureProductionState();
    else captureSearchState();
  } else if (screen === "component-parallel" && currentProduct) {
    if (componentParallelReturnScreen === "components" && componentReturnScreen === "production-search") captureProductionState();
    else captureSearchState();
  } else if (screen === "rakuten-price") {
    state.keyword = document.getElementById("rakuten-keyword") ? document.getElementById("rakuten-keyword").value : "";
    state.ngKeyword = document.getElementById("rakuten-ng-keyword") ? document.getElementById("rakuten-ng-keyword").value : "";
    state.sort = document.getElementById("rakuten-sort") ? document.getElementById("rakuten-sort").value : "";
    state.hits = document.getElementById("rakuten-hits") ? document.getElementById("rakuten-hits").value : "";
    state.targetCategory = document.getElementById("rakuten-target-category") ? document.getElementById("rakuten-target-category").value : "";
    state.providers = getEcMallSelectedProviders();
    state.sellerIds = getEcMallSellerIds();
    state.includeUsed = getEcMallIncludeUsed();
  }
  return state;
}

function saveAppRestoreState(reason) {
  if (appDiscardRestoreStateOnExit) return;
  try {
    localStorage.setItem(APP_RESTORE_STATE_KEY, JSON.stringify(captureAppRestoreState(reason)));
  } catch(e) {}
}

function clearAppRestoreState() {
  try { localStorage.removeItem(APP_RESTORE_STATE_KEY); } catch(e) {}
}

function returnToMenuFresh() {
  appDiscardRestoreStateOnExit = true;
  clearAppRestoreState();
  window.location.reload();
}

function showAuthenticatedHome() {
  if (isCustomerViewer()) {
    showScreen("customer-portal");
    renderCustomerPortal();
    return;
  }
  showScreen("menu");
  renderMenu();
}

function consumeAppRestoreState() {
  try {
    var raw = localStorage.getItem(APP_RESTORE_STATE_KEY);
    if (!raw) return null;
    localStorage.removeItem(APP_RESTORE_STATE_KEY);
    var state = JSON.parse(raw);
    if (!state || !state.ts || Date.now() - state.ts > 15 * 60 * 1000) return null;
    return state;
  } catch(e) {
    try { localStorage.removeItem(APP_RESTORE_STATE_KEY); } catch(ignore) {}
    return null;
  }
}

async function restoreAppStateAfterRefresh() {
  if (appRestoreInProgress || !currentUser) return;
  var state = consumeAppRestoreState();
  if (!state || !state.screen) return;
  appRestoreInProgress = true;
  try {
    if (state.screen === "production-search") {
      await enterProductionSearch();
      productionFilter = state.filter || "all";
      productionCategoryFilter = normalizeProductionCategoryFilter(state.productionCategory || "all");
      productionSearchLimit = Math.min(Math.max(parseInt(state.limit || SEARCH_INITIAL_LIMIT, 10) || SEARCH_INITIAL_LIMIT, SEARCH_INITIAL_LIMIT), SEARCH_FETCH_LIMIT);
      renderProductionFilterChips();
      renderProductionCategoryFilterOptions();
      var pqEl = document.getElementById("production-q");
      if (pqEl) pqEl.value = state.q || "";
      var yearEl = document.getElementById("production-year-filter");
      if (yearEl && state.year !== undefined) yearEl.value = state.year || "";
      await loadProductionProducts();
      if (state.selectedDkdId) {
        await openProductionProductByDkdId(state.selectedDkdId, { syncSearch: false });
      } else {
        renderProductionList();
        await renderProductionDetail(currentProductionRow || null);
      }
    } else if (state.screen === "customer-catalog") {
      if (!isCustomerViewer() && state.customerPortalCustomerId) {
        await loadCustomerPortalPreviewContext(state.customerPortalCustomerId);
      }
      await enterCustomerCatalog({
        query: state.q || "",
        category: state.customerCategory || "all",
        runSearch: true
      });
      if (state.selectedDkdId) await openCustomerCatalogProductById(state.selectedDkdId);
    } else if (state.screen === "search") {
      var restoreCustomerPortalMode = !!state.customerPortalMode || isCustomerViewer();
      if (restoreCustomerPortalMode && !isCustomerViewer() && state.customerPortalCustomerId) {
        await loadCustomerPortalPreviewContext(state.customerPortalCustomerId);
      }
      if (restoreCustomerPortalMode) {
        await enterCustomerCatalog({ query: state.q || "", runSearch: true });
        if (state.selectedDkdId) await openCustomerCatalogProductById(state.selectedDkdId);
        return;
      }
      await enterSearch({ fromCustomerPortal: restoreCustomerPortalMode });
      var qEl = document.getElementById("q");
      if (qEl) qEl.value = state.q || "";
      currentFilter = state.filter || "all";
      productSearchLimit = Math.min(Math.max(parseInt(state.limit || SEARCH_INITIAL_LIMIT, 10) || SEARCH_INITIAL_LIMIT, SEARCH_INITIAL_LIMIT), SEARCH_FETCH_LIMIT);
      syncSearchFilterControls();
      await runProductSearch({ preserveSelection: true });
      if (state.selectedDkdId) await openProductByDkdId(state.selectedDkdId);
      else syncFirstSearchResultDetail();
    } else if (state.screen === "rakuten-price") {
      await enterRakutenPrice();
      var keywordEl = document.getElementById("rakuten-keyword");
      var ngEl = document.getElementById("rakuten-ng-keyword");
      var sortEl = document.getElementById("rakuten-sort");
      var hitsEl = document.getElementById("rakuten-hits");
      var catEl = document.getElementById("rakuten-target-category");
      if (keywordEl) keywordEl.value = state.keyword || "";
      if (ngEl) ngEl.value = state.ngKeyword || "";
      if (sortEl && state.sort) sortEl.value = state.sort;
      if (hitsEl && state.hits) hitsEl.value = state.hits;
      if (catEl && state.targetCategory !== undefined) catEl.value = state.targetCategory || "";
      setEcMallSelectedProviders(state.providers || ecMallDefaultProviders);
      setEcMallSellerIds(state.sellerIds || []);
      setEcMallIncludeUsed(!!state.includeUsed);
      renderEcMallSellerPicker(rakutenLastItems);
      renderRakutenTargets();
    }
  } catch(e) {
    console.warn("restore app state failed", e);
  } finally {
    appRestoreInProgress = false;
  }
}

function manualRefreshApp() {
  saveAppRestoreState("manual-refresh");
  try {
    var url = new URL(window.location.href);
    url.hash = "";
    url.searchParams.set("_dcats_refresh", String(Date.now()));
    window.location.replace(url.toString());
  } catch(e) {
    window.location.reload();
  }
}

window.addEventListener("pagehide", function() {
  saveAppRestoreState("pagehide");
});

document.addEventListener("visibilitychange", function() {
  if (document.hidden) saveAppRestoreState("hidden");
});

document.addEventListener("freeze", function() {
  saveAppRestoreState("freeze");
});

function isAppSafeForAutoReload() {
  if (document.querySelector(".form-overlay.show")) return false;
  var el = document.activeElement;
  if (el) {
    var tag = (el.tagName || "").toUpperCase();
    if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT" || el.isContentEditable) return false;
  }
  if (document.hidden) return true;
  return Date.now() - appUpdateLastActivityAt > 30000;
}

function getAppUpdateBanner() {
  var banner = document.getElementById("app-update-banner");
  if (banner) return banner;
  banner = document.createElement("div");
  banner.id = "app-update-banner";
  banner.className = "app-update-banner";
  banner.innerHTML = "<div><strong id='app-update-title'></strong><span id='app-update-message'></span></div><button id='app-update-reload' type='button'></button>";
  document.body.appendChild(banner);
  document.getElementById("app-update-reload").addEventListener("click", manualRefreshApp);
  return banner;
}

function showAppUpdateBanner(latestVersion, autoReloading) {
  var banner = getAppUpdateBanner();
  var title = document.getElementById("app-update-title");
  var msg = document.getElementById("app-update-message");
  var btn = document.getElementById("app-update-reload");
  title.textContent = t("app_update_title");
  msg.textContent = autoReloading
    ? tf("app_update_auto_message", { current: APP_VERSION, latest: latestVersion })
    : tf("app_update_wait_message", { current: APP_VERSION, latest: latestVersion });
  btn.textContent = t("app_update_reload_now");
  banner.classList.add("show");
}

function scheduleAppUpdateReload(latestVersion) {
  clearTimeout(appUpdateReloadTimer);
  if (isAppSafeForAutoReload()) {
    showAppUpdateBanner(latestVersion, true);
    appUpdateReloadTimer = setTimeout(function() {
      if (isAppSafeForAutoReload()) manualRefreshApp();
      else scheduleAppUpdateReload(latestVersion);
    }, 20000);
  } else {
    showAppUpdateBanner(latestVersion, false);
    appUpdateReloadTimer = setTimeout(function() {
      scheduleAppUpdateReload(latestVersion);
    }, 60000);
  }
}

async function checkForAppUpdate() {
  if (appUpdateDetected || location.protocol === "file:") return;
  try {
    var url = new URL(window.location.href);
    url.hash = "";
    url.searchParams.set("_dcats_version_check", String(Date.now()));
    var r = await fetch(url.toString(), { cache: "no-store" });
    if (!r.ok) return;
    var html = await r.text();
    var versionDocument = new DOMParser().parseFromString(html, "text/html");
    var versionMeta = versionDocument.querySelector('meta[name="dcats-app-version"]');
    var legacyMatch = html.match(/var\s+APP_VERSION\s*=\s*["']([^"']+)["']/);
    var latest = versionMeta ? versionMeta.getAttribute("content") : (legacyMatch && legacyMatch[1]);
    if (!latest) return;
    if (latest !== APP_VERSION && appVersionNumber(latest) >= appVersionNumber(APP_VERSION)) {
      appUpdateDetected = true;
      scheduleAppUpdateReload(latest);
    }
  } catch(e) {
    console.warn("app update check failed", e);
  }
}

function startAppUpdateWatcher() {
  if (appUpdateTimer) return;
  ["mousemove", "mousedown", "keydown", "touchstart", "scroll", "click", "input"].forEach(function(ev) {
    document.addEventListener(ev, markAppUpdateActivity, { passive: true });
  });
  appUpdateTimer = setInterval(checkForAppUpdate, APP_UPDATE_CHECK_INTERVAL_MS);
  setTimeout(checkForAppUpdate, 30000);
  document.addEventListener("visibilitychange", function() {
    if (!document.hidden) checkForAppUpdate();
  });
}

var AUTO_LOGOUT_MS = 8 * 60 * 60 * 1000; // 8時間（ミリ秒）
var autoLogoutTimer = null;

function resetAutoLogoutTimer() {
  clearTimeout(autoLogoutTimer);
  if (!currentUser) return;
  autoLogoutTimer = setTimeout(function() {
    doLogout();
    // ログアウト後にメッセージを表示する
    setTimeout(function() {
      var el = document.getElementById("login-error");
      if (el) {
        setCspStyle(el, "color", "#888");
        el.textContent = "8時間操作がなかったため自動的にログアウトしました / Auto-logged out after 8 hours of inactivity";
      }
    }, 300);
  }, AUTO_LOGOUT_MS);
}

// マウス・タップ・キー操作があるたびにタイマーをリセットする
["mousemove", "mousedown", "keydown", "touchstart", "scroll", "click"].forEach(function(ev) {
  document.addEventListener(ev, function() {
    if (currentUser) resetAutoLogoutTimer();
  }, { passive: true });
});

// =============================================
// スクリーン管理
// =============================================
function showScreen(id) {
  document.querySelectorAll(".screen").forEach(function(s) { s.classList.remove("active"); });
  var el = document.getElementById("screen-" + id);
  if (el) el.classList.add("active");
  window.scrollTo(0, 0);
  logScreenOpen(id);
}
function isScreenActive(id) {
  var el = document.getElementById("screen-" + id);
  return !!(el && el.classList.contains("active"));
}

function relocateRakutenSections(mode) {
  mode = mode || "price";
  var priceBody = document.querySelector("#screen-rakuten-price .rakuten-price-body");
  var bulkHost = document.getElementById("rakuten-bulk-host");
  var bulkCard = document.getElementById("rakuten-bulk-card");
  if (bulkCard) {
    var targetBulkParent = mode === "bulk" ? bulkHost : priceBody;
    if (targetBulkParent && bulkCard.parentElement !== targetBulkParent) {
      var apiCardBefore = mode === "price" ? document.getElementById("rakuten-api-settings-card") : null;
      if (apiCardBefore && apiCardBefore.parentElement === targetBulkParent) targetBulkParent.insertBefore(bulkCard, apiCardBefore);
      else targetBulkParent.appendChild(bulkCard);
    }
  }
  var apiHost = document.getElementById("api-settings-host");
  var apiCard = document.getElementById("rakuten-api-settings-card");
  if (apiCard) {
    var targetApiParent = mode === "api" ? apiHost : priceBody;
    if (targetApiParent && apiCard.parentElement !== targetApiParent) targetApiParent.appendChild(apiCard);
  }
}

// =============================================
// 認証
// =============================================
async function handleAuthState() {
  // パスワード再設定・初回招待リンクからのアクセスを検出する
  var hash = window.location.hash;
  var authLinkType = hash ? new URLSearchParams(hash.slice(1)).get("type") : "";
  if (authLinkType === "recovery" || authLinkType === "invite") {
    // セッションをハッシュから復元する
    var hashResult = await sb.auth.getSession();
    if (!hashResult.data.session) {
      // ハッシュからセッションを設定する
      await sb.auth.setSession({
        access_token: new URLSearchParams(hash.slice(1)).get("access_token"),
        refresh_token: new URLSearchParams(hash.slice(1)).get("refresh_token") || ""
      });
    }
    if (authLinkType === "invite") {
      var resetTitle = document.querySelector("#screen-reset h2");
      var resetDesc = document.querySelector("#screen-reset .reg-desc");
      if (resetTitle) resetTitle.textContent = "初回パスワード設定";
      if (resetDesc) resetDesc.textContent = "D-CATSで使用するパスワードを設定してください（8文字以上）";
    }
    showScreen("reset");
    return;
  }

  // 言語の優先順位:
  //   1. localStorageの設定（前回手動で変更した場合）
  //   2. OSの言語（navigator.language）
  //   3. 英語（フォールバック）
  // ※ ログイン後はprofilesテーブルの設定が最優先になる
  try {
    var savedLang = localStorage.getItem("dcats_lang");
    if (savedLang && TRANSLATIONS[savedLang] !== undefined) {
      currentLang = savedLang;
    } else {
      var osLang = (navigator.language || "en").toLowerCase();
      if (osLang.startsWith("ja")) {
        currentLang = "ja";
      } else if (osLang.startsWith("zh")) {
        currentLang = "zh";
      } else if (osLang.startsWith("tl") || osLang.startsWith("fil")) {
        currentLang = TRANSLATIONS["tl"] ? "tl" : "en";
      } else {
        currentLang = "en";
      }
    }
    applyI18n();
    updateLangSwitchers(currentLang);
  } catch(e) {}

  var result = await sb.auth.getSession();
  if (result.data.session) {
    currentUser = result.data.session.user;
    var ok = await loadProfile();
    if (!ok) return;
    resetAutoLogoutTimer();
    showAuthenticatedHome();
    setTimeout(function() { restoreAppStateAfterRefresh(); }, 0);
  } else {
    showScreen("login");
  }
}

async function loadProfile() {
  var r = await sb.from("profiles").select("*").eq("id", currentUser.id).single();
  userProfile = r.data || { id: currentUser.id, email: currentUser.email, name: "", role: "price_viewer", group_name: "public", status: "active", language: "ja" };
  userProfile.role = normalizeRoleForGroup(userProfile.role, userProfile.group_name || "public");

  // pending / suspended の場合はログアウトしてメッセージを表示する
  if (userProfile.status === "pending") {
    await sb.auth.signOut();
    currentUser = null; userProfile = null;
    showScreen("login");
    var el = document.getElementById("login-error");
    if (el) { setCspStyle(el, "color", "#b07800"); el.textContent = t("pending_msg"); }
    return false;
  }
  if (userProfile.status === "suspended") {
    await sb.auth.signOut();
    currentUser = null; userProfile = null;
    showScreen("login");
    var el = document.getElementById("login-error");
    if (el) { setCspStyle(el, "color", "#c0392b"); el.textContent = t("suspended_msg"); }
    return false;
  }
  await loadCustomerViewerContext();

  // プロファイルの言語設定を優先する
  var lang = userProfile.language || "ja";
  currentLang = (TRANSLATIONS[lang] !== undefined) ? lang : "en";
  applyI18n();
  updateLangSwitchers(lang);
  updateAllHeaders();
  return true;
}

function createActivitySessionId() {
  var rand = Math.random().toString(36).slice(2);
  return "dcats_" + Date.now().toString(36) + "_" + rand;
}

function ensureActivitySessionId(forceNew) {
  if (forceNew) currentActivitySessionId = null;
  if (!currentActivitySessionId) {
    try {
      currentActivitySessionId = forceNew ? "" : (sessionStorage.getItem("dcats_activity_session_id") || "");
    } catch (e) {
      currentActivitySessionId = "";
    }
  }
  if (!currentActivitySessionId) {
    currentActivitySessionId = createActivitySessionId();
    try { sessionStorage.setItem("dcats_activity_session_id", currentActivitySessionId); } catch (e) {}
  }
  return currentActivitySessionId;
}

function clearActivitySessionId() {
  currentActivitySessionId = null;
  try { sessionStorage.removeItem("dcats_activity_session_id"); } catch (e) {}
}

function activityPageUrl() {
  return window.location.origin + window.location.pathname;
}

function activityViewportInfo() {
  return {
    viewport_width: window.innerWidth || document.documentElement.clientWidth || null,
    viewport_height: window.innerHeight || document.documentElement.clientHeight || null
  };
}

function activityTimezone() {
  try { return Intl.DateTimeFormat().resolvedOptions().timeZone || ""; } catch (e) { return ""; }
}

function normalizeActivityMetadata(metadata) {
  if (!metadata || typeof metadata !== "object") return {};
  try {
    var json = JSON.stringify(metadata);
    if (json.length > 3500) {
      return { summary: json.slice(0, 3500), truncated: true };
    }
    return JSON.parse(json);
  } catch (e) {
    return { value: String(metadata).slice(0, 3500) };
  }
}

function activeScreenId() {
  var active = document.querySelector(".screen.active");
  if (!active || !active.id) return "";
  return active.id.replace(/^screen-/, "");
}

function productActivityDesc(product) {
  if (!product) return "";
  return [
    product.manufacturer_part_number || product.core_part_number || "",
    product.genuine_part_number || product.genuine_part_number_2 || "",
    productCategoryLabel(product) || product.category_code || product.category || ""
  ].filter(Boolean).join(" / ");
}

function componentActivityDesc(row) {
  if (!row) return "component";
  return [
    row.component_position || row.source_code || "",
    row.component_name || row.component_part_name || "",
    row.component_manufacturer_part_number || "",
    row.component_genuine_part_number || "",
    row.dkd_shohin_id ? ("DKD " + row.dkd_shohin_id) : ""
  ].filter(Boolean).join(" / ") || "component";
}

function activityDataSummary(data) {
  if (!data || typeof data !== "object") return null;
  var keys = [
    "id",
    "dkd_shohin_id",
    "product_variant_id",
    "genuine_part_number",
    "genuine_part_number_2",
    "manufacturer",
    "manufacturer_part_number",
    "core_part_number",
    "component_genuine_part_number",
    "component_manufacturer_part_number",
    "component_name",
    "component_part_name",
    "component_position",
    "source_code",
    "quantity",
    "assy_manufacturer_part_number",
    "product_kind",
    "image_origin",
    "image_url",
    "storage_path",
    "show_in_sales",
    "show_in_production",
    "sl_part_id",
    "sales_customer_id",
    "email",
    "name",
    "status",
    "role_code",
    "company_code",
    "department_code"
  ];
  var out = {};
  keys.forEach(function(key) {
    if (data[key] !== null && data[key] !== undefined && data[key] !== "") out[key] = data[key];
  });
  return Object.keys(out).length ? out : null;
}

function logUserActivity(eventType, options) {
  options = options || {};
  if (!currentUser || !userProfile || !eventType) return Promise.resolve();
  var throttleMs = options.throttleMs || 0;
  var throttleKey = options.throttleKey ? (eventType + ":" + options.throttleKey) : "";
  if (throttleKey && throttleMs > 0) {
    var now = Date.now();
    if (activityEventThrottleMap[throttleKey] && now - activityEventThrottleMap[throttleKey] < throttleMs) return Promise.resolve();
    activityEventThrottleMap[throttleKey] = now;
  }

  var vp = activityViewportInfo();
  var args = {
    p_event_type: eventType,
    p_user_email: userProfile.email || currentUser.email || null,
    p_user_name: userProfile.name || userProfile.email || currentUser.email || null,
    p_session_id: ensureActivitySessionId(false),
    p_screen: options.screen || activeScreenId() || null,
    p_action: options.action || null,
    p_target_type: options.target_type || null,
    p_target_id: options.target_id == null ? null : String(options.target_id),
    p_target_desc: options.target_desc || null,
    p_result: options.result || "ok",
    p_app_version: APP_VERSION,
    p_page_url: activityPageUrl(),
    p_user_agent: navigator.userAgent || null,
    p_timezone: activityTimezone() || null,
    p_language: navigator.language || currentLang || null,
    p_viewport_width: vp.viewport_width,
    p_viewport_height: vp.viewport_height,
    p_metadata: normalizeActivityMetadata(options.metadata)
  };

  return sb.rpc("log_user_activity_event", args).then(function(r) {
    if (!r || !r.error) return r;
    return sb.from("user_activity_events").insert({
      user_id: currentUser.id,
      user_email: args.p_user_email,
      user_name: args.p_user_name,
      session_id: args.p_session_id,
      event_type: args.p_event_type,
      screen: args.p_screen,
      action: args.p_action,
      target_type: args.p_target_type,
      target_id: args.p_target_id,
      target_desc: args.p_target_desc,
      result: args.p_result,
      app_version: args.p_app_version,
      page_url: args.p_page_url,
      user_agent: args.p_user_agent,
      timezone: args.p_timezone,
      language: args.p_language,
      viewport_width: args.p_viewport_width,
      viewport_height: args.p_viewport_height,
      metadata: args.p_metadata
    });
  }).then(function(r) {
    if (r && r.error) console.warn("activity event log failed", r.error);
    return r;
  }).catch(function(e) {
    console.warn("activity event log failed", e);
  });
}

function logScreenOpen(id) {
  if (!id || !currentUser || !userProfile) return;
  logUserActivity("screen_open", {
    screen: id,
    action: "open_screen",
    throttleKey: "screen:" + id,
    throttleMs: 30000
  });
}

function logPermissionDenied(action, targetType, targetId, targetDesc) {
  logUserActivity("permission_denied", {
    action: action || "permission_denied",
    target_type: targetType || null,
    target_id: targetId || null,
    target_desc: targetDesc || null,
    result: "denied"
  });
}

function showPermissionDenied(action, targetType, targetId, targetDesc) {
  logPermissionDenied(action, targetType, targetId, targetDesc);
  alert(t("err_perm"));
}

function logProductDetailOpen(screen, product) {
  if (!product) return;
  var id = productDkdId(product) || product.id || "";
  var customerContext = screen === "customer-catalog" ? activeCustomerPortalContext() : null;
  logUserActivity("detail_open", {
    screen: screen || activeScreenId() || "search",
    action: "open_product_detail",
    target_type: "core_products",
    target_id: id,
    target_desc: productActivityDesc(product),
    metadata: {
      dkd_shohin_id: id || null,
      manufacturer_part_number: product.manufacturer_part_number || product.core_part_number || null,
      genuine_part_number: product.genuine_part_number || null,
      category: product.category_code || product.category || null,
      sales_customer_id: customerContext && customerContext.sales_customer_id ? customerContext.sales_customer_id : null,
      acting_as_customer: screen === "customer-catalog" ? !isCustomerViewer() : null
    },
    throttleKey: "detail:" + (screen || activeScreenId() || "search") + ":" + id,
    throttleMs: 15000
  });
}

async function recordAuthEvent(eventType) {
  if (!currentUser || !userProfile) return;
  try {
    var vp = activityViewportInfo();
    var payload = {
      user_id: currentUser.id,
      user_email: userProfile.email || currentUser.email || null,
      user_name: userProfile.name || userProfile.email || currentUser.email || null,
      event_type: eventType,
      app_version: APP_VERSION,
      user_agent: navigator.userAgent || null,
      page_url: activityPageUrl(),
      session_id: ensureActivitySessionId(eventType === "login"),
      timezone: activityTimezone() || null,
      language: navigator.language || currentLang || null,
      viewport_width: vp.viewport_width,
      viewport_height: vp.viewport_height
    };
    var r = await sb.rpc("log_user_auth_event", {
      p_event_type: payload.event_type,
      p_user_email: payload.user_email,
      p_user_name: payload.user_name,
      p_session_id: payload.session_id,
      p_app_version: payload.app_version,
      p_page_url: payload.page_url,
      p_user_agent: payload.user_agent,
      p_timezone: payload.timezone,
      p_language: payload.language,
      p_viewport_width: payload.viewport_width,
      p_viewport_height: payload.viewport_height
    });
    if (r.error) r = await sb.from("user_auth_events").insert(payload);
    if (r.error) console.warn("auth event log failed", r.error);
    await logUserActivity(eventType === "logout" ? "session_end" : "session_start", {
      screen: "auth",
      action: eventType,
      target_type: "session",
      target_id: payload.session_id,
      metadata: { auth_event: eventType },
      throttleKey: "session:" + eventType + ":" + payload.session_id,
      throttleMs: 5000
    });
  } catch (e) {
    console.warn("auth event log failed", e);
  }
}

function updateAllHeaders() {
  if (!userProfile) return;
  var name  = userProfile.name || userProfile.email.split("@")[0];
  var label = currentRoleDisplayLabel();
  var cls   = roleClass(userProfile.role);
  var greet = tf("greeting", { name: name });

  ["menu","customer-portal","customer-shipping","customer-catalog","search","production-search","components","component-parallel","rakuten-price","rakuten-bulk","api-settings","rakuten-price-list","core-list-mgmt","component-name-master-mgmt","component-compat-mgmt","product-kind-stock-mgmt","manufacturing-cost-mgmt","finished-label-mgmt","finished-product-shipping","production-ranking-mgmt","manufacturing-ranking-report","sales-pricing-mgmt","purchase-mgmt","customer-access-mgmt","shipping-rate-mgmt","logs"].forEach(function(sc) {
    var nameEl  = document.getElementById(sc + "-username");
    var badgeEl = document.getElementById(sc + "-role-badge");
    if (nameEl)  nameEl.textContent = name;
    if (badgeEl) { badgeEl.textContent = label; badgeEl.className = "role-badge " + cls; }
  });
  var g = document.getElementById("menu-greeting");
  if (g) g.textContent = greet;
  renderCustomerExperienceHeaders();
  configureCustomerSearchShell();
  updateComponentsReturnButton();
}

async function doLogin() {
  var email    = document.getElementById("login-email").value.trim();
  var password = document.getElementById("login-password").value;
  var errorEl  = document.getElementById("login-error");
  var btnEl    = document.getElementById("btn-login");
  if (!email || !password) { errorEl.textContent = t("err_empty"); return; }
  btnEl.disabled = true; btnEl.textContent = t("btn_logging_in"); errorEl.textContent = "";
  var result = await sb.auth.signInWithPassword({ email: email, password: password });
  if (result.error) {
    errorEl.textContent = t("err_login");
    btnEl.disabled = false; btnEl.textContent = t("btn_login");
    return;
  }
  currentUser = result.data.user;
  var profileOk = await loadProfile();
  if (!profileOk) { btnEl.disabled=false; btnEl.textContent=t("btn_login"); return; }
  await recordAuthEvent("login");
  resetAutoLogoutTimer();
  showAuthenticatedHome();
  document.getElementById("login-password").value = "";
  btnEl.disabled = false; btnEl.textContent = t("btn_login");
}

async function doLogout() {
  clearAppRestoreState();
  await recordAuthEvent("logout");
  await sb.auth.signOut();
  clearActivitySessionId();
  currentUser = null; userProfile = null;
  customerViewerContext = null;
  customerPortalPreviewContext = null;
  customerPortalSearchActive = false;
  customerCatalogProducts = [];
  customerCatalogSelectedProduct = null;
  customerCatalogImageInfo = { counts: {}, thumbnails: {} };
  customerManagedUsers = [];
  customerManagedUsersRequestSeq += 1;
  shippingRateRows = [];
  shippingRateLoadSeq += 1;
  salesShippingRateRows = [];
  salesShippingRatesLoaded = false;
  salesShippingRatesPromise = null;
  salesShippingProfile = null;
  salesShippingProfileDkdId = null;
  salesShippingPrefectureCode = "";
  salesShippingCarrierName = "";
  salesShippingServiceName = "";
  salesShippingPackageKeyValue = "";
  productShippingSizeRows = [];
  finishedShipmentCustomers = [];
  finishedShipmentUnits = [];
  finishedShipmentHistoryRows = [];
  finishedShipmentSaving = false;
  allProducts = []; dataLoaded = false;
  slPartsMap = {}; slPresenceMap = {}; currentSlPartIds = [];
  currentProduct = null; currentProductSpecs = []; currentProductNominalSpec = null; currentImages = [];
  showScreen("login");
}

