function renderMenu() {
  var grid = document.getElementById("menu-grid");
  if (!grid || !userProfile) return;
  var canManageUsers = canUseUserManagement();

  var mainItems = [
    { icon: "&#x1F50D;", titleKey: "mi_search_title", descKey: "mi_search_desc", action: "search", available: canViewProductSearch(), tag: null },
    { icon: "&#x1F6CD;", titleKey: "customer_portal_title", descKey: "customer_portal_preview_desc", action: "customer-portal", available: canPreviewCustomerPortal(), tag: null },
    { icon: "&#x1F3ED;", titleKey: "mi_production_title", descKey: "mi_production_desc", action: "production-search", available: canViewProductionFeatures(), tag: null },
    { icon: "&#x1F3F7;", titleKey: "mi_finished_label_title", descKey: "mi_finished_label_desc", action: "finished-label-mgmt", available: canViewFinishedLabelMgmt(), tag: null },
    { icon: "&#x1F69A;", titleKey: "mi_finished_shipping_title", descKey: "mi_finished_shipping_desc", action: "finished-product-shipping", available: canManageFinishedProductShipping(), tag: null },
    { icon: "&#x1F4E6;", titleKey: "mi_core_list_title", descKey: "mi_core_list_desc", action: "core-list-mgmt", available: canViewCoreManagement(), tag: null },
    { icon: "&#x1F4E6;", titleKey: "mi_product_kind_stock_title", descKey: "mi_product_kind_stock_desc", action: "product-kind-stock-mgmt", available: canViewProductKindStockMgmt(), tag: null },
    { icon: "&#x1F9EE;", titleKey: "mi_manufacturing_cost_title", descKey: "mi_manufacturing_cost_desc", action: "manufacturing-cost-mgmt", available: canViewManufacturingCostMgmt(), tag: null },
    { icon: "&#x1F4C8;", titleKey: "mi_rakuten_title", descKey: "mi_rakuten_desc", action: canUseRakutenResearch() ? "rakuten-price" : "rakuten-price-list", available: canUseRakutenResearch() || canViewPriceResearchHistory(), tag: null },
    { icon: "&#x1F512;", titleKey: "mi_changepw_title", descKey: "mi_changepw_desc", action: "change-pw", available: true, tag: null }
  ].filter(function(item) { return item.available; });

  var adminItems = [
    { icon: "&#x1F465;", titleKey: "mi_users_title",  descKey: "mi_users_desc",  action: "users",  available: canManageUsers },
    { icon: "&#x1F6AA;", titleKey: "mi_customer_access_title", descKey: "mi_customer_access_desc", action: "customer-access-mgmt", available: canManageCustomerAccess() },
    { icon: "&#x1F69A;", titleKey: "mi_shipping_title", descKey: "mi_shipping_desc", action: "shipping-rate-mgmt", available: canManageShippingRates() },
    { icon: "&#x1F527;", titleKey: "mi_parts_title", descKey: "mi_parts_desc", action: "parts-mgmt", available: canViewManagementScreen() },
    { icon: "&#x1F524;", titleKey: "mi_component_name_master_title", descKey: "mi_component_name_master_desc", action: "component-name-master-mgmt", available: canManageComponentNameMaster() },
    { icon: "&#x1F517;", titleKey: "mi_component_compat_title", descKey: "mi_component_compat_desc", action: "component-compat-mgmt", available: canManageComponentCompatibility() },
    { icon: "&#x1F4B0;", titleKey: "sales_pricing_title", descKey: "sales_pricing_mgmt_desc", action: "sales-pricing-mgmt", available: canViewSalesPricing() },
    { icon: "&#x1F6D2;", titleKey: "mi_purchase_mgmt_title", descKey: "mi_purchase_mgmt_desc", action: "purchase-mgmt", available: canViewPurchaseMgmt() },
    { icon: "&#x1F4CA;", titleKey: "mi_report_title", descKey: "mi_report_desc", action: "manufacturing-ranking-report", available: canViewManufacturingReport() },
    { icon: "&#x1F504;", titleKey: "mi_kikan_title", descKey: "mi_kikan_desc", action: "kikan-mgmt", available: canManageCompatibility() },
    { icon: "&#x2699;", titleKey: "mi_api_settings_title", descKey: "mi_api_settings_desc", action: "api-settings", available: canManageSharedSettings() },
    { icon: "&#x1F4CB;", titleKey: "mi_logs_title", descKey: "mi_logs_desc", action: "logs", available: canViewOperationLogs() }
  ].filter(function(item) { return item.available; });

  function renderCard(item) {
    var act = item.action ? " data-action=\"" + item.action + "\"" : "";
    var html = "";
    html += "<div class=\"menu-card\"" + act + ">";
    html += "<div class=\"menu-icon\">" + item.icon + "</div>";
    html += "<div class=\"menu-card-title\">" + t(item.titleKey) + "</div>";
    html += "<div class=\"menu-card-desc\">"  + t(item.descKey)  + "</div>";
    if (item.tag) html += "<span class=\"menu-tag " + item.tagClass + "\">" + t(item.tag) + "</span>";
    html += "</div>";
    return html;
  }

  function renderAdminLink(item) {
    var html = "";
    html += "<button type=\"button\" class=\"menu-admin-link\" data-action=\"" + item.action + "\">";
    html += "<span class=\"menu-admin-link-icon\">" + item.icon + "</span>";
    html += "<span><strong>" + t(item.titleKey) + "</strong><small>" + t(item.descKey) + "</small></span>";
    html += "</button>";
    return html;
  }

  var html = "";
  html += "<section class=\"menu-section\">";
  html += "<div class=\"menu-section-head\"><h3 class=\"menu-section-title\">" + t("menu_section_main_title") + "</h3><span class=\"menu-section-note\">" + t("menu_section_main_note") + "</span></div>";
  html += "<div class=\"menu-card-grid\">";
  mainItems.forEach(function(item) { html += renderCard(item); });
  html += "</div></section>";

  if (adminItems.length) {
    html += "<section class=\"menu-section\">";
    html += "<div class=\"menu-section-head\"><h3 class=\"menu-section-title\">" + t("menu_section_admin_title") + "</h3><span class=\"menu-section-note\">" + t("menu_section_admin_note") + "</span></div>";
    html += "<div class=\"menu-admin-panel\">";
    html += "<div class=\"menu-admin-head\"><div class=\"menu-admin-icon\">&#x1F6E0;</div><div><div class=\"menu-admin-title\">" + t("menu_admin_title") + "</div><div class=\"menu-admin-desc\">" + t("menu_admin_desc") + "</div></div></div>";
    html += "<div class=\"menu-admin-grid\">";
    adminItems.forEach(function(item) { html += renderAdminLink(item); });
    html += "</div></div></section>";
  }

  grid.innerHTML = html;

  grid.querySelectorAll(".menu-card:not(.disabled)[data-action], .menu-admin-link:not(.disabled)[data-action]").forEach(function(card) {
    card.addEventListener("click", function() {
      if (card.dataset.action === "search") enterSearch();
      else if (card.dataset.action === "customer-portal") enterCustomerPortal();
      else if (card.dataset.action === "production-search") enterProductionSearch();
      else if (card.dataset.action === "finished-label-mgmt") enterFinishedLabelMgmt();
      else if (card.dataset.action === "finished-product-shipping") enterFinishedProductShipping();
      else if (card.dataset.action === "users") enterUsers();
      else if (card.dataset.action === "customer-access-mgmt") enterCustomerAccessMgmt();
      else if (card.dataset.action === "shipping-rate-mgmt") enterShippingRateMgmt();
      else if (card.dataset.action === "change-pw") enterChangePw();
      else if (card.dataset.action === "parts-mgmt") enterPartsMgmt();
      else if (card.dataset.action === "component-name-master-mgmt") enterComponentNameMasterMgmt();
      else if (card.dataset.action === "component-compat-mgmt") enterComponentCompatMgmt();
      else if (card.dataset.action === "sales-pricing-mgmt") enterSalesPricingMgmt();
      else if (card.dataset.action === "purchase-mgmt") enterPurchaseMgmt();
      else if (card.dataset.action === "core-list-mgmt") enterCoreListMgmt();
      else if (card.dataset.action === "product-kind-stock-mgmt") enterProductKindStockMgmt();
      else if (card.dataset.action === "manufacturing-cost-mgmt") enterManufacturingCostMgmt();
      else if (card.dataset.action === "production-ranking-mgmt") enterProductionRankingMgmt();
      else if (card.dataset.action === "manufacturing-ranking-report") enterManufacturingRankingReport();
      else if (card.dataset.action === "kikan-mgmt") enterKikanMgmt();
      else if (card.dataset.action === "rakuten-price") enterRakutenPrice();
      else if (card.dataset.action === "rakuten-bulk") enterRakutenBulk();
      else if (card.dataset.action === "rakuten-price-list") enterRakutenPriceList();
      else if (card.dataset.action === "api-settings") enterApiSettings();
      else if (card.dataset.action === "logs") enterLogs();
    });
  });
}

function customerPortalValue(id, value) {
  var el = document.getElementById(id);
  if (el) el.textContent = value || "-";
}

function renderCustomerExperienceHeaders() {
  if (!userProfile) return;
  var context = activeCustomerPortalContext() || {};
  var customer = context.customer || null;
  var customerModeReady = !!(context.sales_customer_id && customer);
  var fallbackName = userProfile.name || (userProfile.email || "").split("@")[0];
  var name = isCustomerViewer()
    ? fallbackName
    : (customerModeReady ? (customer.customer_name || fallbackName) : fallbackName);
  var label = customerModeReady ? accessRoleLabel("customer_viewer") : currentRoleDisplayLabel();
  var cls = customerModeReady ? "role-viewer" : roleClass(userProfile.role);
  ["customer-portal", "customer-shipping", "customer-catalog", "customer-users"].forEach(function(prefix) {
    var nameEl = document.getElementById(prefix + "-username");
    var badgeEl = document.getElementById(prefix + "-role-badge");
    if (nameEl) nameEl.textContent = name;
    if (badgeEl) {
      badgeEl.textContent = label;
      badgeEl.className = "role-badge " + cls;
    }
  });
  var exitButton = document.getElementById("btn-exit-customer-mode");
  if (exitButton) setCspStyle(exitButton, "display", canPreviewCustomerPortal() ? "" : "none");
}

function configureCustomerSearchShell() {
  var customerMode = isCustomerViewer() || isCustomerPortalSearchMode();
  var searchScreen = document.getElementById("screen-search");
  if (searchScreen) searchScreen.classList.toggle("customer-search-mode", customerMode);
  var backButton = document.getElementById("btn-back-search");
  if (backButton) backButton.textContent = customerMode ? t("customer_portal_back") : t("btn_back");
  var searchTitle = document.getElementById("search-screen-title");
  if (searchTitle) searchTitle.textContent = customerMode ? t("customer_search_title") : "D-CATS";
  var changePasswordBack = document.getElementById("btn-back-change-pw");
  if (changePasswordBack) changePasswordBack.textContent = customerMode ? t("customer_portal_back") : t("btn_back");
}

function renderCustomerPortalPreviewControls() {
  var previewMode = canPreviewCustomerPortal();
  var previewControl = document.getElementById("customer-portal-preview-control");
  var portalBack = document.getElementById("btn-back-customer-portal");
  if (previewControl) setCspStyle(previewControl, "display", previewMode ? "" : "none");
  if (portalBack) setCspStyle(portalBack, "display", previewMode ? "" : "none");
  var select = document.getElementById("customer-portal-customer-select");
  if (!select || !previewMode) return;
  var selectedId = customerPortalPreviewContext && customerPortalPreviewContext.sales_customer_id
    ? String(customerPortalPreviewContext.sales_customer_id)
    : "";
  var html = "<option value=''>" + esc(t("customer_portal_select_customer_placeholder")) + "</option>";
  detailSalesCustomerOptions.forEach(function(customer) {
    var selected = String(customer.id) === selectedId ? " selected" : "";
    html += "<option value='" + esc(String(customer.id)) + "'" + selected + ">" + esc(detailCustomerOptionLabel(customer)) + "</option>";
  });
  select.innerHTML = html;
}

function renderCustomerPortal() {
  var portal = document.getElementById("screen-customer-portal");
  if (!portal || (!isCustomerViewer() && !canPreviewCustomerPortal())) return;
  var previewMode = canPreviewCustomerPortal();
  var context = activeCustomerPortalContext() || {};
  var customer = context.customer || null;
  var settings = context.settings || defaultCustomerDisplaySettings();
  var linked = !!(context.sales_customer_id && customer);
  var active = linked && customer.is_active !== false;
  var searchable = active && (isCustomerViewer() ? canViewProductSearch() : canPreviewCustomerPortal());
  var searchInput = document.getElementById("customer-portal-q");
  var searchButton = document.getElementById("customer-portal-search-btn");

  customerPortalValue("customer-portal-customer-name", linked ? customer.customer_name : t("customer_portal_link_missing"));
  customerPortalValue("customer-portal-customer-name-value", linked ? customer.customer_name : t("customer_portal_link_missing"));

  var status = document.getElementById("customer-portal-status");
  if (status) {
    status.textContent = !linked
      ? (previewMode ? t("customer_portal_select_customer_placeholder") : t("customer_portal_link_missing"))
      : (!active ? t("customer_portal_inactive") : (searchable ? (previewMode ? t("customer_catalog_acting_status") : t("customer_catalog_customer_status")) : t("customer_portal_search_unavailable")));
    status.className = "customer-portal-status " + (searchable ? "active" : "inactive");
  }
  [searchInput, searchButton].forEach(function(el) {
    if (el) el.disabled = !searchable;
  });
  renderCustomerPortalPreviewControls();
  var accountBand = document.querySelector("#screen-customer-portal .customer-portal-account-band");
  if (accountBand) setCspStyle(accountBand, "display", previewMode ? "none" : "");
  var shippingGuide = document.getElementById("customer-portal-shipping-guide");
  if (shippingGuide) shippingGuide.hidden = !canViewCustomerShippingRates();
  var manageUsersButton = document.getElementById("customer-portal-manage-users");
  if (manageUsersButton) manageUsersButton.hidden = !canManageCustomerPortalUsers();
  renderCustomerExperienceHeaders();
  configureCustomerSearchShell();
}

async function loadCustomerPortalPreviewContext(customerId) {
  if (!canPreviewCustomerPortal()) return;
  customerId = String(customerId || "");
  if (!detailSalesCustomerOptions.length) await loadDetailSalesCustomerOptions();
  var customer = detailSalesCustomerOptions.find(function(row) { return String(row.id) === customerId; }) || null;
  customerPortalPreviewContext = customer ? await loadCustomerPortalContextForCustomer(customer) : null;
  detailSelectedSalesCustomerId = customer ? String(customer.id) : "";
  customerCatalogProducts = [];
  customerCatalogSelectedProduct = null;
  customerCatalogImageInfo = { counts: {}, thumbnails: {} };
  renderCustomerPortal();
}

async function enterCustomerPortal() {
  if (!isCustomerViewer() && !canPreviewCustomerPortal()) {
    showPermissionDenied("open_customer_portal", "sales_customers");
    return;
  }
  customerPortalSearchActive = false;
  showScreen("customer-portal");
  if (canPreviewCustomerPortal()) await loadDetailSalesCustomerOptions();
  renderCustomerPortal();
}

async function customerUserEdgeErrorCode(result) {
  if (result && result.data && result.data.error) return result.data.error;
  var context = result && result.error && result.error.context;
  if (context && typeof context.json === "function") {
    try {
      var body = await context.json();
      if (body && body.error) return body.error;
    } catch (ignore) {}
  }
  return "customer_user_management_failed";
}

function customerUserEdgeErrorMessage(code) {
  var messages = {
    forbidden: t("err_perm"),
    customer_not_found: "お取引先を確認できませんでした。",
    customer_user_not_found: "担当者を確認できませんでした。",
    active_customer_member_required: "有効なメンバーを選択してください。",
    customer_admin_transfer_required: "管理者を停止する前に、別のメンバーへ管理者権限を移行してください。",
    customer_admin_required: "管理者が不在になる操作はできません。",
    customer_user_email_missing: "この担当者にはメールアドレスが登録されていません。",
    customer_user_edit_forbidden: "登録情報の修正は社内の得意先管理権限を持つユーザーだけが実行できます。",
    name_required: "ご担当者名を入力してください。",
    invalid_email: "正しいメールアドレスを入力してください。",
    email_already_registered: "このメールアドレスは別のログインIDで登録済みです。",
    invalid_status: "アカウント状態が正しくありません。"
  };
  return messages[code] || "担当者管理の処理に失敗しました。";
}

async function invokeCustomerUserManagement(body) {
  return sb.functions.invoke("manage-customer-users", { body: body });
}

async function enterCustomerUsers() {
  if (!canManageCustomerPortalUsers()) {
    showPermissionDenied("open_customer_users", "customer_user_links");
    return;
  }
  showScreen("customer-users");
  renderCustomerExperienceHeaders();
  customerPortalValue("customer-users-customer-name", customerViewerContext.customer && customerViewerContext.customer.customer_name);
  await loadCustomerManagedUsers();
}

function returnToCustomerPortalFromUsers() {
  showScreen("customer-portal");
  renderCustomerPortal();
}

function focusCustomerUserInviteForm() {
  var card = document.getElementById("customer-users-invite-card");
  var nameInput = document.getElementById("customer-users-invite-name");
  if (card) {
    card.classList.remove("is-highlighted");
    void card.offsetWidth;
    card.classList.add("is-highlighted");
    card.scrollIntoView({ behavior: "smooth", block: "center" });
    window.setTimeout(function() { card.classList.remove("is-highlighted"); }, 1400);
  }
  if (nameInput) window.setTimeout(function() { nameInput.focus(); }, 300);
}

async function loadCustomerManagedUsers() {
  var requestSeq = ++customerManagedUsersRequestSeq;
  var host = document.getElementById("customer-users-list");
  customerManagedUsers = [];
  if (!host) return;
  host.innerHTML = "<div class='loading'>" + esc(t("loading")) + "</div>";
  if (!canManageCustomerPortalUsers()) {
    renderCustomerManagedUsers("forbidden");
    return;
  }
  var result = await invokeCustomerUserManagement({
    action: "list",
    sales_customer_id: customerViewerContext.sales_customer_id
  });
  if (requestSeq !== customerManagedUsersRequestSeq) return;
  if (result.error || !result.data || !result.data.ok) {
    renderCustomerManagedUsers(await customerUserEdgeErrorCode(result));
    return;
  }
  customerManagedUsers = result.data.users || [];
  renderCustomerManagedUsers();
}

function renderCustomerManagedUsers(errorCode) {
  var host = document.getElementById("customer-users-list");
  var count = document.getElementById("customer-users-count");
  if (!host) return;
  if (count) count.textContent = tf("customer_catalog_count", { n: customerManagedUsers.length });
  if (errorCode) {
    host.innerHTML = "<div class='empty save-err'>" + esc(customerUserEdgeErrorMessage(errorCode)) + "</div>";
    return;
  }
  if (!customerManagedUsers.length) {
    host.innerHTML = "<div class='empty'>登録済みの担当者はいません。</div>";
    return;
  }
  host.innerHTML = customerManagedUsers.map(function(user) {
    var isAdmin = user.customer_role === "admin";
    var status = user.status || "active";
    var roleLabel = isAdmin ? t("customer_users_admin") : t("customer_users_member");
    var state = "<span class='customer-user-role-badge " + (isAdmin ? "admin" : "member") + "'>" + esc(roleLabel) + "</span>" +
      "<span class='status-badge status-" + esc(status) + "'>" + esc(t("users_" + status + "_badge")) + "</span>";
    var statusButton = "";
    var transferButton = "";
    var removeButton = "";
    if (!isAdmin) {
      statusButton = status === "active"
        ? "<button class='btn-suspend customer-managed-status' type='button' data-uid='" + esc(user.id) + "' data-status='suspended'>" + esc(t("btn_suspend")) + "</button>"
        : "<button class='btn-approve customer-managed-status' type='button' data-uid='" + esc(user.id) + "' data-status='active'>" + esc(t("btn_activate")) + "</button>";
      if (status === "active") {
        transferButton = "<button class='btn-sm-edit customer-managed-transfer' type='button' data-uid='" + esc(user.id) + "'>" + esc(t("customer_users_transfer")) + "</button>";
      }
      removeButton = "<button class='btn-suspend customer-managed-remove' type='button' data-uid='" + esc(user.id) + "'>" + esc(t("customer_users_remove")) + "</button>";
    }
    return "<div class='customer-user-row'>" +
      "<div class='customer-user-identity'><strong>" + esc(user.name || "-") + "</strong><span>" + esc(user.email || "-") + "</span></div>" +
      "<div class='customer-user-state'>" + state + "</div>" +
      "<div class='customer-user-actions'>" + transferButton + statusButton +
        "<button class='btn-pw-reset customer-managed-reset' type='button' data-uid='" + esc(user.id) + "'>" + esc(t("btn_send_pw_reset")) + "</button>" +
        removeButton +
      "</div>" +
      "<span class='save-msg customer-user-row-message' id='customer-managed-message-" + esc(user.id) + "'></span>" +
    "</div>";
  }).join("");
  bindCustomerManagedUserEvents();
}

function customerManagedUserById(userId) {
  return customerManagedUsers.find(function(user) { return String(user.id) === String(userId); }) || null;
}

function bindCustomerManagedUserEvents() {
  var host = document.getElementById("customer-users-list");
  if (!host) return;
  host.querySelectorAll(".customer-managed-status").forEach(function(button) {
    button.addEventListener("click", function() { updateCustomerManagedUserStatus(button.dataset.uid, button.dataset.status); });
  });
  host.querySelectorAll(".customer-managed-reset").forEach(function(button) {
    button.addEventListener("click", function() { sendCustomerManagedUserPasswordReset(button.dataset.uid, button); });
  });
  host.querySelectorAll(".customer-managed-transfer").forEach(function(button) {
    button.addEventListener("click", function() { transferCustomerManagedAdmin(button.dataset.uid, button); });
  });
  host.querySelectorAll(".customer-managed-remove").forEach(function(button) {
    button.addEventListener("click", function() { removeCustomerManagedMember(button.dataset.uid, button); });
  });
}

async function inviteCustomerManagedUser() {
  if (!canManageCustomerPortalUsers()) {
    showPermissionDenied("invite_customer_user", "profiles");
    return;
  }
  var nameInput = document.getElementById("customer-users-invite-name");
  var emailInput = document.getElementById("customer-users-invite-email");
  var button = document.getElementById("btn-customer-users-invite");
  var message = document.getElementById("customer-users-invite-message");
  var name = nameInput ? nameInput.value.trim() : "";
  var email = emailInput ? emailInput.value.trim().toLowerCase() : "";
  if (!name || !email) {
    if (message) { message.className = "save-msg save-err customer-users-invite-message"; message.textContent = !name ? "担当者名を入力してください。" : "メールアドレスを入力してください。"; }
    return;
  }
  if (!confirm(name + " / " + email + " を担当者として追加しますか？")) return;
  if (button) button.disabled = true;
  if (message) { message.className = "save-msg customer-users-invite-message"; message.textContent = t("loading"); }
  var result = await sb.functions.invoke("invite-customer-user", {
    body: {
      sales_customer_id: customerViewerContext.sales_customer_id,
      name: name,
      email: email,
      channel: "email"
    }
  });
  if (button) button.disabled = false;
  if (result.error || !result.data || !result.data.ok) {
    var errorCode = await customerAccountInviteErrorCode(result);
    if (message) { message.className = "save-msg save-err customer-users-invite-message"; message.textContent = customerAccountInviteErrorMessage(errorCode); }
    return;
  }
  if (nameInput) nameInput.value = "";
  if (emailInput) emailInput.value = "";
  if (message) { message.className = "save-msg save-ok customer-users-invite-message"; message.textContent = t("customer_users_invite_sent"); }
  await loadCustomerManagedUsers();
}

async function updateCustomerManagedUserStatus(userId, status) {
  var user = customerManagedUserById(userId);
  if (!canManageCustomerPortalUsers() || !user || ["active", "suspended"].indexOf(status) < 0) return;
  if (status === "suspended" && !confirm((user.name || user.email) + " のログインを停止しますか？")) return;
  var result = await invokeCustomerUserManagement({
    action: "set_status",
    sales_customer_id: customerViewerContext.sales_customer_id,
    target_user_id: user.id,
    status: status
  });
  if (result.error || !result.data || !result.data.ok) {
    var message = document.getElementById("customer-managed-message-" + user.id);
    if (message) { message.className = "save-msg save-err customer-user-row-message"; message.textContent = customerUserEdgeErrorMessage(await customerUserEdgeErrorCode(result)); }
    return;
  }
  await loadCustomerManagedUsers();
}

async function sendCustomerManagedUserPasswordReset(userId, button) {
  var user = customerManagedUserById(userId);
  if (!canManageCustomerPortalUsers() || !user) return;
  if (button) button.disabled = true;
  var result = await invokeCustomerUserManagement({
    action: "send_password_reset",
    sales_customer_id: customerViewerContext.sales_customer_id,
    target_user_id: user.id
  });
  if (button) button.disabled = false;
  var message = document.getElementById("customer-managed-message-" + user.id);
  if (result.error || !result.data || !result.data.ok) {
    if (message) { message.className = "save-msg save-err customer-user-row-message"; message.textContent = customerUserEdgeErrorMessage(await customerUserEdgeErrorCode(result)); }
    return;
  }
  if (message) { message.className = "save-msg save-ok customer-user-row-message"; message.textContent = t("msg_pw_reset_sent"); }
}

async function removeCustomerManagedMember(userId, button) {
  var user = customerManagedUserById(userId);
  if (!canManageCustomerPortalUsers() || !user || user.customer_role !== "member") return;
  if (!confirm(tf("customer_users_remove_confirm_detail", { name: user.name || "-", email: user.email || "-" }))) return;
  if (button) button.disabled = true;
  var result = await invokeCustomerUserManagement({
    action: "remove_member",
    sales_customer_id: customerViewerContext.sales_customer_id,
    target_user_id: user.id
  });
  if (button) button.disabled = false;
  if (result.error || !result.data || !result.data.ok) {
    var message = document.getElementById("customer-managed-message-" + user.id);
    if (message) { message.className = "save-msg save-err customer-user-row-message"; message.textContent = customerUserEdgeErrorMessage(await customerUserEdgeErrorCode(result)); }
    return;
  }
  alert(t("customer_users_remove_done"));
  await loadCustomerManagedUsers();
}

async function transferCustomerManagedAdmin(userId, button) {
  var user = customerManagedUserById(userId);
  if (!canManageCustomerPortalUsers() || !user || user.customer_role !== "member" || user.status !== "active") return;
  if (!confirm(tf("customer_users_transfer_confirm_detail", { name: user.name || "-", email: user.email || "-" }))) return;
  if (button) button.disabled = true;
  var result = await invokeCustomerUserManagement({
    action: "transfer_admin",
    sales_customer_id: customerViewerContext.sales_customer_id,
    target_user_id: user.id
  });
  if (button) button.disabled = false;
  if (result.error || !result.data || !result.data.ok) {
    var message = document.getElementById("customer-managed-message-" + user.id);
    if (message) { message.className = "save-msg save-err customer-user-row-message"; message.textContent = customerUserEdgeErrorMessage(await customerUserEdgeErrorCode(result)); }
    return;
  }
  await loadCustomerViewerContext();
  alert(tf("customer_users_transfer_done_detail", { email: user.email || "-" }));
  returnToCustomerPortalFromUsers();
}

async function openCustomerPortalSearch() {
  var context = activeCustomerPortalContext();
  if ((!isCustomerViewer() && !canPreviewCustomerPortal()) || !context || !context.sales_customer_id || (isCustomerViewer() && !canViewProductSearch())) return;
  var portalInput = document.getElementById("customer-portal-q");
  var query = portalInput ? portalInput.value.trim() : "";
  if (!query) {
    if (portalInput) portalInput.focus();
    return;
  }
  await enterCustomerCatalog({ query: query, logActivity: true });
}

function customerCatalogContext() {
  return activeCustomerPortalContext() || {};
}

function customerCatalogProductKind(product) {
  return normalizeProductKind((product && product.default_product_kind) || "rebuilt");
}

function customerCatalogRequiresRegisteredPrice() {
  var settings = customerCatalogContext().settings || defaultCustomerDisplaySettings();
  return !!(settings.priced_products_only || settings.show_parts_without_price === false);
}

async function populateCustomerCatalogCategories() {
  var select = document.getElementById("customer-catalog-category");
  if (!select) return;
  if (!categoryOptions.length) {
    var r = await sb.from("assy_categories")
      .select("category_code,label_ja,label_en,label_zh,sort_order")
      .eq("is_active", true)
      .order("sort_order", { ascending: true });
    if (!r.error) {
      categoryOptions = (r.data || []).filter(function(cat) {
        return (cat.category_code || cat.category) !== "car_air_conditioner";
      });
    }
  }
  var selected = select.value || "all";
  var html = "<option value='all'>" + esc(t("filter_all")) + "</option>";
  var visibilityRows = customerCatalogContext().visibilityRows || [];
  (categoryOptions || []).forEach(function(cat) {
    var code = cat.category_code || cat.category || "";
    if (!code || !customerCategoryIsVisible(code, visibilityRows)) return;
    html += "<option value='" + esc(code) + "'>" + esc(categoryOptionLabel(cat)) + "</option>";
  });
  select.innerHTML = html;
  if (Array.prototype.some.call(select.options, function(option) { return option.value === selected; })) select.value = selected;
}

function renderCustomerCatalogShell() {
  var context = customerCatalogContext();
  var customer = context.customer || null;
  customerPortalValue("customer-catalog-customer-name", customer && customer.customer_name);
  var status = document.getElementById("customer-catalog-mode-status");
  if (status) {
    status.textContent = canPreviewCustomerPortal() ? t("customer_catalog_acting_status") : t("customer_catalog_customer_status");
    status.className = "customer-portal-status active";
  }
  renderCustomerExperienceHeaders();
}

function customerCatalogImageForProduct(product) {
  var dkdId = productDkdId(product);
  return dkdId ? (customerCatalogImageInfo.thumbnails["dkd:" + String(dkdId)] || "") : "";
}

function renderCustomerCatalogList() {
  var list = document.getElementById("customer-catalog-list");
  var count = document.getElementById("customer-catalog-count");
  if (!list || !count) return;
  count.textContent = tf("customer_catalog_count", { n: customerCatalogProducts.length });
  if (!customerCatalogProducts.length) {
    list.innerHTML = "<div class='customer-catalog-empty'>" + esc(t("no_results")) + "</div>";
    return;
  }
  var showImages = customerViewerSetting("show_product_images", true);
  var selectedId = productDkdId(customerCatalogSelectedProduct);
  list.innerHTML = customerCatalogProducts.map(function(product) {
    var dkdId = productDkdId(product);
    var selected = selectedId && selectedId === dkdId ? " selected" : "";
    var thumb = showImages ? customerCatalogImageForProduct(product) : "";
    var media = thumb
      ? thumbImgHtml(thumb, { width: 144, height: 144, resize: "contain", loading: "lazy" })
      : esc(productCategoryLabel(product));
    var makerLine = [product.manufacturer, product.manufacturer_part_number].filter(Boolean).join(" / ");
    return "<button class='customer-catalog-item" + selected + "' type='button' data-customer-catalog-dkd='" + esc(dkdId) + "'>" +
      "<span class='customer-catalog-item-media'>" + media + "</span>" +
      "<span class='customer-catalog-item-copy'>" +
        "<span class='customer-catalog-item-category'>" + esc(productCategoryLabel(product)) + "</span>" +
        "<span class='customer-catalog-item-pn'>" + esc(product.genuine_part_number || product.manufacturer_part_number || "-") + "</span>" +
        (makerLine ? "<span class='customer-catalog-item-sub'>" + esc(makerLine) + "</span>" : "") +
        (product.gltek_part_number ? "<span class='customer-catalog-item-sub'>GLTEK: " + esc(product.gltek_part_number) + "</span>" : "") +
      "</span>" +
    "</button>";
  }).join("");
  list.querySelectorAll("[data-customer-catalog-dkd]").forEach(function(button) {
    button.addEventListener("click", function() {
      openCustomerCatalogProductById(button.dataset.customerCatalogDkd);
    });
  });
}

async function fetchCustomerCatalogPriceMap(products) {
  var map = {};
  var rows = products || [];
  if (!rows.length) return map;
  if (isCustomerViewer()) {
    for (var i = 0; i < rows.length; i += 6) {
      var chunk = rows.slice(i, i + 6);
      var results = await Promise.all(chunk.map(function(product) {
        return sb.rpc("get_customer_product_sales_price", {
          target_dkd_shohin_id: parseInt(productDkdId(product), 10),
          target_product_kind: customerCatalogProductKind(product)
        });
      }));
      chunk.forEach(function(product, index) {
        var result = results[index];
        var row = result && !result.error ? ((result.data || [])[0] || null) : null;
        var value = row && row.sales_price_jpy != null ? parseInt(row.sales_price_jpy, 10) : null;
        if (value === 0 && !customerViewerSetting("show_zero_price", false)) value = null;
        map[productDkdId(product)] = isNaN(value) ? null : value;
      });
    }
    return map;
  }
  var ids = rows.map(function(product) { return parseInt(productDkdId(product), 10); }).filter(function(id) { return !isNaN(id); });
  if (!ids.length) return map;
  var baseResult = await sb.from("product_base_prices")
    .select("dkd_shohin_id,product_kind,base_price_jpy")
    .in("dkd_shohin_id", ids)
    .eq("is_current", true);
  if (baseResult.error) return map;
  var customer = customerCatalogContext().customer || {};
  var rankResult = customer.price_rank_code ? await sb.from("sales_price_ranks")
    .select("rank_code,rate_multiplier,amount_adjustment_jpy,rounding_unit_jpy,rounding_method,is_active")
    .eq("rank_code", customer.price_rank_code)
    .eq("is_active", true)
    .maybeSingle() : { data: null, error: null };
  var rank = rankResult.error ? null : (rankResult.data || {});
  var baseMap = {};
  (baseResult.data || []).forEach(function(row) {
    baseMap[String(row.dkd_shohin_id) + "|" + normalizeProductKind(row.product_kind)] = row.base_price_jpy;
  });
  rows.forEach(function(product) {
    var id = productDkdId(product);
    var base = baseMap[id + "|" + customerCatalogProductKind(product)];
    var value = base == null ? null : calculateSalesPriceClient(parseInt(base, 10), rank || {});
    if (value === 0 && !customerViewerSetting("show_zero_price", false)) value = null;
    map[id] = value;
  });
  return map;
}

async function fetchCustomerCatalogPriceInfo(product, productKind) {
  var target = productKind
    ? Object.assign({}, product, { default_product_kind: normalizeProductKind(productKind) })
    : product;
  var map = await fetchCustomerCatalogPriceMap([target]);
  return map[productDkdId(product)] == null ? null : map[productDkdId(product)];
}

async function runCustomerCatalogSearch(options) {
  options = options || {};
  var context = customerCatalogContext();
  if (!context.sales_customer_id || !context.customer || (isCustomerViewer() ? !canViewProductSearch() : !canPreviewCustomerPortal())) return;
  var input = document.getElementById("customer-catalog-q");
  var categoryEl = document.getElementById("customer-catalog-category");
  var query = input ? input.value.trim() : "";
  var category = categoryEl && categoryEl.value !== "all" ? categoryEl.value : null;
  var list = document.getElementById("customer-catalog-list");
  var count = document.getElementById("customer-catalog-count");
  if (!query && !category) {
    customerCatalogRequestSeq += 1;
    customerCatalogProducts = [];
    customerCatalogSelectedProduct = null;
    customerCatalogImageInfo = { counts: {}, thumbnails: {} };
    if (list) list.innerHTML = "<div class='customer-catalog-empty'>" + esc(t("customer_catalog_search_hint")) + "</div>";
    if (count) count.textContent = "-";
    var emptyDetail = document.getElementById("customer-catalog-detail");
    if (emptyDetail) emptyDetail.innerHTML = "<div class='customer-catalog-detail-empty'><strong>" + esc(t("customer_catalog_select_product")) + "</strong><span>" + esc(t("customer_catalog_select_product_note")) + "</span></div>";
    if (input) input.focus();
    return;
  }
  var seq = ++customerCatalogRequestSeq;
  if (list) list.innerHTML = "<div class='customer-catalog-loading'>" + esc(t("loading")) + "</div>";
  if (count) count.textContent = "-";
  customerCatalogSelectedProduct = null;
  var detail = document.getElementById("customer-catalog-detail");
  if (detail) detail.innerHTML = "<div class='customer-catalog-detail-empty'><strong>" + esc(t("customer_catalog_select_product")) + "</strong><span>" + esc(t("customer_catalog_select_product_note")) + "</span></div>";
  var result;
  if (query) {
    result = await fetchCoreProductMasterMatches(query, category, CUSTOMER_CATALOG_SCAN_LIMIT);
  } else {
    result = await fetchCategoryProducts(category, CUSTOMER_CATALOG_SCAN_LIMIT);
  }
  if (seq !== customerCatalogRequestSeq) return;
  if (result.error) {
    console.warn("customer catalog search failed", result.error);
    customerCatalogProducts = [];
    if (list) list.innerHTML = "<div class='customer-catalog-empty'>" + esc(t("customer_catalog_load_error")) + "</div>";
    return;
  }
  var products = filterVisibleProducts(normalizeCoreProductFastRows(result.data || [])).slice(0, CUSTOMER_CATALOG_SCAN_LIMIT);
  if (customerCatalogRequiresRegisteredPrice() && products.length) {
    products = products.slice(0, CUSTOMER_CATALOG_RESULT_LIMIT);
    var priceMap = await fetchCustomerCatalogPriceMap(products);
    if (seq !== customerCatalogRequestSeq) return;
    products = products.filter(function(product) { return priceMap[productDkdId(product)] != null; });
  }
  customerCatalogProducts = products.slice(0, CUSTOMER_CATALOG_RESULT_LIMIT);
  customerCatalogImageInfo = { counts: {}, thumbnails: {} };
  if (customerViewerSetting("show_product_images", true) && customerCatalogProducts.length) {
    customerCatalogImageInfo = await fetchProductImageCountMapForContext(customerCatalogProducts, "sales");
    if (seq !== customerCatalogRequestSeq) return;
  }
  renderCustomerCatalogList();
  if (customerCatalogProducts.length) await openCustomerCatalogProduct(customerCatalogProducts[0], { autoSelect: true });
  if (options.logActivity) {
    logUserActivity("search", {
      screen: "customer-catalog",
      action: "customer_product_search",
      target_type: "search",
      target_desc: query || category,
      metadata: {
        query: query,
        category_filter: category,
        result_count: customerCatalogProducts.length,
        sales_customer_id: context.sales_customer_id,
        acting_as_customer: !isCustomerViewer()
      },
      throttleKey: "customer-catalog:" + context.sales_customer_id + ":" + query + ":" + (category || ""),
      throttleMs: 3000
    });
  }
}

function customerCatalogFact(label, value) {
  return "<dt>" + esc(label) + "</dt><dd>" + esc(value || "-") + "</dd>";
}

function customerCatalogSpecText(product) {
  var values = [];
  if (product.nominal_gas_type) values.push(product.nominal_gas_type);
  if (product.nominal_type_text) values.push(product.nominal_type_text);
  if (product.nominal_voltage_v != null) values.push(specNumberText(product.nominal_voltage_v, "V"));
  if (product.nominal_current_a != null) values.push(specNumberText(product.nominal_current_a, "A"));
  if (product.nominal_power_kw != null) values.push(specNumberText(product.nominal_power_kw, "kW"));
  else if (product.nominal_power_w != null) values.push(specNumberText(product.nominal_power_w, "W"));
  if (product.nominal_diameter_d != null) values.push("D" + specNumberText(product.nominal_diameter_d, ""));
  return values.join(" / ");
}

function customerCatalogAvailabilityKindHtml(kind, stockQty, price, showPrice, variantRows) {
  var stockText = stockQty == null ? "-" : String(stockQty);
  var priceText = price == null ? t("customer_catalog_price_none") : "JPY " + formatYen(price);
  return "<div class='customer-catalog-availability-kind " + esc(productKindClass(kind)) + "'>" +
    "<div class='customer-catalog-availability-kind-title'>" + esc(productKindLabel(kind)) + "</div>" +
    "<div class='customer-catalog-availability-metrics" + (showPrice ? "" : " stock-only") + "'>" +
      "<div class='customer-catalog-availability-metric stock'><span>" + esc(t("customer_catalog_stock_qty")) + "</span><strong>" + esc(stockText) + "</strong><small>" + esc(t("customer_catalog_stock_unit")) + "</small></div>" +
      (showPrice ? "<div class='customer-catalog-availability-metric price'><span>" + esc(t("customer_portal_price_display")) + "</span><strong>" + esc(priceText) + "</strong></div>" : "") +
    "</div>" +
    renderCoreReturnPolicyHtml(kind, variantRows, { compact: true, showTitle: false }) +
  "</div>";
}

function renderCustomerCatalogDetailBase(product) {
  var detail = document.getElementById("customer-catalog-detail");
  if (!detail || !product) return;
  var settings = customerCatalogContext().settings || defaultCustomerDisplaySettings();
  var isAc = productCategoryKey(product) === "ac_compressor";
  var facts = "";
  facts += customerCatalogFact(t("f_genuine_pn"), product.genuine_part_number);
  if (product.genuine_part_number_2) facts += customerCatalogFact(t("f_genuine_pn2"), product.genuine_part_number_2);
  if (isAc && product.genuine_body_part_number) facts += customerCatalogFact(t("f_genuine_body_pn"), product.genuine_body_part_number);
  if (isAc && product.genuine_clutch_part_number) facts += customerCatalogFact(t("f_genuine_clutch_pn"), product.genuine_clutch_part_number);
  facts += customerCatalogFact(t("f_manufacturer"), product.manufacturer);
  facts += customerCatalogFact(t("f_mfr_pn"), product.manufacturer_part_number);
  if (isAc && product.manufacturer_body_part_number) facts += customerCatalogFact(t("f_mfr_body_pn"), product.manufacturer_body_part_number);
  if (isAc && product.manufacturer_clutch_part_number) facts += customerCatalogFact(t("f_mfr_clutch_pn"), product.manufacturer_clutch_part_number);
  var spec = customerCatalogSpecText(product);
  if (spec) facts += customerCatalogFact(t("spec_section"), spec);
  var imageHtml = settings.show_product_images
    ? "<div class='customer-catalog-images' id='customer-catalog-images'><div class='customer-catalog-image-main'>" + esc(t("img_loading")) + "</div></div>"
    : "";
  var availabilityTitle = settings.show_sales_price ? t("customer_catalog_stock_price_title") : t("product_kind_stock");
  var availabilityHtml = "<section class='customer-catalog-availability'><h3>" + esc(availabilityTitle) + "</h3><div class='customer-catalog-availability-grid' id='customer-catalog-availability'><div class='customer-catalog-loading'>" + esc(t("loading")) + "</div></div></section>";
  var vehicleHtml = settings.show_vehicle_info
    ? "<details class='customer-catalog-detail-section customer-catalog-vehicle-section' id='customer-catalog-vehicle-disclosure'><summary>" + esc(t("customer_catalog_vehicle_list")) + "</summary><div class='customer-catalog-table-wrap' id='customer-catalog-vehicle'></div></details>"
    : "";
  var compatibleHtml = settings.show_compatible_parts
    ? "<section class='customer-catalog-detail-section'><h3>" + esc(t("kikan_section")) + "</h3><div id='customer-catalog-compatible'><div class='customer-catalog-loading'>" + esc(t("loading")) + "</div></div></section>"
    : "";
  detail.innerHTML =
    "<div class='customer-catalog-detail-head'>" +
      "<div><div class='customer-catalog-detail-kicker'>" + esc(productCategoryLabel(product)) + "</div><h2>" + esc(product.genuine_part_number || product.manufacturer_part_number || "-") + "</h2></div>" +
      "<div class='customer-catalog-detail-gltek'><span>GLTEK</span><strong>" + esc(product.gltek_part_number || "-") + "</strong></div>" +
    "</div>" +
    availabilityHtml +
    "<div class='customer-catalog-detail-main'>" + imageHtml + "<div><dl class='customer-catalog-facts'>" + facts + "</dl></div></div>" +
    vehicleHtml + compatibleHtml;
}

async function loadCustomerCatalogImages(product, seq) {
  var wrap = document.getElementById("customer-catalog-images");
  if (!wrap) return;
  var result = await fetchAllCoreProductImagesForContext(parseInt(productDkdId(product), 10), "sales");
  if (seq !== customerCatalogDetailSeq || !wrap.isConnected) return;
  var images = result.error ? [] : (result.data || []);
  if (!images.length) {
    wrap.innerHTML = "<div class='customer-catalog-image-main'>" + esc(t("img_none")) + "</div>";
    return;
  }
  function renderSelected(index) {
    var main = wrap.querySelector(".customer-catalog-image-main");
    if (!main) return;
    main.innerHTML = thumbImgHtml(images[index], { width: 720, height: 540, resize: "contain", loading: "eager", fetchPriority: "high" });
    var img = main.querySelector("img");
    if (img) img.addEventListener("click", function() { openFullscreen(index, images); });
    wrap.querySelectorAll("[data-customer-image-index]").forEach(function(button) {
      button.classList.toggle("active", parseInt(button.dataset.customerImageIndex, 10) === index);
    });
  }
  wrap.innerHTML = "<div class='customer-catalog-image-main'></div><div class='customer-catalog-image-thumbs'>" + images.slice(0, 8).map(function(image, index) {
    return "<button class='customer-catalog-image-thumb' type='button' data-customer-image-index='" + index + "'>" + thumbImgHtml(image, { width: 128, height: 128, resize: "contain" }) + "</button>";
  }).join("") + "</div>";
  wrap.querySelectorAll("[data-customer-image-index]").forEach(function(button) {
    button.addEventListener("click", function() { renderSelected(parseInt(button.dataset.customerImageIndex, 10)); });
  });
  renderSelected(0);
}

async function loadCustomerCatalogAvailability(product, seq) {
  var wrap = document.getElementById("customer-catalog-availability");
  if (!wrap) return;
  var dkdId = parseInt(productDkdId(product), 10);
  var kinds = ["rebuilt", "aftermarket_new"];
  var settings = customerCatalogContext().settings || defaultCustomerDisplaySettings();
  var showPrice = !!settings.show_sales_price;
  var stockRequest = sb.from("core_product_variants")
    .select("product_kind,stock_qty,core_return_required,core_charge_jpy")
    .eq("dkd_shohin_id", dkdId)
    .eq("is_active", true)
    .in("product_kind", kinds);
  var priceRequest = showPrice
    ? Promise.all(kinds.map(function(kind) { return fetchCustomerCatalogPriceInfo(product, kind); }))
    : Promise.resolve([null, null]);
  var results = await Promise.all([stockRequest, priceRequest]);
  if (seq !== customerCatalogDetailSeq || !wrap.isConnected) return;
  var stockResult = results[0];
  var prices = results[1] || [];
  var variantRows = stockResult && !stockResult.error ? (stockResult.data || []) : [];
  var stockMap = { rebuilt: 0, aftermarket_new: 0 };
  if (stockResult.error) {
    console.warn("customer catalog stock lookup failed", stockResult.error);
    stockMap = { rebuilt: null, aftermarket_new: null };
  } else {
    (stockResult.data || []).forEach(function(row) {
      var kind = normalizeProductKind(row.product_kind);
      if (!Object.prototype.hasOwnProperty.call(stockMap, kind)) return;
      var qty = parseFloat(row.stock_qty);
      if (!isNaN(qty)) stockMap[kind] += qty;
    });
  }
  wrap.innerHTML = kinds.map(function(kind, index) {
    return customerCatalogAvailabilityKindHtml(kind, stockMap[kind], prices[index], showPrice, variantRows);
  }).join("");
}

async function loadCustomerCatalogVehicles(product, seq) {
  var wrap = document.getElementById("customer-catalog-vehicle");
  if (!wrap) return;
  wrap.innerHTML = "<div class='customer-catalog-loading'>" + esc(t("loading")) + "</div>";
  var rows = await fetchCatalogVehicleApplications(product);
  if (seq !== customerCatalogDetailSeq || !wrap.isConnected) return;
  wrap.innerHTML = renderVehicleApplicationsTable(rows || []);
}

function bindCustomerCatalogVehicleDisclosure(product, seq) {
  var disclosure = document.getElementById("customer-catalog-vehicle-disclosure");
  if (!disclosure) return;
  disclosure.addEventListener("toggle", function() {
    if (!disclosure.open || disclosure.dataset.loaded === "true" || disclosure.dataset.loading === "true") return;
    disclosure.dataset.loading = "true";
    loadCustomerCatalogVehicles(product, seq).then(function() {
      if (seq === customerCatalogDetailSeq && disclosure.isConnected) disclosure.dataset.loaded = "true";
    }).finally(function() {
      if (disclosure.isConnected) disclosure.dataset.loading = "false";
    });
  });
}

async function loadCustomerCatalogCompatible(product, seq) {
  var wrap = document.getElementById("customer-catalog-compatible");
  if (!wrap) return;
  var result = await sb.rpc("get_kikan_compatible_parts", {
    target_dkd_shohin_id: parseInt(productDkdId(product), 10),
    target_manufacturer: product.manufacturer || null,
    target_manufacturer_part_number: product.manufacturer_part_number || null,
    target_genuine_part_number: product.genuine_part_number || null
  });
  if (seq !== customerCatalogDetailSeq || !wrap.isConnected) return;
  var rows = result.error ? [] : filterVisibleProducts(result.data || []).filter(function(row) {
    return productDkdId(row) !== productDkdId(product);
  }).slice(0, 20);
  if (!rows.length) {
    wrap.innerHTML = "<div class='customer-catalog-empty'>" + esc(t("kikan_none")) + "</div>";
    return;
  }
  wrap.innerHTML = "<div class='customer-catalog-compatible-list'>" + rows.map(function(row) {
    return "<button class='customer-catalog-compatible' type='button' data-customer-compatible-dkd='" + esc(productDkdId(row)) + "'><strong>" + esc(row.genuine_part_number || row.manufacturer_part_number || "-") + "</strong><span>" + esc([row.manufacturer, row.manufacturer_part_number].filter(Boolean).join(" / ")) + "</span></button>";
  }).join("") + "</div>";
  wrap.querySelectorAll("[data-customer-compatible-dkd]").forEach(function(button) {
    button.addEventListener("click", function() { openCustomerCatalogProductById(button.dataset.customerCompatibleDkd); });
  });
}

async function openCustomerCatalogProduct(product, options) {
  options = options || {};
  if (!product || !isCustomerVisibleProduct(product)) return;
  customerCatalogSelectedProduct = product;
  var seq = ++customerCatalogDetailSeq;
  renderCustomerCatalogList();
  renderCustomerCatalogDetailBase(product);
  if (!options.autoSelect) {
    logProductDetailOpen("customer-catalog", product);
    if (window.innerWidth < 761) {
      var detail = document.getElementById("customer-catalog-detail");
      if (detail) detail.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  }
  var settings = customerCatalogContext().settings || defaultCustomerDisplaySettings();
  bindCustomerCatalogVehicleDisclosure(product, seq);
  var loads = [];
  if (settings.show_product_images) loads.push(loadCustomerCatalogImages(product, seq));
  loads.push(loadCustomerCatalogAvailability(product, seq));
  if (settings.show_compatible_parts) loads.push(loadCustomerCatalogCompatible(product, seq));
  await Promise.allSettled(loads);
}

async function openCustomerCatalogProductById(dkdId) {
  var id = parseInt(dkdId, 10);
  if (isNaN(id)) return;
  var product = customerCatalogProducts.find(function(row) { return parseInt(productDkdId(row), 10) === id; }) || null;
  if (!product) {
    var result = await sb.from("core_products").select(CORE_PRODUCT_FAST_SELECT).eq("dkd_shohin_id", id).maybeSingle();
    if (result.error || !result.data) return;
    product = normalizeCoreProductFastRows([result.data])[0];
  }
  await openCustomerCatalogProduct(product);
}

async function enterCustomerCatalog(options) {
  options = options || {};
  var context = customerCatalogContext();
  if ((!isCustomerViewer() && !canPreviewCustomerPortal()) || !context.sales_customer_id || !context.customer || (isCustomerViewer() && !canViewProductSearch())) {
    showPermissionDenied("open_customer_catalog", "core_products");
    return;
  }
  customerPortalSearchActive = true;
  showScreen("customer-catalog");
  renderCustomerCatalogShell();
  await populateCustomerCatalogCategories();
  var input = document.getElementById("customer-catalog-q");
  var category = document.getElementById("customer-catalog-category");
  if (input && options.query !== undefined) input.value = options.query || "";
  if (category && options.category) category.value = options.category;
  if ((options.query !== undefined && options.query !== "") || options.runSearch) {
    await runCustomerCatalogSearch({ logActivity: !!options.logActivity });
  } else {
    renderCustomerCatalogList();
    if (customerCatalogSelectedProduct) await openCustomerCatalogProduct(customerCatalogSelectedProduct, { autoSelect: true });
  }
}

function returnToCustomerPortal() {
  customerPortalSearchActive = false;
  showScreen("customer-portal");
  renderCustomerPortal();
}

function exitCustomerMode() {
  if (!canPreviewCustomerPortal()) return;
  customerPortalSearchActive = false;
  customerPortalPreviewContext = null;
  detailSelectedSalesCustomerId = "";
  customerCatalogProducts = [];
  customerCatalogSelectedProduct = null;
  customerCatalogImageInfo = { counts: {}, thumbnails: {} };
  clearAppRestoreState();
  showScreen("menu");
  renderMenu();
  updateAllHeaders();
}

function returnFromProductSearch() {
  closePanel();
  if (customerPortalSearchActive || isCustomerViewer()) {
    customerPortalSearchActive = false;
    showScreen("customer-portal");
    renderCustomerPortal();
    return;
  }
  returnToMenuFresh();
}

// =============================================
// 送料一覧・送料マスタ
// =============================================
function shippingPrefectureLabel(code) {
  var numericCode = parseInt(code, 10);
  var row = SHIPPING_PREFECTURES.find(function(item) { return item[0] === numericCode; });
  if (!row) return "-";
  if (currentLang === "en") return row[2];
  if (currentLang === "zh") return row[3];
  return row[1];
}

function shippingPrefectureOptionsHtml(selected, includeAll) {
  selected = String(selected == null ? "" : selected);
  var html = includeAll ? "<option value='all'>" + esc(t("shipping_all_prefectures")) + "</option>" : "";
  SHIPPING_PREFECTURES.forEach(function(row) {
    var value = String(row[0]);
    html += "<option value='" + value + "'" + (value === selected ? " selected" : "") + ">" + esc(shippingPrefectureLabel(row[0])) + "</option>";
  });
  return html;
}

function populateShippingPrefectureSelects() {
  [
    ["customer-shipping-prefecture", true],
    ["shipping-rate-prefecture-filter", true],
    ["shipping-rate-prefecture", false]
  ].forEach(function(config) {
    var select = document.getElementById(config[0]);
    if (!select) return;
    var selected = select.value || (config[1] ? "all" : "1");
    select.innerHTML = shippingPrefectureOptionsHtml(selected, config[1]);
    if (Array.from(select.options).some(function(option) { return option.value === selected; })) select.value = selected;
  });
}

function shippingCarrierNames() {
  return shippingUniqueValues("carrier_name");
}

function shippingUniqueValues(fieldName) {
  var seen = {};
  return shippingRateRows.map(function(row) { return String(row[fieldName] || "").trim(); }).filter(function(name) {
    if (!name || seen[name]) return false;
    seen[name] = true;
    return true;
  }).sort(function(a, b) { return a.localeCompare(b, "ja"); });
}

function populateShippingCarrierSelects() {
  var carriers = shippingCarrierNames();
  ["customer-shipping-carrier", "shipping-rate-carrier-filter"].forEach(function(id) {
    var select = document.getElementById(id);
    if (!select) return;
    var selected = select.value || "all";
    var html = "<option value='all'>" + esc(t("shipping_all_carriers")) + "</option>";
    carriers.forEach(function(name) {
      html += "<option value='" + esc(name) + "'>" + esc(name) + "</option>";
    });
    select.innerHTML = html;
    select.value = carriers.indexOf(selected) >= 0 ? selected : "all";
  });
  var datalist = document.getElementById("shipping-rate-carrier-list");
  if (datalist) datalist.innerHTML = carriers.map(function(name) { return "<option value='" + esc(name) + "'></option>"; }).join("");
}

function populateShippingDetailSelects() {
  [
    ["service_name", "shipping_all_services", ["customer-shipping-service", "shipping-rate-service-filter"], "shipping-rate-service-list"],
    ["package_size_label", "shipping_all_sizes", ["customer-shipping-size", "shipping-rate-size-filter"], "shipping-rate-size-list"]
  ].forEach(function(config) {
    var values = shippingUniqueValues(config[0]);
    config[2].forEach(function(id) {
      var select = document.getElementById(id);
      if (!select) return;
      var selected = select.value || "all";
      select.innerHTML = "<option value='all'>" + esc(t(config[1])) + "</option>" + values.map(function(value) {
        return "<option value='" + esc(value) + "'>" + esc(value) + "</option>";
      }).join("");
      select.value = values.indexOf(selected) >= 0 ? selected : "all";
    });
    var datalist = document.getElementById(config[3]);
    if (datalist) datalist.innerHTML = values.map(function(value) { return "<option value='" + esc(value) + "'></option>"; }).join("");
  });
}

function shippingTaxLabel(taxType) {
  if (taxType === "included") return t("shipping_tax_included");
  if (taxType === "excluded") return t("shipping_tax_excluded");
  return t("shipping_tax_unknown");
}

function shippingFeeHtml(value, taxType) {
  if (value === null || value === undefined || value === "") {
    return "<span class='shipping-rate-fee pending'>" + esc(t("shipping_inquiry")) + "</span>";
  }
  var amount = parseInt(value, 10);
  if (isNaN(amount)) return "<span class='shipping-rate-fee pending'>" + esc(t("shipping_inquiry")) + "</span>";
  var normalizedTaxType = ["included", "excluded"].indexOf(taxType) >= 0 ? taxType : "unknown";
  return "<span class='shipping-rate-fee'>¥" + esc(amount.toLocaleString("ja-JP")) + "</span>" +
    "<span class='shipping-rate-tax-label " + normalizedTaxType + "'>" + esc(shippingTaxLabel(normalizedTaxType)) + "</span>";
}

function shippingPackageHtml(row) {
  var limits = [];
  if (row.max_size_cm != null) limits.push(esc(String(row.max_size_cm)) + " cm");
  if (row.max_weight_kg != null) limits.push(esc(String(Number(row.max_weight_kg))) + " kg");
  return "<strong>" + esc(row.package_size_label || "-") + "</strong>" +
    (limits.length ? "<span class='shipping-rate-package-limits'>" + limits.join(" / ") + "</span>" : "");
}

function shippingRateDetailHtml(row) {
  var html = "";
  if (row.origin_region) html += "<span class='shipping-rate-origin'>" + esc(t("shipping_origin_region")) + ": " + esc(row.origin_region) + "</span>";
  if (row.remote_island_condition) html += "<span><b>" + esc(t("shipping_island_condition")) + ":</b> " + esc(row.remote_island_condition) + "</span>";
  if (row.note) html += "<span><b>" + esc(t("shipping_note")) + ":</b> " + esc(row.note) + "</span>";
  return html || "-";
}

function shippingRateCell(labelKey, content, className) {
  var cellClass = className || "customer-shipping-cell";
  var labelClass = cellClass === "shipping-rate-mgmt-cell" ? "shipping-rate-cell-label" : "customer-shipping-mobile-label";
  return "<div class='" + esc(cellClass) + "'><span class='" + labelClass + "'>" + esc(t(labelKey)) + "</span>" + content + "</div>";
}

function shippingPackageKey(row) {
  row = row || {};
  return [
    row.carrier_name || "",
    row.service_name || "",
    row.package_size_label || "",
    row.max_size_cm == null ? "" : row.max_size_cm,
    row.max_weight_kg == null ? "" : Number(row.max_weight_kg)
  ].map(function(value) { return encodeURIComponent(String(value)); }).join("|");
}

function shippingPackageDefinitionKey(row) {
  row = row || {};
  return [
    row.package_size_label || "",
    row.max_size_cm == null ? "" : row.max_size_cm,
    row.max_weight_kg == null ? "" : Number(row.max_weight_kg)
  ].map(function(value) { return encodeURIComponent(String(value)); }).join("|");
}

function uniqueShippingPackages(rows, definitionOnly) {
  var seen = {};
  return (rows || []).filter(function(row) {
    var key = definitionOnly ? shippingPackageDefinitionKey(row) : shippingPackageKey(row);
    if (!key || seen[key]) return false;
    seen[key] = true;
    return true;
  }).sort(function(a, b) {
    var sizeA = a.max_size_cm == null ? Number.MAX_SAFE_INTEGER : Number(a.max_size_cm);
    var sizeB = b.max_size_cm == null ? Number.MAX_SAFE_INTEGER : Number(b.max_size_cm);
    if (sizeA !== sizeB) return sizeA - sizeB;
    var weightA = a.max_weight_kg == null ? Number.MAX_SAFE_INTEGER : Number(a.max_weight_kg);
    var weightB = b.max_weight_kg == null ? Number.MAX_SAFE_INTEGER : Number(b.max_weight_kg);
    if (weightA !== weightB) return weightA - weightB;
    return String(a.package_size_label || "").localeCompare(String(b.package_size_label || ""), "ja");
  });
}

function shippingPackageOptionLabel(row) {
  var limits = [];
  if (row.max_size_cm != null) limits.push(String(row.max_size_cm) + " cm");
  if (row.max_weight_kg != null) limits.push(String(Number(row.max_weight_kg)) + " kg");
  return String(row.package_size_label || "-") + (limits.length ? " / " + limits.join(" / ") : "");
}

async function ensureSalesShippingRateRows() {
  if (salesShippingRatesLoaded) return salesShippingRateRows;
  if (salesShippingRatesPromise) return salesShippingRatesPromise;
  salesShippingRatesPromise = (async function() {
    var result = await sb.from("customer_shipping_rates")
      .select("shipping_rate_id,carrier_name,service_name,package_size_label,max_size_cm,max_weight_kg,prefecture_code,standard_fee_jpy,remote_island_fee_jpy,remote_island_condition,note,origin_region,tax_type,display_order,is_active")
      .eq("is_active", true)
      .order("display_order", { ascending: true })
      .order("carrier_name", { ascending: true })
      .order("prefecture_code", { ascending: true })
      .limit(1000);
    if (result.error) throw result.error;
    salesShippingRateRows = result.data || [];
    salesShippingRatesLoaded = true;
    return salesShippingRateRows;
  })();
  try {
    return await salesShippingRatesPromise;
  } finally {
    salesShippingRatesPromise = null;
  }
}

async function fetchCoreProductShippingProfile(dkdId) {
  var id = parseInt(dkdId, 10);
  if (isNaN(id)) return null;
  var result = await sb.from("core_products")
    .select("dkd_shohin_id,shipping_weight_kg,shipping_size_cm,shipping_package_size_label")
    .eq("dkd_shohin_id", id)
    .maybeSingle();
  if (result.error) throw result.error;
  return result.data || {
    dkd_shohin_id: id,
    shipping_weight_kg: null,
    shipping_size_cm: null,
    shipping_package_size_label: null
  };
}

function shippingProfileText(profile) {
  profile = profile || {};
  var values = [];
  if (profile.shipping_package_size_label) values.push(String(profile.shipping_package_size_label));
  else if (profile.shipping_size_cm != null) values.push(String(profile.shipping_size_cm) + " cm");
  if (profile.shipping_weight_kg != null) values.push(String(Number(profile.shipping_weight_kg)) + " kg");
  return values.length ? values.join(" / ") : t("product_shipping_unset");
}

async function populateProductShippingSizeSelect(product) {
  var select = document.getElementById("pf-shipping-package-size");
  if (!select) return;
  select.innerHTML = "<option value=''>" + esc(t("product_shipping_unset")) + "</option>";
  try {
    await ensureSalesShippingRateRows();
    productShippingSizeRows = uniqueShippingPackages(salesShippingRateRows, true);
    productShippingSizeRows.forEach(function(row) {
      var option = document.createElement("option");
      option.value = shippingPackageDefinitionKey(row);
      option.textContent = shippingPackageOptionLabel(row);
      select.appendChild(option);
    });
    product = product || {};
    var selected = productShippingSizeRows.find(function(row) {
      var labelMatches = String(row.package_size_label || "") === String(product.shipping_package_size_label || "");
      var sizeMatches = String(row.max_size_cm == null ? "" : row.max_size_cm) === String(product.shipping_size_cm == null ? "" : product.shipping_size_cm);
      return labelMatches && sizeMatches;
    });
    if (!selected && (product.shipping_package_size_label || product.shipping_size_cm != null)) {
      selected = {
        package_size_label: product.shipping_package_size_label || (String(product.shipping_size_cm) + " cm"),
        max_size_cm: product.shipping_size_cm,
        max_weight_kg: null
      };
      productShippingSizeRows.push(selected);
      var retainedOption = document.createElement("option");
      retainedOption.value = shippingPackageDefinitionKey(selected);
      retainedOption.textContent = shippingPackageOptionLabel(selected);
      select.appendChild(retainedOption);
    }
    select.value = selected ? shippingPackageDefinitionKey(selected) : "";
  } catch (error) {
    console.warn("product shipping sizes lookup failed", error);
    productShippingSizeRows = [];
  }
}

function productShippingFormValue() {
  var weightInput = document.getElementById("pf-shipping-weight");
  var sizeSelect = document.getElementById("pf-shipping-package-size");
  var rawWeight = weightInput ? String(weightInput.value || "").trim() : "";
  var weight = rawWeight ? Number(rawWeight) : null;
  if (rawWeight && (!isFinite(weight) || weight <= 0 || weight > 99999.999)) return { error: true };
  var selectedKey = sizeSelect ? sizeSelect.value : "";
  var selected = selectedKey ? productShippingSizeRows.find(function(row) {
    return shippingPackageDefinitionKey(row) === selectedKey;
  }) : null;
  if (selectedKey && !selected) return { error: true };
  return {
    error: false,
    shipping_weight_kg: weight,
    shipping_size_cm: selected && selected.max_size_cm != null ? Number(selected.max_size_cm) : null,
    shipping_package_size_label: selected ? (selected.package_size_label || null) : null
  };
}

function salesShippingUniqueValues(rows, fieldName) {
  var seen = {};
  return (rows || []).map(function(row) { return String(row[fieldName] || "").trim(); }).filter(function(value) {
    if (!value || seen[value]) return false;
    seen[value] = true;
    return true;
  });
}

function salesShippingMatchingPackage(packages, profile) {
  profile = profile || {};
  return (packages || []).find(function(row) {
    var labelMatches = String(row.package_size_label || "") === String(profile.shipping_package_size_label || "");
    var sizeMatches = String(row.max_size_cm == null ? "" : row.max_size_cm) === String(profile.shipping_size_cm == null ? "" : profile.shipping_size_cm);
    return labelMatches && sizeMatches;
  }) || null;
}

function bindSalesShippingEstimateActions() {
  var prefecture = document.getElementById("sales-shipping-prefecture");
  var carrier = document.getElementById("sales-shipping-carrier");
  var service = document.getElementById("sales-shipping-service");
  var packageSize = document.getElementById("sales-shipping-package-size");
  if (prefecture) prefecture.onchange = function() {
    salesShippingPrefectureCode = prefecture.value || "";
    renderSalesShippingEstimate();
  };
  if (carrier) carrier.onchange = function() {
    salesShippingCarrierName = carrier.value || "";
    salesShippingServiceName = "";
    salesShippingPackageKeyValue = "";
    renderSalesShippingEstimate();
  };
  if (service) service.onchange = function() {
    salesShippingServiceName = service.value || "";
    salesShippingPackageKeyValue = "";
    renderSalesShippingEstimate();
  };
  if (packageSize) packageSize.onchange = function() {
    salesShippingPackageKeyValue = packageSize.value || "";
    renderSalesShippingEstimate();
  };
}

function renderSalesShippingEstimate(loadError) {
  var host = document.getElementById("sales-shipping-estimate-wrap");
  if (!host) return;
  if (loadError) {
    host.innerHTML = "<div class='sales-shipping-message error'>" + esc(t("sales_shipping_profile_load_error")) + "</div>";
    return;
  }
  var rows = salesShippingRateRows || [];
  var carriers = salesShippingUniqueValues(rows, "carrier_name");
  if (!carriers.length) {
    host.innerHTML = "<div class='sales-shipping-message'>" + esc(t("shipping_no_rates")) + "</div>";
    return;
  }
  if (carriers.indexOf(salesShippingCarrierName) < 0) salesShippingCarrierName = carriers[0];
  var carrierRows = rows.filter(function(row) { return String(row.carrier_name || "") === salesShippingCarrierName; });
  var services = salesShippingUniqueValues(carrierRows, "service_name");
  if (services.indexOf(salesShippingServiceName) < 0) {
    var profileService = services.find(function(serviceName) {
      return !!salesShippingMatchingPackage(uniqueShippingPackages(carrierRows.filter(function(row) {
        return String(row.service_name || "") === serviceName;
      }), false), salesShippingProfile);
    });
    salesShippingServiceName = profileService || services[0] || "";
  }
  var serviceRows = carrierRows.filter(function(row) { return String(row.service_name || "") === salesShippingServiceName; });
  var packages = uniqueShippingPackages(serviceRows, false);
  var savedPackage = salesShippingMatchingPackage(packages, salesShippingProfile);
  var selectedPackage = packages.find(function(row) { return shippingPackageKey(row) === salesShippingPackageKeyValue; }) || savedPackage;
  if (selectedPackage && !salesShippingPackageKeyValue) salesShippingPackageKeyValue = shippingPackageKey(selectedPackage);
  if (!selectedPackage) salesShippingPackageKeyValue = "";

  var profileHasSize = !!(salesShippingProfile && (salesShippingProfile.shipping_package_size_label || salesShippingProfile.shipping_size_cm != null));
  var html = "<div class='sales-shipping-profile'><span>" + esc(t("sales_shipping_profile")) + "</span><strong>" + esc(shippingProfileText(salesShippingProfile)) + "</strong></div>";
  if (!profileHasSize) html += "<div class='sales-shipping-message manual'>" + esc(t("sales_shipping_manual_size_note")) + "</div>";
  html += "<div class='sales-shipping-controls'>";
  html += "<label><span>" + esc(t("sales_shipping_destination")) + "</span><select id='sales-shipping-prefecture'><option value=''>" + esc(t("sales_shipping_select_prefecture")) + "</option>" + shippingPrefectureOptionsHtml(salesShippingPrefectureCode, false) + "</select></label>";
  html += "<label><span>" + esc(t("shipping_carrier")) + "</span><select id='sales-shipping-carrier'>" + carriers.map(function(name) { return "<option value='" + esc(name) + "'" + (name === salesShippingCarrierName ? " selected" : "") + ">" + esc(name) + "</option>"; }).join("") + "</select></label>";
  html += "<label><span>" + esc(t("shipping_service")) + "</span><select id='sales-shipping-service'>" + services.map(function(name) { return "<option value='" + esc(name) + "'" + (name === salesShippingServiceName ? " selected" : "") + ">" + esc(name) + "</option>"; }).join("") + "</select></label>";
  html += "<label class='sales-shipping-size-control'><span>" + esc(t("shipping_package_size")) + "</span><select id='sales-shipping-package-size'><option value=''>" + esc(t("sales_shipping_select_size")) + "</option>" + packages.map(function(row) { var key = shippingPackageKey(row); return "<option value='" + esc(key) + "'" + (key === salesShippingPackageKeyValue ? " selected" : "") + ">" + esc(shippingPackageOptionLabel(row)) + "</option>"; }).join("") + "</select></label>";
  html += "</div>";

  var selectedRate = null;
  if (selectedPackage && salesShippingPrefectureCode) {
    selectedRate = serviceRows.find(function(row) {
      return String(row.prefecture_code) === String(salesShippingPrefectureCode) && shippingPackageKey(row) === shippingPackageKey(selectedPackage);
    }) || null;
  }
  if (selectedPackage && salesShippingProfile && salesShippingProfile.shipping_weight_kg != null && selectedPackage.max_weight_kg != null && Number(salesShippingProfile.shipping_weight_kg) > Number(selectedPackage.max_weight_kg)) {
    html += "<div class='sales-shipping-message warning'>" + esc(t("sales_shipping_weight_over")) + "</div>";
  } else if (!salesShippingPrefectureCode || !selectedPackage) {
    html += "<div class='sales-shipping-result pending'>" + esc(!salesShippingPrefectureCode ? t("sales_shipping_select_prefecture") : t("sales_shipping_select_size")) + "</div>";
  } else if (!selectedRate) {
    html += "<div class='sales-shipping-message warning'>" + esc(t("sales_shipping_no_rate")) + "</div>";
  } else {
    html += "<div class='sales-shipping-result'><span>" + esc(t("sales_shipping_rate")) + "</span><div>" + shippingFeeHtml(selectedRate.standard_fee_jpy, selectedRate.tax_type) + "</div></div>";
    html += "<div class='sales-shipping-island'><span><b>" + esc(t("shipping_island_fee")) + ":</b> " + shippingFeeHtml(selectedRate.remote_island_fee_jpy, selectedRate.tax_type) + "</span>";
    if (selectedRate.remote_island_condition) html += "<span><b>" + esc(t("shipping_island_condition")) + ":</b> " + esc(selectedRate.remote_island_condition) + "</span>";
    if (selectedRate.note) html += "<span><b>" + esc(t("shipping_note")) + ":</b> " + esc(selectedRate.note) + "</span>";
    html += "</div>";
  }
  host.innerHTML = html;
  var prefectureSelect = document.getElementById("sales-shipping-prefecture");
  if (prefectureSelect) prefectureSelect.value = salesShippingPrefectureCode;
  bindSalesShippingEstimateActions();
}

async function loadSalesShippingEstimateForCurrent(seq) {
  var section = document.getElementById("sales-shipping-estimate-section");
  var host = document.getElementById("sales-shipping-estimate-wrap");
  if (!section || !host || !currentProduct || !canViewCustomerShippingRates()) {
    if (section) setCspStyle(section, "display", "none");
    return;
  }
  setCspStyle(section, "display", "block");
  host.innerHTML = "<div class='sales-detail-empty'>" + esc(t("loading")) + "</div>";
  var dkdId = parseInt(productDkdId(currentProduct), 10);
  if (isNaN(dkdId)) return;
  try {
    var values = await Promise.all([ensureSalesShippingRateRows(), fetchCoreProductShippingProfile(dkdId)]);
    if (seq !== detailSecondaryRequestSeq || !currentProduct || parseInt(productDkdId(currentProduct), 10) !== dkdId) return;
    salesShippingProfile = values[1];
    salesShippingProfileDkdId = dkdId;
    salesShippingPackageKeyValue = "";
    currentProduct = Object.assign({}, currentProduct, salesShippingProfile || {});
    renderSalesShippingEstimate();
  } catch (error) {
    console.warn("sales shipping estimate lookup failed", error);
    if (seq === detailSecondaryRequestSeq) renderSalesShippingEstimate(true);
  }
}

function sortedShippingRows(rows) {
  return (rows || []).slice().sort(function(a, b) {
    var orderDiff = (parseInt(a.display_order, 10) || 0) - (parseInt(b.display_order, 10) || 0);
    if (orderDiff) return orderDiff;
    var carrierDiff = String(a.carrier_name || "").localeCompare(String(b.carrier_name || ""), "ja");
    if (carrierDiff) return carrierDiff;
    return (parseInt(a.prefecture_code, 10) || 0) - (parseInt(b.prefecture_code, 10) || 0);
  });
}

function filteredShippingRows(prefectureId, carrierId, serviceId, sizeId, statusId) {
  var prefecture = (document.getElementById(prefectureId) || {}).value || "all";
  var carrier = (document.getElementById(carrierId) || {}).value || "all";
  var service = serviceId ? ((document.getElementById(serviceId) || {}).value || "all") : "all";
  var packageSize = sizeId ? ((document.getElementById(sizeId) || {}).value || "all") : "all";
  var status = statusId ? ((document.getElementById(statusId) || {}).value || "all") : "active";
  return sortedShippingRows(shippingRateRows.filter(function(row) {
    if (prefecture !== "all" && String(row.prefecture_code) !== prefecture) return false;
    if (carrier !== "all" && String(row.carrier_name || "") !== carrier) return false;
    if (service !== "all" && String(row.service_name || "") !== service) return false;
    if (packageSize !== "all" && String(row.package_size_label || "") !== packageSize) return false;
    if (status === "active" && row.is_active === false) return false;
    if (status === "inactive" && row.is_active !== false) return false;
    return true;
  }));
}

async function enterCustomerShipping() {
  if (!canViewCustomerShippingRates()) {
    showPermissionDenied("open_customer_shipping", "customer_shipping_rates");
    return;
  }
  customerPortalSearchActive = false;
  showScreen("customer-shipping");
  renderCustomerExperienceHeaders();
  populateShippingPrefectureSelects();
  var prefecture = document.getElementById("customer-shipping-prefecture");
  var carrier = document.getElementById("customer-shipping-carrier");
  var service = document.getElementById("customer-shipping-service");
  var packageSize = document.getElementById("customer-shipping-size");
  if (prefecture) prefecture.value = "all";
  if (carrier) carrier.value = "all";
  if (service) service.value = "all";
  if (packageSize) packageSize.value = "all";
  await loadCustomerShippingRates();
}

function returnToCustomerPortalFromShipping() {
  showScreen("customer-portal");
  renderCustomerPortal();
}

async function loadCustomerShippingRates() {
  var requestSeq = ++shippingRateLoadSeq;
  var host = document.getElementById("customer-shipping-list");
  if (host) host.innerHTML = "<div class='customer-shipping-empty'>" + esc(t("loading")) + "</div>";
  var result = await sb.from("customer_shipping_rates")
    .select("shipping_rate_id,carrier_name,service_name,package_size_label,max_size_cm,max_weight_kg,prefecture_code,standard_fee_jpy,remote_island_fee_jpy,remote_island_condition,note,origin_region,tax_type,display_order,is_active")
    .eq("is_active", true)
    .order("display_order", { ascending: true })
    .order("carrier_name", { ascending: true })
    .order("prefecture_code", { ascending: true })
    .limit(1000);
  if (requestSeq !== shippingRateLoadSeq) return;
  if (result.error) {
    console.warn("customer shipping rates lookup failed", result.error);
    shippingRateRows = [];
    renderCustomerShippingRates(true);
    return;
  }
  shippingRateRows = result.data || [];
  populateShippingCarrierSelects();
  populateShippingDetailSelects();
  renderCustomerShippingRates();
}

function renderCustomerShippingRates(loadError) {
  var host = document.getElementById("customer-shipping-list");
  var count = document.getElementById("customer-shipping-count");
  if (!host) return;
  if (loadError) {
    if (count) count.textContent = "-";
    host.innerHTML = "<div class='customer-shipping-empty save-err'>" + esc(t("shipping_load_error")) + "</div>";
    return;
  }
  var rows = filteredShippingRows("customer-shipping-prefecture", "customer-shipping-carrier", "customer-shipping-service", "customer-shipping-size");
  if (count) count.textContent = tf("customer_catalog_count", { n: rows.length });
  if (!rows.length) {
    host.innerHTML = "<div class='customer-shipping-empty'>" + esc(t("shipping_no_rates")) + "</div>";
    return;
  }
  var html = "<div class='customer-shipping-head'>" +
    "<span>" + esc(t("shipping_carrier")) + "</span>" +
    "<span>" + esc(t("shipping_service")) + "</span>" +
    "<span>" + esc(t("shipping_package_size")) + "</span>" +
    "<span>" + esc(t("shipping_prefecture")) + "</span>" +
    "<span>" + esc(t("shipping_standard_fee")) + "</span>" +
    "<span>" + esc(t("shipping_island_fee")) + "</span>" +
    "<span>" + esc(t("shipping_rate_detail")) + "</span></div>";
  rows.forEach(function(row) {
    html += "<div class='customer-shipping-row'>";
    html += shippingRateCell("shipping_carrier", "<strong>" + esc(row.carrier_name || "-") + "</strong>");
    html += shippingRateCell("shipping_service", "<strong>" + esc(row.service_name || "-") + "</strong>");
    html += shippingRateCell("shipping_package_size", shippingPackageHtml(row));
    html += shippingRateCell("shipping_prefecture", "<strong>" + esc(shippingPrefectureLabel(row.prefecture_code)) + "</strong>");
    html += shippingRateCell("shipping_standard_fee", shippingFeeHtml(row.standard_fee_jpy, row.tax_type));
    html += shippingRateCell("shipping_island_fee", shippingFeeHtml(row.remote_island_fee_jpy, row.tax_type));
    html += shippingRateCell("shipping_rate_detail", "<div class='shipping-rate-detail'>" + shippingRateDetailHtml(row) + "</div>");
    html += "</div>";
  });
  host.innerHTML = html;
}

