    "<div class='core-qty-card aftermarket_new'><div class='core-qty-label'>" + esc(productKindLabel("aftermarket_new")) + "</div><div class='core-qty-value'>" + esc(kikanStockQtyText(product, "aftermarket_new")) + "</div><div class='core-qty-sub'>" + esc(t("product_kind_stock_qty")) + "</div></div>" +
  "</div>";
