function closeEcCategoryTargetBuilder() {
  var overlay = document.getElementById("ec-category-target-overlay");
  if (overlay) overlay.classList.remove("show");
}

async function confirmEcCategoryTargetBuilder() {
  var merged = addSelectedEcCategoryTargets();
  if (!merged || !merged.total) return;
  var saved = await saveEcMallTargets();
  if (!saved) return;
  var message = tf("ec_category_target_added", merged) + " / " + tf("ec_targets_saved", { n: rakutenTargets.length });
  setRakutenStatus(message, false);
  var status = document.getElementById("ec-category-target-search-status");
  if (status) status.textContent = message;
  closeEcCategoryTargetBuilder();
}

function ecResearchDefaultScheduleSettings() {
  return {
    schedule_enabled: true,
    cron_expression: "0 17 * * *",
    timezone: "Asia/Tokyo",
    quiet_window_start: "02:00",
    quiet_window_end: "05:00",
    default_provider_keys: ecMallDefaultProviders.slice(),
    default_hits: 30,
    default_sort: "+itemPrice",
    default_include_used: false
  };
}

function pad2(n) {
  n = parseInt(n, 10);
  return (n < 10 ? "0" : "") + String(isNaN(n) ? 0 : n);
}

function normalizeTimeInput(value, fallback) {
  var text = String(value || fallback || "00:00").trim();
  var m = text.match(/^(\d{1,2}):(\d{2})/);
  if (!m) return fallback || "00:00";
  var h = Math.max(0, Math.min(23, parseInt(m[1], 10)));
  var min = Math.max(0, Math.min(59, parseInt(m[2], 10)));
  return pad2(h) + ":" + pad2(min);
}

function jstTimeToDailyCronExpression(timeValue) {
  var time = normalizeTimeInput(timeValue, "02:00").split(":");
  var minute = parseInt(time[1], 10);
  var utcHour = (parseInt(time[0], 10) + 15) % 24;
  return String(minute) + " " + String(utcHour) + " * * *";
}

function dailyCronExpressionToJstTime(cronExpression) {
  var m = String(cronExpression || "").match(/^(\d{1,2})\s+(\d{1,2})\s+\*\s+\*\s+\*$/);
  if (!m) return "02:00";
  var minute = Math.max(0, Math.min(59, parseInt(m[1], 10)));
  var jstHour = (Math.max(0, Math.min(23, parseInt(m[2], 10))) + 9) % 24;
  return pad2(jstHour) + ":" + pad2(minute);
}

function normalizeEcResearchScheduleSettings(row) {
  var defaults = ecResearchDefaultScheduleSettings();
  row = row || {};
  var start = normalizeTimeInput(row.quiet_window_start || dailyCronExpressionToJstTime(row.cron_expression), defaults.quiet_window_start);
  return {
    schedule_enabled: row.schedule_enabled == null ? defaults.schedule_enabled : !!row.schedule_enabled,
    cron_expression: row.cron_expression || jstTimeToDailyCronExpression(start),
    timezone: row.timezone || defaults.timezone,
    quiet_window_start: start,
    quiet_window_end: normalizeTimeInput(row.quiet_window_end, defaults.quiet_window_end),
    default_provider_keys: row.default_provider_keys && row.default_provider_keys.length ? row.default_provider_keys : defaults.default_provider_keys,
    default_hits: row.default_hits || defaults.default_hits,
    default_sort: row.default_sort || defaults.default_sort,
    default_include_used: !!row.default_include_used,
    updated_at: row.updated_at || null
  };
}

function applyEcResearchScheduleForm(settings) {
  settings = normalizeEcResearchScheduleSettings(settings || ecResearchScheduleSettings);
  var enabledEl = document.getElementById("ec-schedule-enabled");
  var startEl = document.getElementById("ec-schedule-start");
  var endEl = document.getElementById("ec-schedule-end");
  var hitsEl = document.getElementById("ec-schedule-hits");
  var sortEl = document.getElementById("ec-schedule-sort");
  if (enabledEl) enabledEl.checked = !!settings.schedule_enabled;
  if (startEl) startEl.value = settings.quiet_window_start;
  if (endEl) endEl.value = settings.quiet_window_end;
  if (hitsEl) hitsEl.value = String(settings.default_hits || 30);
  if (sortEl) sortEl.value = settings.default_sort || "+itemPrice";
  updateEcResearchScheduleFormAccess();
}

function updateEcResearchScheduleFormAccess() {
  var canManage = canManageEcResearchSchedule();
  var panel = document.getElementById("ec-research-schedule-panel");
  if (panel) panel.hidden = !canManage;
  ["ec-schedule-enabled","ec-schedule-start","ec-schedule-end","ec-schedule-hits","ec-schedule-sort"].forEach(function(id) {
    var el = document.getElementById(id);
    if (el) el.disabled = !canManage;
  });
  var saveBtn = document.getElementById("btn-ec-save-schedule");
  if (saveBtn) setCspStyle(saveBtn, "display", canManage ? "" : "none");
  var status = document.getElementById("ec-schedule-status");
  if (status && !canManage) status.textContent = t("ec_schedule_admin_only");
}

function collectEcResearchScheduleForm() {
  var start = normalizeTimeInput((document.getElementById("ec-schedule-start") || {}).value, "02:00");
  var end = normalizeTimeInput((document.getElementById("ec-schedule-end") || {}).value, "05:00");
  var hits = parseInt((document.getElementById("ec-schedule-hits") || {}).value || "30", 10);
  if (isNaN(hits)) hits = 30;
  hits = Math.max(1, Math.min(50, hits));
  return normalizeEcResearchScheduleSettings({
    schedule_enabled: !!((document.getElementById("ec-schedule-enabled") || {}).checked),
    cron_expression: jstTimeToDailyCronExpression(start),
    timezone: "Asia/Tokyo",
    quiet_window_start: start,
    quiet_window_end: end,
    default_provider_keys: getEcMallSelectedProviders(),
    default_hits: hits,
    default_sort: (document.getElementById("ec-schedule-sort") || {}).value || "+itemPrice",
    default_include_used: getEcMallIncludeUsed()
  });
}

function setEcScheduleStatus(message, isError) {
  var el = document.getElementById("ec-schedule-status");
  if (!el) return;
  el.textContent = message || "";
  setCspStyle(el, "color", isError ? "#e24b4a" : "");
}

async function loadEcResearchScheduleSettings() {
  try {
    var r = await sb.from("ec_price_research_settings")
      .select("schedule_enabled,cron_expression,timezone,quiet_window_start,quiet_window_end,default_provider_keys,default_hits,default_sort,default_include_used,updated_at")
      .eq("id", true)
      .maybeSingle();
    if (r.error) throw new Error(r.error.message);
    ecResearchScheduleSettings = normalizeEcResearchScheduleSettings(r.data);
    applyEcResearchScheduleForm(ecResearchScheduleSettings);
    setEcScheduleStatus("", false);
  } catch(e) {
    ecResearchScheduleSettings = ecResearchDefaultScheduleSettings();
    applyEcResearchScheduleForm(ecResearchScheduleSettings);
    setEcScheduleStatus(tf("ec_schedule_load_failed", { error: e.message || e }), true);
  }
}

async function saveEcResearchScheduleSettings() {
  if (!canManageEcResearchSchedule()) {
    setEcScheduleStatus(t("ec_schedule_admin_only"), true);
    return;
  }
  var settings = collectEcResearchScheduleForm();
  var btn = document.getElementById("btn-ec-save-schedule");
  if (btn) btn.disabled = true;
  setEcScheduleStatus(t("loading"), false);
  try {
    var r = await sb.rpc("save_ec_price_research_schedule", {
      p_schedule_enabled: settings.schedule_enabled,
      p_cron_expression: settings.cron_expression,
      p_timezone: settings.timezone,
      p_quiet_window_start: settings.quiet_window_start,
      p_quiet_window_end: settings.quiet_window_end,
      p_default_provider_keys: settings.default_provider_keys,
      p_default_hits: settings.default_hits,
      p_default_sort: settings.default_sort,
      p_default_include_used: settings.default_include_used
    });
    if (r.error) throw new Error(r.error.message);
    ecResearchScheduleSettings = normalizeEcResearchScheduleSettings(Array.isArray(r.data) ? r.data[0] : r.data || settings);
    applyEcResearchScheduleForm(ecResearchScheduleSettings);
    loadEcMallResearchStatus();
    setEcScheduleStatus(t("ec_schedule_saved"), false);
  } catch(e) {
    setEcScheduleStatus(tf("ec_schedule_save_failed", { error: e.message || e }), true);
  } finally {
    if (btn) btn.disabled = false;
  }
}

async function runEcMallResearchNow() {
  if (!canUseRakutenResearch()) { setRakutenStatus(t("err_perm"), true); return; }
  if (ecResearchManualRunStarting || ecResearchIsRunning(ecResearchLatestStatus)) {
    setRakutenStatus(t("ec_run_now_already_running"), false);
    syncEcResearchRunningControls(ecResearchLatestStatus);
    return;
  }
  try {
    var latestStatus = await loadEcMallResearchStatus({ silent: true }).catch(function() { return ecResearchLatestStatus; });
    if (ecResearchIsRunning(latestStatus)) {
      setRakutenStatus(t("ec_run_now_already_running"), false);
      syncEcResearchRunningControls(latestStatus);
      return;
    }
    ecResearchManualRunStarting = true;
    ecResearchManualRunStartedAt = Date.now();
    syncEcResearchRunningControls(latestStatus);
    setRakutenStatus(t("ec_run_now_starting"), false);
    var schedule = collectEcResearchScheduleForm();
    var targetLimit = Math.min(1000, Math.max(1, (latestStatus && latestStatus.targetCount) || (ecResearchLatestStatus && ecResearchLatestStatus.targetCount) || 500));
    var r = await sb.functions.invoke("ec-price-research-start", {
      body: {
        limit: targetLimit,
        batch_size: 5,
        hits: schedule.default_hits || 30,
        sort: schedule.default_sort || "+itemPrice",
        provider_keys: getEcMallSelectedProviders()
      }
    });
    if (r.error) throw new Error(r.error.message || r.error);
    if (r.data && r.data.already_running) {
      setRakutenStatus(t("ec_run_now_already_running"), false);
    } else {
      setRakutenStatus(t("ec_run_now_started"), false);
    }
    await loadEcMallResearchStatus({ silent: true }).catch(function() {});
    setTimeout(function() {
      loadEcMallResearchStatus({ silent: true }).catch(function(e) {
        console.warn("ec price research status refresh failed", e);
      });
    }, 3000);
  } catch(e) {
    ecResearchManualRunStarting = false;
    ecResearchManualRunStartedAt = 0;
    syncEcResearchRunningControls(ecResearchLatestStatus);
    setRakutenStatus(tf("ec_run_now_failed", { error: e.message || e }), true);
  }
}

function ecResearchRunStatusLabel(status) {
  var key = "ec_research_run_" + String(status || "none");
  var label = t(key);
  return label === key ? (status || "-") : label;
}

function ecResearchRunDoneCount(run) {
  run = run || {};
  return Number(run.success_count || 0) + Number(run.failed_count || 0) + Number(run.skipped_count || 0);
}

function ecResearchIsRunning(status) {
  return !!(status && status.latestRun && status.latestRun.status === "running");
}

function ecResearchIsStarting() {
  return !!(ecResearchManualRunStarting && Date.now() - ecResearchManualRunStartedAt < 30000);
}

function syncEcResearchRunningControls(status) {
  var running = ecResearchIsStarting() || ecResearchIsRunning(status || ecResearchLatestStatus);
  var runBtn = document.getElementById("btn-ec-run-now");
  var bulkBtn = document.getElementById("btn-rakuten-run-bulk");
  if (runBtn) {
    runBtn.disabled = running;
    runBtn.textContent = running ? t("ec_research_run_running") : t("ec_run_now");
  }
  if (bulkBtn) bulkBtn.disabled = running;
}

function scheduleEcResearchStatusPolling(status) {
  clearTimeout(ecResearchStatusPollTimer);
  ecResearchStatusPollTimer = null;
  if (!ecResearchIsRunning(status) && !ecResearchIsStarting()) return;
  ecResearchStatusPollTimer = setTimeout(function() {
    loadEcMallResearchStatus({ silent: true }).catch(function(e) {
      console.warn("ec price research status polling failed", e);
      scheduleEcResearchStatusPolling(ecResearchLatestStatus);
    });
  }, 10000);
}

function renderEcMallResearchStatus(status) {
  var wrap = document.getElementById("ec-mall-research-status");
  if (!wrap) return;
  status = status || {};
  var latest = status.latestRun || null;
  var categoryText = status.categoryLabels && status.categoryLabels.length ? status.categoryLabels.slice(0, 4).join(" / ") : "-";
  if (status.categoryLabels && status.categoryLabels.length > 4) categoryText += " +" + (status.categoryLabels.length - 4);
  var runText = latest ? ecResearchRunStatusLabel(latest.status) : "-";
  var doneCount = ecResearchRunDoneCount(latest);
  var progressText = latest && latest.status === "running"
    ? tf("ec_research_progress", { done: doneCount, total: latest.target_count || 0 })
    : t("ec_research_success") + " " + (latest ? (latest.success_count || 0) : 0) + "/" + (latest ? (latest.target_count || 0) : 0);
  var runSub = latest
    ? [formatDateTime(latest.finished_at || latest.started_at), progressText, latest.failed_count ? t("ec_research_failed") + " " + latest.failed_count : "", latest.status === "running" ? t("ec_research_running_note") : ""].filter(Boolean).join(" / ")
    : t("ec_research_no_runs");
  var schedule = normalizeEcResearchScheduleSettings(ecResearchScheduleSettings);
  var scheduleValue = schedule.schedule_enabled ? schedule.quiet_window_start : "--:--";
  var scheduleSub = schedule.schedule_enabled
    ? tf("ec_schedule_daily_at", { time: schedule.quiet_window_start, timezone: schedule.timezone })
    : t("ec_schedule_disabled");
  wrap.innerHTML = "<div class='ec-research-status-grid'>" +
    "<div class='ec-research-stat'><div class='ec-research-stat-label'>" + esc(t("ec_research_saved_targets")) + "</div><div class='ec-research-stat-value'>" + esc(String(status.targetCount || 0)) + "</div><div class='ec-research-stat-sub'>" + esc(t("ec_research_enabled_targets")) + "</div></div>" +
    "<div class='ec-research-stat'><div class='ec-research-stat-label'>" + esc(t("ec_research_categories")) + "</div><div class='ec-research-stat-value'>" + esc(String(status.categoryCount || 0)) + "</div><div class='ec-research-stat-sub'>" + esc(categoryText) + "</div></div>" +
    "<div class='ec-research-stat'><div class='ec-research-stat-label'>" + esc(t("ec_research_schedule")) + "</div><div class='ec-research-stat-value'>" + esc(scheduleValue) + "</div><div class='ec-research-stat-sub'>" + esc(scheduleSub) + "</div></div>" +
    "<div class='ec-research-stat'><div class='ec-research-stat-label'>" + esc(t("ec_research_latest_run")) + "</div><div class='ec-research-stat-value'>" + esc(runText) + "</div><div class='ec-research-stat-sub'>" + esc(runSub) + "</div></div>" +
  "</div>";
  syncEcResearchRunningControls(status);
}

async function loadEcMallResearchStatus(options) {
  options = options || {};
  var wrap = document.getElementById("ec-mall-research-status");
  if (wrap && !options.silent) wrap.innerHTML = "<div class='loading'>" + esc(t("loading")) + "</div>";
  try {
    var targetsR = await sb.from("ec_price_research_targets")
      .select("id,category,last_run_at,last_status")
      .eq("enabled", true)
      .limit(5000);
    if (targetsR.error) throw targetsR.error;
    var runR = await sb.from("ec_price_research_runs")
      .select("id,status,triggered_by,target_count,success_count,failed_count,skipped_count,started_at,finished_at,error")
      .order("started_at", { ascending: false })
      .limit(1);
    if (runR.error) throw runR.error;
    var categoryMap = {};
    (targetsR.data || []).forEach(function(row) {
      var cat = ecMallNormalizeTargetCategory(row.category || "");
      if (cat) categoryMap[cat] = true;
    });
    var categoryLabels = Object.keys(categoryMap).sort(function(a, b) {
      return tCat(a).localeCompare(tCat(b), "ja");
    }).map(function(cat) { return tCat(cat); });
    var latestRun = (runR.data || [])[0] || null;
    if (latestRun && latestRun.status === "running" && latestRun.started_at) {
      var startedAtMs = Date.parse(latestRun.started_at);
      var runTargetRows = (targetsR.data || []).filter(function(row) {
        var lastRunMs = Date.parse(row.last_run_at || "");
        return Number.isFinite(lastRunMs) && Number.isFinite(startedAtMs) && lastRunMs >= startedAtMs - 1000;
      });
      latestRun = Object.assign({}, latestRun, {
        success_count: runTargetRows.filter(function(row) { return row.last_status === "completed"; }).length,
        failed_count: runTargetRows.filter(function(row) { return row.last_status === "failed"; }).length,
        skipped_count: runTargetRows.filter(function(row) { return row.last_status === "skipped"; }).length
      });
    }
    ecResearchLatestStatus = {
      targetCount: (targetsR.data || []).length,
      categoryCount: categoryLabels.length,
      categoryLabels: categoryLabels,
      latestRun: latestRun
    };
    if (!ecResearchIsRunning(ecResearchLatestStatus) && !ecResearchIsStarting()) {
      ecResearchManualRunStarting = false;
      ecResearchManualRunStartedAt = 0;
    }
    renderEcMallResearchStatus(ecResearchLatestStatus);
    scheduleEcResearchStatusPolling(ecResearchLatestStatus);
    return ecResearchLatestStatus;
  } catch(e) {
    console.warn("ec price research status failed", e);
    if (wrap) wrap.innerHTML = "<div class='empty'>" + esc(t("ec_research_status_failed")) + "</div>";
    syncEcResearchRunningControls(ecResearchLatestStatus);
    return null;
  }
}

function renderRakutenTargets() {
  var wrap = document.getElementById("rakuten-targets");
  if (!wrap) return;
  if (!rakutenTargets.length) {
    wrap.innerHTML = "<div class='empty'>" + t("rakuten_targets_empty") + "</div>";
    updateEcMallTargetSelectionStatus();
    return;
  }
  var html = "<div class='rakuten-target-list'>";
  html += "<div class='rakuten-target-row header'><div class='rakuten-target-check-cell'><input type='checkbox' data-ec-target-select-all='1' aria-label='" + esc(t("ec_target_select_all")) + "'></div><div>" + t("rakuten_keyword") + "</div><div>メーカー品番</div><div>純正品番</div><div>DKD商品ID</div><div>調査先</div><div>商品状態</div><div></div></div>";
  rakutenTargets.slice(0, 200).forEach(function(x, idx) {
    var providers = (x.provider_keys && x.provider_keys.length ? x.provider_keys : ecMallDefaultProviders).map(ecMallProviderLabel).join(" / ");
    var conditionText = x.include_used ? t("ec_mall_include_used") : t("rakuten_condition_rebuilt") + " / " + t("rakuten_condition_new");
    html += "<div class='rakuten-target-row'>";
    html += "<div class='rakuten-target-check-cell'><input class='ec-target-select' type='checkbox' data-ec-target-select='" + idx + "' aria-label='" + esc(ecMallTargetDisplayName(x)) + "'></div>";
    html += "<div class='rakuten-target-num'>" + esc(x.search_number || "-") + "</div>";
    html += "<div class='rakuten-target-num'>" + esc(x.manufacturer_part_number || "-") + "</div>";
    html += "<div class='rakuten-target-num'>" + esc(x.genuine_part_number || "-") + "</div>";
    html += "<div class='rakuten-target-muted'>" + esc(x.dkd_shohin_id || "-") + "</div>";
    html += "<div class='rakuten-target-muted'>" + esc(providers || "-") + "</div>";
    html += "<div class='rakuten-target-muted'>" + esc(conditionText) + "</div>";
    html += "<div><button class='btn-sm-del rakuten-target-delete' type='button' data-ec-target-delete='" + idx + "'>" + esc(t("btn_delete")) + "</button></div>";
    html += "</div>";
  });
  html += "</div>";
  if (rakutenTargets.length > 200) html += "<div class='rakuten-note' data-dcats-inline-style='s-301647f5065e'>200 件まで表示しています</div>";
  wrap.innerHTML = html;
  updateEcMallTargetSelectionStatus();
}

function getEcMallSelectedTargetIndexes() {
  return Array.prototype.slice.call(document.querySelectorAll(".ec-target-select:checked")).map(function(el) {
    return parseInt(el.getAttribute("data-ec-target-select"), 10);
  }).filter(function(idx, pos, arr) {
    return !isNaN(idx) && idx >= 0 && idx < rakutenTargets.length && arr.indexOf(idx) === pos;
  });
}

function setEcMallTargetVisibleSelection(value) {
  Array.prototype.slice.call(document.querySelectorAll(".ec-target-select")).forEach(function(el) {
    el.checked = !!value;
  });
  updateEcMallTargetSelectionStatus();
}

function updateEcMallTargetSelectionStatus() {
  var selected = getEcMallSelectedTargetIndexes().length;
  var total = rakutenTargets.length;
  var status = document.getElementById("rakuten-target-status");
  if (status) {
    status.textContent = total ? (selected ? tf("ec_target_selection_status", { selected: selected, total: total }) : tf("rakuten_loaded_targets", { n: total })) : "";
  }
  var selectedBtn = document.getElementById("btn-ec-delete-selected-targets");
  if (selectedBtn) selectedBtn.disabled = !selected;
  var allBtn = document.getElementById("btn-ec-delete-all-targets");
  if (allBtn) allBtn.disabled = !total;
  var selectAll = document.querySelector("[data-ec-target-select-all]");
  var visible = Array.prototype.slice.call(document.querySelectorAll(".ec-target-select"));
  if (selectAll) {
    selectAll.checked = !!visible.length && selected === visible.length;
    selectAll.indeterminate = selected > 0 && selected < visible.length;
  }
}

function ecMallTargetDisplayName(target) {
  if (!target) return "-";
  return [
    target.search_number,
    target.manufacturer_part_number,
    target.genuine_part_number,
    target.dkd_shohin_id || target.shohin_cd
  ].filter(Boolean).join(" / ") || "-";
}

async function deleteEcMallTarget(index) {
  index = parseInt(index, 10);
  if (isNaN(index) || index < 0 || index >= rakutenTargets.length) return;
  var target = rakutenTargets[index];
  if (!confirm(tf("ec_target_delete_confirm", { target: ecMallTargetDisplayName(target) }))) return;
  var removed = rakutenTargets.splice(index, 1)[0];
  renderRakutenTargets();
  try {
    var updatePayload = { enabled: false, updated_by: currentUser ? currentUser.id : null };
    var r = null;
    if (removed.id) {
      r = await sb.from("ec_price_research_targets").update(updatePayload).eq("id", removed.id).select("id");
    }
    if (r && r.error) throw new Error(r.error.message);
    if (r && !(r.data || []).length) throw new Error(t("ec_research_no_product_results"));
    setRakutenStatus(t("ec_target_deleted"), false);
    loadEcMallResearchStatus();
  } catch(e) {
    rakutenTargets.splice(Math.min(index, rakutenTargets.length), 0, removed);
    renderRakutenTargets();
    setRakutenStatus(tf("ec_target_delete_failed", { error: e.message || e }), true);
  }
}

async function disableEcMallTargetRows(targets) {
  var ids = (targets || []).map(function(target) {
    return target && target.id ? target.id : null;
  }).filter(Boolean);
  if (!ids.length) return;
  var updatePayload = { enabled: false, updated_by: currentUser ? currentUser.id : null };
  for (var i = 0; i < ids.length; i += 100) {
    var chunk = ids.slice(i, i + 100);
    var r = await sb.from("ec_price_research_targets").update(updatePayload).in("id", chunk).select("id");
    if (r.error) throw new Error(r.error.message);
    if ((r.data || []).length !== chunk.length) throw new Error(t("ec_research_no_product_results"));
  }
}

async function deleteEcMallTargetsByIndexes(indexes, options) {
  options = options || {};
  indexes = (indexes || []).filter(function(idx, pos, arr) {
    return !isNaN(idx) && idx >= 0 && idx < rakutenTargets.length && arr.indexOf(idx) === pos;
  }).sort(function(a, b) { return b - a; });
  if (!indexes.length) {
    setRakutenStatus(t("ec_target_delete_none_selected"), true);
    return;
  }
  if (!confirm(tf(options.all ? "ec_target_delete_all_confirm" : "ec_target_delete_selected_confirm", { n: indexes.length }))) return;
  var removed = [];
  indexes.forEach(function(idx) {
    removed.push({ index: idx, target: rakutenTargets.splice(idx, 1)[0] });
  });
  renderRakutenTargets();
  try {
    await disableEcMallTargetRows(removed.map(function(x) { return x.target; }));
    setRakutenStatus(tf(options.all ? "ec_target_delete_all_done" : "ec_target_delete_selected_done", { n: removed.length }), false);
    loadEcMallResearchStatus();
  } catch(e) {
    removed.sort(function(a, b) { return a.index - b.index; }).forEach(function(item) {
      rakutenTargets.splice(Math.min(item.index, rakutenTargets.length), 0, item.target);
    });
    renderRakutenTargets();
    setRakutenStatus(tf("ec_target_delete_failed", { error: e.message || e }), true);
  }
}

async function deleteSelectedEcMallTargets() {
  await deleteEcMallTargetsByIndexes(getEcMallSelectedTargetIndexes(), { all: false });
}

async function deleteAllEcMallTargets() {
  await deleteEcMallTargetsByIndexes(rakutenTargets.map(function(_, idx) { return idx; }), { all: true });
}

function mergeEcMallTargets(targets) {
  var result = { total: 0, added: 0, updated: 0 };
  (targets || []).forEach(function(target) {
    if (!target || !target.search_number) return;
    result.total++;
    if (mergeEcMallTarget(target)) result.added++;
    else result.updated++;
  });
  return result;
}

function ecMallTargetSameKey(a, b) {
  var ak = (a && (a.target_key || ecMallTargetKey(a))) || "";
  var bk = (b && (b.target_key || ecMallTargetKey(b))) || "";
  if (ak && bk && ak === bk) return true;
  var as = String((a && a.search_number) || "").trim().toUpperCase();
  var bs = String((b && b.search_number) || "").trim().toUpperCase();
  return !!(as && bs && as === bs);
}

function mergeEcMallTarget(target) {
  if (!target || !target.search_number) return false;
  target.provider_keys = getEcMallSelectedProviders();
  target.seller_ids = getEcMallSellerIds();
  target.include_used = getEcMallIncludeUsed();
  target.priority = target.priority || (rakutenTargets.length + 1) * 10;
  target.target_key = target.target_key || ecMallTargetKey(target);
  for (var i=0; i<rakutenTargets.length; i++) {
    if (!ecMallTargetSameKey(rakutenTargets[i], target)) continue;
    var existing = rakutenTargets[i];
    var merged = Object.assign({}, existing, target);
    ["part_id","dkd_shohin_id","shohin_cd","genuine_part_number","genuine_part_number_2","manufacturer_part_number","daiko_part_number","manufacturer","category"].forEach(function(field) {
      if ((merged[field] === null || merged[field] === undefined || merged[field] === "") && existing[field]) merged[field] = existing[field];
    });
    merged.id = existing.id || target.id;
    merged.target_key = existing.target_key || target.target_key || ecMallTargetKey(merged);
    merged.priority = existing.priority || target.priority;
    rakutenTargets[i] = merged;
    return false;
  }
  rakutenTargets.push(target);
  return true;
}

function exactCoreProductMatchForEcTarget(rows, query) {
  rows = rows || [];
  var raw = String(query || "").trim();
  var normalized = normalizePartQuery(raw);
  var rawUpper = raw.toUpperCase();
  for (var i=0; i<rows.length; i++) {
    var row = rows[i] || {};
    if (rawUpper && String(row.dkd_shohin_id || row.shohin_cd || "").toUpperCase() === rawUpper) return row;
    var values = [
      row.manufacturer_part_number,
      row.genuine_part_number,
      row.genuine_part_number_2,
      row.daiko_part_number,
      row.genuine_body_part_number,
      row.manufacturer_body_part_number,
      row.genuine_clutch_part_number,
      row.manufacturer_clutch_part_number
    ];
    for (var j=0; j<values.length; j++) {
      if (normalized && normalizePartQuery(values[j]) === normalized) return row;
    }
  }
  return null;
}

async function resolveEcMallSingleTarget(value) {
  var raw = cleanPartNumberValue(value);
  if (!raw) return null;
  var categoryValue = ecMallNormalizeTargetCategory((document.getElementById("rakuten-target-category") || {}).value || "");
  var lookupValues = [raw, rakutenKeywordPartOnly(raw)].map(cleanPartNumberValue).filter(Boolean);
  lookupValues = Array.from(new Set(lookupValues));
  for (var i=0; i<lookupValues.length; i++) {
    var r = await fetchCoreProductMasterMatches(lookupValues[i], categoryValue || null, 10);
    if (r.error) throw new Error(r.error.message);
    var matched = exactCoreProductMatchForEcTarget(r.data || [], lookupValues[i]);
    if (matched) return rakutenTargetFromPart(matched, "manual");
  }
  var searchNumber = /\s/.test(raw) ? raw : rakutenDenseKeyword(raw, { category: categoryValue });
  var target = {
    part_id: null,
    dkd_shohin_id: null,
    genuine_part_number: "",
    genuine_part_number_2: "",
    manufacturer_part_number: /\s/.test(raw) ? "" : raw,
    daiko_part_number: "",
    manufacturer: "",
    category: categoryValue || "",
    search_number: searchNumber || raw,
    search_number_type: "manual_keyword",
    source_type: "manual",
    provider_keys: getEcMallSelectedProviders(),
    seller_ids: getEcMallSellerIds(),
    include_used: getEcMallIncludeUsed()
  };
  target.target_key = ecMallTargetKey(target);
  return target;
}

async function addEcMallSingleTarget() {
  var input = document.getElementById("ec-mall-single-target-input");
  var value = input ? input.value.trim() : "";
  if (!value) {
    setRakutenStatus(t("ec_single_target_required"), true);
    return;
  }
  var target = await resolveEcMallSingleTarget(value);
  if (!target || !target.search_number) {
    setRakutenStatus(t("ec_single_target_required"), true);
    return;
  }
  var added = mergeEcMallTarget(target);
  renderRakutenTargets();
  var saved = await saveEcMallTargets();
  if (!saved) return;
  if (input) input.value = "";
  setRakutenStatus(tf("ec_single_target_added", { keyword: target.search_number }) + (added ? "" : " / " + t("ec_single_target_updated")) + " / " + tf("ec_targets_saved", { n: rakutenTargets.length }), false);
}

async function loadEcMallSavedTargets() {
  var status = document.getElementById("rakuten-target-status");
  if (status) status.textContent = t("rakuten_loading_master");
  var r = await sb.from("ec_price_research_targets")
    .select("id,target_key,part_id,dkd_shohin_id,shohin_cd,manufacturer,category,daiko_part_number,genuine_part_number,genuine_part_number_2,manufacturer_part_number,search_number,search_number_type,provider_keys,seller_ids,include_used,priority")
    .eq("enabled", true)
    .order("priority", { ascending: true })
    .order("id", { ascending: true })
    .limit(500);
  if (r.error) throw new Error(r.error.message);
  rakutenTargets = (r.data || []).map(ecMallTargetFromDb).filter(function(x) { return x.search_number; });
  if (rakutenTargets[0]) {
    setEcMallSelectedProviders(rakutenTargets[0].provider_keys || ecMallDefaultProviders);
    setEcMallIncludeUsed(!!rakutenTargets[0].include_used);
    setEcMallSellerIds(rakutenTargets[0].seller_ids || []);
    renderEcMallSellerPicker(rakutenLastItems);
  }
  renderRakutenTargets();
}

async function saveEcMallTargets(options) {
  options = options || {};
  if (!rakutenTargets.length) { setRakutenStatus(t("rakuten_targets_empty"), true); return false; }
  var providerKeys = getEcMallSelectedProviders();
  if (!providerKeys.length) { setRakutenStatus(t("ec_mall_providers") + "を選択してください", true); return false; }
  var sellerIds = getEcMallSellerIds();
  setEcMallSellerIds(sellerIds);
  var includeUsed = getEcMallIncludeUsed();
  await normalizeEcMallTargetsForSave(rakutenTargets);
  var payloads = [];
  var payloadByKey = {};
  rakutenTargets.filter(function(target) { return target.search_number; }).forEach(function(target, idx) {
    target.provider_keys = providerKeys;
    target.seller_ids = sellerIds;
    target.include_used = includeUsed;
    target.priority = target.priority || (idx + 1) * 10;
    target.target_key = target.target_key || ecMallTargetKey(target);
    var payload = ecMallTargetPayload(target);
    if (payloadByKey[payload.target_key]) {
      payloadByKey[payload.target_key] = Object.assign(payloadByKey[payload.target_key], payload);
    } else {
      payloadByKey[payload.target_key] = payload;
      payloads.push(payload);
    }
  });
  if (!payloads.length) { setRakutenStatus(t("rakuten_targets_empty"), true); return false; }
  var r = await sb.from("ec_price_research_targets")
    .upsert(payloads, { onConflict: "target_key" })
    .select("id,target_key");
  if (r.error) throw new Error(r.error.message);
  var idMap = {};
  (r.data || []).forEach(function(row) { idMap[row.target_key] = row.id; });
  rakutenTargets.forEach(function(target) {
    var key = target.target_key || ecMallTargetKey(target);
    if (idMap[key]) target.id = idMap[key];
    target.target_key = key;
    target.provider_keys = providerKeys;
    target.seller_ids = sellerIds;
    target.include_used = includeUsed;
  });
  renderRakutenTargets();
  setRakutenStatus(tf(options.conditionsOnly ? "ec_conditions_saved" : "ec_targets_saved", { n: payloads.length }), false);
  loadEcMallResearchStatus();
  return true;
}

function parseUploadedPartList(text) {
  var lines = String(text || "").split(/\r?\n/).map(function(x) { return x.trim(); }).filter(Boolean);
  if (!lines.length) return [];
  var first = parseEcMallDelimitedLine(lines[0]).map(normalizeEcMallUploadHeader);
  var headerNames = ["dkd_shohin_id","dkd商品id","dkd商品コード","shohin_cd","product_id","商品id","商品コード","manufacturer_part_number","メーカー品番","genuine_part_number","純正品番","search_number","keyword","検索キーワード","検索品番","品番","category","カテゴリ","対象カテゴリ"];
  var hasHeader = first.some(function(h) { return headerNames.indexOf(h) >= 0; });
  var selectedCategory = ecMallNormalizeTargetCategory((document.getElementById("rakuten-target-category") || {}).value || "");
  var targets = [];
  for (var i=(hasHeader ? 1 : 0); i<lines.length; i++) {
    var cols = parseEcMallDelimitedLine(lines[i]);
    var row = {};
    if (hasHeader) first.forEach(function(h, idx) { row[h] = cols[idx] || ""; });
    else row.keyword = cols[0] || "";
    var dkd = cleanPartNumberValue(row.dkd_shohin_id || row["dkd商品id"] || row["dkd商品コード"] || "");
    var productCode = cleanPartNumberValue(row.shohin_cd || row.product_id || row["商品id"] || row["商品コード"] || "");
    var mfr = cleanPartNumberValue(row.manufacturer_part_number || row["メーカー品番"] || "");
    var daiko = ecMallIsInternalDaikoPartNumber(mfr) ? mfr : "";
    if (daiko) mfr = "";
    var genuine = cleanPartNumberValue(row.genuine_part_number || row["純正品番"] || "");
    var keyword = cleanPartNumberValue(row.search_number || row.keyword || row["検索キーワード"] || row["検索品番"] || row["品番"] || mfr || genuine || dkd || productCode);
    if (daiko && rakutenPartKey(keyword) === rakutenPartKey(daiko)) keyword = cleanPartNumberValue(genuine || dkd || productCode);
    var category = ecMallNormalizeTargetCategory(ecMallCategoryFromUpload(row.category || row["カテゴリ"] || row["対象カテゴリ"] || "") || selectedCategory);
    if (!keyword) continue;
    var target = {
      part_id: null,
      dkd_shohin_id: dkd || null,
      shohin_cd: productCode || null,
      genuine_part_number: genuine,
      manufacturer_part_number: mfr,
      daiko_part_number: daiko,
      manufacturer: "",
      category: category || "",
      search_number: keyword,
      search_number_type: mfr ? "manufacturer_part_number" : (genuine ? "genuine_part_number" : "uploaded_number"),
      source_type: "upload",
      provider_keys: getEcMallSelectedProviders(),
      seller_ids: getEcMallSellerIds(),
      include_used: getEcMallIncludeUsed()
    };
    target.target_key = ecMallTargetKey(target);
    targets.push(target);
  }
  return targets;
}

function ecMallCategoryFromUpload(value) {
  var text = cleanPartNumberValue(value);
  if (!text) return "";
  var lowered = text.toLowerCase();
  for (var i=0; i<(categoryOptions || []).length; i++) {
    var cat = categoryOptions[i] || {};
    var code = cat.category_code || cat.category || "";
    var labels = [code, cat.label_ja, cat.label_en, cat.label_zh, categoryOptionLabel(cat)];
    for (var j=0; j<labels.length; j++) {
      if (String(labels[j] || "").trim().toLowerCase() === lowered) return ecMallNormalizeTargetCategory(code || text);
    }
  }
  return ecMallNormalizeTargetCategory(text);
}

function ecMallCsvCell(value) {
  var text = String(value == null ? "" : value);
  if (/[",\r\n]/.test(text)) return '"' + text.replace(/"/g, '""') + '"';
  return text;
}

function parseEcMallDelimitedLine(line) {
  var cols = [];
  var cur = "";
  var inQuote = false;
  var text = String(line == null ? "" : line);
  for (var i=0; i<text.length; i++) {
    var ch = text.charAt(i);
    if (ch === '"') {
      if (inQuote && text.charAt(i + 1) === '"') {
        cur += '"';
        i++;
      } else {
        inQuote = !inQuote;
      }
    } else if (!inQuote && (ch === "," || ch === "\t")) {
      cols.push(cur);
      cur = "";
    } else {
      cur += ch;
    }
  }
  cols.push(cur);
  return cols.map(function(x) { return String(x || "").replace(/^\uFEFF/, "").trim(); });
}

function normalizeEcMallUploadHeader(value) {
  return String(value || "").replace(/^\uFEFF/, "").trim().replace(/^"|"$/g, "").toLowerCase();
}

function downloadEcMallUploadTemplate() {
  var rows = [
    ["検索キーワード","メーカー品番","純正品番","カテゴリ"]
  ];
  var csv = rows.map(function(row) {
    return row.map(ecMallCsvCell).join(",");
  }).join("\r\n") + "\r\n";
  var blob = new Blob(["\ufeff" + csv], { type: "text/csv;charset=utf-8" });
  var url = URL.createObjectURL(blob);
  var a = document.createElement("a");
  a.href = url;
  a.download = "ec_price_research_targets_template.csv";
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(function() { URL.revokeObjectURL(url); }, 1000);
  setRakutenStatus(t("ec_upload_template_downloaded"), false);
}

function chooseEcMallResolvedPart(rows, target) {
  rows = rows || [];
  if (!rows.length) return null;
  var explicitDkd = target && target.dkd_shohin_id && /^\d+$/.test(String(target.dkd_shohin_id));
  if (!explicitDkd) {
    var external = rows.find(function(row) { return !ecMallIsInternalDaikoPartRow(row); });
    if (external) return external;
  }
  return rows[0];
}

async function resolveRakutenTarget(target) {
  if (target.part_id) return target;
  var queries = [];
  if (target.dkd_shohin_id && /^\d+$/.test(String(target.dkd_shohin_id))) {
    queries.push({ col: "dkd_shohin_id", val: parseInt(target.dkd_shohin_id, 10) });
    queries.push({ col: "shohin_cd", val: parseInt(target.dkd_shohin_id, 10) });
  }
  if (target.manufacturer_part_number) queries.push({ col: "manufacturer_part_number", val: target.manufacturer_part_number });
  if (target.genuine_part_number) queries.push({ col: "genuine_part_number", val: target.genuine_part_number });
  if (target.search_number) {
    queries.push({ col: "manufacturer_part_number", val: target.search_number });
    queries.push({ col: "genuine_part_number", val: target.search_number });
  }
  for (var i=0; i<queries.length; i++) {
    var q = queries[i];
    var r = await sb.from("parts")
      .select("id, dkd_shohin_id, shohin_cd, genuine_part_number, genuine_part_number_2, manufacturer_part_number, daiko_part_number, manufacturer, category")
      .eq(q.col, q.val)
      .limit(10);
    var row = chooseEcMallResolvedPart(r.data || [], target);
    if (row) {
      var resolved = rakutenTargetFromPart(row, target.source_type || "upload");
      resolved.search_number = target.search_number || resolved.search_number;
      resolved.search_number_type = target.search_number_type || resolved.search_number_type;
      return resolved;
    }
  }
  return target;
}

async function handleRakutenUploadFile() {
  var input = document.getElementById("rakuten-upload-file");
  var file = input && input.files ? input.files[0] : null;
  if (!file) return;
  try {
    setRakutenStatus(t("ec_upload_processing"), false);
    var text = await file.text();
    var parsed = parseUploadedPartList(text);
    if (!parsed.length) {
      setRakutenStatus(t("ec_upload_no_targets"), true);
      return;
    }
    var resolved = [];
    for (var i=0; i<parsed.length; i++) {
      resolved.push(await resolveRakutenTarget(parsed[i]));
    }
    var merged = mergeEcMallTargets(resolved);
    if (!merged.total) {
      setRakutenStatus(t("ec_upload_no_targets"), true);
      return;
    }
    renderRakutenTargets();
    var saved = await saveEcMallTargets();
    if (!saved) return;
    setRakutenStatus(tf("ec_upload_targets_saved", merged), false);
  } catch(e) {
    setRakutenStatus(tf("ec_upload_failed", { error: e.message || e }), true);
  } finally {
    if (input) input.value = "";
  }
}

function chunkArray(arr, size) {
  var chunks = [];
  for (var i=0; i<arr.length; i+=size) chunks.push(arr.slice(i, i + size));
  return chunks;
}

function rakutenTargetDoneKey(target) {
  if (target.id) return "target:" + target.id;
  if (target.part_id) return "part:" + target.part_id;
  if (target.dkd_shohin_id) return "dkd:" + target.dkd_shohin_id;
  return "search:" + String(target.search_number || "").toUpperCase();
}

async function loadRakutenDoneKeys(targets) {
  var done = {};
  try {
    var targetIds = targets.map(function(t) { return t.id; }).filter(Boolean);
    var dkdIdsNew = targets.map(function(t) { return t.dkd_shohin_id; }).filter(Boolean);
    var searchNumbersNew = targets.map(function(t) { return t.search_number; }).filter(Boolean);
    for (var ti=0; ti<chunkArray(targetIds, 500).length; ti++) {
      var targetChunk = chunkArray(targetIds, 500)[ti];
      var rTarget = await sb.from("ec_price_research_results").select("target_id").in("target_id", targetChunk);
      if (rTarget.error) throw new Error(rTarget.error.message);
      (rTarget.data || []).forEach(function(row) { if (row.target_id) done["target:" + row.target_id] = true; });
    }
    for (var di=0; di<chunkArray(dkdIdsNew, 500).length; di++) {
      var dkdChunkNew = chunkArray(dkdIdsNew, 500)[di];
      var rDkdNew = await sb.from("ec_price_research_results").select("dkd_shohin_id").in("dkd_shohin_id", dkdChunkNew);
      if (rDkdNew.error) throw new Error(rDkdNew.error.message);
      (rDkdNew.data || []).forEach(function(row) { if (row.dkd_shohin_id) done["dkd:" + row.dkd_shohin_id] = true; });
    }
    for (var si=0; si<chunkArray(searchNumbersNew, 500).length; si++) {
      var searchChunkNew = chunkArray(searchNumbersNew, 500)[si];
      var rSearchNew = await sb.from("ec_price_research_results").select("search_keyword").in("search_keyword", searchChunkNew);
      if (rSearchNew.error) throw new Error(rSearchNew.error.message);
      (rSearchNew.data || []).forEach(function(row) { if (row.search_keyword) done["search:" + String(row.search_keyword).toUpperCase()] = true; });
    }
    return done;
  } catch(e) {
    console.warn("ec price research done lookup failed, falling back to legacy rakuten table", e);
  }
  var partIds = targets.map(function(t) { return t.part_id; }).filter(Boolean);
  var dkdIds = targets.map(function(t) { return t.dkd_shohin_id; }).filter(Boolean);
  var searchNumbers = targets.map(function(t) { return t.search_number; }).filter(Boolean);
  for (var i=0; i<chunkArray(partIds, 500).length; i++) {
    var partChunk = chunkArray(partIds, 500)[i];
    var rPart = await sb.from("rakuten_price_surveys").select("part_id").in("part_id", partChunk);
    if (rPart.error) throw new Error(rPart.error.message);
    (rPart.data || []).forEach(function(row) { if (row.part_id) done["part:" + row.part_id] = true; });
  }
  for (var j=0; j<chunkArray(dkdIds, 500).length; j++) {
    var dkdChunk = chunkArray(dkdIds, 500)[j];
    var rDkd = await sb.from("rakuten_price_surveys").select("dkd_shohin_id").in("dkd_shohin_id", dkdChunk);
    if (rDkd.error) throw new Error(rDkd.error.message);
    (rDkd.data || []).forEach(function(row) { if (row.dkd_shohin_id) done["dkd:" + row.dkd_shohin_id] = true; });
  }
  for (var k=0; k<chunkArray(searchNumbers, 500).length; k++) {
    var searchChunk = chunkArray(searchNumbers, 500)[k];
    var rSearch = await sb.from("rakuten_price_surveys").select("search_number").in("search_number", searchChunk);
    if (rSearch.error) throw new Error(rSearch.error.message);
    (rSearch.data || []).forEach(function(row) { if (row.search_number) done["search:" + String(row.search_number).toUpperCase()] = true; });
  }
  return done;
}

async function filterRakutenUnsurveyedTargets() {
  if (!rakutenTargets.length) { setRakutenStatus(t("rakuten_targets_empty"), true); return; }
  setRakutenStatus(t("rakuten_loading_master"), false);
  var before = rakutenTargets.length;
  var done = await loadRakutenDoneKeys(rakutenTargets);
  rakutenTargets = rakutenTargets.filter(function(target) { return !done[rakutenTargetDoneKey(target)]; });
  renderRakutenTargets();
  setRakutenStatus(tf("rakuten_unsurveyed_done", { remaining: rakutenTargets.length, skipped: before - rakutenTargets.length }), false);
}

function rakutenUsesServerProxy() {
  return !!(RAKUTEN_USE_EDGE_FUNCTION && sb && sb.functions && typeof sb.functions.invoke === "function");
}

function rakutenCanUseDirectBrowserApi() {
  return false;
}

function rakutenBrowserKeysAvailable() {
  return false;
}

function buildRakutenApiRequest(keyword, ngKeyword, sort, hits, opts) {
  opts = opts || {};
  return {
    provider: opts.provider || "rakuten",
    keyword: keyword || "",
    ngKeyword: ngKeyword || "",
    sort: sort || "",
    hits: hits || "",
    sellerIds: opts.sellerIds || getEcMallSellerIds(),
    availability: opts.availability != null ? opts.availability : "1",
    field: opts.field != null ? opts.field : "1",
    orFlag: opts.orFlag || "",
    minimal: !!opts.minimal
  };
}

async function rakutenInvokeServerProxy(payload) {
  var r = await sb.functions.invoke(RAKUTEN_EDGE_FUNCTION_NAME, { body: payload });
  if (r.error && RAKUTEN_EDGE_FUNCTION_NAME !== "rakuten-search" && (!payload.provider || payload.provider === "rakuten")) {
    console.warn("ec-mall-search failed; falling back to legacy rakuten-search", r.error);
    r = await sb.functions.invoke("rakuten-search", { body: payload });
  }
  if (r.error) {
    var msg = r.error.message || String(r.error);
    try {
      if (r.error.context && typeof r.error.context.json === "function") {
        var errBody = await r.error.context.json();
        msg = (errBody && (errBody.error || errBody.message)) || msg;
      }
    } catch(e) {}
    throw new Error(msg);
  }
  if (r.data && r.data.error) throw new Error(r.data.error);
  return r.data && Object.prototype.hasOwnProperty.call(r.data, "data") ? r.data.data : r.data;
}

async function fetchRakutenApiData(keyword, ngKeyword, sort, hits, opts) {
  var payload = buildRakutenApiRequest(keyword, ngKeyword, sort, hits, opts);
  if (rakutenUsesServerProxy()) {
    return rakutenInvokeServerProxy(payload);
  }
  if (!rakutenCanUseDirectBrowserApi()) {
    throw new Error("rakuten_proxy_unavailable");
  }
  throw new Error("rakuten_proxy_unavailable");
}

function yen(n) {
  if (n == null || isNaN(Number(n))) return "-";
  return "\u00a5" + Number(n).toLocaleString();
}

function getRakutenImage(item) {
  if (item.imageUrl) return item.imageUrl;
  var imgs = item.mediumImageUrls || item.smallImageUrls || [];
  if (!imgs.length) return "";
  var first = imgs[0];
  return typeof first === "string" ? first : (first.imageUrl || "");
}

function normalizeRakutenCondition(item) {
  if (item.productType === "used" || item.condition === "used") return "used";
  if (item.productType === "rebuilt" || item.condition === "rebuilt") return "rebuilt";
  if (item.productType === "new" || item.condition === "new") return "new";
  if (item.productType === "other" || item.condition === "other") return "other";
  var text = [
    item.itemName,
    item.itemCaption,
    item.catchcopy
  ].join(" ");
  if (
    text.indexOf("\u30ea\u30d3\u30eb\u30c8") >= 0 ||
    text.indexOf("\u30ea\u30d3\u30eb\u30c9") >= 0 ||
    text.indexOf("\u518d\u751f") >= 0 ||
    /rebuilt|remanufactured|reman/i.test(text)
  ) return "rebuilt";
  if (text.indexOf("\u65b0\u54c1") >= 0 || text.indexOf("\u672a\u4f7f\u7528") >= 0 || /new/i.test(text)) return "new";
  if (
    text.indexOf("\u4e2d\u53e4") >= 0 ||
    text.indexOf("\u30ea\u30e6\u30fc\u30b9") >= 0 ||
    text.indexOf("\u30ea\u30b5\u30a4\u30af\u30eb") >= 0 ||
    text.indexOf("\u518d\u4f7f\u7528") >= 0 ||
    text.indexOf("\u52d5\u4f5c\u78ba\u8a8d\u6e08") >= 0 ||
    text.indexOf("\u73fe\u72b6") >= 0 ||
    /used|pre[-\s]?owned|second[-\s]?hand/i.test(text)
  ) return "used";
  return "other";
}

function rakutenConditionLabel(condition) {
  if (condition === "used") return t("rakuten_condition_used");
  if (condition === "rebuilt") return t("rakuten_condition_rebuilt");
  if (condition === "new") return t("rakuten_condition_new");
  return t("rakuten_condition_other");
}

function enrichRakutenItems(items) {
  return (items || []).map(function(item) {
    item.providerKey = item.providerKey || item.provider || "rakuten";
    item.mall = item.mall || ecMallProviderLabel(item.providerKey);
    if (item.totalPrice == null && item.itemPrice != null) item.totalPrice = Number(item.itemPrice || 0) + Number(item.shippingPrice || 0);
    item.condition = item.condition || normalizeRakutenCondition(item);
    item.productType = item.productType || item.condition;
    return item;
  });
}

function compactRakutenItemsForDisplay(items) {
  return (items || []).map(function(item) {
    if (!item || typeof item !== "object") return item;
    var compact = Object.assign({}, item);
    delete compact.raw;
    delete compact.raw_payload;
    return compact;
  });
}

function filterEcMallItemsByCondition(items, includeUsed) {
  var enriched = enrichRakutenItems(items);
  if (includeUsed) return enriched;
  return enriched.filter(function(item) {
    return (item.condition || item.productType) !== "used";
  });
}

function rakutenLooseKeyword(keyword) {
  return String(keyword || "").replace(/[-\s_　]/g, "");
}

function rakutenSearchNumbers(keyword, target) {
  target = target || {};
  var values = [target.manufacturer_part_number, target.genuine_part_number, rakutenKeywordPartOnly(keyword), keyword];
  var seen = {};
  return values.map(cleanPartNumberValue).filter(function(v) {
    var key = rakutenPartKey(v);
    if (!key || key.length < 5 || seen[key]) return false;
    seen[key] = true;
    return true;
  });
}

function rakutenKeywordCandidates(keyword, target) {
  target = target || {};
  var candidates = [];
  rakutenSearchNumbers(keyword, target).forEach(function(number) {
    candidates.push(rakutenDenseKeyword(number, target));
    var loose = rakutenLooseKeyword(number);
    if (loose && loose !== number) candidates.push(rakutenDenseKeyword(loose, target));
    if (!rakutenPrimaryCategoryKeyword(target)) candidates.push(number);
  });
  if (!candidates.length) candidates.push(keyword);
  var seen = {};
  return candidates.map(function(v) { return String(v || "").trim(); })
    .filter(function(v) {
      if (!v || seen[v]) return false;
      seen[v] = true;
      return true;
    });
}

function rakutenItemText(item) {
  return [item.itemName, item.itemCaption, item.catchcopy, item.itemCode, item.shopName, item.sellerId].join(" ");
}

function rakutenItemMatchesTarget(item, keyword, target) {
  var text = rakutenItemText(item);
  var compact = rakutenPartKey(text);
  var numbers = rakutenSearchNumbers(keyword, target);
  if (numbers.length) {
    return numbers.some(function(number) { return compact.indexOf(rakutenPartKey(number)) >= 0; });
  }
  var lower = text.toLowerCase();
  var categoryWords = rakutenCategoryKeywords(target && target.category);
  return categoryWords.some(function(word) { return lower.indexOf(String(word).toLowerCase()) >= 0; });
}

function filterRakutenItemsByTarget(items, keyword, target) {
  return enrichRakutenItems(items || []).filter(function(item) {
    return rakutenItemMatchesTarget(item, keyword, target || {});
  });
}

function rakutenMallSearchUrl(keyword, provider) {
  return ecMallSearchUrl(provider || "rakuten", keyword);
}

function sleep(ms) {
  return new Promise(function(resolve) { setTimeout(resolve, ms); });
}

function isRakutenRateLimitError(err) {
  var msg = err && err.message ? err.message : String(err || "");
  return msg.indexOf("429") >= 0 || msg.indexOf("too_many_requests") >= 0;
}

function rakutenFriendlyError(err) {
  var msg = err && err.message ? err.message : String(err || "");
  if (isRakutenRateLimitError(err)) {
    var waitSeconds = Math.max(1, Math.ceil((rakutenApiCooldownUntil - Date.now()) / 1000));
    return tf("rakuten_rate_cooldown", { seconds: waitSeconds });
  }
  if (msg.indexOf("rakuten_proxy_unavailable") >= 0 || msg.indexOf("Failed to send a request") >= 0) {
    return "EC mall server proxy is not available. Deploy the Supabase Edge Function ec-mall-search.";
  }
  if (msg.indexOf("missing_env:RAKUTEN_") >= 0) {
    return "Rakuten API secrets are not set on the Supabase Edge Function.";
  }
  if (msg.indexOf("missing_env:YAHOO_") >= 0) {
    return "Yahoo API secrets are not set on the Supabase Edge Function.";
  }
  if (msg.indexOf("missing_provider") >= 0) {
    return "調査先を1つ以上選択してください。";
  }
  if (msg.indexOf("forbidden") >= 0 || msg.indexOf("profile_lookup_failed") >= 0) {
    return "This account is not allowed to use EC mall price research.";
  }
  if (msg.indexOf("HTTP_REFERRER_NOT_ALLOWED") >= 0) {
    return "HTTP_REFERRER_NOT_ALLOWED: 楽天Web Serviceのアプリ設定で「許可されたWebサイト」に " + location.origin + " を登録してください。";
  }
  if (msg.indexOf("REQUEST_CONTEXT_BODY_HTTP_REFERRER_MISSING") >= 0) {
    return "REQUEST_CONTEXT_BODY_HTTP_REFERRER_MISSING: 楽天APIに呼び出し元サイト情報が届いていません。D-CATSを通常の画面から開き直してください。";
  }
  if (msg.indexOf("Invalid Access Key") >= 0) {
    return "Invalid Access Key: accessKeyが違います。楽天Web Serviceのアプリ設定から新しいアクセスキーを確認してください。";
  }
  if (msg.indexOf("REQUESTED_SCOPES_NOT_ALLOWED") >= 0) {
    return "REQUESTED_SCOPES_NOT_ALLOWED: 楽天Web Serviceのアプリ設定でAPIアクセススコープに楽天市場APIを許可してください。";
  }
  return msg;
}

function openRakutenDiagnosticUrl() {
  testRakutenApiKeys();
}

async function waitForRakutenApiSlot(extraDelayMs) {
  var now = Date.now();
  if (rakutenApiCooldownUntil > now) {
    var waitSeconds = Math.ceil((rakutenApiCooldownUntil - now) / 1000);
    throw new Error("HTTP 429 cooldown " + waitSeconds + "s");
  }
  var minInterval = Math.max(2500, Number(extraDelayMs || 0));
  var elapsed = now - rakutenApiLastRequestAt;
  if (elapsed < minInterval) await sleep(minInterval - elapsed);
  rakutenApiLastRequestAt = Date.now();
}

function setRakutenCooldown(seconds) {
  rakutenApiCooldownUntil = Date.now() + Math.max(1, seconds || 60) * 1000;
}

async function fetchRakutenItemsOnce(keyword, ngKeyword, sort, hits, opts) {
  opts = opts || {};
  await waitForRakutenApiSlot(opts.throttleMs);
  var data = await fetchRakutenApiData(keyword, ngKeyword, sort, hits, opts);
  if (data && data.error) throw new Error(data.error_description || data.error);
  if (data && data.errors) throw new Error(data.errors.errorMessage || JSON.stringify(data.errors));
  return enrichRakutenItems(((data && data.Items) || (data && data.items) || []).map(function(row) {
    return row && row.Item ? row.Item : row;
  }));
}

async function fetchRakutenItems(keyword, ngKeyword, sort, hits, target, config) {
  config = config || {};
  rakutenLastDebug = [];
  var variants = [];
  if (config.bulk) {
    rakutenKeywordCandidates(keyword, target).forEach(function(candidate) {
      variants.push({ keyword: candidate, opts: { field: "0", availability: "0", throttleMs: 3500 } });
    });
  } else {
    rakutenKeywordCandidates(keyword, target).forEach(function(candidate) {
      variants.push({ keyword: candidate, opts: { field: "1", availability: "1", throttleMs: 2500 } });
      variants.push({ keyword: candidate, opts: { field: "0", availability: "1", throttleMs: 2500 } });
      variants.push({ keyword: candidate, opts: { field: "0", availability: "0", throttleMs: 2500 } });
    });
  }
  var providers = config.providers || (target && target.provider_keys && target.provider_keys.length ? target.provider_keys : getEcMallSelectedProviders());
  var sellerIds = config.sellerIds || (target && target.seller_ids && target.seller_ids.length ? target.seller_ids : getEcMallSellerIds());
  providers = providers.filter(function(provider) { return ecMallDefaultProviders.indexOf(provider) >= 0; });
  if (!providers.length) throw new Error("missing_provider");
  var allItems = [];
  var seenItems = {};
  var lastErr = null;
  for (var p=0; p<providers.length; p++) {
    var providerKey = providers[p];
    var providerFound = false;
    var tried = {};
    for (var i=0; i<variants.length; i++) {
      var v = variants[i];
      var tryKey = providerKey + "|" + v.keyword + "|" + v.opts.field + "|" + v.opts.availability;
      if (!v.keyword || tried[tryKey]) continue;
      tried[tryKey] = true;
      try {
        var opts = Object.assign({}, v.opts, { provider: providerKey, sellerIds: sellerIds });
        var rawItems = await fetchRakutenItemsOnce(v.keyword, ngKeyword, sort, hits, opts);
        var items = filterRakutenItemsByTarget(rawItems, keyword, target);
        rakutenLastDebug.push({ provider: providerKey, keyword: v.keyword, field: v.opts.field, availability: v.opts.availability, count: items.length, rawCount: rawItems.length });
        items.forEach(function(item) {
          var key = [item.providerKey || providerKey, item.itemUrl, item.sellerId, item.itemName, item.itemPrice].join("|");
          if (seenItems[key]) return;
          seenItems[key] = true;
          allItems.push(item);
        });
        if (items.length > 0) {
          providerFound = true;
          break;
        }
      } catch(e) {
        rakutenLastDebug.push({ provider: providerKey, keyword: v.keyword, field: v.opts.field, availability: v.opts.availability, count: 0, error: e.message || String(e) });
        lastErr = e;
        if (isRakutenRateLimitError(e)) { setRakutenCooldown(60); throw e; }
        if ((e.message || "").indexOf("not found") >= 0) continue;
        if ((e.message || "").indexOf("missing_env:") >= 0 && providerKey === "rakuten") continue;
      }
    }
    if (!providerFound && config.bulk) continue;
  }
  if (!allItems.length && lastErr && providers.length === 1) throw lastErr;
  return enrichRakutenItems(allItems);
}

async function validateRakutenApiConnection() {
  var providers = getEcMallSelectedProviders();
  if (!providers.length) throw new Error("missing_provider");
  return fetchRakutenItemsOnce("福袋", "", "", "", { minimal: providers[0] === "rakuten", provider: providers[0], throttleMs: 500 });
}

async function testRakutenApiKeys() {
  if (rakutenCanUseDirectBrowserApi() && !rakutenUsesServerProxy() && !rakutenBrowserKeysAvailable()) {
    setRakutenStatus(t("rakuten_missing_key"), true);
    return;
  }
  setRakutenStatus(t("rakuten_searching"), false);
  try {
    var items = await validateRakutenApiConnection();
    setRakutenStatus(t("rakuten_test_ok") + " (" + items.length + "件)", false);
  } catch(e) {
    setRakutenStatus(t("rakuten_test_failed") + ": " + rakutenFriendlyError(e), true);
  }
}

function summarizeRakutenPrices(items) {
  var prices = (items || []).map(function(item) { return Number(ecMallItemTotalPrice(item) || item.itemPrice || 0); }).filter(function(v) { return v > 0; });
  if (!prices.length) return { count: (items || []).length, min: null, avg: null, max: null };
  return {
    count: (items || []).length,
    min: Math.min.apply(Math, prices),
    avg: Math.round(prices.reduce(function(a,b) { return a + b; }, 0) / prices.length),
    max: Math.max.apply(Math, prices)
  };
}

function rakutenConditionSummaries(items) {
  var groups = { used: [], rebuilt: [], new: [], other: [] };
  enrichRakutenItems(items).forEach(function(item) {
    groups[item.condition || "other"].push(item);
  });
  return ["used", "rebuilt", "new", "other"].map(function(key) {
    var summary = summarizeRakutenPrices(groups[key]);
    summary.condition = key;
    return summary;
  }).filter(function(summary) { return summary.count > 0; });
}

function rakutenConditionSummaryMap(items) {
  var map = { used: { count: 0, min: null, avg: null, max: null }, rebuilt: { count: 0, min: null, avg: null, max: null }, new: { count: 0, min: null, avg: null, max: null }, other: { count: 0, min: null, avg: null, max: null } };
  rakutenConditionSummaries(items).forEach(function(summary) {
    map[summary.condition] = summary;
  });
  return map;
}

function ecMallItemTotalPrice(item) {
  if (item.totalPrice != null && !isNaN(Number(item.totalPrice))) return Number(item.totalPrice);
  if (item.itemPrice == null || isNaN(Number(item.itemPrice))) return null;
  return Number(item.itemPrice) + Number(item.shippingPrice || 0);
}

