function ecMallRawPayload(item) {
  if (!item || typeof item !== "object") return {};
  if (item.raw_payload && typeof item.raw_payload === "object") return item.raw_payload;
  if (item.raw && typeof item.raw === "object") return item.raw;
  return {};
}

function ecMallDirectValue(obj, path) {
  var cur = obj;
  for (var i=0; i<path.length; i++) {
    if (!cur || typeof cur !== "object") return "";
    cur = cur[path[i]];
  }
  return cur == null ? "" : cur;
}

function ecMallSellerIdFromItem(item) {
  item = item || {};
  var raw = ecMallRawPayload(item);
  var values = [
    item.sellerId, item.shopCode, item.seller_id, item.storeId, item.store_id,
    ecMallDirectValue(item, ["seller", "userId"]),
    ecMallDirectValue(item, ["seller", "sellerId"]),
    ecMallDirectValue(item, ["seller", "id"]),
    raw.sellerId, raw.shopCode, raw.seller_id, raw.storeId, raw.store_id,
    ecMallDirectValue(raw, ["seller", "userId"]),
    ecMallDirectValue(raw, ["seller", "sellerId"]),
    ecMallDirectValue(raw, ["seller", "id"])
  ];
  for (var i=0; i<values.length; i++) {
    var v = String(values[i] || "").trim();
    if (v) return v;
  }
  return "";
}

function ecMallLooksLikeOpaqueSellerId(value) {
  var text = String(value || "").trim();
  return /^[A-Za-z0-9_-]{20,}$/.test(text) && /[A-Za-z]/.test(text) && /\d/.test(text);
}

function ecMallLooksLikeOnlyMask(value) {
  return /^[*＊・.\s]+$/.test(String(value || "").trim());
}

function ecMallLooksLikeMaskedSellerName(value) {
  return /[*＊]{3,}/.test(String(value || "").trim());
}

function ecMallLooksLikeBrokenSellerName(value) {
  var text = String(value || "").trim();
  if (!text) return true;
  return ecMallLooksLikeOpaqueSellerId(text) || ecMallLooksLikeOnlyMask(text) || ecMallLooksLikeMaskedSellerName(text) || text.indexOf("???") >= 0 || text.indexOf("\uFFFD") >= 0;
}

function ecMallCleanSellerNameCandidate(value) {
  var text = String(value || "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
  if (!text || text.length > 80) return "";
  return text;
}

function ecMallPushSellerNameCandidate(list, value, id) {
  var text = ecMallCleanSellerNameCandidate(value);
  if (!text) return;
  if (id && text === id) return;
  if (ecMallLooksLikeBrokenSellerName(text)) return;
  if (/^https?:\/\//i.test(text)) return;
  if (/^(?:auction|auc_store|store|seller|user|unknown|-|null)$/i.test(text)) return;
  if (/^\d+(?:\.\d+)?%?$/.test(text)) return;
  var key = text.toLowerCase();
  for (var i=0; i<list.length; i++) {
    if (String(list[i]).toLowerCase() === key) return;
  }
  list.push(text);
}

function ecMallCollectSellerNameCandidatesFromObject(obj, list, id, depth, inSellerContext) {
  if (!obj || typeof obj !== "object" || depth > 5 || list.length >= 8) return;
  Object.keys(obj).forEach(function(key) {
    if (list.length >= 8) return;
    var value = obj[key];
    var keyText = String(key || "");
    var sellerContext = inSellerContext || /(seller|shop|store|merchant|vendor)/i.test(keyText);
    if (typeof value === "string") {
      var nameKey = /(name|display|nick|nickname|title|company|shop|store|seller)/i.test(keyText);
      if (sellerContext && nameKey) ecMallPushSellerNameCandidate(list, value, id);
      return;
    }
    if (value && typeof value === "object") {
      ecMallCollectSellerNameCandidatesFromObject(value, list, id, depth + 1, sellerContext);
    }
  });
}

function ecMallSellerNameCandidates(item) {
  item = item || {};
  var id = ecMallSellerIdFromItem(item);
  var list = [];
  [
    ecMallKnownSellerName(item),
    item.shopName, item.sellerName, item.storeName, item.seller_name, item.shop_name, item.store_name,
    item.displayName, item.sellerDisplayName,
    ecMallDirectValue(item, ["seller", "displayName"]),
    ecMallDirectValue(item, ["seller", "name"]),
    ecMallDirectValue(item, ["shop", "name"]),
    ecMallDirectValue(item, ["shop", "shopName"]),
    ecMallDirectValue(item, ["store", "name"]),
    ecMallDirectValue(item, ["store", "storeName"])
  ].forEach(function(value) {
    ecMallPushSellerNameCandidate(list, value, id);
  });
  ecMallCollectSellerNameCandidatesFromObject(ecMallRawPayload(item), list, id, 0, false);
  return list;
}

function ecMallProviderKeyFromItem(item) {
  item = item || {};
  var provider = String(item.providerKey || item.provider_key || item.provider || "").trim();
  if (provider) return provider;
  var url = String(item.itemUrl || item.item_url || "").toLowerCase();
  return url.indexOf("auctions.yahoo.co.jp") >= 0 ? "yahoo_auction" : "";
}

function ecMallObservedMaskedSellerName(item) {
  item = item || {};
  var raw = ecMallRawPayload(item);
  var values = [
    item.shopName, item.sellerName, item.storeName, item.seller_name, item.shop_name, item.store_name,
    ecMallDirectValue(item, ["seller", "displayName"]),
    ecMallDirectValue(item, ["seller", "name"]),
    raw.shopName, raw.sellerName, raw.storeName, raw.seller_name, raw.shop_name, raw.store_name,
    ecMallDirectValue(raw, ["seller", "displayName"]),
    ecMallDirectValue(raw, ["seller", "name"]),
    ecMallDirectValue(raw, ["sellerNameReview", "observedName"])
  ];
  for (var i=0; i<values.length; i++) {
    var text = ecMallCleanSellerNameCandidate(values[i]);
    if (ecMallLooksLikeMaskedSellerName(text)) return text;
  }
  return "";
}

function ecMallIndexResolvedSellerNames(items) {
  (items || []).forEach(function(item) {
    if (ecMallProviderKeyFromItem(item) !== "yahoo_auction") return;
    var id = ecMallSellerIdFromItem(item);
    if (!id) return;
    var raw = ecMallRawPayload(item);
    var names = [];
    [
      item.shopName, item.sellerName, item.storeName, item.seller_name, item.shop_name, item.store_name,
      ecMallDirectValue(item, ["seller", "displayName"]),
      ecMallDirectValue(item, ["seller", "name"]),
      raw.shopName, raw.sellerName, raw.storeName, raw.seller_name, raw.shop_name, raw.store_name,
      ecMallDirectValue(raw, ["seller", "displayName"]),
      ecMallDirectValue(raw, ["seller", "name"])
    ].forEach(function(value) {
      ecMallPushSellerNameCandidate(names, value, id);
    });
    if (names[0]) ecMallResolvedSellerNames[id] = names[0];
  });
}

function ecMallKnownSellerName(item) {
  var id = ecMallSellerIdFromItem(item);
  return ecMallResolvedSellerNames[id] || EC_MALL_KNOWN_YAHOO_AUCTION_SELLERS[id] || "";
}

function ecMallSellerKey(item) {
  var id = ecMallSellerIdFromItem(item).toLowerCase();
  var name = String(ecMallSellerNameCandidates(item)[0] || "").trim().toLowerCase();
  var compactName = name.replace(/[ \t\r\n\u3000]/g, "");
  if (
    compactName.indexOf("自動車パーツの宝箱sol") >= 0 ||
    compactName.indexOf("エスオーエル") >= 0 ||
    compactName.indexOf("sol補修パーツ館") >= 0 ||
    ["solltd", "s-o-l", "fj5nes99sc8hdj1phpkroqdww62ug", "cywc2j57dbqjcnescuthj1eqczrbg", "7krn5ajlxpj99m5xd1bnffyowzgpn"].indexOf(id) >= 0
  ) return "name:sol";
  if (name) return (item.providerKey || "mall") + ":name:" + name;
  if (id) return (item.providerKey || "mall") + ":" + id;
  return (item.providerKey || "mall") + ":" + (item.itemUrl || item.itemName || "");
}

function ecMallSellerDisplayName(item) {
  item = item || {};
  var id = ecMallSellerIdFromItem(item);
  var candidate = ecMallSellerNameCandidates(item)[0] || "";
  if (candidate) return candidate;
  var maskedName = ecMallObservedMaskedSellerName(item);
  if (maskedName) return maskedName;
  if (id && !ecMallLooksLikeOpaqueSellerId(id)) return id;
  var provider = ecMallProviderKeyFromItem(item);
  if (provider === "yahoo_auction") return "ヤフオク出品者";
  if (provider === "yahoo_shopping") return "Yahooショッピング出品者";
  return id || item.shopCode || "-";
}

function ecMallSellerNeedsReview(item) {
  if (ecMallProviderKeyFromItem(item) !== "yahoo_auction") return false;
  var id = ecMallSellerIdFromItem(item);
  if (!id || ecMallKnownSellerName(item)) return false;
  return ecMallSellerNameCandidates(item).length === 0;
}

function ecMallSellerProfileUrl(item) {
  if (ecMallProviderKeyFromItem(item) !== "yahoo_auction") return "";
  var id = ecMallSellerIdFromItem(item);
  return id ? "https://auctions.yahoo.co.jp/seller/" + encodeURIComponent(id) + "?user_type=c" : "";
}

function ecMallSellerReviewSuffixHtml(item) {
  return "";
}

function renderEcMallSellerReviewPanel(rows) {
  return "";
}

function ecMallItemRuleText(item) {
  var raw = item && item.raw && typeof item.raw === "object" ? item.raw : {};
  return [
    item && item.itemName,
    item && item.itemCaption,
    item && item.catchcopy,
    raw.detailText
  ].join("\n").toLowerCase();
}

function ecMallIsComponentOnlyItem(item) {
  var text = ecMallItemRuleText(item || {});
  var compact = text.replace(/[\s　・･_\-]/g, "");
  return (
    /ブラシ\s*(assy|ａｓｓｙ)?|ブラシassy|ブラシＡＳＳＹ|ブラシホルダー|カーボンブラシ|brush\s*(assy|assembly|holder)/i.test(text) ||
    /マグネット\s*スイッチ|magnet\s*switch|solenoid\s*switch/i.test(text) ||
    /レギュレータ|レギュレーター|regulator|プーリー|pulley|ベアリング|bearing|リペアキット|repair\s*kit|オーバーホール\s*キット|overhaul\s*kit/i.test(text) ||
    /内部部品|補修用部品|補修専用部品|交換部品|単品販売|部品単品/.test(text) ||
    compact.indexOf("マグネットスイッチ") >= 0 ||
    compact.indexOf("補修専用部品") >= 0 ||
    compact.indexOf("補修用部品") >= 0
  );
}

function ecMallBest3Rows(items, includeUsed) {
  var rows = [];
  var conditions = includeUsed ? ["used", "rebuilt", "new"] : ["rebuilt", "new"];
  conditions.forEach(function(condition) {
    var bySeller = {};
    enrichRakutenItems(items).forEach(function(item) {
      if ((item.condition || item.productType) !== condition) return;
      var total = ecMallItemTotalPrice(item);
      if (total == null || total <= 0) return;
      if (ecMallIsComponentOnlyItem(item)) return;
      var key = ecMallSellerKey(item);
      if (!bySeller[key] || total < ecMallItemTotalPrice(bySeller[key])) bySeller[key] = item;
    });
    Object.keys(bySeller).map(function(key) { return bySeller[key]; })
      .sort(function(a, b) { return ecMallItemTotalPrice(a) - ecMallItemTotalPrice(b); })
      .slice(0, 3)
      .forEach(function(item, index) {
        rows.push({ product_type: condition, rank_no: index + 1, item: item });
      });
  });
  return rows;
}

function renderEcMallBest3Html(items, includeUsed) {
  ecMallIndexResolvedSellerNames(items);
  var conditions = includeUsed ? ["used", "rebuilt", "new"] : ["rebuilt", "new"];
  var rows = ecMallBest3Rows(items, includeUsed);
  if (!rows.length) return "";
  var html = "<div class='ec-best3'>";
  conditions.forEach(function(condition) {
    var conditionRows = rows.filter(function(row) { return row.product_type === condition; });
    html += "<div class='ec-best3-card'>";
    html += "<div class='ec-best3-title'>" + esc(tf("ec_best3_title", { type: rakutenConditionLabel(condition) })) + "</div>";
    if (!conditionRows.length) {
      html += "<div class='rakuten-note'>-</div>";
    } else {
      conditionRows.forEach(function(row) {
        var item = row.item;
        var seller = ecMallSellerDisplayName(item);
        html += "<div class='ec-best3-row'>";
        html += "<div>#" + row.rank_no + "</div>";
        html += "<div><div class='mgmt-pn'>" + esc(seller) + ecMallSellerReviewSuffixHtml(item) + "</div><div class='mgmt-sub'><span class='ec-provider-badge'>" + esc(ecMallProviderLabel(item.providerKey || item.provider)) + "</span></div></div>";
        html += "<div class='price-value'>" + yen(ecMallItemTotalPrice(item)) + "</div>";
        html += "</div>";
      });
    }
    html += "</div>";
  });
  html += "</div>";
  return html;
}

async function ensureEcMallTarget(target, keyword) {
  target = target || {};
  target.search_number = target.search_number || keyword;
  target.search_number_type = target.search_number_type || "manual_keyword";
  target.provider_keys = target.provider_keys && target.provider_keys.length ? target.provider_keys : getEcMallSelectedProviders();
  target.seller_ids = target.seller_ids && target.seller_ids.length ? target.seller_ids : getEcMallSellerIds();
  target.include_used = target.include_used == null ? getEcMallIncludeUsed() : !!target.include_used;
  target.target_key = target.target_key || ecMallTargetKey(target);
  await normalizeEcMallTargetsForSave([target]);
  var payload = ecMallTargetPayload(target);
  if (!payload.search_number || !payload.target_key) return target;
  var r = await sb.from("ec_price_research_targets")
    .upsert(payload, { onConflict: "target_key" })
    .select("id,target_key")
    .single();
  if (r.error) throw new Error(r.error.message);
  target.id = r.data.id;
  target.target_key = r.data.target_key;
  return target;
}

async function saveRakutenSurveyLegacy(target, items, keyword, ngKeyword, sort) {
  target = target || {};
  items = enrichRakutenItems(items);
  var summary = summarizeRakutenPrices(items);
  var payload = {
    part_id: target.part_id || null,
    dkd_shohin_id: target.dkd_shohin_id || null,
    genuine_part_number: target.genuine_part_number || null,
    manufacturer_part_number: target.manufacturer_part_number || null,
    manufacturer: target.manufacturer || null,
    category: ecMallNormalizeTargetCategory(target.category) || null,
    search_number: keyword,
    search_number_type: target.search_number_type || null,
    source_type: target.source_type || "manual",
    result_count: summary.count,
    min_price_jpy: summary.min,
    avg_price_jpy: summary.avg,
    max_price_jpy: summary.max,
    ng_keyword: ngKeyword || null,
    sort_order: sort || null,
    items: items || [],
    searched_by: currentUser ? currentUser.id : null,
    searched_at: new Date().toISOString()
  };
  var r = await sb.from("rakuten_price_surveys").insert(payload).select("id").single();
  if (r.error) throw new Error(r.error.message);
  return r.data;
}

async function saveRakutenSurvey(target, items, keyword, ngKeyword, sort) {
  target = target || {};
  items = enrichRakutenItems(items);
  var now = new Date().toISOString();
  try {
    target = await ensureEcMallTarget(target, keyword);
    var includeUsed = target.include_used == null ? getEcMallIncludeUsed() : !!target.include_used;
    var bestRows = ecMallBest3Rows(items, includeUsed);
    var runPayload = {
      triggered_by: target.source_type === "master" || target.source_type === "upload" || target.source_type === "saved" ? "manual_bulk" : "manual",
      status: "running",
      requested_by: currentUser ? currentUser.id : null,
      started_at: now,
      target_count: 1,
      settings: {
        keyword: keyword,
        ngKeyword: ngKeyword || null,
        sort: sort || null,
        providers: target.provider_keys || getEcMallSelectedProviders(),
        seller_ids: target.seller_ids || getEcMallSellerIds(),
        include_used: includeUsed
      }
    };
    var runR = await sb.from("ec_price_research_runs").insert(runPayload).select("id").single();
    if (runR.error) throw new Error(runR.error.message);
    var runId = runR.data.id;
    if (bestRows.length) {
      var resultPayloads = bestRows.map(function(row) {
        var item = row.item;
        return {
          run_id: runId,
          target_id: target.id || null,
          dkd_shohin_id: target.dkd_shohin_id || null,
          part_id: target.part_id || null,
          search_keyword: keyword,
          provider_key: item.providerKey || item.provider || "rakuten",
          product_type: row.product_type,
          rank_no: row.rank_no,
          seller_id: ecMallSellerIdFromItem(item) || null,
          seller_name: ecMallSellerDisplayName(item) === "-" ? null : ecMallSellerDisplayName(item),
          item_name: item.itemName || null,
          item_url: item.itemUrl || null,
          image_url: getRakutenImage(item) || null,
          price_jpy: item.itemPrice == null ? null : Number(item.itemPrice),
          shipping_jpy: item.shippingPrice == null ? null : Number(item.shippingPrice),
          total_price_jpy: ecMallItemTotalPrice(item),
          match_rank: item.matchRank || null,
          source_method: item.sourceMethod || "api",
          raw_payload: item.raw || item,
          surveyed_at: now
        };
      });
      var resultR = await sb.from("ec_price_research_results").insert(resultPayloads);
      if (resultR.error) throw new Error(resultR.error.message);
    }
    await sb.from("ec_price_research_runs").update({
      status: bestRows.length ? "completed" : "skipped",
      finished_at: new Date().toISOString(),
      success_count: bestRows.length ? 1 : 0,
      skipped_count: bestRows.length ? 0 : 1
    }).eq("id", runId);
    if (target.id) {
      await sb.from("ec_price_research_targets").update({
        last_run_at: now,
        last_success_at: bestRows.length ? now : null,
        last_status: bestRows.length ? "completed" : "skipped",
        last_error: bestRows.length ? null : "no_rankable_items",
        updated_by: currentUser ? currentUser.id : null
      }).eq("id", target.id);
    }
    return { id: runId, bestRows: bestRows };
  } catch(e) {
    console.warn("ec price research save failed; falling back to legacy rakuten_price_surveys", e);
    return saveRakutenSurveyLegacy(target, items, keyword, ngKeyword, sort);
  }
}

async function searchRakutenPrices() {
  if (rakutenApiBusy) return;
  var cooldownMs = rakutenApiCooldownUntil - Date.now();
  if (cooldownMs > 0) {
    setRakutenStatus(tf("rakuten_rate_wait", { seconds: Math.ceil(cooldownMs / 1000) }), true);
    return;
  }
  var searchBtn = document.getElementById("btn-rakuten-search");
  rakutenApiBusy = true;
  if (searchBtn) searchBtn.disabled = true;
  var keyword = document.getElementById("rakuten-keyword").value.trim();
  var ngKeyword = document.getElementById("rakuten-ng-keyword").value.trim();
  var sort = document.getElementById("rakuten-sort").value;
  var hits = document.getElementById("rakuten-hits").value;
  var providers = getEcMallSelectedProviders();
  var sellerIds = getEcMallSellerIds();
  setEcMallSellerIds(sellerIds);
  var includeUsed = getEcMallIncludeUsed();

  if (!keyword) {
    setRakutenStatus(t("rakuten_missing_keyword"), true);
    rakutenApiBusy = false;
    if (searchBtn) searchBtn.disabled = false;
    return;
  }
  if (!providers.length) {
    setRakutenStatus(t("ec_mall_providers") + "を選択してください", true);
    rakutenApiBusy = false;
    if (searchBtn) searchBtn.disabled = false;
    return;
  }
  rakutenActiveTarget = rakutenActiveTarget || { search_number: keyword, search_number_type: "manual_keyword", source_type: "manual" };
  rakutenActiveTarget.provider_keys = providers;
  rakutenActiveTarget.seller_ids = sellerIds;
  rakutenActiveTarget.include_used = includeUsed;
  if (rakutenCanUseDirectBrowserApi() && !rakutenUsesServerProxy() && !rakutenBrowserKeysAvailable()) {
    setRakutenStatus(t("rakuten_missing_key"), true);
    rakutenApiBusy = false;
    if (searchBtn) searchBtn.disabled = false;
    return;
  }
  setRakutenStatus(t("rakuten_searching"), false);
  document.getElementById("rakuten-results").innerHTML = "<div class='loading'>" + t("loading") + "</div>";
  document.getElementById("rakuten-summary").innerHTML = "";

  try {
    rakutenLastItems = filterEcMallItemsByCondition(
      await fetchRakutenItems(keyword, ngKeyword, sort, hits, rakutenActiveTarget, { providers: providers, sellerIds: sellerIds }),
      includeUsed
    );
    await saveRakutenSurvey(rakutenActiveTarget, rakutenLastItems, keyword, ngKeyword, sort);
    rakutenLastItems = compactRakutenItemsForDisplay(rakutenLastItems);
    renderRakutenResults(rakutenLastItems, keyword);
    setRakutenStatus(t("rakuten_saved_result"), false);
  } catch(e) {
    if (isRakutenRateLimitError(e)) setRakutenCooldown(60);
    document.getElementById("rakuten-results").innerHTML = "<div class='empty'>" + t("rakuten_error") + ": " + esc(rakutenFriendlyError(e)) + "</div>";
    setRakutenStatus(t("rakuten_error"), true);
  } finally {
    rakutenApiBusy = false;
    if (searchBtn) searchBtn.disabled = false;
  }
}

async function runRakutenBulkSurvey() {
  if (rakutenApiBusy) return;
  if (!rakutenTargets.length) { setRakutenStatus(t("rakuten_targets_empty"), true); return; }
  var ngKeyword = document.getElementById("rakuten-ng-keyword").value.trim();
  var sort = document.getElementById("rakuten-sort").value;
  var hits = document.getElementById("rakuten-hits").value;
  var providers = getEcMallSelectedProviders();
  var sellerIds = getEcMallSellerIds();
  setEcMallSellerIds(sellerIds);
  var includeUsed = getEcMallIncludeUsed();
  if (!providers.length) { setRakutenStatus(t("ec_mall_providers") + "を選択してください", true); return; }
  if (rakutenCanUseDirectBrowserApi() && !rakutenUsesServerProxy() && !rakutenBrowserKeysAvailable()) { setRakutenStatus(t("rakuten_missing_key"), true); return; }
  rakutenApiBusy = true;
  try {
    try {
      var cooldownMs = rakutenApiCooldownUntil - Date.now();
      if (cooldownMs > 0) {
        setRakutenStatus(tf("rakuten_rate_wait", { seconds: Math.ceil(cooldownMs / 1000) }), true);
        return;
      }
      setRakutenStatus(t("rakuten_searching"), false);
      await validateRakutenApiConnection();
    } catch(e) {
      setRakutenStatus(tf("rakuten_bulk_preflight_failed", { error: rakutenFriendlyError(e) }), true);
      return;
    }
    var saved = 0;
    var failed = 0;
    var firstError = "";
    var stoppedByRateLimit = false;
    var rateLimitRemaining = 0;
    for (var i=0; i<rakutenTargets.length; i++) {
      var target = rakutenTargets[i];
      if (!target.search_number) continue;
      target.provider_keys = providers;
      target.seller_ids = sellerIds.length ? sellerIds : (target.seller_ids || []);
      target.include_used = includeUsed;
      setRakutenStatus(tf("rakuten_bulk_running", { done: i + 1, total: rakutenTargets.length }), false);
      try {
        var items = filterEcMallItemsByCondition(
          await fetchRakutenItems(target.search_number, ngKeyword, sort, hits, target, { bulk: true, providers: target.provider_keys, sellerIds: target.seller_ids }),
          includeUsed
        );
        await saveRakutenSurvey(target, items, target.search_number, ngKeyword, sort);
        saved++;
        if (i === 0) {
          rakutenLastItems = compactRakutenItemsForDisplay(items);
          renderRakutenResults(rakutenLastItems, target.search_number);
        }
      } catch(e) {
        console.warn("rakuten bulk item failed", target.search_number, e);
        if (isRakutenRateLimitError(e)) {
          firstError = target.search_number + ": " + rakutenFriendlyError(e);
          setRakutenCooldown(60);
          stoppedByRateLimit = true;
          rakutenTargets = rakutenTargets.slice(i);
          rateLimitRemaining = rakutenTargets.length;
          renderRakutenTargets();
          break;
        }
        failed++;
        if (!firstError) firstError = target.search_number + ": " + rakutenFriendlyError(e);
      }
    }
    if (stoppedByRateLimit) setRakutenStatus(tf("rakuten_bulk_rate_limited", { saved: saved, remaining: rateLimitRemaining, error: firstError }), true);
    else if (failed) setRakutenStatus(tf("rakuten_bulk_failed", { saved: saved, failed: failed, error: firstError }), true);
    else setRakutenStatus(tf("rakuten_bulk_done", { n: saved }), false);
    loadRakutenPriceList();
  } finally {
    rakutenApiBusy = false;
  }
}

function renderRakutenResults(items, keyword, options) {
  options = options || {};
  var resultEl = document.getElementById("rakuten-results");
  var summaryEl = document.getElementById("rakuten-summary");
  rakutenLastResultKeyword = keyword || rakutenLastResultKeyword || "";
  if (!options.preserveLimit) rakutenVisibleResultCount = EC_MALL_RESULT_INITIAL_RENDER;
  ecMallIndexResolvedSellerNames(items || []);
  renderEcMallSellerPicker(items || []);
  if (!items || items.length === 0) {
    summaryEl.innerHTML = "";
    var debugRows = rakutenLastDebug.map(function(row) {
      var label = esc(ecMallProviderLabel(row.provider)) + " / " + esc(row.keyword) + " / field=" + esc(row.field) + " / availability=" + esc(row.availability) + " / " + esc(row.error || (row.count + "件"));
      return "<li>" + label + " <a href='" + esc(rakutenMallSearchUrl(row.keyword, row.provider)) + "' target='_blank' rel='noopener'>" + t("rakuten_open_mall_search") + "</a></li>";
    }).join("");
    resultEl.innerHTML =
      "<div class='rakuten-debug'><strong>" + t("rakuten_no_results") + "</strong><br>" +
      esc(t("rakuten_no_results_debug")) +
      (debugRows ? "<div data-dcats-inline-style='s-301647f5065e'><strong>" + t("rakuten_tried_keywords") + "</strong><ul data-dcats-inline-style='s-c4f7723a6395'>" + debugRows + "</ul></div>" : "") +
      "</div>";
    return;
  }
  var prices = items.map(function(item) { return Number(ecMallItemTotalPrice(item) || item.itemPrice || 0); }).filter(function(v) { return v > 0; });
  var min = prices.length ? Math.min.apply(Math, prices) : null;
  var max = prices.length ? Math.max.apply(Math, prices) : null;
  var avg = prices.length ? prices.reduce(function(a,b) { return a + b; }, 0) / prices.length : null;
  var conditionHtml = rakutenConditionSummaries(items).map(function(s) {
    return "<div class='rakuten-stat'><div class='rakuten-stat-label'>" + esc(rakutenConditionLabel(s.condition)) + " / " + t("rakuten_count") + " " + s.count + "</div><div class='rakuten-stat-value'>" + yen(s.min) + "</div><div class='rakuten-note'>" + t("rakuten_avg") + " " + yen(s.avg) + " / " + t("rakuten_max") + " " + yen(s.max) + "</div></div>";
  }).join("");
  summaryEl.innerHTML =
    "<div class='rakuten-stat'><div class='rakuten-stat-label'>" + t("rakuten_count") + "</div><div class='rakuten-stat-value'>" + items.length + "</div></div>" +
    "<div class='rakuten-stat'><div class='rakuten-stat-label'>" + t("rakuten_min") + "</div><div class='rakuten-stat-value'>" + yen(min) + "</div></div>" +
    "<div class='rakuten-stat'><div class='rakuten-stat-label'>" + t("rakuten_avg") + "</div><div class='rakuten-stat-value'>" + yen(avg == null ? null : Math.round(avg)) + "</div></div>" +
    "<div class='rakuten-stat'><div class='rakuten-stat-label'>" + t("rakuten_max") + "</div><div class='rakuten-stat-value'>" + yen(max) + "</div></div>" +
    conditionHtml;

  var displayItems = enrichRakutenItems(items);
  var visibleItems = displayItems.slice(0, Math.max(EC_MALL_RESULT_INITIAL_RENDER, rakutenVisibleResultCount));
  var html = renderEcMallBest3Html(displayItems, getEcMallIncludeUsed()) + "<div class='rakuten-results'>";
  visibleItems.forEach(function(item) {
    var img = getRakutenImage(item);
    var meta = [];
    meta.push(ecMallProviderLabel(item.providerKey || item.provider));
    meta.push(rakutenConditionLabel(item.condition));
    var sellerDisplay = ecMallSellerDisplayName(item);
    if (sellerDisplay && sellerDisplay !== "-") meta.push("出品者 " + sellerDisplay);
    if (item.postageFlag != null) meta.push(item.postageFlag === 0 ? "送料込" : "送料別");
    if (item.taxFlag != null) meta.push(item.taxFlag === 0 ? "税込" : "税別");
    if (item.reviewCount != null) meta.push("レビュー " + item.reviewCount);
    html += "<div class='rakuten-item'>";
    img = safeHttpsUrl(img);
    html += "<div class='rakuten-thumb'>" + (img ? "<img src='" + esc(img) + "' loading='lazy' decoding='async' fetchpriority='low' width='72' height='72'>" : "No image") + "</div>";
    html += "<div>";
    html += "<div class='rakuten-item-name'>" + esc(item.itemName || "-") + "</div>";
    html += "<div class='rakuten-item-shop'>" + esc(sellerDisplay || item.shopName || "-") + ecMallSellerReviewSuffixHtml(item) + "</div>";
    html += "<div class='rakuten-item-price'>" + yen(ecMallItemTotalPrice(item) || item.itemPrice) + "</div>";
    html += "<div class='rakuten-item-meta'>" + meta.map(esc).join("<span>/</span>") + "</div>";
    var itemUrl = safeHttpsUrl(item.itemUrl, ["rakuten.co.jp", "shopping.yahoo.co.jp", "yahoo.co.jp", "auctions.yahoo.co.jp"]);
    if (itemUrl) html += "<a class='rakuten-item-link' href='" + esc(itemUrl) + "' target='_blank' rel='noopener'>" + t("rakuten_open") + "</a>";
    html += "</div></div>";
  });
  if (visibleItems.length < displayItems.length) {
    html += "<div class='rakuten-result-more'><button class='btn-load-more' type='button' data-rakuten-result-more='1'>" +
      esc(tf("rakuten_result_more", { n: displayItems.length - visibleItems.length })) + "</button></div>";
  }
  html += "</div>";
  resultEl.innerHTML = html;
}

function showMoreRakutenResults() {
  rakutenVisibleResultCount += EC_MALL_RESULT_RENDER_STEP;
  renderRakutenResults(rakutenLastItems, rakutenLastResultKeyword, { preserveLimit: true });
}

function clearEcMallPriceListInitialState() {
  ecPriceListRenderToken += 1;
  ecPriceHistoryGroupMap = {};
  var countEl = document.getElementById("rakuten-list-count");
  var list = document.getElementById("rakuten-list");
  if (countEl) countEl.textContent = "";
  if (list) {
    list.className = "ec-mall-grouped-list";
    list.innerHTML = "";
  }
}

async function enterRakutenPriceList() {
  if (!canViewPriceResearchHistory()) { alert(t("err_perm")); return; }
  showScreen("rakuten-price-list");
  var nameEl = document.getElementById("rakuten-price-list-username");
  if (nameEl && userProfile) nameEl.textContent = userProfile.name || userProfile.email.split("@")[0];
  var manageBtn = document.getElementById("btn-rakuten-list-to-search");
  if (manageBtn) setCspStyle(manageBtn, "display", canUseRakutenResearch() ? "" : "none");
  clearEcMallPriceListInitialState();
}

function ecPriceListGroupKey(row) {
  row = row || {};
  if (row.target_id) return "target:" + row.target_id;
  if (row.dkd_shohin_id) return "dkd:" + row.dkd_shohin_id;
  return "search:" + String(row.search_number || row.manufacturer_part_number || row.genuine_part_number || "");
}

function ecPriceListSearchMatches(value, rawQuery, normalizedQuery, compactQuery) {
  if (value === null || value === undefined || value === "") return false;
  var text = normalizeAsciiWidth(String(value)).toLowerCase();
  if (rawQuery && text.indexOf(rawQuery) >= 0) return true;
  if (compactQuery && normalizedContains(value, compactQuery)) return true;
  return !!(normalizedQuery && normalizePartQuery(value).indexOf(normalizedQuery) >= 0);
}

function ecPriceListRowMatchesSearch(row, q) {
  q = normalizeAsciiWidth(String(q || "")).trim();
  if (!q) return true;
  var rawQuery = q.toLowerCase();
  var normalizedQuery = normalizePartQuery(q);
  var compactQuery = norm(q);
  var values = [
    row.dkd_shohin_id,
    row.shohin_cd,
    row.search_number,
    row.genuine_part_number,
    row.genuine_part_number_2,
    row.manufacturer_part_number,
    row.daiko_part_number,
    row.manufacturer,
    row.category,
    row.seller_id,
    row.seller_name,
    ecMallSellerDisplayName(row),
    row.item_name,
    row.source_type,
    row.provider_key ? ecMallProviderLabel(row.provider_key) : ""
  ];
  return values.some(function(value) {
    return ecPriceListSearchMatches(value, rawQuery, normalizedQuery, compactQuery);
  });
}

function ecPriceListRowMatchesSellerFilter(row, sellerQ) {
  sellerQ = normalizeAsciiWidth(String(sellerQ || "")).trim();
  if (!sellerQ) return true;
  row = row || {};
  var rawQuery = sellerQ.toLowerCase();
  var normalizedQuery = normalizePartQuery(sellerQ);
  var compactQuery = norm(sellerQ);
  var values = [
    row.seller_id,
    row.seller_name,
    ecMallSellerIdFromItem(row),
    ecMallSellerDisplayName(row),
    row.shopName,
    row.shop_name,
    row.storeName,
    row.store_name,
    row.item_url,
    row.itemUrl
  ];
  ecMallSellerNameCandidates(row).forEach(function(name) {
    values.push(name);
  });
  return values.some(function(value) {
    return ecPriceListSearchMatches(value, rawQuery, normalizedQuery, compactQuery);
  });
}

function ecPriceListLegacyItems(row) {
  var items = row && row.items;
  if (Array.isArray(items)) return items;
  if (typeof items === "string" && items.trim()) {
    try {
      var parsed = JSON.parse(items);
      return Array.isArray(parsed) ? parsed : [];
    } catch(e) {
      return [];
    }
  }
  return [];
}

function ecPriceListLegacyRowMatchesSellerFilter(row, sellerQ) {
  sellerQ = normalizeAsciiWidth(String(sellerQ || "")).trim();
  if (!sellerQ) return true;
  if (ecPriceListRowMatchesSellerFilter(row, sellerQ)) return true;
  return ecPriceListLegacyItems(row).some(function(item) {
    return ecPriceListRowMatchesSellerFilter(item, sellerQ);
  });
}

function filterEcPriceResearchRowsForList(rows, q, sellerQ) {
  q = normalizeAsciiWidth(String(q || "")).trim();
  sellerQ = normalizeAsciiWidth(String(sellerQ || "")).trim();
  if (!q && !sellerQ) return rows || [];
  var groups = {};
  (rows || []).forEach(function(row) {
    var key = ecPriceListGroupKey(row);
    if (!groups[key]) groups[key] = [];
    groups[key].push(row);
  });
  var out = [];
  Object.keys(groups).forEach(function(key) {
    var groupRows = groups[key];
    if (q && !groupRows.some(function(row) { return ecPriceListRowMatchesSearch(row, q); })) {
      return;
    }
    if (sellerQ) {
      groupRows = groupRows.filter(function(row) {
        return ecPriceListRowMatchesSellerFilter(row, sellerQ);
      });
    }
    if (groupRows.length) {
      out = out.concat(groupRows);
    }
  });
  return out;
}

function filterRakutenLegacyRowsForList(rows, q, sellerQ) {
  q = normalizeAsciiWidth(String(q || "")).trim();
  sellerQ = normalizeAsciiWidth(String(sellerQ || "")).trim();
  if (!q && !sellerQ) return rows || [];
  return (rows || []).filter(function(row) {
    return (!q || ecPriceListRowMatchesSearch(row, q)) &&
      (!sellerQ || ecPriceListLegacyRowMatchesSellerFilter(row, sellerQ));
  });
}

function ecMallSelectColumnsWithoutRawPayload(selectColumns) {
  return String(selectColumns || "").split(",").map(function(col) {
    return col.trim();
  }).filter(function(col) {
    return col && col !== "raw_payload";
  }).join(",");
}

async function fetchEcPriceListRows(tableName, selectColumns, orderColumn, maxRows) {
  var rows = [];
  var limit = Math.max(1, parseInt(maxRows || EC_PRICE_LIST_DEFAULT_LIMIT, 10) || EC_PRICE_LIST_DEFAULT_LIMIT);
  var pageSize = Math.min(EC_PRICE_LIST_PAGE_SIZE, limit);
  for (var from = 0; from < limit; from += pageSize) {
    var to = Math.min(from + pageSize, limit) - 1;
    var r = await sb.from(tableName)
      .select(selectColumns)
      .order(orderColumn, { ascending: false })
      .range(from, to);
    if (r.error) {
      var fallbackColumns = selectColumns.indexOf("raw_payload") >= 0 ? ecMallSelectColumnsWithoutRawPayload(selectColumns) : "";
      if (fallbackColumns) {
        console.warn("raw_payload select failed; retrying without raw_payload", r.error);
        return fetchEcPriceListRows(tableName, fallbackColumns, orderColumn, maxRows);
      }
      return r;
    }
    var page = r.data || [];
    rows = rows.concat(page);
    if (page.length < (to - from + 1)) break;
  }
  return { data: rows, error: null };
}

async function loadRakutenPriceList() {
  var q = (document.getElementById("rakuten-list-search") || {}).value || "";
  q = normalizeAsciiWidth(q).trim();
  var sellerQ = (document.getElementById("rakuten-list-seller-filter") || {}).value || "";
  sellerQ = normalizeAsciiWidth(sellerQ).trim();
  var hasFilter = !!(q || sellerQ);
  ecPriceListRenderToken += 1;
  if (!hasFilter) {
    clearEcMallPriceListInitialState();
    return;
  }
  try {
    ecMallFallbackToLegacySurveys = false;
    var r = await fetchEcPriceListRows(
      "ec_price_research_latest_best3",
      "id,run_id,target_id,dkd_shohin_id,shohin_cd,manufacturer,category,daiko_part_number,genuine_part_number,genuine_part_number_2,manufacturer_part_number,search_number,provider_key,product_type,rank_no,seller_id,seller_name,item_name,item_url,price_jpy,shipping_jpy,total_price_jpy,source_method,surveyed_at",
      "surveyed_at",
      hasFilter ? EC_PRICE_LIST_SEARCH_SCAN_LIMIT : EC_PRICE_LIST_DEFAULT_LIMIT
    );
    if (r.error) throw new Error(r.error.message);
    ecMallIndexResolvedSellerNames(r.data || []);
    renderEcMallPriceList(filterEcPriceResearchRowsForList(r.data || [], q, sellerQ));
  } catch(e) {
    console.warn("ec price research list failed; falling back to legacy rakuten list", e);
    ecMallFallbackToLegacySurveys = true;
    var legacyR = await fetchEcPriceListRows(
      "rakuten_price_surveys",
      "id,part_id,dkd_shohin_id,genuine_part_number,manufacturer_part_number,manufacturer,category,search_number,source_type,result_count,min_price_jpy,avg_price_jpy,max_price_jpy,items,searched_at",
      "searched_at",
      hasFilter ? EC_PRICE_LIST_SEARCH_SCAN_LIMIT : 200
    );
    renderRakutenPriceList(filterRakutenLegacyRowsForList(legacyR.data || [], q, sellerQ));
  }
}

function ecPriceHistoryColor(type, provider) {
  var colors = {
    "rebuilt|rakuten": "#d63384",
    "rebuilt|yahoo_shopping": "#9f2f7f",
    "rebuilt|yahoo_auction": "#f472b6",
    "new|rakuten": "#1a6fd4",
    "new|yahoo_shopping": "#0f9f9a",
    "new|yahoo_auction": "#7c3aed",
    "used|rakuten": "#6b7280",
    "used|yahoo_shopping": "#92400e",
    "used|yahoo_auction": "#475467"
  };
  return colors[String(type || "other") + "|" + String(provider || "")] || colors[String(type || "other") + "|rakuten"] || "#667085";
}

function ecPriceHistoryProviderSort(provider) {
  return { rakuten: 1, yahoo_shopping: 2, yahoo_auction: 3 }[provider] || 9;
}

function ecPriceHistorySeriesLabel(series) {
  return ecMallProductTypeLabel(series.type) + " / " + ecMallProviderLabel(series.providerKey);
}

function ecPriceHistoryPointPrice(row) {
  var price = parsePriceNumber(row.total_price_jpy);
  if (price === null) price = parsePriceNumber(row.price_jpy);
  return price !== null && price > 0 ? price : null;
}

function ecPriceHistoryPreparedPoints(rows) {
  var points = [];
  (rows || []).forEach(function(row) {
    var type = row.product_type || "other";
    if (["rebuilt", "new", "used"].indexOf(type) < 0) return;
    var providerKey = row.provider_key || "unknown";
    var ts = new Date(row.surveyed_at || 0).getTime();
    var price = ecPriceHistoryPointPrice(row);
    if (!ts || isNaN(ts) || price === null) return;
    points.push({ row: row, type: type, providerKey: providerKey, ts: ts, price: price });
  });
  return points;
}

function ecPriceHistoryFilterPointsByRange(points, rangeDays) {
  points = points || [];
  if (!points.length) return [];
  if (rangeDays && rangeDays !== "all") {
    var days = parseInt(rangeDays, 10);
    if (!isNaN(days) && days > 0) {
      var maxTs = Math.max.apply(null, points.map(function(p) { return p.ts; }));
      var minAllowed = maxTs - days * 24 * 60 * 60 * 1000;
      points = points.filter(function(p) { return p.ts >= minAllowed; });
    }
  }
  return points;
}

function filterEcPriceHistoryRowsByRange(rows, rangeDays) {
  return ecPriceHistoryFilterPointsByRange(ecPriceHistoryPreparedPoints(rows), rangeDays).map(function(p) { return p.row; });
}

function ecPriceHistoryGroupTitle(group) {
  var r = (group && group.meta) || group || {};
  return String(r.search_number || r.manufacturer_part_number || r.genuine_part_number || r.dkd_shohin_id || r.shohin_cd || "-");
}

function ecPriceHistoryGroupMeta(group, rows) {
  var r = (group && group.meta) || group || {};
  var parts = [];
  if (r.dkd_shohin_id || r.shohin_cd) parts.push("DKD商品ID " + (r.dkd_shohin_id || r.shohin_cd));
  if (r.manufacturer_part_number) parts.push(r.manufacturer_part_number);
  if (r.genuine_part_number) parts.push(r.genuine_part_number);
  if (r.manufacturer) parts.push(r.manufacturer);
  if (rows && rows.length) parts.push(tf("ec_price_history_rows", { n: rows.length }));
  return parts.filter(Boolean).join(" / ");
}

async function fetchEcPriceHistoryRowsForGroup(group) {
  var r = (group && group.meta) || group || {};
  var cols = "id,run_id,target_id,dkd_shohin_id,search_keyword,provider_key,product_type,rank_no,seller_id,seller_name,item_name,item_url,price_jpy,shipping_jpy,total_price_jpy,surveyed_at";
  function buildQuery(selectColumns) {
    var query = sb.from("ec_price_research_results")
      .select(selectColumns)
      .order("surveyed_at", { ascending: true })
      .limit(5000);
    if (r.dkd_shohin_id) {
      query = query.eq("dkd_shohin_id", parseInt(r.dkd_shohin_id, 10));
    } else if (r.target_id) {
      query = query.eq("target_id", r.target_id);
    } else if (r.search_number) {
      query = query.eq("search_keyword", r.search_number);
    } else if (r.manufacturer_part_number) {
      query = query.eq("search_keyword", r.manufacturer_part_number);
    } else if (r.genuine_part_number) {
      query = query.eq("search_keyword", r.genuine_part_number);
    } else {
      return null;
    }
    return query;
  }
  var query = buildQuery(cols);
  if (!query) return [];
  var res = await query;
  if (res.error) throw new Error(res.error.message);
  return res.data || [];
}

function buildEcPriceHistorySeries(rows, rangeDays) {
  var typed = ecPriceHistoryFilterPointsByRange(ecPriceHistoryPreparedPoints(rows), rangeDays);
  if (!typed.length) return [];
  var bucket = {};
  typed.forEach(function(p) {
    var key = p.type + "|" + p.providerKey + "|" + p.ts;
    if (!bucket[key] || p.price < bucket[key].price) bucket[key] = p;
  });
  var groups = {};
  Object.keys(bucket).forEach(function(key) {
    var p = bucket[key];
    var groupKey = p.type + "|" + p.providerKey;
    if (!groups[groupKey]) groups[groupKey] = { type: p.type, providerKey: p.providerKey, points: [] };
    groups[groupKey].points.push(p);
  });
  return Object.keys(groups).map(function(key) {
    groups[key].points.sort(function(a, b) { return a.ts - b.ts; });
    return groups[key];
  }).sort(function(a, b) {
    var typeDiff = ecMallProductTypeSort(a.type) - ecMallProductTypeSort(b.type);
    if (typeDiff) return typeDiff;
    return ecPriceHistoryProviderSort(a.providerKey) - ecPriceHistoryProviderSort(b.providerKey);
  });
}

function ecPriceHistoryNiceMax(maxPrice) {
  maxPrice = Math.max(1000, Number(maxPrice || 0));
  var rough = maxPrice * 1.12;
  var pow = Math.pow(10, Math.max(0, Math.floor(Math.log10(rough)) - 1));
  return Math.ceil(rough / pow) * pow;
}

function ecPriceHistoryAxisDate(ts, compact) {
  var d = new Date(ts);
  if (compact) return (d.getMonth() + 1) + "/" + d.getDate();
  return d.getFullYear() + "/" + (d.getMonth() + 1) + "/" + d.getDate();
}

function ecPriceHistoryStepPath(points, xScale, yScale, left, right) {
  if (!points.length) return "";
  if (points.length === 1) {
    var x = xScale(points[0].ts);
    var y = yScale(points[0].price);
    return "M " + Math.max(left, x - 10).toFixed(1) + " " + y.toFixed(1) + " L " + Math.min(right, x + 10).toFixed(1) + " " + y.toFixed(1);
  }
  var d = "M " + xScale(points[0].ts).toFixed(1) + " " + yScale(points[0].price).toFixed(1);
  for (var i = 1; i < points.length; i++) {
    var xNext = xScale(points[i].ts);
    var yPrev = yScale(points[i - 1].price);
    var yNext = yScale(points[i].price);
    d += " L " + xNext.toFixed(1) + " " + yPrev.toFixed(1) + " L " + xNext.toFixed(1) + " " + yNext.toFixed(1);
  }
  return d;
}

function renderEcPriceHistorySvg(series) {
  var allPoints = [];
  series.forEach(function(s) { allPoints = allPoints.concat(s.points); });
  if (!allPoints.length) return "";
  var viewportW = window.innerWidth || 0;
  var wideChart = viewportW >= 1440;
  var mediumChart = viewportW >= 900;
  var width = wideChart ? 1720 : (mediumChart ? 1360 : 980);
  var height = wideChart ? 680 : (mediumChart ? 580 : 460);
  var left = wideChart ? 136 : (mediumChart ? 124 : 98);
  var right = wideChart ? 44 : 34, top = 34, bottom = 82;
  var plotW = width - left - right;
  var plotH = height - top - bottom;
  var minTs = Math.min.apply(null, allPoints.map(function(p) { return p.ts; }));
  var maxTs = Math.max.apply(null, allPoints.map(function(p) { return p.ts; }));
  if (minTs === maxTs) {
    minTs -= 12 * 60 * 60 * 1000;
    maxTs += 12 * 60 * 60 * 1000;
  }
  var maxPrice = Math.max.apply(null, allPoints.map(function(p) { return p.price; }));
  var yMax = ecPriceHistoryNiceMax(maxPrice);
  function xScale(ts) { return left + ((ts - minTs) / (maxTs - minTs)) * plotW; }
  function yScale(price) { return top + plotH - (price / yMax) * plotH; }
  var svg = "<svg class='ec-price-history-chart' viewBox='0 0 " + width + " " + height + "' role='img' aria-label='price history chart'>";
  var yTickCount = 5;
  for (var yi = 0; yi <= yTickCount; yi++) {
    var val = Math.round((yMax / yTickCount) * yi);
    var y = yScale(val);
    svg += "<line class='ec-price-history-grid' x1='" + left + "' y1='" + y.toFixed(1) + "' x2='" + (width - right) + "' y2='" + y.toFixed(1) + "'/>";
    svg += "<text class='ec-price-history-axis' x='" + (left - 12) + "' y='" + (y + 5).toFixed(1) + "' text-anchor='end'>" + esc(yen(val)) + "</text>";
  }
  var xTickCount = 5;
  for (var xi = 0; xi <= xTickCount; xi++) {
    var ts = minTs + ((maxTs - minTs) / xTickCount) * xi;
    var x = xScale(ts);
    svg += "<line class='ec-price-history-grid' x1='" + x.toFixed(1) + "' y1='" + top + "' x2='" + x.toFixed(1) + "' y2='" + (height - bottom) + "'/>";
    svg += "<text class='ec-price-history-axis' x='" + x.toFixed(1) + "' y='" + (height - 26) + "' text-anchor='middle'>" + esc(ecPriceHistoryAxisDate(ts, xi > 0 && xi < xTickCount)) + "</text>";
  }
  svg += "<line class='ec-price-history-axis-line' x1='" + left + "' y1='" + (height - bottom) + "' x2='" + (width - right) + "' y2='" + (height - bottom) + "'/>";
  svg += "<line class='ec-price-history-axis-line' x1='" + left + "' y1='" + top + "' x2='" + left + "' y2='" + (height - bottom) + "'/>";
  series.forEach(function(s) {
    var color = ecPriceHistoryColor(s.type, s.providerKey);
    var path = ecPriceHistoryStepPath(s.points, xScale, yScale, left, width - right);
    svg += "<path class='ec-price-history-line' d='" + path + "' stroke='" + color + "'/>";
    s.points.forEach(function(p) {
      svg += "<circle class='ec-price-history-point' cx='" + xScale(p.ts).toFixed(1) + "' cy='" + yScale(p.price).toFixed(1) + "' r='4.2' fill='" + color + "'/>";
    });
  });
  svg += "</svg>";
  return svg;
}

function renderEcPriceHistoryLegend(series) {
  var legend = document.getElementById("ec-price-history-legend");
  if (!legend) return;
  if (!series.length) {
    legend.innerHTML = "";
    return;
  }
  legend.innerHTML = series.map(function(s) {
    return "<span class='ec-price-history-legend-item'><span class='ec-price-history-dot " + ecPriceHistoryColorClass(s.type, s.providerKey) + "'></span>" + esc(ecPriceHistorySeriesLabel(s)) + "</span>";
  }).join("");
}

function renderEcPriceHistorySummary(series) {
  if (!series.length) return "";
  var html = "<div class='ec-price-history-summary'>";
  series.forEach(function(s) {
    var latest = s.points[s.points.length - 1];
    var lowest = s.points.slice().sort(function(a, b) { return a.price - b.price; })[0];
    html += "<div class='ec-price-history-stat'>";
    html += "<div class='ec-price-history-stat-label'>" + esc(ecPriceHistorySeriesLabel(s)) + "</div>";
    html += "<div class='ec-price-history-stat-value'>" + esc(yen(latest.price)) + "</div>";
    html += "<div class='ec-price-history-stat-sub'>" + esc(t("ec_price_history_latest") + " " + formatDateTime(latest.row.surveyed_at)) + "</div>";
    html += "<div class='ec-price-history-stat-sub'>" + esc(t("ec_price_history_lowest") + " " + yen(lowest.price) + " / " + formatDateTime(lowest.row.surveyed_at)) + "</div>";
    html += "</div>";
  });
  html += "</div>";
  return html;
}

function renderEcPriceHistoryRecentTable(rows) {
  var usable = (rows || []).filter(function(row) { return ecPriceHistoryPointPrice(row) !== null; })
    .sort(function(a, b) { return new Date(b.surveyed_at || 0) - new Date(a.surveyed_at || 0); })
    .slice(0, 30);
  if (!usable.length) return "";
  var html = "<div class='ec-price-history-table'><table><tr><th>" + esc(t("rakuten_latest")) + "</th><th>" + esc(t("ec_mall_condition_filters")) + "</th><th>" + esc(t("ec_price_history_seller")) + "</th><th>" + esc(t("ec_price_history_rank_price")) + "</th></tr>";
  usable.forEach(function(row) {
    var seller = ecMallSellerDisplayName(row);
    var url = safeHttpsUrl(row.item_url, ["rakuten.co.jp", "shopping.yahoo.co.jp", "yahoo.co.jp", "auctions.yahoo.co.jp"]);
    var sellerHtml = url ? "<a href='" + esc(url) + "' target='_blank' rel='noopener'>" + esc(seller) + "</a>" : esc(seller);
    var rank = parseInt(row.rank_no || 0, 10);
    var rankLabel = rank > 0 ? "#" + rank + " " : "";
    html += "<tr><td>" + esc(formatDateTime(row.surveyed_at)) + "</td>";
    html += "<td>" + esc(ecMallProductTypeLabel(row.product_type)) + " <span class='ec-provider-badge'>" + esc(ecMallProviderLabel(row.provider_key)) + "</span></td>";
    html += "<td>" + sellerHtml + ecMallSellerReviewSuffixHtml(row) + "</td>";
    html += "<td><div class='price-value'>" + esc(rankLabel + yen(ecPriceHistoryPointPrice(row))) + "</div></td></tr>";
  });
  html += "</table></div>";
  return html;
}

function renderEcPriceHistorySellerRanking(rows) {
  var points = ecPriceHistoryPreparedPoints(rows);
  if (!points.length) return "";
  var groups = {};
  points.forEach(function(p) {
    var row = p.row || {};
    var seller = String(ecMallSellerDisplayName(row)).trim() || "-";
    var sellerKey = String(row.seller_id || seller).trim().toLowerCase();
    var key = p.providerKey + "|" + p.type + "|" + sellerKey;
    if (!groups[key]) {
      groups[key] = { seller: seller, providerKey: p.providerKey, type: p.type, lowest: p, latest: p, count: 0 };
    }
    groups[key].count++;
    if (p.price < groups[key].lowest.price) groups[key].lowest = p;
    if (p.ts > groups[key].latest.ts) groups[key].latest = p;
  });
  var ranked = Object.keys(groups).map(function(key) { return groups[key]; })
    .sort(function(a, b) {
      var priceDiff = a.lowest.price - b.lowest.price;
      if (priceDiff) return priceDiff;
      var typeDiff = ecMallProductTypeSort(a.type) - ecMallProductTypeSort(b.type);
      if (typeDiff) return typeDiff;
      return ecPriceHistoryProviderSort(a.providerKey) - ecPriceHistoryProviderSort(b.providerKey);
    })
    .slice(0, 20);
  if (!ranked.length) return "";
  var html = "<div class='ec-price-history-table seller-ranking'><table><tr><th class='rank-cell'>#</th><th>" + esc(t("ec_price_history_seller")) + "</th><th>" + esc(t("ec_mall_providers")) + "</th><th>" + esc(t("ec_mall_condition_filters")) + "</th><th>" + esc(t("ec_price_history_lowest")) + "</th><th>" + esc(t("ec_price_history_latest_price")) + "</th><th>" + esc(t("ec_price_history_count")) + "</th><th>" + esc(t("ec_price_history_last_surveyed")) + "</th></tr>";
  ranked.forEach(function(group, index) {
    var url = safeHttpsUrl((group.lowest.row || {}).item_url, ["rakuten.co.jp", "shopping.yahoo.co.jp", "yahoo.co.jp", "auctions.yahoo.co.jp"]);
    var sellerHtml = url ? "<a href='" + esc(url) + "' target='_blank' rel='noopener'>" + esc(group.seller) + "</a>" : esc(group.seller);
    html += "<tr>";
    html += "<td class='rank-cell'>" + (index + 1) + "</td>";
    html += "<td>" + sellerHtml + ecMallSellerReviewSuffixHtml((group.latest || {}).row) + "</td>";
    html += "<td><span class='ec-provider-badge'>" + esc(ecMallProviderLabel(group.providerKey)) + "</span></td>";
    html += "<td>" + esc(ecMallProductTypeLabel(group.type)) + "</td>";
    html += "<td class='price-cell'><div class='price-value'>" + esc(yen(group.lowest.price)) + "</div></td>";
    html += "<td class='price-cell'><div class='price-value'>" + esc(yen(group.latest.price)) + "</div></td>";
    html += "<td>" + esc(String(group.count)) + "</td>";
    html += "<td>" + esc(formatDateTime((group.latest.row || {}).surveyed_at)) + "</td>";
    html += "</tr>";
  });
  html += "</table></div>";
  return html;
}

function updateEcPriceHistoryRangeButtons() {
  var range = ecPriceHistoryState ? ecPriceHistoryState.rangeDays : "all";
  document.querySelectorAll("#ec-price-history-range [data-ec-history-range]").forEach(function(btn) {
    btn.classList.toggle("active", String(btn.dataset.ecHistoryRange || "") === String(range || "all"));
  });
}

function renderEcPriceHistoryContent() {
  var body = document.getElementById("ec-price-history-body");
  var title = document.getElementById("ec-price-history-title");
  var meta = document.getElementById("ec-price-history-meta");
  if (!body || !ecPriceHistoryState) return;
  var rows = ecPriceHistoryState.rows || [];
  ecMallIndexResolvedSellerNames(rows);
  var group = ecPriceHistoryState.group || {};
  var rangeDays = ecPriceHistoryState.rangeDays || "all";
  var rowsForRange = filterEcPriceHistoryRowsByRange(rows, rangeDays);
  if (title) title.textContent = t("ec_price_history_title") + " - " + ecPriceHistoryGroupTitle(group);
  if (meta) meta.textContent = ecPriceHistoryGroupMeta(group, rows);
  var series = buildEcPriceHistorySeries(rowsForRange, "all");
  renderEcPriceHistoryLegend(series);
  updateEcPriceHistoryRangeButtons();
  if (!series.length) {
    body.innerHTML = "<div class='empty'>" + esc(t("ec_price_history_no_data")) + "</div>";
    return;
  }
  body.innerHTML = renderEcPriceHistorySummary(series) +
    "<div class='ec-price-history-chart-wrap'>" + renderEcPriceHistorySvg(series) + "</div>" +
    "<div class='price-section-title' data-dcats-inline-style='s-0ee7f66ad9c0'>" + esc(t("ec_price_history_seller_ranking")) + "</div>" +
    renderEcPriceHistorySellerRanking(rowsForRange) +
    "<div class='price-section-title' data-dcats-inline-style='s-0ee7f66ad9c0'>" + esc(t("ec_price_history_recent")) + "</div>" +
    renderEcPriceHistoryRecentTable(rowsForRange);
}

function closeEcPriceHistoryOverlay() {
  var overlay = document.getElementById("ec-price-history-overlay");
  if (overlay) overlay.classList.remove("show");
}

async function openEcPriceHistoryForGroup(group) {
  if (!canViewPriceResearchHistory()) { alert(t("err_perm")); return; }
  var overlay = document.getElementById("ec-price-history-overlay");
  var body = document.getElementById("ec-price-history-body");
  var title = document.getElementById("ec-price-history-title");
  var meta = document.getElementById("ec-price-history-meta");
  if (!overlay || !body) return;
  ecPriceHistoryState = { group: group, rows: [], rangeDays: "all" };
  if (title) title.textContent = t("ec_price_history_title") + " - " + ecPriceHistoryGroupTitle(group);
  if (meta) meta.textContent = ecPriceHistoryGroupMeta(group, []);
  body.innerHTML = "<div class='loading'>" + esc(t("ec_price_history_loading")) + "</div>";
  renderEcPriceHistoryLegend([]);
  updateEcPriceHistoryRangeButtons();
  overlay.classList.add("show");
  try {
    var rows = await fetchEcPriceHistoryRowsForGroup(group);
    if (!ecPriceHistoryState || ecPriceHistoryState.group !== group) return;
    ecMallIndexResolvedSellerNames(rows);
    ecPriceHistoryState.rows = rows;
    renderEcPriceHistoryContent();
  } catch(e) {
    body.innerHTML = "<div class='empty'>" + esc(tf("ec_price_history_failed", { error: e.message || e })) + "</div>";
  }
}

function bindEcPriceHistoryButtons(root) {
  (root || document).querySelectorAll("[data-ec-price-history-key]").forEach(function(btn) {
    if (btn.dataset.ecPriceHistoryBound === "1") return;
    btn.dataset.ecPriceHistoryBound = "1";
    btn.addEventListener("click", function() {
      var group = ecPriceHistoryGroupMap[this.dataset.ecPriceHistoryKey || ""];
      if (group) openEcPriceHistoryForGroup(group);
    });
  });
}

function scheduleEcPriceListRenderChunk(callback) {
  if (typeof requestAnimationFrame === "function") {
    requestAnimationFrame(callback);
  } else {
    setTimeout(callback, 0);
  }
}

function renderEcMallPriceList(rows) {
  rows = rows || [];
  var renderToken = ++ecPriceListRenderToken;
  var countEl = document.getElementById("rakuten-list-count");
  var groups = {};
  ecPriceHistoryGroupMap = {};
  rows.forEach(function(row) {
    var key = row.target_id ? "target:" + row.target_id : (row.dkd_shohin_id ? "dkd:" + row.dkd_shohin_id : "search:" + row.search_number);
    if (!groups[key]) groups[key] = { meta: row, rows: [] };
    groups[key].rows.push(row);
    if (new Date(row.surveyed_at) > new Date(groups[key].meta.surveyed_at)) groups[key].meta = row;
  });
  var listRows = Object.keys(groups).map(function(key) { return groups[key]; })
    .sort(function(a, b) { return new Date(b.meta.surveyed_at) - new Date(a.meta.surveyed_at); });
  var list = document.getElementById("rakuten-list");
  if (!list) return;
  if (list) list.className = "ec-mall-grouped-list";
  if (!listRows.length) {
    if (countEl) countEl.textContent = "0 検索条件（Best3行 0 件）";
    list.innerHTML = "<div class='empty'>" + t("rakuten_no_saved_results") + "</div>";
    return;
  }
  function countText(rendered) {
    var text = listRows.length + " 検索条件（Best3行 " + rows.length + " 件）";
    if (rendered != null && rendered < listRows.length) text += " / 表示中 " + rendered + " 件";
    return text;
  }
  function bestCell(group, productType) {
    var best = group.rows.filter(function(row) { return row.product_type === productType; })
      .sort(function(a, b) { return (a.rank_no || 99) - (b.rank_no || 99); });
    if (!best.length) return "<span class='muted'>-</span>";
    return best.map(function(row) {
      var seller = ecMallSellerDisplayName(row);
      var itemUrl = safeHttpsUrl(row.item_url, ["rakuten.co.jp", "shopping.yahoo.co.jp", "yahoo.co.jp", "auctions.yahoo.co.jp"]);
      var sellerHtml = itemUrl ? "<a href='" + esc(itemUrl) + "' target='_blank' rel='noopener'>" + esc(seller) + "</a>" : esc(seller);
      return "<div class='mgmt-sub' data-dcats-inline-style='s-0d248ae75a53'><strong>#" + esc(row.rank_no) + "</strong> " + sellerHtml + " <span class='ec-provider-badge'>" + esc(ecMallProviderLabel(row.provider_key)) + "</span>" + ecMallSellerReviewSuffixHtml(row) + "<div class='price-value'>" + yen(row.total_price_jpy || row.price_jpy) + "</div></div>";
    }).join("");
  }
  function rowHtml(group, idx) {
    var r = group.meta;
    var historyKey = "g" + idx;
    ecPriceHistoryGroupMap[historyKey] = group;
    var keyword = r.search_number || r.manufacturer_part_number || r.genuine_part_number || r.dkd_shohin_id || r.shohin_cd || "-";
    var productId = r.dkd_shohin_id || r.shohin_cd || "";
    var productSub = productId && String(productId) !== String(keyword) ? "DKD商品ID " + productId : "";
    var displayMfr = ecMallDisplayManufacturerPartNumber(r);
    var displayMaker = ecMallDisplayManufacturerName(r);
    var html = "<tr>";
    html += "<td><div class='mgmt-pn'>" + esc(String(keyword)) + "</div><div class='mgmt-sub'>" + esc(productSub) + "</div></td>";
    html += "<td><div class='mgmt-pn'>" + esc(displayMfr || "-") + "</div><div class='mgmt-sub'>" + esc(displayMaker || "") + "</div></td>";
    html += "<td><div class='mgmt-pn'>" + esc(r.genuine_part_number || "-") + "</div><div class='mgmt-sub'>" + esc(r.genuine_part_number_2 || tCat(r.category) || "") + "</div></td>";
    html += "<td>" + bestCell(group, "used") + "</td>";
    html += "<td>" + bestCell(group, "rebuilt") + "</td>";
    html += "<td>" + bestCell(group, "new") + "</td>";
    html += "<td data-dcats-inline-style='s-eb99a4c193ed'>" + esc(new Date(r.surveyed_at).toLocaleString("ja-JP")) + "</td>";
    html += "<td><button class='btn-sm-edit ec-history-btn' type='button' data-ec-price-history-key='" + esc(historyKey) + "'>" + esc(t("ec_price_history")) + "</button></td>";
    html += "</tr>";
    return html;
  }
  var html = "<table class='mgmt-table ec-price-result-table ec-mall-grouped-result-table'>";
  html += "<thead><tr><th>" + t("rakuten_keyword") + "</th><th>" + t("f_mfr_pn") + "</th><th>" + t("f_genuine_pn") + "</th><th>" + t("rakuten_condition_used") + " Best3</th><th>" + t("rakuten_condition_rebuilt") + " Best3</th><th>" + t("rakuten_condition_new") + " Best3</th><th>" + t("rakuten_latest") + "</th><th>" + t("ec_price_history") + "</th></tr></thead><tbody></tbody>";
  html += "</table>";
  list.innerHTML = html;
  if (countEl) countEl.textContent = countText(0);
  var tbody = list.querySelector("tbody");
  var rendered = 0;
  function renderChunk() {
    if (renderToken !== ecPriceListRenderToken || !tbody || !tbody.parentNode) return;
    var end = Math.min(rendered + EC_PRICE_LIST_RENDER_CHUNK_SIZE, listRows.length);
    var chunkHtml = "";
    for (var i = rendered; i < end; i++) {
      chunkHtml += rowHtml(listRows[i], i);
    }
    if (chunkHtml) {
      tbody.insertAdjacentHTML("beforeend", chunkHtml);
      bindEcPriceHistoryButtons(tbody);
    }
    rendered = end;
    if (countEl) countEl.textContent = countText(rendered);
    if (rendered < listRows.length) scheduleEcPriceListRenderChunk(renderChunk);
  }
  renderChunk();
}

function renderRakutenPriceList(rows) {
  var countEl = document.getElementById("rakuten-list-count");
  if (countEl) countEl.textContent = rows.length + " 件（最新200件）";
  var list = document.getElementById("rakuten-list");
  if (list) list.className = "";
  if (!rows.length) {
    list.innerHTML = "<div class='empty'>" + t("rakuten_no_saved_results") + "</div>";
    return;
  }
  var html = "<table class='mgmt-table ec-price-result-table'>";
  html += "<tr><th>" + t("rakuten_keyword") + "</th><th>" + t("f_mfr_pn") + "</th><th>" + t("f_genuine_pn") + "</th><th>" + t("rakuten_count") + "</th><th>" + t("rakuten_condition_used") + "</th><th>" + t("rakuten_condition_rebuilt") + "</th><th>" + t("rakuten_condition_new") + "</th><th>" + t("rakuten_condition_other") + "</th><th>" + t("rakuten_min") + "</th><th>" + t("rakuten_avg") + "</th><th>" + t("rakuten_latest") + "</th></tr>";
  rows.forEach(function(r) {
    var conditionMap = rakutenConditionSummaryMap(r.items || []);
    function conditionCell(summary) {
      if (!summary || !summary.count) return "<span class='muted'>-</span>";
      return "<div class='price-value'>" + yen(summary.min) + "</div><div class='mgmt-sub'>" + summary.count + "件 / 平均 " + yen(summary.avg) + "</div>";
    }
    var keyword = r.search_number || r.manufacturer_part_number || r.genuine_part_number || r.dkd_shohin_id || "-";
    var productSub = r.dkd_shohin_id && String(r.dkd_shohin_id) !== String(keyword) ? "DKD商品ID " + r.dkd_shohin_id : "";
    var keywordSub = [productSub, r.source_type || ""].filter(Boolean).join(" / ");
    html += "<tr>";
    html += "<td><div class='mgmt-pn'>" + esc(String(keyword)) + "</div><div class='mgmt-sub'>" + esc(keywordSub || "-") + "</div></td>";
    html += "<td><div class='mgmt-pn'>" + esc(r.manufacturer_part_number || r.search_number || "-") + "</div><div class='mgmt-sub'>" + esc(r.manufacturer || "") + "</div></td>";
    html += "<td><div class='mgmt-pn'>" + esc(r.genuine_part_number || "-") + "</div><div class='mgmt-sub'>" + esc(tCat(r.category) || "") + "</div></td>";
    html += "<td>" + esc(String(r.result_count || 0)) + "</td>";
    html += "<td>" + conditionCell(conditionMap.used) + "</td>";
    html += "<td>" + conditionCell(conditionMap.rebuilt) + "</td>";
    html += "<td>" + conditionCell(conditionMap.new) + "</td>";
    html += "<td>" + conditionCell(conditionMap.other) + "</td>";
    html += "<td><div class='price-value'>" + yen(r.min_price_jpy) + "</div></td>";
    html += "<td><div class='price-value'>" + yen(r.avg_price_jpy) + "</div></td>";
    html += "<td data-dcats-inline-style='s-eb99a4c193ed'>" + esc(new Date(r.searched_at).toLocaleString("ja-JP")) + "</td>";
    html += "</tr>";
  });
  html += "</table>";
  list.innerHTML = html;
}

// =============================================
// ログヘルパー（操作ログをDBに記録）
// =============================================
async function writeLog(operation, tableName, targetId, targetDesc, beforeData, afterData) {
  if (!userProfile) return;
  var result = await sb.from("operation_logs").insert({
    user_id:     userProfile.id,
    user_email:  userProfile.email,
    user_name:   userProfile.name || userProfile.email,
    operation:   operation,
    table_name:  tableName,
    target_id:   targetId,
    target_desc: targetDesc,
    before_data: beforeData || null,
    after_data:  afterData  || null
  });
  logUserActivity(operation === "insert" ? "insert" : (operation === "delete" ? "delete" : "update"), {
    action: operation,
    target_type: tableName,
    target_id: targetId,
    target_desc: targetDesc,
    result: result && result.error ? "error" : "ok",
    metadata: {
      operation: operation,
      table_name: tableName,
      target_desc: targetDesc || null,
      before_summary: activityDataSummary(beforeData),
      after_summary: activityDataSummary(afterData)
    }
  });
  if (result && result.error) console.warn("operation log failed", result.error);
}

