var partsMgmtData = [];
var partFormMode  = "add"; // "add" or "edit"
var partFormSource = "parts"; // "parts" or "core_products"
var coreProductFormContext = "sales"; // "sales" or "production"

async function enterPartsMgmt() {
  if (!canViewManagementScreen()) { alert(t("err_perm")); return; }
  showScreen("parts-mgmt");
  var nameEl  = document.getElementById("parts-mgmt-username");
  var badgeEl = document.getElementById("parts-mgmt-role-badge");
  if (nameEl)  nameEl.textContent  = userProfile.name || userProfile.email.split("@")[0];
  if (badgeEl) { badgeEl.textContent = currentRoleDisplayLabel(); badgeEl.className = "role-badge " + roleClass(userProfile.role); }
  var addBtn = document.getElementById("btn-add-part");
  if (addBtn) setCspStyle(addBtn, "display", canEdit() ? "" : "none");
  await loadPartsMgmt();
}

async function loadPartsMgmt() {
  var q = document.getElementById("parts-mgmt-search").value.trim();

  if (!isDaikoGroup()) {
    var visibleDkdIds = await fetchActiveSlLinkedDkdIds(10000);
    var mappedParts = [];
    for (var vi = 0; vi < visibleDkdIds.length; vi += 200) {
      var idChunk = visibleDkdIds.slice(vi, vi + 200);
      var rp = await sb.from("core_products")
        .select(CORE_PRODUCT_FAST_SELECT)
        .in("dkd_shohin_id", idChunk)
        .order("manufacturer_part_number", { ascending: true })
        .order("genuine_part_number", { ascending: true });
      if (rp.error) {
        console.warn("linked core product lookup failed", rp.error);
        continue;
      }
      normalizeCoreProductFastRows(rp.data || []).forEach(function(p) {
        p._coreLinkedOnly = true;
        mappedParts.push(p);
      });
    }
    if (q) {
      var nq = norm(q);
      mappedParts = mappedParts.filter(function(p) {
        return [
          p.dkd_shohin_id,
          p.genuine_part_number,
          p.genuine_part_number_2,
          p.manufacturer_part_number,
          p.gltek_part_number,
          p.manufacturer,
          p.daiko_part_number
        ].some(function(v) { return norm(v).indexOf(nq) >= 0; });
      });
    }
    partsMgmtData = mappedParts.slice(0, 200);
    renderPartsMgmt();
    return;
  }

  var query = sb.from("parts").select("*").order("id").limit(200);
  if (q) {
    query = query.or(
      "genuine_part_number.ilike.%" + q + "%," +
      "manufacturer_part_number.ilike.%" + q + "%," +
      "manufacturer.ilike.%" + q + "%"
    );
  }
  var r = await query;
  partsMgmtData = r.data || [];
  renderPartsMgmt();
}

function renderPartsMgmt() {
  var list     = document.getElementById("parts-mgmt-list");
  var countEl  = document.getElementById("parts-mgmt-count");
  if (countEl) countEl.textContent = partsMgmtData.length + " 件";
  if (!partsMgmtData.length) { list.innerHTML = "<div class='empty'>該当する商品がありません</div>"; return; }
  var html = "<table class='mgmt-table'><tr><th>商品コード</th><th>純正品番</th><th>メーカー品番</th><th>GLTEK品番</th><th>メーカー</th><th>カテゴリ</th><th></th></tr>";
  partsMgmtData.forEach(function(p) {
    html += "<tr>";
    html += "<td><div class='mgmt-pn'>" + esc(String(p.dkd_shohin_id || p.shohin_cd || "-")) + "</div></td>";
    html += "<td><div class='mgmt-pn'>" + esc(p.genuine_part_number || "-") + "</div></td>";
    html += "<td><div class='mgmt-pn'>" + esc(p.manufacturer_part_number || "-") + "</div></td>";
    html += "<td><div class='mgmt-pn'>" + esc(p.gltek_part_number || "-") + "</div></td>";
    html += "<td><div class='mgmt-sub'>" + esc(p.manufacturer || "-") + "</div></td>";
    html += "<td><div class='mgmt-sub'>" + tCat(p.category) + "</div></td>";
    html += "<td><div class='mgmt-actions'>";
    if (!p._coreLinkedOnly) {
      html += "<button class='btn-sm-edit' data-pid='" + p.id + "'>" + t("btn_edit") + "</button>";
      html += "<button class='btn-sm-del' data-pdel='" + p.id + "'>" + t("btn_delete") + "</button>";
    }
    html += "</div></td>";
    html += "</tr>";
  });
  html += "</table>";
  list.innerHTML = html;
  if (!canEdit()) {
    list.querySelectorAll("[data-pid], [data-pdel]").forEach(function(btn) { btn.remove(); });
    return;
  }

  list.querySelectorAll(".btn-sm-edit").forEach(function(btn) {
    btn.addEventListener("click", function() { openPartForm("edit", parseInt(btn.dataset.pid,10)); });
  });
  list.querySelectorAll(".btn-sm-del").forEach(function(btn) {
    btn.addEventListener("click", function() { deletePart(parseInt(btn.dataset.pdel,10)); });
  });
}

function openPartForm(mode, partId) {
  partFormSource = "parts";
  partFormMode = mode;
  coreProductFormContext = "sales";
  var overlay  = document.getElementById("part-form-overlay");
  var title    = document.getElementById("part-form-title");
  var errEl    = document.getElementById("part-form-error");
  errEl.textContent = "";
  setProductFormFieldMode("parts", mode);

  if (mode === "add") {
    title.textContent = t("part_form_add_title");
    document.getElementById("part-form-id").value        = "";
    document.getElementById("pf-shohin-cd").value        = "";
    document.getElementById("pf-genuine-pn").value       = "";
    document.getElementById("pf-genuine-pn2").value      = "";
    document.getElementById("pf-mfr-pn").value           = "";
    document.getElementById("pf-mfr").value              = "";
    document.getElementById("pf-vehicle-mfr").value      = "";
    document.getElementById("pf-body-type").value        = "";
    document.getElementById("pf-compatible").value       = "";
    document.getElementById("pf-model").value            = "";
    document.getElementById("pf-category").value         = "Alternator";
  } else {
    var p = partsMgmtData.find(function(x){ return x.id === partId; });
    if (!p) return;
    title.textContent = t("part_form_edit_title");
    document.getElementById("part-form-id").value        = p.id;
    document.getElementById("pf-shohin-cd").value        = p.dkd_shohin_id || p.shohin_cd || "";
    document.getElementById("pf-genuine-pn").value       = p.genuine_part_number || "";
    document.getElementById("pf-genuine-pn2").value      = p.genuine_part_number_2 || "";
    document.getElementById("pf-mfr-pn").value           = p.manufacturer_part_number || "";
    document.getElementById("pf-mfr").value              = p.manufacturer || "";
    document.getElementById("pf-vehicle-mfr").value      = p.vehicle_manufacturer || "";
    document.getElementById("pf-body-type").value        = p.body_type || "";
    document.getElementById("pf-compatible").value       = p.compatible_car_models || "";
    document.getElementById("pf-model").value            = p.model || "";
    document.getElementById("pf-category").value         = p.category || "Alternator";
  }
  applySpecFormCategory();
  setGltekProductAddPanel();
  overlay.classList.add("show");
}

async function savePartForm() {
  if (partFormSource === "core_products") {
    await saveCoreProductForm();
    return;
  }
  var errEl   = document.getElementById("part-form-error");
  errEl.textContent = "";
  var gpn     = document.getElementById("pf-genuine-pn").value.trim();
  if (!gpn) { errEl.textContent = t("required_part_number"); return; }
  var scd = document.getElementById("pf-shohin-cd").value.trim();
  if (!scd) { errEl.textContent = t("required_shohin_cd"); return; }

  var data = {
    genuine_part_number:      gpn,
    genuine_part_number_2:    document.getElementById("pf-genuine-pn2").value.trim() || null,
    manufacturer_part_number: document.getElementById("pf-mfr-pn").value.trim() || null,
    manufacturer:             document.getElementById("pf-mfr").value.trim() || null,
    category:                 document.getElementById("pf-category").value,
    updated_at:               new Date().toISOString()
  };
  data.dkd_shohin_id = parseInt(scd, 10);

  var partId = document.getElementById("part-form-id").value;
  var r;
  if (partFormMode === "add") {
    r = await sb.from("parts").insert(data).select();
    if (r.error) { errEl.textContent = t("msg_part_err") + ": " + r.error.message; return; }
    var newId = (r.data && r.data[0]) ? r.data[0].id : null;
    await writeLog("insert", "parts", newId, gpn, null, data);
  } else {
    var before = partsMgmtData.find(function(x){ return x.id === parseInt(partId,10); });
    r = await sb.from("parts").update(data).eq("id", partId);
    if (r.error) { errEl.textContent = t("msg_part_err") + ": " + r.error.message; return; }
    await writeLog("update", "parts", parseInt(partId,10), gpn, before, data);
  }
  document.getElementById("part-form-overlay").classList.remove("show");
  await loadPartsMgmt();
}

