async function enterCoreListMgmt() {
  if (!canViewCoreManagement()) { alert(t("err_perm")); return; }
  showScreen("core-list-mgmt");
  var addBtn = document.getElementById("btn-add-core-list");
  var collectionAddBtn = document.getElementById("btn-add-core-collection");
  var createBtn = document.getElementById("btn-create-core-list-from-ranking");
  if (addBtn) setCspStyle(addBtn, "display", canManageProductionRecords() ? "" : "none");
  if (collectionAddBtn) setCspStyle(collectionAddBtn, "display", canManageProductionRecords() ? "" : "none");
  if (createBtn) setCspStyle(createBtn, "display", canManageProductionRecords() ? "" : "none");
  resetCoreCollectionControls();
  await setCoreListMode("collection");
}

function resetCoreCollectionControls() {
  var search = document.getElementById("core-collection-search");
  var category = document.getElementById("core-collection-category");
  var state = document.getElementById("core-collection-state");
  var priority = document.getElementById("core-collection-priority");
  var inventorySearch = document.getElementById("core-list-search");
  if (search) search.value = "";
  if (category) category.value = "";
  if (state) state.value = "all";
  if (priority) priority.value = "";
  if (inventorySearch) inventorySearch.value = "";
}

async function setCoreListMode(mode) {
  coreListMode = mode === "inventory" ? "inventory" : "collection";
  var collectionBtn = document.getElementById("btn-core-list-mode-collection");
  var inventoryBtn = document.getElementById("btn-core-list-mode-inventory");
  var collectionToolbar = document.getElementById("core-list-collection-toolbar");
  var inventoryToolbar = document.getElementById("core-list-inventory-toolbar");
  if (collectionBtn) {
    collectionBtn.classList.toggle("active", coreListMode === "collection");
    collectionBtn.setAttribute("aria-selected", coreListMode === "collection" ? "true" : "false");
  }
  if (inventoryBtn) {
    inventoryBtn.classList.toggle("active", coreListMode === "inventory");
    inventoryBtn.setAttribute("aria-selected", coreListMode === "inventory" ? "true" : "false");
  }
  if (collectionToolbar) collectionToolbar.classList.toggle("hidden", coreListMode !== "collection");
  if (inventoryToolbar) inventoryToolbar.classList.toggle("hidden", coreListMode !== "inventory");
  var loadMoreWrap = document.getElementById("core-list-load-more-wrap");
  if (loadMoreWrap) setCspStyle(loadMoreWrap, "display", "none");
  if (coreListMode === "collection") await loadCoreCollectionList();
  else await loadCoreListMgmt();
}

function coreCollectionPriorityLabel(value) {
  return value === "high" ? "高" : (value === "low" ? "低" : "通常");
}

function coreCollectionStatusLabel(value) {
  return value === "completed" ? "完了" : (value === "paused" ? "保留" : "収集中");
}

function coreCollectionSourceDetail(row) {
  var details = [];
  if (row && row.source_hint) details.push(row.source_hint);
  if (row && row.source_rank) details.push("元順位 #" + row.source_rank);
  if (row && row.shipment_count != null) details.push("出荷 " + row.shipment_count + "台");
  return details.join(" / ") || "-";
}

function coreCollectionStockQty(row) {
  var stock = row ? coreCollectionStockMap[String(row.dkd_shohin_id)] : null;
  return stock ? stock.quantity : 0;
}

function coreCollectionShortageQty(row) {
  var target = parseInt(row && row.target_quantity || 0, 10) || 0;
  return Math.max(target - coreCollectionStockQty(row), 0);
}

var CORE_COLLECTION_CATEGORY_ORDER = ["starter", "alternator", "ac_compressor", "distributor", "other"];

function coreCollectionCategoryKey(product) {
  var code = String(product && (product.category_code || product.category) || "");
  return CORE_COLLECTION_CATEGORY_ORDER.indexOf(code) >= 0 ? code : "other";
}

function coreCollectionCategoryOrder(product) {
  return CORE_COLLECTION_CATEGORY_ORDER.indexOf(coreCollectionCategoryKey(product));
}

function coreCollectionStoredOrder(row) {
  var value = parseInt(row && row.sort_order, 10);
  return isNaN(value) ? Number.MAX_SAFE_INTEGER : value;
}

function compareCoreCollectionStoredOrder(a, b) {
  var orderDiff = coreCollectionStoredOrder(a) - coreCollectionStoredOrder(b);
  if (orderDiff) return orderDiff;
  return String(a && (a.id || a.dkd_shohin_id) || "").localeCompare(String(b && (b.id || b.dkd_shohin_id) || ""), "ja", { numeric: true });
}

function assignCoreCollectionCategoryRanks() {
  var categoryRows = {};
  coreCollectionRows.forEach(function(row) {
    var product = coreCollectionProductMap[String(row.dkd_shohin_id)] || {};
    var category = coreCollectionCategoryKey(product);
    if (!categoryRows[category]) categoryRows[category] = [];
    categoryRows[category].push(row);
  });
  Object.keys(categoryRows).forEach(function(category) {
    categoryRows[category].sort(compareCoreCollectionStoredOrder).forEach(function(row, index) {
      row._category_rank = index + 1;
    });
  });
}

function coreCollectionCategoryRank(row) {
  return parseInt(row && row._category_rank, 10) || "";
}

function coreCollectionCategoryMatches(product, category) {
  if (!category) return true;
  return coreCollectionCategoryKey(product) === category;
}

function applyCoreCollectionFilters(options) {
  options = options || {};
  var qEl = document.getElementById("core-collection-search");
  var categoryEl = document.getElementById("core-collection-category");
  var stateEl = document.getElementById("core-collection-state");
  var priorityEl = document.getElementById("core-collection-priority");
  var q = qEl ? norm(qEl.value.trim()) : "";
  var category = categoryEl ? categoryEl.value : "";
  var state = stateEl ? stateEl.value : "all";
  var priority = priorityEl ? priorityEl.value : "";
  if (!options.preserveRenderLimit) coreCollectionRenderLimit = CORE_COLLECTION_RENDER_PAGE_SIZE;
  assignCoreCollectionCategoryRanks();
  coreCollectionFilteredRows = coreCollectionRows.filter(function(row) {
    var product = coreCollectionProductMap[String(row.dkd_shohin_id)] || {};
    var stock = coreCollectionStockMap[String(row.dkd_shohin_id)] || {};
    if (q && ![
      row.dkd_shohin_id,
      row.source_hint,
      row.note,
      product.genuine_part_number,
      product.genuine_part_number_2,
      product.manufacturer_part_number,
      product.manufacturer,
      product.daiko_part_number,
      (stock.parts || []).join(" "),
      (stock.locations || []).join(" ")
    ].some(function(value) { return normalizedContains(value, q); })) return false;
    if (!coreCollectionCategoryMatches(product, category)) return false;
    if (priority && row.priority !== priority) return false;
    var stockQty = coreCollectionStockQty(row);
    var shortage = coreCollectionShortageQty(row);
    if (state === "needed" && !(row.status === "collecting" && shortage > 0)) return false;
    if (state === "in_stock" && stockQty <= 0) return false;
    if (state === "sufficient" && shortage > 0) return false;
    if (["collecting", "completed", "paused"].indexOf(state) >= 0 && row.status !== state) return false;
    return true;
  });
  coreCollectionFilteredRows.sort(function(a, b) {
    var ap = coreCollectionProductMap[String(a.dkd_shohin_id)] || {};
    var bp = coreCollectionProductMap[String(b.dkd_shohin_id)] || {};
    var rankDiff = (coreCollectionCategoryRank(a) || Number.MAX_SAFE_INTEGER) - (coreCollectionCategoryRank(b) || Number.MAX_SAFE_INTEGER);
    if (rankDiff) return rankDiff;
    var categoryDiff = coreCollectionCategoryOrder(ap) - coreCollectionCategoryOrder(bp);
    if (categoryDiff) return categoryDiff;
    return compareCoreCollectionStoredOrder(a, b);
  });
}

async function loadCoreCollectionList() {
  var list = document.getElementById("core-list-list");
  if (list) list.innerHTML = "<div class='loading'>" + esc(t("loading")) + "</div>";
  var r = await sb.from("core_collection_list_items")
    .select("*")
    .order("sort_order", { ascending: true, nullsFirst: false })
    .order("updated_at", { ascending: false })
    .limit(2000);
  if (r.error) {
    if (list) list.innerHTML = "<div class='empty'>収集リストの読み込みに失敗しました: " + esc(r.error.message) + "</div>";
    return;
  }
  coreCollectionRows = r.data || [];
  coreCollectionProductMap = {};
  coreCollectionStockMap = {};
  await Promise.all([
    loadCoreCollectionProducts(coreCollectionRows),
    loadCoreCollectionStock(coreCollectionRows)
  ]);
  applyCoreCollectionFilters();
  renderCoreCollectionList();
}

async function loadCoreCollectionProducts(rows) {
  var ids = Array.from(new Set((rows || []).map(function(row) { return parseInt(row.dkd_shohin_id, 10); }).filter(function(id) { return !isNaN(id); })));
  var requests = [];
  for (var i = 0; i < ids.length; i += 200) {
    requests.push(sb.from("core_products").select(CORE_PRODUCT_FAST_SELECT).in("dkd_shohin_id", ids.slice(i, i + 200)));
  }
  var results = await Promise.all(requests);
  results.forEach(function(r) {
    if (r.error) {
      console.warn("core collection product lookup failed", r.error);
      return;
    }
    normalizeCoreProductFastRows(r.data || []).forEach(function(product) {
      coreCollectionProductMap[String(product.dkd_shohin_id)] = product;
    });
  });
}

async function loadCoreCollectionStock(rows) {
  var ids = Array.from(new Set((rows || []).map(function(row) { return parseInt(row.dkd_shohin_id, 10); }).filter(function(id) { return !isNaN(id); })));
  var requests = [];
  for (var i = 0; i < ids.length; i += 200) {
    requests.push(sb.from("production_core_list_entries")
      .select("dkd_shohin_id, quantity, core_part_number, location")
      .in("dkd_shohin_id", ids.slice(i, i + 200)));
  }
  var results = await Promise.all(requests);
  results.forEach(function(r) {
    if (r.error) {
      console.warn("core collection stock lookup failed", r.error);
      return;
    }
    (r.data || []).forEach(function(stockRow) {
      var key = String(stockRow.dkd_shohin_id);
      var stock = coreCollectionStockMap[key] || { quantity: 0, parts: [], locations: [] };
      stock.quantity += parseInt(stockRow.quantity || 0, 10) || 0;
      if (stockRow.core_part_number && stock.parts.indexOf(stockRow.core_part_number) < 0) stock.parts.push(stockRow.core_part_number);
      if (stockRow.location && stock.locations.indexOf(stockRow.location) < 0) stock.locations.push(stockRow.location);
      coreCollectionStockMap[key] = stock;
    });
  });
}

function renderCoreCollectionStockBadge(row) {
  var qty = coreCollectionStockQty(row);
  return "<span class='core-stock-badge " + (qty > 0 ? "has-stock" : "no-stock") + "'>" + (qty > 0 ? "在庫あり " + esc(String(qty)) : "在庫なし") + "</span>";
}

function updateCoreCollectionLoadMoreButton() {
  var wrap = document.getElementById("core-list-load-more-wrap");
  var btn = document.getElementById("core-list-load-more");
  if (!wrap || !btn || coreListMode !== "collection") return;
  var visibleCount = Math.min(coreCollectionRenderLimit, coreCollectionFilteredRows.length);
  var remaining = Math.max(coreCollectionFilteredRows.length - visibleCount, 0);
  setCspStyle(wrap, "display", remaining > 0 ? "block" : "none");
  btn.disabled = false;
  btn.textContent = remaining > 0 ? "さらに表示（残り" + remaining + "件）" : t("btn_load_more");
}

function renderCoreCollectionList() {
  var list = document.getElementById("core-list-list");
  var countEl = document.getElementById("core-list-count");
  if (!list) return;
  var visibleRows = coreCollectionFilteredRows.slice(0, coreCollectionRenderLimit);
  var totalTarget = 0;
  var totalStock = 0;
  var totalShortage = 0;
  coreCollectionFilteredRows.forEach(function(row) {
    totalTarget += parseInt(row.target_quantity || 0, 10) || 0;
    totalStock += coreCollectionStockQty(row);
    totalShortage += coreCollectionShortageQty(row);
  });
  if (countEl) countEl.innerHTML = esc(String(coreCollectionFilteredRows.length)) + " 件" +
    (visibleRows.length < coreCollectionFilteredRows.length ? " <span class='core-count-pill'>表示 " + esc(String(visibleRows.length)) + " / " + esc(String(coreCollectionFilteredRows.length)) + "</span>" : "") +
    " <span class='core-count-pill'>目標 " + esc(String(totalTarget)) + "</span>" +
    " <span class='core-count-pill stock'>現在庫 " + esc(String(totalStock)) + "</span>" +
    " <span class='core-count-pill shortage'>不足 " + esc(String(totalShortage)) + "</span>";
  if (!coreCollectionRows.length) {
    list.innerHTML = "<div class='empty'>収集対象はまだ登録されていません。<br>「収集対象を追加」または「製造ランキングから追加」で、買い集めるコアを登録してください。</div>";
    updateCoreCollectionLoadMoreButton();
    return;
  }
  if (!coreCollectionFilteredRows.length) {
    list.innerHTML = "<div class='empty'>条件に該当する収集対象はありません。</div>";
    updateCoreCollectionLoadMoreButton();
    return;
  }
  if (!isPC()) {
    var mobileHtml = "<div class='core-collection-mobile-cards'>";
    visibleRows.forEach(function(row) {
      var product = coreCollectionProductMap[String(row.dkd_shohin_id)] || {};
      var stock = coreCollectionStockMap[String(row.dkd_shohin_id)] || {};
      var shortage = coreCollectionShortageQty(row);
      var categoryRank = coreCollectionCategoryRank(row);
      mobileHtml += "<div class='core-collection-card'>";
      mobileHtml += "<div class='core-collection-card-head'><div><div class='core-main-pn'>" + esc(product.manufacturer_part_number || product.genuine_part_number || ("DKD " + row.dkd_shohin_id)) + "</div><div class='mgmt-sub'>" + esc(productionCategoryLabel(product)) + (categoryRank ? " #" + esc(String(categoryRank)) : "") + " / " + esc(product.genuine_part_number || "-") + " / " + esc(product.manufacturer || "-") + "</div></div><span class='core-priority-badge " + esc(row.priority) + "'>" + esc(coreCollectionPriorityLabel(row.priority)) + "</span></div>";
      mobileHtml += "<div class='core-collection-card-badges'>" + renderCoreCollectionStockBadge(row) + "<span class='core-status-badge " + esc(row.status) + "'>" + esc(coreCollectionStatusLabel(row.status)) + "</span></div>";
      mobileHtml += "<div class='core-collection-qty-grid'><div><span>目標</span><strong>" + esc(String(row.target_quantity || 0)) + "</strong></div><div><span>現在庫</span><strong>" + esc(String(coreCollectionStockQty(row))) + "</strong></div><div class='shortage'><span>不足</span><strong>" + esc(String(shortage)) + "</strong></div></div>";
      mobileHtml += "<div class='core-collection-meta'>" + esc(productionCategoryLabel(product)) + " / DKD " + esc(String(row.dkd_shohin_id)) + (stock.parts && stock.parts.length ? "<br>在庫品番: " + esc(stock.parts.join(" / ")) : "") + "</div>";
      mobileHtml += "<div class='core-collection-note'><strong>追加元</strong> " + esc(coreCollectionSourceDetail(row)) + "<br><strong>メモ</strong> " + esc(row.note || "-") + "</div>";
      mobileHtml += "<div class='core-list-card-actions'><button class='btn-sm-edit' data-core-collection-edit='" + row.id + "'>編集</button><button class='btn-sm-edit production-action-secondary' data-core-collection-complete='" + row.id + "'>" + (row.status === "completed" ? "収集再開" : "完了") + "</button><button class='btn-sm-del' data-core-collection-delete='" + row.id + "'>削除</button></div>";
      mobileHtml += "</div>";
    });
    list.innerHTML = mobileHtml + "</div>";
    bindCoreCollectionActions();
    updateCoreCollectionLoadMoreButton();
    return;
  }
  var html = "<table class='mgmt-table core-collection-table'><tr><th>カテゴリ順位・優先</th><th>対象品番</th><th>区分・メーカー</th><th>現在庫</th><th>目標</th><th>不足</th><th>状態・追加元</th><th>操作</th></tr>";
  visibleRows.forEach(function(row) {
    var product = coreCollectionProductMap[String(row.dkd_shohin_id)] || {};
    var stock = coreCollectionStockMap[String(row.dkd_shohin_id)] || {};
    var shortage = coreCollectionShortageQty(row);
    var categoryRank = coreCollectionCategoryRank(row);
    html += "<tr>";
    html += "<td><div class='core-category-rank'><span>" + esc(productionCategoryLabel(product)) + "</span>" + (categoryRank ? "<strong>#" + esc(String(categoryRank)) + "</strong>" : "") + "</div><span class='core-priority-badge " + esc(row.priority) + "'>" + esc(coreCollectionPriorityLabel(row.priority)) + "</span></td>";
    html += "<td><div class='core-main-pn'>" + esc(product.manufacturer_part_number || product.genuine_part_number || ("DKD " + row.dkd_shohin_id)) + "</div><div class='mgmt-pn'>純正 " + esc(product.genuine_part_number || "-") + "</div><div class='mgmt-sub'>DKD " + esc(String(row.dkd_shohin_id)) + "</div></td>";
    html += "<td>" + esc(productionCategoryLabel(product)) + "<div class='mgmt-sub'>" + esc(product.manufacturer || "-") + "</div></td>";
    html += "<td>" + renderCoreCollectionStockBadge(row) + (stock.parts && stock.parts.length ? "<div class='mgmt-sub'>" + esc(stock.parts.join(" / ")) + "</div>" : "") + "</td>";
    html += "<td><span class='core-qty-pill target'>" + esc(String(row.target_quantity || 0)) + "</span></td>";
    html += "<td><span class='core-shortage-value " + (shortage > 0 ? "needed" : "enough") + "'>" + esc(String(shortage)) + "</span></td>";
    html += "<td><span class='core-status-badge " + esc(row.status) + "'>" + esc(coreCollectionStatusLabel(row.status)) + "</span><div class='core-note'>" + esc(coreCollectionSourceDetail(row)) + "</div><div class='mgmt-sub'>" + esc(row.note || "") + "</div></td>";
    html += "<td><div class='mgmt-actions'><button class='btn-sm-edit' data-core-collection-edit='" + row.id + "'>編集</button><button class='btn-sm-edit production-action-secondary' data-core-collection-complete='" + row.id + "'>" + (row.status === "completed" ? "再開" : "完了") + "</button><button class='btn-sm-del' data-core-collection-delete='" + row.id + "'>削除</button></div></td>";
    html += "</tr>";
  });
  list.innerHTML = html + "</table>";
  bindCoreCollectionActions();
  updateCoreCollectionLoadMoreButton();
}

function bindCoreCollectionActions() {
  var list = document.getElementById("core-list-list");
  if (!list) return;
  if (!canManageProductionRecords()) {
    list.querySelectorAll("[data-core-collection-edit], [data-core-collection-complete], [data-core-collection-delete]").forEach(function(btn) { btn.remove(); });
    return;
  }
  list.querySelectorAll("[data-core-collection-edit]").forEach(function(btn) {
    btn.addEventListener("click", function() { openCoreCollectionForm("edit", parseInt(btn.dataset.coreCollectionEdit, 10)); });
  });
  list.querySelectorAll("[data-core-collection-complete]").forEach(function(btn) {
    btn.addEventListener("click", function() { toggleCoreCollectionCompleted(parseInt(btn.dataset.coreCollectionComplete, 10)); });
  });
  list.querySelectorAll("[data-core-collection-delete]").forEach(function(btn) {
    btn.addEventListener("click", function() { deleteCoreCollectionRow(parseInt(btn.dataset.coreCollectionDelete, 10)); });
  });
}

function renderCoreCollectionSelectedProduct(product) {
  var info = document.getElementById("ccf-product-info");
  if (!info) return;
  if (!product) {
    info.innerHTML = "";
    return;
  }
  var stock = coreCollectionStockMap[String(product.dkd_shohin_id)] || { quantity: 0 };
  var productCode = product.shohin_cd || product.dks_shohin_cd || "-";
  info.innerHTML = "<strong>" + esc(product.manufacturer_part_number || product.genuine_part_number || ("DKD " + product.dkd_shohin_id)) + "</strong><span>純正 " + esc(product.genuine_part_number || "-") + " / " + esc(product.manufacturer || "-") + " / DKD " + esc(String(product.dkd_shohin_id)) + "</span><span class='core-collection-selected-status'>品番マスタ登録あり / 商品CD " + esc(String(productCode)) + " / 現在庫 " + esc(String(stock.quantity || 0)) + "</span>";
}

function openCoreCollectionForm(mode, rowId) {
  if (!canManageProductionRecords()) { alert(t("err_perm")); return; }
  coreCollectionFormMode = mode === "edit" ? "edit" : "add";
  var row = coreCollectionFormMode === "edit" ? coreCollectionRows.find(function(item) { return item.id === rowId; }) : null;
  var product = row ? (coreCollectionProductMap[String(row.dkd_shohin_id)] || {}) : null;
  setProductionRankingFormValue("ccf-id", row && row.id);
  setProductionRankingFormValue("ccf-dkd-id", row && row.dkd_shohin_id);
  setProductionRankingFormValue("ccf-product-search", "");
  setProductionRankingFormValue("ccf-target-quantity", row ? row.target_quantity : 1);
  setProductionRankingFormValue("ccf-priority", row ? row.priority : "normal");
  setProductionRankingFormValue("ccf-status", row ? row.status : "collecting");
  setProductionRankingFormValue("ccf-source-hint", row && row.source_hint);
  setProductionRankingFormValue("ccf-note", row && row.note);
  document.getElementById("core-collection-form-title").textContent = row ? "収集対象を編集" : "収集対象を追加";
  document.getElementById("core-collection-form-error").textContent = "";
  var candidates = document.getElementById("ccf-product-candidates");
  candidates.innerHTML = "";
  setCspStyle(candidates, "display", "none");
  var searchRow = document.getElementById("ccf-product-search-row");
  if (searchRow) setCspStyle(searchRow, "display", row ? "none" : "");
  renderCoreCollectionSelectedProduct(product);
  document.getElementById("core-collection-form-overlay").classList.add("show");
}

function isCoreCollectionMasterProduct(product) {
  if (!product) return false;
  if (product.legacy_part_id !== null && product.legacy_part_id !== undefined && String(product.legacy_part_id).trim()) return true;
  if (String(product.shohin_cd || product.dks_shohin_cd || "").trim()) return true;
  return !!String(product.dks_relation_type || "").trim();
}

async function enrichCoreCollectionMasterStatus(products) {
  var rows = normalizeCoreProductFastRows(products || []);
  var unresolvedIds = rows.filter(function(product) {
    return !isCoreCollectionMasterProduct(product);
  }).map(function(product) {
    return parseInt(product.dkd_shohin_id, 10);
  }).filter(function(id) {
    return !isNaN(id);
  });
  if (!unresolvedIds.length) return { data: rows, error: null };

  var linkResult = await sb.from("core_product_dks_links")
    .select("dkd_shohin_id")
    .in("dkd_shohin_id", unresolvedIds)
    .limit(1000);
  if (linkResult.error) return linkResult;
  var linkedIds = {};
  (linkResult.data || []).forEach(function(link) {
    linkedIds[String(link.dkd_shohin_id)] = true;
  });
  rows.forEach(function(product) {
    if (linkedIds[String(product.dkd_shohin_id)]) product.dks_relation_type = "linked";
  });
  return { data: rows, error: null };
}

async function validateCoreCollectionMasterProduct(dkdId) {
  var productResult = await sb.from("core_products")
    .select("dkd_shohin_id,legacy_part_id,dks_shohin_cd")
    .eq("dkd_shohin_id", dkdId)
    .maybeSingle();
  if (productResult.error || !productResult.data) return productResult;
  if (isCoreCollectionMasterProduct(productResult.data)) return productResult;

  var linkResult = await sb.from("core_product_dks_links")
    .select("id")
    .eq("dkd_shohin_id", dkdId)
    .limit(1);
  if (linkResult.error) return linkResult;
  if ((linkResult.data || []).length) {
    return { data: Object.assign({}, productResult.data, { dks_relation_type: "linked" }), error: null };
  }

  var searchedProduct = coreCollectionProductCandidates.find(function(product) {
    return String(product.dkd_shohin_id) === String(dkdId);
  });
  return isCoreCollectionMasterProduct(searchedProduct)
    ? { data: searchedProduct, error: null }
    : { data: null, error: null };
}

async function searchCoreCollectionProductCandidates() {
  var input = document.getElementById("ccf-product-search");
  var wrap = document.getElementById("ccf-product-candidates");
  var q = input ? input.value.trim() : "";
  if (!wrap) return;
  if (!q) {
    coreCollectionProductCandidates = [];
    wrap.innerHTML = "";
    setCspStyle(wrap, "display", "none");
    return;
  }
  setCspStyle(wrap, "display", "block");
  wrap.innerHTML = "<div class='candidate-empty'>検索中...</div>";
  var r = await fetchCoreProductMasterMatches(q, null, 30);
  if (r.error) {
    wrap.innerHTML = "<div class='candidate-empty'>" + esc(r.error.message) + "</div>";
    return;
  }
  var statusResult = await enrichCoreCollectionMasterStatus(r.data || []);
  if (statusResult.error) {
    wrap.innerHTML = "<div class='candidate-empty'>品番マスタの確認に失敗しました: " + esc(statusResult.error.message) + "</div>";
    return;
  }
  coreCollectionProductCandidates = filterVisibleProducts(statusResult.data || []);
  if (!coreCollectionProductCandidates.length) {
    wrap.innerHTML = "<div class='candidate-empty'><strong>品番マスタ未登録</strong><span>該当する商品がありません。</span></div>";
    return;
  }
  var existingIds = {};
  coreCollectionRows.forEach(function(row) { existingIds[String(row.dkd_shohin_id)] = true; });
  wrap.innerHTML = coreCollectionProductCandidates.map(function(product, index) {
    var exists = !!existingIds[String(product.dkd_shohin_id)];
    var isMaster = isCoreCollectionMasterProduct(product);
    var statusClass = exists ? "existing" : (isMaster ? "master" : "missing");
    var statusLabel = exists ? "収集リスト登録済み" : (isMaster ? "品番マスタ登録あり" : "品番マスタ未登録");
    var productCode = product.shohin_cd || product.dks_shohin_cd || "-";
    return "<button type='button' class='candidate-item core-collection-candidate-item' data-core-collection-candidate='" + index + "' " + (exists || !isMaster ? "disabled" : "") + "><span class='core-collection-candidate-head'><strong>" + esc(product.manufacturer_part_number || product.genuine_part_number || ("DKD " + product.dkd_shohin_id)) + "</strong><span class='core-collection-master-badge " + statusClass + "'>" + statusLabel + "</span></span><small>純正 " + esc(product.genuine_part_number || "-") + " / " + esc(product.manufacturer || "-") + " / 商品CD " + esc(String(productCode)) + " / " + esc(productionCategoryLabel(product)) + "</small></button>";
  }).join("");
}

async function selectCoreCollectionProductCandidate(index) {
  var product = coreCollectionProductCandidates[index];
  if (!product) return;
  document.getElementById("ccf-dkd-id").value = product.dkd_shohin_id || "";
  var candidates = document.getElementById("ccf-product-candidates");
  candidates.innerHTML = "";
  setCspStyle(candidates, "display", "none");
  if (!Object.prototype.hasOwnProperty.call(coreCollectionStockMap, String(product.dkd_shohin_id))) {
    await loadCoreCollectionStock([{ dkd_shohin_id: product.dkd_shohin_id }]);
  }
  renderCoreCollectionSelectedProduct(product);
}

async function saveCoreCollectionForm() {
  var errorEl = document.getElementById("core-collection-form-error");
  errorEl.textContent = "";
  if (!canManageProductionRecords()) { errorEl.textContent = t("err_perm"); return; }
  var dkdId = nullableIntFromInput("ccf-dkd-id");
  var targetQty = nullableIntFromInput("ccf-target-quantity");
  if (!dkdId) { errorEl.textContent = "対象商品を選択してください。"; return; }
  if (targetQty == null || targetQty < 0) { errorEl.textContent = "収集目標数は0以上で入力してください。"; return; }
  if (coreCollectionFormMode === "add") {
    var masterCheck = await validateCoreCollectionMasterProduct(dkdId);
    if (masterCheck.error) {
      errorEl.textContent = "基幹商品マスタの確認に失敗しました: " + masterCheck.error.message;
      return;
    }
    if (!isCoreCollectionMasterProduct(masterCheck.data)) {
      errorEl.textContent = "基幹商品マスタに存在する商品だけ追加できます。";
      return;
    }
  }
  var data = {
    dkd_shohin_id: dkdId,
    target_quantity: targetQty,
    priority: document.getElementById("ccf-priority").value,
    status: document.getElementById("ccf-status").value,
    source_hint: nullableTextFromInput("ccf-source-hint"),
    note: nullableTextFromInput("ccf-note"),
    updated_by: currentUser ? currentUser.id : null,
    updated_at: new Date().toISOString()
  };
  var id = nullableIntFromInput("ccf-id");
  var r;
  if (coreCollectionFormMode === "add") {
    data.created_by = currentUser ? currentUser.id : null;
    data.sort_order = coreCollectionRows.reduce(function(maxValue, row) {
      var value = parseInt(row.sort_order, 10);
      return isNaN(value) ? maxValue : Math.max(maxValue, value);
    }, 0) + 1;
    data.source_type = "manual";
    r = await sb.from("core_collection_list_items").insert(data).select().single();
    if (!r.error) await writeLog("insert", "core_collection_list_items", r.data && r.data.id, "DKD " + dkdId, null, data);
  } else {
    var before = coreCollectionRows.find(function(row) { return row.id === id; });
    r = await sb.from("core_collection_list_items").update(data).eq("id", id).select().single();
    if (!r.error) await writeLog("update", "core_collection_list_items", id, "DKD " + dkdId, before, data);
  }
  if (r.error) {
    errorEl.textContent = r.error.code === "23505" ? "この商品は収集リストに登録済みです。" : (t("msg_part_err") + ": " + r.error.message);
    return;
  }
  document.getElementById("core-collection-form-overlay").classList.remove("show");
  await loadCoreCollectionList();
}

async function toggleCoreCollectionCompleted(id) {
  if (!canManageProductionRecords()) { alert(t("err_perm")); return; }
  var row = coreCollectionRows.find(function(item) { return item.id === id; });
  if (!row) return;
  var status = row.status === "completed" ? "collecting" : "completed";
  var data = { status: status, updated_by: currentUser ? currentUser.id : null, updated_at: new Date().toISOString() };
  var r = await sb.from("core_collection_list_items").update(data).eq("id", id);
  if (r.error) { alert(t("msg_part_err") + ": " + r.error.message); return; }
  await writeLog("update", "core_collection_list_items", id, "DKD " + row.dkd_shohin_id, { status: row.status }, data);
  await loadCoreCollectionList();
}

async function deleteCoreCollectionRow(id) {
  if (!canManageProductionRecords()) { alert(t("err_perm")); return; }
  var row = coreCollectionRows.find(function(item) { return item.id === id; });
  if (!row || !confirm("この収集対象を削除しますか？")) return;
  var r = await sb.from("core_collection_list_items").delete().eq("id", id);
  if (r.error) { alert(t("msg_part_err") + ": " + r.error.message); return; }
  await writeLog("delete", "core_collection_list_items", id, "DKD " + row.dkd_shohin_id, row, null);
  await loadCoreCollectionList();
}

function csvCoreCollectionCell(value) {
  return '"' + String(value == null ? "" : value).replace(/"/g, '""') + '"';
}

function exportCoreCollectionCsv() {
  applyCoreCollectionFilters({ preserveRenderLimit: true });
  if (!coreCollectionFilteredRows.length) { alert("出力する収集対象がありません。"); return; }
  var lines = [["カテゴリ順位", "追加元", "元順位", "2025出荷数", "優先度", "状態", "カテゴリ", "メーカー", "メーカー品番", "純正品番", "DKD商品ID", "現在庫", "目標数", "不足数", "入手先候補", "メモ"]];
  coreCollectionFilteredRows.forEach(function(row) {
    var product = coreCollectionProductMap[String(row.dkd_shohin_id)] || {};
    lines.push([
      coreCollectionCategoryRank(row),
      row.source_hint || "",
      row.source_rank || "",
      row.shipment_count == null ? "" : row.shipment_count,
      coreCollectionPriorityLabel(row.priority),
      coreCollectionStatusLabel(row.status),
      productionCategoryLabel(product),
      product.manufacturer || "",
      product.manufacturer_part_number || "",
      product.genuine_part_number || "",
      row.dkd_shohin_id,
      coreCollectionStockQty(row),
      row.target_quantity || 0,
      coreCollectionShortageQty(row),
      row.source_hint || "",
      row.note || ""
    ]);
  });
  var csv = "\uFEFF" + lines.map(function(row) { return row.map(csvCoreCollectionCell).join(","); }).join("\r\n");
  var blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
  var url = URL.createObjectURL(blob);
  var link = document.createElement("a");
  link.href = url;
  link.download = "D-CATS_コア収集リスト_" + new Date().toISOString().slice(0, 10) + ".csv";
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function coreListSearchKey() {
  var input = document.getElementById("core-list-search");
  return input ? norm(input.value.trim()) : "";
}

function coreListRowMatches(row, q) {
  if (!q) return true;
  var p = coreListProductMap[String(row.dkd_shohin_id)] || {};
  return [
    row.dkd_shohin_id,
    row.core_part_number,
    row.location,
    row.note,
    p.genuine_part_number,
    p.manufacturer_part_number,
    p.manufacturer,
    p.daiko_part_number
  ].some(function(v) { return normalizedContains(v, q); });
}

function updateCoreListLoadMoreButton() {
  var wrap = document.getElementById("core-list-load-more-wrap");
  var btn = document.getElementById("core-list-load-more");
  if (!wrap || !btn) return;
  setCspStyle(wrap, "display", coreListHasMore ? "block" : "none");
  btn.disabled = !!coreListLoadingMore;
  btn.textContent = coreListLoadingMore ? t("loading") : t("btn_load_more");
}

async function fetchCoreListRawPage(limit) {
  var from = coreListRawOffset;
  var to = from + limit - 1;
  var r = await sb.from("production_core_list_entries")
    .select("*")
    .order("updated_at", { ascending: false })
    .order("id", { ascending: false })
    .range(from, to);
  if (r.error) return r;
  var rows = r.data || [];
  coreListRawOffset += rows.length;
  coreListHasMore = rows.length === limit;
  return { data: rows, error: null };
}

async function loadCoreListMgmt(options) {
  options = options || {};
  var q = coreListSearchKey();
  var append = !!options.append && q === coreListCurrentSearchKey;
  var list = document.getElementById("core-list-list");
  if (coreListLoadingMore) return;
  if (!append) {
    coreListMgmtRows = [];
    coreListProductMap = {};
    coreListRawOffset = 0;
    coreListHasMore = true;
    coreListCurrentSearchKey = q;
    if (list) list.innerHTML = "<div class='loading'>" + t("loading") + "</div>";
  }

  coreListLoadingMore = true;
  updateCoreListLoadMoreButton();
  try {
    var added = 0;
    var chunks = 0;
    var maxChunks = q ? CORE_LIST_SEARCH_SCAN_CHUNKS : 1;
    while (coreListHasMore && added < CORE_LIST_PAGE_SIZE && chunks < maxChunks) {
      chunks += 1;
      var r = await fetchCoreListRawPage(CORE_LIST_PAGE_SIZE);
      if (r.error) {
        if (list) list.innerHTML = "<div class='empty'>" + esc(t("msg_part_err") + ": " + r.error.message) + "</div>";
        return;
      }
      var rawRows = r.data || [];
      if (!rawRows.length) break;
      await loadCoreListProductMap(rawRows);
      var rows = rawRows.filter(function(row) { return coreListRowMatches(row, q); });
      coreListMgmtRows = coreListMgmtRows.concat(rows);
      added += rows.length;
      if (!q) break;
    }
    renderCoreListMgmt();
  } finally {
    coreListLoadingMore = false;
    updateCoreListLoadMoreButton();
  }
}

async function loadCoreListProductMap(rows) {
  var ids = [];
  (rows || []).forEach(function(row) {
    if (row.dkd_shohin_id != null && !coreListProductMap[String(row.dkd_shohin_id)] && ids.indexOf(row.dkd_shohin_id) < 0) ids.push(row.dkd_shohin_id);
  });
  if (!ids.length) return;
  var r = await sb.from("core_products").select(CORE_PRODUCT_FAST_SELECT).in("dkd_shohin_id", ids).limit(500);
  if (r.error) {
    console.warn("core list product lookup failed", r.error);
    r = await sb.from("core_product_search_view").select("*").in("dkd_shohin_id", ids).limit(500);
    if (r.error) {
      console.warn("core list product view fallback failed", r.error);
      return;
    }
  }
  normalizeCoreProductFastRows(r.data || []).forEach(function(p) {
    coreListProductMap[String(p.dkd_shohin_id)] = p;
  });
}

function renderCoreListMgmt() {
  var list = document.getElementById("core-list-list");
  var countEl = document.getElementById("core-list-count");
  if (countEl) countEl.textContent = coreListMgmtRows.length + " 件";
  if (!list) return;
  if (countEl) {
    var initialTotalQty = sumProductionCoreEntryQty(coreListMgmtRows);
    countEl.innerHTML = esc(String(coreListMgmtRows.length)) + " 件 <span class='core-count-pill'>コア合計 " + esc(String(initialTotalQty)) + "</span>";
  }
  if (!coreListMgmtRows.length) {
    list.innerHTML = coreListHasMore
      ? "<div class='empty'>" + esc(t("no_results")) + "</div>"
      : "<div class='empty'>コアリストはまだ登録されていません。<br>「コアを追加」から基幹商品に紐づくコア品番・数量・置き場を登録してください。</div>";
    return;
  }
  if (!isPC()) {
    var mobileHtml = "<div class='core-list-mobile-cards'>";
    coreListMgmtRows.forEach(function(row) {
      var p = coreListProductMap[String(row.dkd_shohin_id)] || {};
      var fallbackPartNumber = row.core_part_number || "";
      var updatedText = formatDateTime(row.updated_at);
      function mobileField(label, value) {
        return "<div class='core-list-card-field'><span class='core-list-card-label'>" + esc(label) + "</span><div class='core-list-card-value'>" + value + "</div></div>";
      }
      mobileHtml += "<div class='core-list-card'>";
      mobileHtml += "<div class='core-list-card-head'><div><div class='core-main-pn'>" + esc(row.core_part_number || "-") + "</div><div class='mgmt-sub'>" + esc(productionCategoryLabel(p)) + "</div></div><span class='core-qty-pill'>" + esc(String(row.quantity == null ? 0 : row.quantity)) + "</span></div>";
      mobileHtml += "<div class='core-list-card-grid'>";
      mobileHtml += mobileField(t("f_manufacturer"), "<span class='core-maker-badge'>" + esc(p.manufacturer || "-") + "</span>");
      mobileHtml += mobileField(t("f_genuine_pn"), "<span class='mgmt-pn'>" + esc(p.genuine_part_number || fallbackPartNumber || "-") + "</span><div class='mgmt-sub'>" + esc(p.manufacturer_part_number || fallbackPartNumber || "-") + "</div>");
      mobileHtml += mobileField(t("core_list_location"), esc(row.location || "-"));
      mobileHtml += "</div>";
      mobileHtml += "<div class='core-list-card-note'><span class='core-list-card-label'>" + esc(t("core_list_note")) + "</span><div class='core-note'>" + esc(row.note || "-") + "</div><div class='mgmt-sub'>DKD " + esc(String(row.dkd_shohin_id || "-")) + " / " + esc(updatedText) + "</div></div>";
      mobileHtml += "<div class='core-list-card-actions'>";
      mobileHtml += "<button class='btn-sm-edit production-action-secondary' data-core-image='" + esc(String(row.id)) + "'>" + esc(t("btn_upload")) + "</button>";
      mobileHtml += "<button class='btn-sm-edit' data-core-edit='" + esc(String(row.id)) + "'>" + esc(t("btn_edit")) + "</button>";
      mobileHtml += "<button class='btn-sm-del' data-core-del='" + esc(String(row.id)) + "'>" + esc(t("btn_delete")) + "</button>";
      mobileHtml += "</div></div>";
    });
    mobileHtml += "</div>";
    list.innerHTML = mobileHtml;
    if (!canUploadCoreImages()) {
      list.querySelectorAll("[data-core-image]").forEach(function(btn) { btn.remove(); });
    } else {
      list.querySelectorAll("[data-core-image]").forEach(function(btn) {
        btn.addEventListener("click", function() { openCorePhotoChoice(parseInt(btn.dataset.coreImage, 10)); });
      });
    }
    if (!canManageProductionRecords()) {
      list.querySelectorAll("[data-core-edit], [data-core-del]").forEach(function(btn) { btn.remove(); });
      return;
    }
    list.querySelectorAll("[data-core-edit]").forEach(function(btn) {
      btn.addEventListener("click", function() { openCoreListForm("edit", parseInt(btn.dataset.coreEdit, 10)); });
    });
    list.querySelectorAll("[data-core-del]").forEach(function(btn) {
      btn.addEventListener("click", function() { deleteCoreListRow(parseInt(btn.dataset.coreDel, 10)); });
    });
    return;
  }
  var html = "<table class='mgmt-table core-list-table'>";
  html += "<tr><th>コア品番</th><th>メーカー</th><th>純正品番</th><th>数量</th><th>置き場</th><th>メモ</th><th>操作</th></tr>";
  coreListMgmtRows.forEach(function(row) {
    var p = coreListProductMap[String(row.dkd_shohin_id)] || {};
    var fallbackPartNumber = row.core_part_number || "";
    var updatedText = formatDateTime(row.updated_at);
    html += "<tr>";
    html += "<td><div class='core-main-pn'>" + esc(row.core_part_number || "-") + "</div><div class='mgmt-sub'>" + esc(productionCategoryLabel(p)) + "</div></td>";
    html += "<td><span class='core-maker-badge'>" + esc(p.manufacturer || "-") + "</span></td>";
    html += "<td><div class='mgmt-pn'>" + esc(p.genuine_part_number || fallbackPartNumber || "-") + "</div><div class='mgmt-sub'>" + esc(p.manufacturer_part_number || fallbackPartNumber || "-") + " / DKD " + esc(String(row.dkd_shohin_id || "-")) + "</div></td>";
    html += "<td><span class='core-qty-pill'>" + esc(String(row.quantity == null ? 0 : row.quantity)) + "</span></td>";
    html += "<td>" + esc(row.location || "-") + "</td>";
    html += "<td><div class='core-note'>" + esc(row.note || "-") + "</div><div class='mgmt-sub'>" + esc(updatedText) + "</div></td>";
    html += "<td><div class='mgmt-actions'>";
    html += "<button class='btn-sm-edit production-action-secondary' data-core-image='" + row.id + "'>" + esc(t("btn_upload")) + "</button>";
    html += "<button class='btn-sm-edit' data-core-edit='" + row.id + "'>" + t("btn_edit") + "</button>";
    html += "<button class='btn-sm-del' data-core-del='" + row.id + "'>" + t("btn_delete") + "</button>";
    html += "</div></td>";
    html += "</tr>";
  });
  html += "</table>";
  list.innerHTML = html;
  if (!canUploadCoreImages()) {
    list.querySelectorAll("[data-core-image]").forEach(function(btn) { btn.remove(); });
  } else {
    list.querySelectorAll("[data-core-image]").forEach(function(btn) {
      btn.addEventListener("click", function() { openCorePhotoChoice(parseInt(btn.dataset.coreImage, 10)); });
    });
  }
  if (!canManageProductionRecords()) {
    list.querySelectorAll("[data-core-edit], [data-core-del]").forEach(function(btn) { btn.remove(); });
    if (countEl) {
      var readonlyTotalQty = sumProductionCoreEntryQty(coreListMgmtRows);
      countEl.innerHTML = esc(String(coreListMgmtRows.length)) + " 件 <span class='core-count-pill'>コア合計 " + esc(String(readonlyTotalQty)) + "</span>";
    }
    return;
  }

  list.querySelectorAll("[data-core-edit]").forEach(function(btn) {
    btn.addEventListener("click", function() { openCoreListForm("edit", parseInt(btn.dataset.coreEdit, 10)); });
  });
  list.querySelectorAll("[data-core-del]").forEach(function(btn) {
    btn.addEventListener("click", function() { deleteCoreListRow(parseInt(btn.dataset.coreDel, 10)); });
  });
  if (countEl) {
    var totalQty = sumProductionCoreEntryQty(coreListMgmtRows);
    countEl.innerHTML = esc(String(coreListMgmtRows.length)) + " 件 <span class='core-count-pill'>コア合計 " + esc(String(totalQty)) + "</span>";
  }
}

function coreListRowAndProduct(rowId) {
  var row = coreListMgmtRows.find(function(x) { return x.id === rowId; });
  var product = row ? (coreListProductMap[String(row.dkd_shohin_id)] || {}) : {};
  return { row: row, product: product };
}

function buildCoreAiCameraUrl(rowId, mode) {
  var ctx = coreListRowAndProduct(rowId);
  var row = ctx.row;
  var p = ctx.product || {};
  var url = new URL(CORE_AI_CAMERA_TEST_URL);
  url.searchParams.set("page", "camera");
  url.searchParams.set("source", "dcats_core_list");
  url.searchParams.set("mode", mode || "core_count");
  url.searchParams.set("dcats_version", APP_VERSION);
  if (row) {
    url.searchParams.set("core_list_entry_id", String(row.id || ""));
    url.searchParams.set("dkd_shohin_id", String(row.dkd_shohin_id || ""));
    if (row.core_part_number) url.searchParams.set("core_part_number", row.core_part_number);
    if (row.quantity != null) url.searchParams.set("quantity", String(row.quantity));
    if (row.location) url.searchParams.set("location", row.location);
  }
  if (p.genuine_part_number) url.searchParams.set("genuine_part_number", p.genuine_part_number);
  if (p.manufacturer_part_number) url.searchParams.set("manufacturer_part_number", p.manufacturer_part_number);
  if (p.manufacturer) url.searchParams.set("manufacturer", p.manufacturer);
  if (p.category_code || p.category) url.searchParams.set("category", p.category_code || p.category);
  return url;
}

function openCorePhotoChoice(rowId) {
  if (!canUploadCoreImages()) { alert(t("err_perm")); return; }
  var ctx = coreListRowAndProduct(rowId);
  var row = ctx.row;
  if (!row || !row.dkd_shohin_id) {
    alert("画像登録にはDKD商品IDが必要です。");
    return;
  }
  var p = ctx.product || {};
  corePhotoChoiceRowId = rowId;
  var context = document.getElementById("core-photo-choice-context");
  if (context) {
    var title = row.core_part_number || p.manufacturer_part_number || p.genuine_part_number || ("DKD " + row.dkd_shohin_id);
    var meta = [
      p.manufacturer || "-",
      p.genuine_part_number || "-",
      p.manufacturer_part_number || "-",
      "DKD " + (row.dkd_shohin_id || "-")
    ].join(" / ");
    context.innerHTML = "<strong>" + esc(title) + "</strong>" + esc(meta);
  }
  document.getElementById("core-photo-choice-overlay").classList.add("show");
}

function closeCorePhotoChoice() {
  corePhotoChoiceRowId = null;
  document.getElementById("core-photo-choice-overlay").classList.remove("show");
}

function openCoreListCameraAi(rowId) {
  if (!canUploadCoreImages()) { alert(t("err_perm")); return; }
  var ctx = coreListRowAndProduct(rowId);
  var row = ctx.row;
  if (!row || !row.dkd_shohin_id) {
    alert("カメラAIにはDKD商品IDが必要です。");
    return;
  }
  var url = buildCoreAiCameraUrl(rowId, "core_photo_add");
  try {
    localStorage.setItem("dcats_core_camera_pending", JSON.stringify({
      mode: "core_photo_add",
      core_list_entry_id: row.id || null,
      dkd_shohin_id: row.dkd_shohin_id || null,
      core_part_number: row.core_part_number || "",
      opened_at: new Date().toISOString()
    }));
  } catch (e) {
    console.warn("core camera pending state failed", e);
  }
  closeCorePhotoChoice();
  window.open(url.toString(), "_blank", "noopener");
}

function openCoreListCameraCount(rowId) {
  if (!canUploadCoreImages()) { alert(t("err_perm")); return; }
  var row = coreListMgmtRows.find(function(x) { return x.id === rowId; });
  if (!row || !row.dkd_shohin_id) {
    alert("カメラ計数にはDKD商品IDが必要です。");
    return;
  }
  var url = buildCoreAiCameraUrl(rowId, "core_count");
  window.open(url.toString(), "_blank", "noopener");
}

function openCoreListImageUpload(rowId) {
  if (!canUploadCoreImages()) { alert(t("err_perm")); return; }
  var row = coreListMgmtRows.find(function(x) { return x.id === rowId; });
  if (!row || !row.dkd_shohin_id) {
    alert("画像登録にはDKD商品IDが必要です。");
    return;
  }
  var input = document.createElement("input");
  input.type = "file";
  input.accept = "image/*";
  input.multiple = true;
  input.setAttribute("capture", "environment");
  input.addEventListener("change", function(event) {
    uploadCoreListImages(event, rowId).catch(function(error) {
      alert("コア画像登録に失敗しました: " + ((error && error.message) || String(error)));
    });
  });
  input.click();
}

function coreImageFileExtension(file) {
  var type = String((file && file.type) || "").toLowerCase();
  if (type.indexOf("png") >= 0) return "png";
  if (type.indexOf("webp") >= 0) return "webp";
  var name = String((file && file.name) || "");
  var match = name.match(/\.([a-z0-9]{2,5})$/i);
  return match ? match[1].toLowerCase() : "jpg";
}

async function uploadCoreListImages(event, rowId) {
  if (!canUploadCoreImages()) { alert(t("err_perm")); return; }
  var files = Array.from(event.target.files || []);
  if (!files.length) return;
  var row = coreListMgmtRows.find(function(x) { return x.id === rowId; });
  if (!row || !row.dkd_shohin_id) {
    alert("画像登録にはDKD商品IDが必要です。");
    return;
  }

  var dkdId = parseInt(row.dkd_shohin_id, 10);
  if (isNaN(dkdId)) {
    alert("DKD商品IDが不正です。");
    return;
  }

  var uploaded = 0;
  for (var i = 0; i < files.length; i++) {
    var file = files[i];
    if (!file || String(file.type || "").indexOf("image/") !== 0) {
      alert("画像ファイルのみ登録できます。");
      continue;
    }
    if (file.size > 10 * 1024 * 1024) {
      alert("10MB以下の画像を選択してください: " + (file.name || ""));
      continue;
    }
    var ext = coreImageFileExtension(file);
    var path = "dkd_" + dkdId + "/used_core/core_list_" + rowId + "_" + Date.now() + "_" + Math.random().toString(36).slice(2) + "." + ext;
    var up = await sb.storage.from("product-images").upload(path, file, { upsert: false, contentType: file.type || undefined });
    if (up.error) { alert(t("err_upload") + ": " + up.error.message); continue; }
    var urlR = sb.storage.from("product-images").getPublicUrl(path);
    var dbR = await sb.from("core_product_images").insert({
      dkd_shohin_id: dkdId,
      product_kind: "used_core",
      image_url: urlR.data.publicUrl,
      storage_path: path,
      caption: row.core_part_number ? ("CORE " + row.core_part_number) : "CORE"
    });
    if (dbR.error) { alert(t("err_db") + ": " + dbR.error.message); continue; }
    uploaded += 1;
  }
  event.target.value = "";
  if (uploaded > 0) {
    await writeLog("insert", "core_product_images", dkdId, "core list image upload", null, { count: uploaded, core_list_entry_id: rowId });
    alert(uploaded + "枚のコア画像を登録しました。");
  }
}

async function openCoreListImageDelete(rowId) {
  if (!canManageUsedCoreImages()) { showPermissionDenied("delete_image", "core_product_images"); return; }
  var ctx = coreListRowAndProduct(rowId);
  var row = ctx.row;
  if (!row || !row.dkd_shohin_id) {
    alert("画像の削除にはDKD商品IDが必要です。");
    return;
  }
  var dkdId = parseInt(row.dkd_shohin_id, 10);
  if (isNaN(dkdId)) {
    alert("DKD商品IDが不正です。");
    return;
  }
  var r = await sb.from("core_product_images")
    .select("*")
    .eq("dkd_shohin_id", dkdId)
    .eq("product_kind", "used_core")
    .order("created_at", { ascending: false });
  if (r.error) {
    alert(t("msg_save_err") + ": " + r.error.message);
    return;
  }
  currentImageDeleteContext = "core_list";
  currentImageDeleteCoreListRowId = rowId;
  currentImageDeleteActivityProduct = ctx.product || {
    dkd_shohin_id: dkdId,
    core_part_number: row.core_part_number || ""
  };
  currentImages = (r.data || []).map(function(img) {
    img._activity_product = currentImageDeleteActivityProduct;
    img._core_list_entry_id = rowId;
    return img;
  }).filter(function(img) {
    return canDeleteImageTarget(img, "sales");
  });
  closeCorePhotoChoice();
  renderImageDeleteDialog();
  document.getElementById("image-delete-overlay").classList.add("show");
}

function openCoreListForm(mode, rowId) {
  if (!canManageProductionRecords()) { alert(t("err_perm")); return; }
  coreListFormMode = mode;
  var row = mode === "edit" ? coreListMgmtRows.find(function(x) { return x.id === rowId; }) : null;
  var p = row ? (coreListProductMap[String(row.dkd_shohin_id)] || {}) : {};
  document.getElementById("core-list-form-error").textContent = "";
  document.getElementById("core-list-form-title").textContent = mode === "add" ? t("btn_add_core_list") : t("core_list_edit_title");
  setProductionRankingFormValue("clf-id", row && row.id);
  setProductionRankingFormValue("clf-dkd-id", row && row.dkd_shohin_id);
  setProductionRankingFormValue("clf-core-part", row && row.core_part_number);
  setProductionRankingFormValue("clf-quantity", row ? row.quantity : 1);
  setProductionRankingFormValue("clf-location", row && row.location);
  setProductionRankingFormValue("clf-note", row && row.note);
  setProductionRankingFormValue("clf-product-search", "");
  document.getElementById("clf-product-candidates").innerHTML = "";
  document.getElementById("clf-product-info").textContent = row ? [
    "DKD " + (row.dkd_shohin_id || "-"),
    p.manufacturer_part_number || "-",
    p.genuine_part_number || "-",
    p.manufacturer || "-"
  ].join(" / ") : "";
  document.getElementById("core-list-form-overlay").classList.add("show");
}

async function searchCoreListProductCandidates() {
  var input = document.getElementById("clf-product-search");
  var wrap = document.getElementById("clf-product-candidates");
  var q = input ? input.value.trim() : "";
  if (!wrap) return;
  if (!q) {
    coreListProductCandidates = [];
    wrap.innerHTML = "";
    return;
  }
  var r = await sb.rpc("search_core_products", {
    search_text: q,
    category_filter: null,
    require_sl: false,
    max_rows: 20
  });
  if (r.error) {
    wrap.innerHTML = "<div class='candidate-empty'>" + esc(r.error.message) + "</div>";
    return;
  }
  coreListProductCandidates = r.data || [];
  if (!coreListProductCandidates.length) {
    wrap.innerHTML = "<div class='candidate-empty'>" + t("no_results") + "</div>";
    return;
  }
  wrap.innerHTML = coreListProductCandidates.map(function(p, i) {
    var title = p.manufacturer_part_number || p.genuine_part_number || p.daiko_part_number || ("DKD " + p.dkd_shohin_id);
    var meta = [
      "DKD " + (p.dkd_shohin_id || "-"),
      p.genuine_part_number || "-",
      p.manufacturer || "-",
      productionCategoryLabel(p)
    ].join(" / ");
    return "<button type='button' class='candidate-item' data-core-candidate-index='" + i + "'><strong>" + esc(title) + "</strong><small>" + esc(meta) + "</small></button>";
  }).join("");
}

function selectCoreListProductCandidate(index) {
  var p = coreListProductCandidates[index];
  if (!p) return;
  document.getElementById("clf-dkd-id").value = p.dkd_shohin_id || "";
  if (!document.getElementById("clf-core-part").value.trim()) {
    document.getElementById("clf-core-part").value = p.manufacturer_part_number || p.genuine_part_number || "";
  }
  document.getElementById("clf-product-info").textContent = [
    "DKD " + (p.dkd_shohin_id || "-"),
    p.manufacturer_part_number || "-",
    p.genuine_part_number || "-",
    p.manufacturer || "-"
  ].join(" / ");
  document.getElementById("clf-product-candidates").innerHTML = "";
}

async function saveCoreListForm() {
  var errEl = document.getElementById("core-list-form-error");
  errEl.textContent = "";
  if (!canManageProductionRecords()) { errEl.textContent = t("err_perm"); return; }
  var dkdId = nullableIntFromInput("clf-dkd-id");
  var qty = nullableIntFromInput("clf-quantity");
  if (!dkdId) { errEl.textContent = "DKD商品IDは必須です"; return; }
  if (qty == null || qty < 0) { errEl.textContent = "数量は0以上で入力してください"; return; }
  var data = {
    dkd_shohin_id: dkdId,
    core_part_number: nullableTextFromInput("clf-core-part"),
    quantity: qty,
    location: nullableTextFromInput("clf-location"),
    note: nullableTextFromInput("clf-note"),
    updated_at: new Date().toISOString()
  };
  var id = document.getElementById("clf-id").value;
  var r;
  if (coreListFormMode === "add") {
    data.created_by = currentUser ? currentUser.id : null;
    r = await sb.from("production_core_list_entries").insert(data).select();
    if (r.error) { errEl.textContent = t("msg_part_err") + ": " + r.error.message; return; }
    var newId = (r.data && r.data[0]) ? r.data[0].id : null;
    await writeLog("insert", "production_core_list_entries", newId, "DKD " + dkdId, null, data);
  } else {
    var before = coreListMgmtRows.find(function(x) { return x.id === parseInt(id, 10); });
    r = await sb.from("production_core_list_entries").update(data).eq("id", id);
    if (r.error) { errEl.textContent = t("msg_part_err") + ": " + r.error.message; return; }
    await writeLog("update", "production_core_list_entries", parseInt(id, 10), "DKD " + dkdId, before, data);
  }
  document.getElementById("core-list-form-overlay").classList.remove("show");
  productionLoaded = false;
  await loadCoreListMgmt();
}

async function createCoreListFromRanking() {
  if (!canManageProductionRecords()) { alert(t("err_perm")); return; }
  var btn = document.getElementById("btn-create-core-list-from-ranking");
  if (btn) btn.disabled = true;
  try {
    var targetText = prompt("製造ランキングの商品について、確保したいコア在庫数を入力してください。", "1");
    if (targetText == null) return;
    var targetQty = parseInt(targetText, 10);
    if (isNaN(targetQty) || targetQty < 0) {
      alert("目標数は0以上の整数で入力してください。");
      return;
    }
    var existing = await sb.from("core_collection_list_items").select("dkd_shohin_id, sort_order").limit(10000);
    if (existing.error) { alert(t("msg_part_err") + ": " + existing.error.message); return; }
    var existingIds = {};
    var nextSortOrder = 1;
    (existing.data || []).forEach(function(row) {
      if (row.dkd_shohin_id != null) existingIds[String(row.dkd_shohin_id)] = true;
      var sortOrder = parseInt(row.sort_order, 10);
      if (!isNaN(sortOrder)) nextSortOrder = Math.max(nextSortOrder, sortOrder + 1);
    });
    var src = await sb.from("production_instruction_candidates")
      .select("dkd_shohin_id, priority_rank, source_year")
      .not("dkd_shohin_id", "is", null)
      .order("priority_rank", { ascending: true })
      .limit(500);
    if (src.error) { alert(t("msg_part_err") + ": " + src.error.message); return; }
    var rows = [];
    (src.data || []).forEach(function(row) {
      var key = String(row.dkd_shohin_id);
      if (existingIds[key]) return;
      existingIds[key] = true;
      var rank = parseInt(row.priority_rank || 0, 10) || 0;
      rows.push({
        dkd_shohin_id: row.dkd_shohin_id,
        target_quantity: targetQty,
        priority: rank > 0 && rank <= 30 ? "high" : (rank > 100 ? "low" : "normal"),
        status: "collecting",
        source_hint: "製造ランキング",
        sort_order: nextSortOrder++,
        source_type: "production",
        source_rank: rank || null,
        shipment_count: null,
        note: [rank ? "順位 #" + rank : "", row.source_year ? String(row.source_year) + "年度" : ""].filter(Boolean).join(" / ") || null,
        created_by: currentUser ? currentUser.id : null,
        updated_by: currentUser ? currentUser.id : null,
        updated_at: new Date().toISOString()
      });
    });
    if (!rows.length) {
      alert(t("core_list_no_ranking_source"));
      return;
    }
    var ins = await sb.from("core_collection_list_items").insert(rows).select("id");
    if (ins.error) { alert(t("msg_part_err") + ": " + ins.error.message); return; }
    await writeLog("insert", "core_collection_list_items", null, "ranking import", null, { count: rows.length, target_quantity: targetQty });
    alert("製造ランキングから収集対象を" + rows.length + "件追加しました。現在庫が目標数以上の商品は「目標数あり」で確認できます。");
    await loadCoreCollectionList();
  } finally {
    if (btn) btn.disabled = false;
  }
}

async function deleteCoreListRow(id) {
  if (!canManageProductionRecords()) { alert(t("err_perm")); return; }
  var row = coreListMgmtRows.find(function(x) { return x.id === id; });
  if (!confirm(t("core_list_delete_confirm"))) return;
  var r = await sb.from("production_core_list_entries").delete().eq("id", id);
  if (r.error) { alert(t("msg_part_err") + ": " + r.error.message); return; }
  await writeLog("delete", "production_core_list_entries", id, row ? ("DKD " + row.dkd_shohin_id) : String(id), row, null);
  productionLoaded = false;
  await loadCoreListMgmt();
}

// =============================================
// 在庫管理
// =============================================
function productKindStockModeTitleKey() {
  return "screen_product_kind_stock_title";
}

function productKindStockAllowedKinds() {
  return ["rebuilt", "aftermarket_new", "used_core"];
}

function productKindStockKindAllowed(kind) {
  if (!kind) return false;
  return productKindStockAllowedKinds().indexOf(normalizeProductKind(kind)) >= 0;
}

function productKindStockDefaultKindForProduct(product, selectedKind) {
  if (selectedKind && productKindStockKindAllowed(selectedKind)) return normalizeProductKind(selectedKind);
  var defaultKind = product && product.default_product_kind ? normalizeProductKind(product.default_product_kind) : "";
  if (defaultKind && productKindStockKindAllowed(defaultKind)) return defaultKind;
  return productKindStockAllowedKinds()[0] || "rebuilt";
}

function configureProductKindStockMode(mode) {
  productKindStockMode = "stock";
  var title = document.querySelector("#screen-product-kind-stock-mgmt .logo-text");
  if (title) {
    var key = productKindStockModeTitleKey();
    title.setAttribute("data-i18n", key);
    title.textContent = t(key);
  }
  var select = document.getElementById("product-kind-stock-kind");
  if (!select) return;
  var current = select.value || "";
  var html = "";
  html += "<option value=''>" + esc(t("product_kind_stock_kind_all")) + "</option>";
  productKindStockAllowedKinds().forEach(function(kind) {
    html += "<option value='" + esc(kind) + "'>" + esc(productKindLabel(kind)) + "</option>";
  });
  select.innerHTML = html;
  select.disabled = false;
  select.value = productKindStockKindAllowed(current) ? normalizeProductKind(current) : "";
}

async function enterProductKindStockMgmt() {
  if (!canViewProductKindStockMgmt()) { alert(t("err_perm")); return; }
  showScreen("product-kind-stock-mgmt");
  configureProductKindStockMode();
  var saveBtn = document.getElementById("btn-product-kind-stock-save");
  if (saveBtn) setCspStyle(saveBtn, "display", canEditProductKindStockMgmt() ? "" : "none");
  await populateProductKindStockCategoryOptions();
  renderProductKindStockEmpty();
}

function renderProductKindStockEmpty() {
  productKindStockRows = [];
  productKindStockProductMap = {};
  productKindStockDirtyMap = {};
  productKindStockComponentMetaMap = {};
  productKindStockPriceMap = {};
  productKindStockHistoryVariantId = null;
  productKindStockHistoryRows = [];
  var countEl = document.getElementById("product-kind-stock-count");
  var list = document.getElementById("product-kind-stock-list");
  renderProductKindStockHistoryHint();
  if (countEl) countEl.textContent = "";
  if (list) list.innerHTML = "<div class='empty'>" + esc(t("product_kind_stock_search_hint")) + "</div>";
}

async function populateProductKindStockCategoryOptions() {
  var select = document.getElementById("product-kind-stock-category");
  if (!select) return;
  if (!categoryOptions.length) {
    var r = await sb.from("assy_categories")
      .select("category_code,label_ja,label_en,label_zh,sort_order,is_active")
      .eq("is_active", true)
      .order("sort_order", { ascending: true });
    if (!r.error) {
      categoryOptions = (r.data || []).filter(function(cat) {
        return (cat.category_code || cat.category) !== "car_air_conditioner";
      });
    }
  }
  var current = select.value || "";
  var html = "<option value=''>" + esc(t("filter_all")) + "</option>";
  (categoryOptions || []).forEach(function(cat) {
    var code = cat.category_code || cat.category || "";
    if (!code) return;
    var label = currentLang === "en" ? (cat.label_en || cat.label_ja || code) : currentLang === "zh" ? (cat.label_zh || cat.label_ja || code) : (cat.label_ja || cat.label_en || code);
    html += "<option value='" + esc(code) + "'>" + esc(label) + "</option>";
  });
  select.innerHTML = html;
  select.value = current;
}

function applyProductKindStockVariantFilters(query, kind, state) {
  query = query.eq("is_active", true);
  var allowedKinds = productKindStockAllowedKinds();
  kind = kind ? normalizeProductKind(kind) : "";
  if (kind && allowedKinds.indexOf(kind) >= 0) query = query.eq("product_kind", kind);
  else if (allowedKinds.length) query = query.in("product_kind", allowedKinds);
  if (state === "stocked") query = query.gt("stock_qty", 0);
  if (state === "empty") query = query.or("stock_qty.is.null,stock_qty.eq.0");
  return query;
}

async function fetchProductKindStockVariantsByIds(ids, kind, state, maxRows) {
  maxRows = maxRows || 300;
  var rows = [];
  for (var i = 0; i < ids.length && rows.length < maxRows; i += 200) {
    var chunk = ids.slice(i, i + 200);
    var query = sb.from("core_product_variants")
      .select("product_variant_id,dkd_shohin_id,product_kind,sl_part_id,display_label,stock_qty,stock_location,stock_note,is_active,updated_at")
      .in("dkd_shohin_id", chunk)
      .order("dkd_shohin_id", { ascending: true })
      .order("product_kind", { ascending: true });
    query = applyProductKindStockVariantFilters(query, kind, state);
    var r = await query;
    if (r.error) return r;
    (r.data || []).forEach(function(row) {
      if (rows.length < maxRows) rows.push(row);
    });
  }
  return { data: rows, error: null };
}

async function fetchProductKindStockVariantsDirect(kind, state, maxRows) {
  var query = sb.from("core_product_variants")
    .select("product_variant_id,dkd_shohin_id,product_kind,sl_part_id,display_label,stock_qty,stock_location,stock_note,is_active,updated_at")
    .order("updated_at", { ascending: false, nullsFirst: false })
    .order("dkd_shohin_id", { ascending: true })
    .limit(maxRows || 300);
  query = applyProductKindStockVariantFilters(query, kind, state);
  return await query;
}

async function loadProductKindStockProductMap(variants, seededRows) {
  productKindStockProductMap = {};
  (seededRows || []).forEach(function(p) {
    var id = productDkdId(p);
    if (id) productKindStockProductMap[String(id)] = p;
  });
  var ids = [];
  (variants || []).forEach(function(row) {
    var id = parseInt(row.dkd_shohin_id, 10);
    if (!isNaN(id) && !productKindStockProductMap[String(id)] && ids.indexOf(id) < 0) ids.push(id);
  });
  for (var i = 0; i < ids.length; i += 200) {
    var chunk = ids.slice(i, i + 200);
    var r = await sb.from("core_products")
      .select(CORE_PRODUCT_FAST_SELECT)
      .in("dkd_shohin_id", chunk)
      .limit(chunk.length);
    if (r.error) {
      console.warn("product-kind stock product lookup failed", r.error);
      continue;
    }
    normalizeCoreProductFastRows(r.data || []).forEach(function(p) {
      var id = productDkdId(p);
      if (id) productKindStockProductMap[String(id)] = p;
    });
  }
}

function emptyProductKindComponentMeta() {
  return { count: 0, unitTotal: 0, priceKnown: false };
}

function addProductKindComponentMeta(map, key, row) {
  if (!key) return;
  if (!map[key]) map[key] = emptyProductKindComponentMeta();
  var meta = map[key];
  meta.count += 1;
  var price = parseInt(row.unit_price_jpy, 10);
  if (!isNaN(price)) {
    var qty = parseFloat(String(row.quantity || "1").replace(/[^\d.]/g, ""));
    if (isNaN(qty) || qty <= 0) qty = 1;
    meta.unitTotal += Math.round(price * qty);
    meta.priceKnown = true;
  }
}

function mergeProductKindComponentMeta(a, b) {
  var meta = emptyProductKindComponentMeta();
  a = a || {};
  b = b || {};
  meta.count = (a.count || 0) + (b.count || 0);
  meta.unitTotal = (a.unitTotal || 0) + (b.unitTotal || 0);
  meta.priceKnown = !!(a.priceKnown || b.priceKnown);
  return meta;
}

function productKindStockCommonMetaKey(dkdId, kind) {
  return "k:" + String(dkdId || "") + ":" + normalizeProductKind(kind);
}

function productKindStockVariantMetaKey(variantId) {
  return "v:" + String(variantId || "");
}

function productKindStockComponentMeta(row) {
  if (!row) return emptyProductKindComponentMeta();
  var common = productKindStockComponentMetaMap[productKindStockCommonMetaKey(row.dkd_shohin_id, row.product_kind)];
  var variant = row.product_variant_id ? productKindStockComponentMetaMap[productKindStockVariantMetaKey(row.product_variant_id)] : null;
  return mergeProductKindComponentMeta(common, variant);
}

function productKindStockPriceKey(dkdId, kind) {
  return "p:" + String(dkdId || "") + ":" + normalizeProductKind(kind);
}

function productKindStockPriceForRow(row) {
  if (!row) return null;
  var variantKey = row.product_variant_id ? productKindStockVariantMetaKey(row.product_variant_id) : "";
  return (variantKey && productKindStockPriceMap[variantKey]) ||
    productKindStockPriceMap[productKindStockPriceKey(row.dkd_shohin_id, row.product_kind)] ||
    null;
}

function productKindStockAllKinds() {
  return productKindStockAllowedKinds();
}

function productKindStockExistingKinds(dkdId) {
  var map = {};
  (productKindStockRows || []).forEach(function(row) {
    if (row.product_variant_id && String(row.dkd_shohin_id || "") === String(dkdId || "")) {
      map[normalizeProductKind(row.product_kind)] = true;
    }
  });
  return map;
}

function productKindStockAddableKinds(dkdId) {
  var existing = productKindStockExistingKinds(dkdId);
  return productKindStockAllKinds().filter(function(kind) { return !existing[kind]; });
}

function productKindStockAddDefaultKind(row, kinds) {
  kinds = kinds || [];
  var preferred = normalizeProductKind(row && (row.suggested_add_kind || row.product_kind) || "");
  if (preferred && kinds.indexOf(preferred) >= 0) return preferred;
  return kinds[0] || "";
}

function renderProductKindStockAddKindHtml(row) {
  if (!canEditProductKindStockMgmt()) return "";
  var kinds = productKindStockAddableKinds(row.dkd_shohin_id);
  if (!kinds.length) return "";
  var id = String(row.product_variant_id || row.dkd_shohin_id || "");
  var selectedKind = productKindStockAddDefaultKind(row, kinds);
  var html = "<span class='stock-mgmt-add-kind'>";
  html += "<select data-stock-add-kind-select='" + esc(id) + "' aria-label='" + esc(t("product_kind_add_select")) + "'>";
  kinds.forEach(function(kind) {
    html += "<option value='" + esc(kind) + "'" + (kind === selectedKind ? " selected" : "") + ">" + esc(productKindLabel(kind)) + "</option>";
  });
  html += "</select>";
  html += "<button class='btn-sm-edit production-action-secondary' data-stock-add-kind='" + esc(id) + "' data-stock-add-dkd='" + esc(String(row.dkd_shohin_id || "")) + "'>" + esc(t("product_kind_add")) + "</button>";
  html += "</span>";
  return html;
}

async function loadProductKindStockComponentMeta(rows) {
  productKindStockComponentMetaMap = {};
  var ids = [];
  (rows || []).forEach(function(row) {
    var id = parseInt(row.dkd_shohin_id, 10);
    if (!isNaN(id) && ids.indexOf(id) < 0) ids.push(id);
  });
  for (var i = 0; i < ids.length; i += 150) {
    var chunk = ids.slice(i, i + 150);
    var r = await sb.from("assembly_component_usages")
      .select("dkd_shohin_id,product_kind,product_variant_id,quantity,unit_price_jpy,is_catalog_evidence")
      .in("dkd_shohin_id", chunk)
      .limit(10000);
    if (r.error) {
      console.warn("product-kind component meta lookup failed", r.error);
      continue;
    }
    (r.data || []).forEach(function(row) {
      var kind = normalizeProductKind(row.product_kind || "rebuilt");
      if (row.product_variant_id) {
        addProductKindComponentMeta(productKindStockComponentMetaMap, productKindStockVariantMetaKey(row.product_variant_id), row);
      } else {
        addProductKindComponentMeta(productKindStockComponentMetaMap, productKindStockCommonMetaKey(row.dkd_shohin_id, kind), row);
      }
    });
  }
}

async function loadProductKindStockPriceMeta(rows) {
  productKindStockPriceMap = {};
  if (!canViewBasePrice()) return;
  var ids = [];
  (rows || []).forEach(function(row) {
    var id = parseInt(row.dkd_shohin_id, 10);
    if (!isNaN(id) && ids.indexOf(id) < 0) ids.push(id);
  });
  for (var i = 0; i < ids.length; i += 150) {
    var chunk = ids.slice(i, i + 150);
    var r = await sb.from("product_base_prices")
      .select("id,dkd_shohin_id,product_kind,product_variant_id,base_price_jpy,price_basis,basis_note,effective_start,is_current")
      .in("dkd_shohin_id", chunk)
      .eq("is_current", true);
    if (r.error) {
      console.warn("product-kind base price lookup failed", r.error);
      continue;
    }
    (r.data || []).forEach(function(row) {
      var kind = normalizeProductKind(row.product_kind || "rebuilt");
      if (row.product_variant_id) productKindStockPriceMap[productKindStockVariantMetaKey(row.product_variant_id)] = row;
      if (!row.product_variant_id) productKindStockPriceMap[productKindStockPriceKey(row.dkd_shohin_id, kind)] = row;
    });
  }
}

function sortProductKindStockRows(rows) {
  return (rows || []).slice().sort(function(a, b) {
    var pa = productKindStockProductMap[String(a.dkd_shohin_id)] || {};
    var pb = productKindStockProductMap[String(b.dkd_shohin_id)] || {};
    var ak = [
      productCategoryLabel(pa),
      pa.manufacturer || "",
      pa.genuine_part_number || "",
      pa.manufacturer_part_number || ""
    ].join("|");
    var bk = [
      productCategoryLabel(pb),
      pb.manufacturer || "",
      pb.genuine_part_number || "",
      pb.manufacturer_part_number || ""
    ].join("|");
    var base = ak.localeCompare(bk);
    if (base) return base;
    return productKindSortValue(a.product_kind) - productKindSortValue(b.product_kind);
  });
}

function productKindStockRowKey(row) {
  if (!row) return "";
  if (row.product_variant_id) return String(row.product_variant_id);
  return "new-" + String(row.dkd_shohin_id || "") + "-" + normalizeProductKind(row.product_kind || "rebuilt");
}

function productKindStockRowByKey(key) {
  key = String(key || "");
  var id = parseInt(key, 10);
  if (!isNaN(id)) {
    return (productKindStockRows || []).find(function(row) {
      return parseInt(row.product_variant_id, 10) === id;
    }) || null;
  }
  return (productKindStockRows || []).find(function(row) {
    return productKindStockRowKey(row) === key;
  }) || null;
}

function addProductKindStockVirtualRow(dkdId, kind) {
  kind = normalizeProductKind(kind || "rebuilt");
  productKindStockRows.push({
    product_variant_id: null,
    dkd_shohin_id: dkdId,
    product_kind: kind,
    suggested_add_kind: kind,
    sl_part_id: null,
    display_label: "",
    stock_qty: null,
    stock_location: "",
    stock_note: "",
    is_active: false,
    updated_at: null,
    is_virtual: true
  });
}

async function loadProductKindStockMgmt() {
  if (!canViewProductKindStockMgmt()) { alert(t("err_perm")); return; }
  var list = document.getElementById("product-kind-stock-list");
  var countEl = document.getElementById("product-kind-stock-count");
  if (list) list.innerHTML = "<div class='loading'>" + t("loading") + "</div>";
  if (countEl) countEl.textContent = t("loading");
  productKindStockDirtyMap = {};
  productKindStockHistoryVariantId = null;
  productKindStockHistoryRows = [];
  renderProductKindStockHistoryHint();

  var rawQ = document.getElementById("product-kind-stock-search").value.trim();
  var q = normalizeAsciiWidth(rawQ).trim();
  var category = document.getElementById("product-kind-stock-category").value || "";
  var kind = document.getElementById("product-kind-stock-kind").value || "";
  kind = kind && productKindStockKindAllowed(kind) ? normalizeProductKind(kind) : "";
  var state = document.getElementById("product-kind-stock-state").value || "";
  var productRows = [];
  var productIds = [];
  var variants;

  if (q || category) {
    var pr = q ? await fetchCoreProductMasterMatches(q, category || null, 300) : await fetchCategoryProducts(category, 300);
    if (pr.error) {
      if (list) list.innerHTML = "<div class='empty'>" + esc(t("msg_part_err") + ": " + pr.error.message) + "</div>";
      if (countEl) countEl.textContent = "";
      return;
    }
    productRows = normalizeCoreProductFastRows(pr.data || []);
    productRows.forEach(function(p) {
      var id = productDkdId(p);
      if (id && productIds.indexOf(id) < 0) productIds.push(id);
    });
    var variantFetchLimit = Math.max(300, productIds.length * productKindStockAllowedKinds().length);
    variants = productIds.length ? await fetchProductKindStockVariantsByIds(productIds, kind, state, variantFetchLimit) : { data: [], error: null };
  } else {
    variants = await fetchProductKindStockVariantsDirect(kind, state, 300);
  }

  if (variants.error) {
    if (list) list.innerHTML = "<div class='empty'>" + esc(t("msg_part_err") + ": " + variants.error.message) + "</div>";
    if (countEl) countEl.textContent = "";
    return;
  }

  productKindStockRows = variants.data || [];
  if (productRows.length && state !== "stocked") {
    var existingRowsForVirtual = productKindStockRows;
    if (state) {
      var existingAll = productIds.length ? await fetchProductKindStockVariantsByIds(productIds, kind, "", Math.max(300, productIds.length * productKindStockAllowedKinds().length)) : { data: [], error: null };
      if (!existingAll.error) existingRowsForVirtual = existingAll.data || [];
    }
    var hasVariant = {};
    existingRowsForVirtual.forEach(function(row) {
      if (row.product_variant_id) {
        hasVariant[String(row.dkd_shohin_id || "") + "|" + normalizeProductKind(row.product_kind)] = true;
      }
    });
    var targetKinds = kind ? [kind] : productKindStockAllowedKinds();
    productRows.forEach(function(p) {
      var id = productDkdId(p);
      if (!id) return;
      targetKinds.forEach(function(targetKind) {
        var key = String(id) + "|" + normalizeProductKind(targetKind);
        if (hasVariant[key]) return;
        addProductKindStockVirtualRow(id, targetKind);
      });
    });
  }
  await loadProductKindStockProductMap(productKindStockRows, productRows);
  productKindStockComponentMetaMap = {};
  productKindStockPriceMap = {};
  productKindStockRows = sortProductKindStockRows(productKindStockRows);
  renderProductKindStockMgmt();
}

function productKindStockInputValue(variantId, field) {
  var el = document.querySelector("[data-stock-variant='" + String(variantId) + "'][data-stock-field='" + field + "']");
  return el ? el.value : "";
}

function productKindStockRowPayload(variantId) {
  var qtyText = productKindStockInputValue(variantId, "stock_qty").trim();
  var qty = qtyText === "" ? 0 : parseInt(qtyText, 10);
  if (isNaN(qty) || qty < 0 || String(qty) !== String(qtyText === "" ? 0 : Number(qtyText))) {
    return { error: t("product_kind_stock_invalid_qty") };
  }
  return {
    stock_qty: qty,
    stock_location: productKindStockInputValue(variantId, "stock_location").trim() || null,
    stock_note: productKindStockInputValue(variantId, "stock_note").trim() || null
  };
}

function markProductKindStockDirty(variantId) {
  if (!canEditProductKindStockMgmt()) return;
  if (!variantId) return;
  productKindStockDirtyMap[String(variantId)] = true;
  var row = document.querySelector("[data-stock-row='" + String(variantId) + "']");
  if (row) row.classList.add("dirty");
  updateProductKindStockCount();
}

function updateProductKindStockCount() {
  var countEl = document.getElementById("product-kind-stock-count");
  if (!countEl) return;
  countEl.textContent = tf("product_kind_stock_count", {
    n: productKindStockRows.length,
    m: Object.keys(productKindStockDirtyMap).length
  });
}

function renderProductKindStockMgmt() {
  var list = document.getElementById("product-kind-stock-list");
  if (!list) return;
  updateProductKindStockCount();
  if (!productKindStockRows.length) {
    list.innerHTML = "<div class='empty'>" + esc(t("no_results")) + "</div>";
    return;
  }

  var editable = canEditProductKindStockMgmt();
  var html = "<div class='stock-mgmt-table-wrap'><table class='mgmt-table stock-mgmt-table'>";
  html += "<tr><th>" + esc(t("f_genuine_pn")) + "</th><th>" + esc(t("f_mfr_pn")) + "</th><th>" + esc(t("f_manufacturer")) + "</th><th>" + esc(t("inventory_kind_section")) + "</th>";
  html += "<th>" + esc(t("product_kind_stock_qty")) + "</th><th>" + esc(t("product_kind_stock_location")) + "</th><th>" + esc(t("product_kind_stock_note")) + "</th><th>" + esc(t("component_actions")) + "</th></tr>";
  productKindStockRows.forEach(function(row) {
    var variantId = row.product_variant_id;
    var rowKey = productKindStockRowKey(row);
    var p = productKindStockProductMap[String(row.dkd_shohin_id)] || {};
    var kind = normalizeProductKind(row.product_kind);
    var sl = row.sl_part_id ? (t("product_kind_sl") + " " + row.sl_part_id) : "";
    var hasVariant = !!variantId;
    var disabled = editable ? "" : " disabled";
    html += "<tr class='stock-mgmt-row' data-stock-row='" + esc(rowKey) + "'>";
    html += "<td><div class='mgmt-pn'>" + esc(p.genuine_part_number || "-") + "</div><div class='mgmt-sub'>DKD " + esc(String(row.dkd_shohin_id || "-")) + "</div></td>";
    html += "<td><div class='mgmt-pn'>" + esc(p.manufacturer_part_number || "-") + "</div><div class='mgmt-sub'>" + esc(productCategoryLabel(p) || "-") + "</div></td>";
    html += "<td>" + esc(p.manufacturer || "-") + "</td>";
    html += "<td><div class='stock-mgmt-kind'><span class='product-kind-pill " + productKindClass(kind) + "'>" + esc(productKindLabel(kind)) + "</span><span class='mgmt-sub'>" + esc(row.display_label || sl || "-") + "</span></div></td>";
    html += "<td><input class='stock-mgmt-input stock-mgmt-qty' type='number' min='0' step='1' data-stock-variant='" + esc(rowKey) + "' data-stock-field='stock_qty' value='" + esc(row.stock_qty == null ? "0" : String(row.stock_qty)) + "'" + disabled + "></td>";
    html += "<td><input class='stock-mgmt-input' type='text' data-stock-variant='" + esc(rowKey) + "' data-stock-field='stock_location' value='" + esc(row.stock_location || "") + "'" + disabled + "></td>";
    html += "<td><input class='stock-mgmt-input' type='text' data-stock-variant='" + esc(rowKey) + "' data-stock-field='stock_note' value='" + esc(row.stock_note || "") + "'" + disabled + "><div class='mgmt-sub'>" + esc(formatDateTime(row.updated_at)) + "</div></td>";
    html += "<td><div class='stock-mgmt-actions'>";
    if (editable) html += "<button class='btn-sm-edit' data-stock-save-row='" + esc(rowKey) + "'>" + esc(t("product_kind_stock_save")) + "</button>";
    html += "</div></td>";
    html += "</tr>";
  });
  html += "</table></div>";
  list.innerHTML = html;

  if (editable) {
    list.querySelectorAll("[data-stock-field]").forEach(function(input) {
      input.addEventListener("input", function() { markProductKindStockDirty(input.dataset.stockVariant); });
    });
    list.querySelectorAll("[data-stock-save-row]").forEach(function(btn) {
      btn.addEventListener("click", function() { saveProductKindStockRow(btn.dataset.stockSaveRow); });
    });
  }
  list.querySelectorAll("[data-stock-open-components]").forEach(function(btn) {
    btn.addEventListener("click", function() { openProductKindStockComponents(btn.dataset.stockOpenComponents); });
  });
  list.querySelectorAll("[data-stock-open-history]").forEach(function(btn) {
    btn.addEventListener("click", function() { loadProductKindStockHistory(btn.dataset.stockOpenHistory); });
  });
  list.querySelectorAll("[data-stock-open-price]").forEach(function(btn) {
    btn.addEventListener("click", function() { openProductKindStockSalesPricing(btn.dataset.stockOpenPrice); });
  });
  list.querySelectorAll("[data-stock-add-kind]").forEach(function(btn) {
    btn.addEventListener("click", function() { addProductKindStockVariant(btn.dataset.stockAddKind, btn.dataset.stockAddDkd); });
  });
}

function renderProductKindStockHistoryHint() {
  var wrap = document.getElementById("product-kind-stock-history");
  if (!wrap) return;
  wrap.className = "stock-history-panel empty";
  wrap.innerHTML = esc(t("product_kind_stock_history_hint"));
}

function productKindStockRowByVariantId(variantId) {
  var id = parseInt(variantId, 10);
  if (isNaN(id)) return null;
  return productKindStockRows.find(function(row) {
    return parseInt(row.product_variant_id, 10) === id;
  }) || null;
}

function stockMovementTypeLabel(type) {
  type = String(type || "");
  if (type === "receipt") return t("stock_movement_receipt");
  if (type === "shipment") return t("stock_movement_shipment");
  if (type === "production_complete") return t("stock_movement_production_complete");
  if (type === "production_use") return t("stock_movement_production_use");
  if (type === "inventory_adjustment") return t("stock_movement_inventory_adjustment");
  if (type === "manual_set") return t("stock_movement_manual_set");
  return type || "-";
}

function stockMovementDeltaHtml(delta) {
  var n = parseInt(delta, 10);
  if (isNaN(n)) return "-";
  var cls = n > 0 ? " plus" : (n < 0 ? " minus" : "");
  var text = (n > 0 ? "+" : "") + String(n);
  return "<span class='stock-history-delta" + cls + "'>" + esc(text) + "</span>";
}

function renderProductKindStockHistoryPanel(row, loading) {
  var wrap = document.getElementById("product-kind-stock-history");
  if (!wrap) return;
  if (!row) {
    renderProductKindStockHistoryHint();
    return;
  }
  var p = productKindStockProductMap[String(row.dkd_shohin_id)] || {};
  var currentQty = row.stock_qty == null ? 0 : (parseInt(row.stock_qty, 10) || 0);
  var title = [p.genuine_part_number || "-", p.manufacturer_part_number || "-", p.manufacturer || "-"].join(" / ");
  wrap.className = "stock-history-panel";
  var html = "<div class='stock-history-head'>";
  html += "<div><div class='stock-history-title'>" + esc(t("product_kind_stock_history")) + "</div><div class='stock-history-sub'>" + esc(title) + "<br>" + esc(productKindLabel(row.product_kind)) + "</div></div>";
  html += "<div class='stock-history-current'><span>" + esc(t("product_kind_stock_current")) + " " + esc(String(currentQty)) + "</span><span>" + esc(t("product_kind_stock_location")) + " " + esc(row.stock_location || "-") + "</span></div>";
  html += "</div>";
  if (canEditProductKindStockMgmt()) {
    html += "<div class='stock-history-form'>";
    html += "<div><label>" + esc(t("product_kind_stock_movement_type")) + "</label><select id='stock-history-movement-type'>" +
      "<option value='receipt'>" + esc(t("stock_movement_receipt")) + "</option>" +
      "<option value='shipment'>" + esc(t("stock_movement_shipment")) + "</option>" +
      "<option value='production_complete'>" + esc(t("stock_movement_production_complete")) + "</option>" +
      "<option value='production_use'>" + esc(t("stock_movement_production_use")) + "</option>" +
      "</select></div>";
    html += "<div><label>" + esc(t("product_kind_stock_movement_qty")) + "</label><input id='stock-history-movement-qty' type='number' min='1' step='1' value='1'></div>";
    html += "<div class='stock-history-note-field'><label>" + esc(t("product_kind_stock_movement_note")) + "</label><input id='stock-history-movement-note' type='text'></div>";
    html += "<div><button class='btn-primary' id='btn-stock-history-apply' type='button'>" + esc(t("product_kind_stock_movement_apply")) + "</button></div>";
    html += "</div>";
  }
  if (loading) {
    html += "<div class='loading'>" + esc(t("loading")) + "</div>";
  } else if (!productKindStockHistoryRows.length) {
    html += "<div class='empty' data-dcats-inline-style='s-7be3925bdca3'>" + esc(t("product_kind_stock_history_empty")) + "</div>";
  } else {
    html += "<div class='stock-history-table-wrap'><table class='stock-history-table'><tr><th>" + esc(t("created_at")) + "</th><th>" + esc(t("product_kind_stock_movement_type")) + "</th><th>" + esc(t("product_kind_stock_delta_after")) + "</th><th>" + esc(t("product_kind_stock_location")) + "</th><th>" + esc(t("product_kind_stock_movement_note")) + "</th></tr>";
    productKindStockHistoryRows.forEach(function(mv) {
      html += "<tr>";
      html += "<td>" + esc(formatDateTime(mv.created_at)) + "</td>";
      html += "<td>" + esc(stockMovementTypeLabel(mv.movement_type)) + "</td>";
      html += "<td>" + stockMovementDeltaHtml(mv.quantity_delta) + " / " + esc(String(mv.stock_qty_after == null ? "-" : mv.stock_qty_after)) + "</td>";
      html += "<td>" + esc(mv.stock_location || "-") + "</td>";
      html += "<td>" + esc(mv.note || "-") + "</td>";
      html += "</tr>";
    });
    html += "</table></div>";
  }
  wrap.innerHTML = html;
  var btn = document.getElementById("btn-stock-history-apply");
  if (btn) btn.addEventListener("click", function() { applyProductKindStockMovement(row.product_variant_id); });
}

async function loadProductKindStockHistory(variantId) {
  var row = productKindStockRowByVariantId(variantId);
  if (!row) return;
  productKindStockHistoryVariantId = parseInt(variantId, 10);
  productKindStockHistoryRows = [];
  renderProductKindStockHistoryPanel(row, true);
  var r = await sb.from("core_product_variant_stock_movements")
    .select("id,product_variant_id,dkd_shohin_id,product_kind,movement_type,quantity_delta,stock_qty_after,stock_location,note,created_at")
    .eq("product_variant_id", productKindStockHistoryVariantId)
    .order("created_at", { ascending: false })
    .limit(50);
  if (r.error) {
    productKindStockHistoryRows = [];
    renderProductKindStockHistoryPanel(row, false);
    alert(t("msg_part_err") + ": " + r.error.message);
    return;
  }
  productKindStockHistoryRows = r.data || [];
  renderProductKindStockHistoryPanel(row, false);
  var wrap = document.getElementById("product-kind-stock-history");
  if (wrap && wrap.scrollIntoView) wrap.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

async function applyProductKindStockMovement(variantId) {
  if (!canEditProductKindStockMgmt()) { alert(t("err_perm")); return; }
  var row = productKindStockRowByVariantId(variantId);
  if (!row) return;
  var typeEl = document.getElementById("stock-history-movement-type");
  var qtyEl = document.getElementById("stock-history-movement-qty");
  var noteEl = document.getElementById("stock-history-movement-note");
  var movementType = typeEl ? (typeEl.value || "receipt") : "receipt";
  var qty = qtyEl ? parseInt(qtyEl.value, 10) : NaN;
  if (isNaN(qty) || qty <= 0) {
    alert(t("product_kind_stock_movement_invalid_qty"));
    return;
  }
  var currentQty = row.stock_qty == null ? 0 : (parseInt(row.stock_qty, 10) || 0);
  var sign = (movementType === "shipment" || movementType === "production_use") ? -1 : 1;
  var newQty = currentQty + sign * qty;
  if (newQty < 0) {
    alert(t("product_kind_stock_movement_negative"));
    return;
  }
  var btn = document.getElementById("btn-stock-history-apply");
  if (btn) btn.disabled = true;
  var before = Object.assign({}, row);
  try {
    var r = await sb.rpc("set_core_product_variant_stock", {
      target_product_variant_id: parseInt(variantId, 10),
      new_stock_qty: newQty,
      target_stock_location: row.stock_location || null,
      target_stock_note: row.stock_note || null,
      target_movement_type: movementType,
      target_note: noteEl ? (noteEl.value.trim() || null) : null
    });
    if (r.error) throw r.error;
    var saved = Array.isArray(r.data) ? (r.data[0] || null) : r.data;
    row.stock_qty = saved && saved.stock_qty != null ? saved.stock_qty : newQty;
    row.stock_location = saved ? (saved.stock_location || "") : (row.stock_location || "");
    row.stock_note = saved ? (saved.stock_note || "") : (row.stock_note || "");
    row.updated_at = new Date().toISOString();
    await writeLog("update", "core_product_variants", variantId, stockMovementTypeLabel(movementType), before, {
      stock_qty: row.stock_qty,
      movement_type: movementType,
      quantity_delta: sign * qty
    });
    renderProductKindStockMgmt();
    await loadProductKindStockHistory(variantId);
    alert(t("product_kind_stock_movement_saved"));
  } catch (e) {
    alert(t("msg_save_err") + ": " + ((e && e.message) || String(e)));
  } finally {
    if (btn) btn.disabled = false;
  }
}

async function productKindStockProductForRow(row) {
  if (!row) return null;
  var p = productKindStockProductMap[String(row.dkd_shohin_id)] || null;
  if (p && productDkdId(p)) return p;
  var r = await sb.from("core_products")
    .select(CORE_PRODUCT_FAST_SELECT)
    .eq("dkd_shohin_id", row.dkd_shohin_id)
    .maybeSingle();
  if (r.error || !r.data) {
    alert(t("msg_part_err") + ": " + (r.error ? r.error.message : "not found"));
    return null;
  }
  p = normalizeCoreProductFastRows([r.data])[0];
  productKindStockProductMap[String(row.dkd_shohin_id)] = p;
  return p;
}

async function openProductKindStockComponents(variantId) {
  var id = parseInt(variantId, 10);
  if (isNaN(id)) return;
  var row = productKindStockRows.find(function(x) { return parseInt(x.product_variant_id, 10) === id; });
  if (!row) return;
  var p = await productKindStockProductForRow(row);
  if (!p) return;
  currentProduct = p;
  currentCoreDkdShohinId = productDkdId(p);
  currentProductSpecs = [];
  currentProductNominalSpec = null;
  currentImages = [];
  currentSelectedProductKind = normalizeProductKind(row.product_kind);
  currentSelectedComponentVariantId = row.product_variant_id ? String(row.product_variant_id) : "";
  await enterComponentsScreen("product-kind-stock-mgmt");
}

async function openProductKindStockSalesPricing(variantId) {
  if (!canViewSalesPricing()) { alert(t("err_perm")); return; }
  var id = parseInt(variantId, 10);
  if (isNaN(id)) return;
  var row = productKindStockRows.find(function(x) { return parseInt(x.product_variant_id, 10) === id; });
  if (!row) return;
  var p = await productKindStockProductForRow(row);
  if (!p) return;
  currentProduct = p;
  currentCoreDkdShohinId = productDkdId(p);
  currentProductVariants = await fetchProductVariantsByDkdId(row.dkd_shohin_id);
  currentSelectedProductKind = normalizeProductKind(row.product_kind);
  currentSalesPricingProductKind = currentSelectedProductKind;
  await openSalesPricingForCurrent();
}

async function addProductKindStockVariant(selectKey, dkdId) {
  if (!canEditProductKindStockMgmt()) { alert(t("err_perm")); return; }
  var select = document.querySelector("[data-stock-add-kind-select='" + String(selectKey || "") + "']");
  var rawKind = select ? select.value : "";
  if (!rawKind || !productKindStockKindAllowed(rawKind)) return;
  var kind = normalizeProductKind(rawKind);
  var dkd = parseInt(dkdId, 10);
  if (isNaN(dkd) || !kind) return;
  var existing = await sb.from("core_product_variants")
    .select("product_variant_id")
    .eq("dkd_shohin_id", dkd)
    .eq("product_kind", kind)
    .eq("is_active", true)
    .limit(1);
  if (existing.error) {
    alert(t("msg_save_err") + ": " + existing.error.message);
    return;
  }
  if ((existing.data || []).length) {
    await loadProductKindStockMgmt();
    return;
  }
  var payload = {
    dkd_shohin_id: dkd,
    product_kind: kind,
    display_label: null,
    stock_qty: 0,
    stock_location: null,
    stock_note: null,
    core_return_required: coreReturnRequiredDefault(kind),
    core_charge_jpy: null,
    is_active: true
  };
  var r = await sb.from("core_product_variants")
    .insert(payload)
    .select("product_variant_id")
    .single();
  if (r.error) {
    alert(t("msg_save_err") + ": " + r.error.message);
    return;
  }
  await writeLog("insert", "core_product_variants", r.data && r.data.product_variant_id, productKindLabel(kind), null, payload);
  await loadProductKindStockMgmt();
}

async function ensureProductKindStockVariant(row, options) {
  options = options || {};
  if (!row) return null;
  var existingId = parseInt(row.product_variant_id, 10);
  if (!isNaN(existingId)) return existingId;
  var dkd = parseInt(row.dkd_shohin_id, 10);
  var kind = normalizeProductKind(row.product_kind || "rebuilt");
  if (isNaN(dkd) || !productKindStockKindAllowed(kind)) return null;

  var existing = await sb.from("core_product_variants")
    .select("product_variant_id,stock_qty,stock_location,stock_note,display_label,sl_part_id,updated_at")
    .eq("dkd_shohin_id", dkd)
    .eq("product_kind", kind)
    .eq("is_active", true)
    .limit(1);
  if (existing.error) {
    if (options.silent) throw new Error(existing.error.message);
    alert(t("msg_save_err") + ": " + existing.error.message);
    return null;
  }
  if ((existing.data || []).length) {
    var found = existing.data[0];
    row.product_variant_id = found.product_variant_id;
    row.stock_qty = found.stock_qty;
    row.stock_location = found.stock_location || "";
    row.stock_note = found.stock_note || "";
    row.display_label = found.display_label || row.display_label || "";
    row.sl_part_id = found.sl_part_id || row.sl_part_id || null;
    row.updated_at = found.updated_at || row.updated_at || null;
    row.is_virtual = false;
    row.is_active = true;
    return parseInt(found.product_variant_id, 10);
  }

  var payload = {
    dkd_shohin_id: dkd,
    product_kind: kind,
    display_label: null,
    stock_qty: 0,
    stock_location: null,
    stock_note: null,
    core_return_required: coreReturnRequiredDefault(kind),
    core_charge_jpy: null,
    is_active: true
  };
  var r = await sb.from("core_product_variants")
    .insert(payload)
    .select("product_variant_id")
    .single();
  if (r.error) {
    if (options.silent) throw new Error(r.error.message);
    alert(t("msg_save_err") + ": " + r.error.message);
    return null;
  }
  row.product_variant_id = r.data && r.data.product_variant_id;
  row.stock_qty = 0;
  row.stock_location = "";
  row.stock_note = "";
  row.is_virtual = false;
  row.is_active = true;
  row.updated_at = new Date().toISOString();
  await writeLog("insert", "core_product_variants", row.product_variant_id, productKindLabel(kind), null, payload);
  return parseInt(row.product_variant_id, 10);
}

async function saveProductKindStockRow(variantId, options) {
  options = options || {};
  if (!canEditProductKindStockMgmt()) {
    if (!options.silent) alert(t("err_perm"));
    return false;
  }
  var originalKey = String(variantId || "");
  var row = productKindStockRowByKey(originalKey);
  if (!row) return false;
  var payload = productKindStockRowPayload(originalKey);
  if (payload.error) {
    if (!options.silent) alert(payload.error);
    else throw new Error(payload.error);
    return false;
  }
  var before = Object.assign({}, row);
  var id = await ensureProductKindStockVariant(row, options);
  if (!id) return false;
  var r = await sb.rpc("set_core_product_variant_stock", {
    target_product_variant_id: id,
    new_stock_qty: payload.stock_qty,
    target_stock_location: payload.stock_location,
    target_stock_note: payload.stock_note,
    target_movement_type: "manual_set",
    target_note: "product-kind stock management"
  });
  if (r.error) {
    if (!options.silent) alert(t("msg_save_err") + ": " + r.error.message);
    else throw new Error(r.error.message);
    return false;
  }
  row.stock_qty = payload.stock_qty;
  row.stock_location = payload.stock_location;
  row.stock_note = payload.stock_note;
  row.updated_at = new Date().toISOString();
  if (originalKey && originalKey !== String(id)) delete productKindStockDirtyMap[originalKey];
  productKindStockDirtyMap[String(id)] = false;
  delete productKindStockDirtyMap[String(id)];
  await writeLog("update", "core_product_variants", id, productKindLabel(row.product_kind), before, payload);
  if (!options.silent) {
    renderProductKindStockMgmt();
    if (String(productKindStockHistoryVariantId || "") === String(id)) await loadProductKindStockHistory(id);
    alert(t("product_kind_stock_row_saved"));
  }
  return true;
}

async function saveProductKindStockChanges() {
  if (!canEditProductKindStockMgmt()) { alert(t("err_perm")); return; }
  var ids = Object.keys(productKindStockDirtyMap).filter(function(id) { return productKindStockDirtyMap[id]; });
  if (!ids.length) { alert(t("product_kind_stock_no_changes")); return; }
  var btn = document.getElementById("btn-product-kind-stock-save");
  if (btn) btn.disabled = true;
  var saved = 0;
  try {
    for (var i = 0; i < ids.length; i++) {
      var ok = await saveProductKindStockRow(ids[i], { silent: true });
      if (ok) saved++;
    }
    renderProductKindStockMgmt();
    alert(tf("product_kind_stock_saved_count", { n: saved }));
  } catch (e) {
    alert(t("msg_save_err") + ": " + (e.message || e));
  } finally {
    if (btn) btn.disabled = false;
  }
}

// =============================================
// 製造原価計算
// =============================================
async function enterManufacturingCostMgmt() {
  if (!canViewManufacturingCostMgmt()) { alert(t("err_perm")); return; }
  showScreen("manufacturing-cost-mgmt");
  updateAllHeaders();
  setManufacturingCostEditControls();
  loadManufacturingCostCategoryCoreCosts();
  var coreEl = document.getElementById("manufacturing-cost-core-cost");
  if (coreEl && Object.prototype.hasOwnProperty.call(manufacturingCostCategoryCoreCosts || {}, "__default")) {
    coreEl.value = manufacturingCostCategoryCoreCosts.__default;
  }
  await populateManufacturingCostCategoryOptions();
  renderManufacturingCostCategoryCoreCosts();
  await refreshManufacturingCostSavedLists();
  renderManufacturingCostCandidateEmpty("");
  renderManufacturingCostEmpty();
  var q = document.getElementById("manufacturing-cost-query");
  if (q) q.focus();
}

function renderManufacturingCostEmpty() {
  manufacturingCostRows = [];
  manufacturingCostProductMap = {};
  manufacturingCostComponentMap = {};
  manufacturingCostCorePolicyMap = {};
  manufacturingCostListItemSnapshotMap = null;
  var countEl = document.getElementById("manufacturing-cost-count");
  var summaryEl = document.getElementById("manufacturing-cost-summary");
  var listEl = document.getElementById("manufacturing-cost-list");
  if (countEl) countEl.textContent = tf("manufacturing_cost_selected_count", { n: 0 });
  if (summaryEl) summaryEl.innerHTML = "";
  if (listEl) listEl.innerHTML = "<div class='empty'>" + esc(t("manufacturing_cost_search_hint")) + "</div>";
}

function renderManufacturingCostCandidateEmpty(message) {
  manufacturingCostCandidateRows = [];
  manufacturingCostCandidateMode = "";
  manufacturingCostCandidateStatusMap = {};
  var wrap = document.getElementById("manufacturing-cost-candidates");
  if (!wrap) return;
  if (!message) {
    wrap.innerHTML = "";
    return;
  }
  wrap.innerHTML = "<div class='manufacturing-cost-candidate-panel'><div class='empty'>" + esc(message) + "</div></div>";
}

async function populateManufacturingCostCategoryOptions() {
  var select = document.getElementById("manufacturing-cost-category");
  if (!select) return;
  if (!categoryOptions.length) {
    var r = await sb.from("assy_categories")
      .select("category_code,label_ja,label_en,label_zh,sort_order,is_active")
      .eq("is_active", true)
      .order("sort_order", { ascending: true });
    if (!r.error) {
      categoryOptions = (r.data || []).filter(function(cat) {
        return (cat.category_code || cat.category) !== "car_air_conditioner";
      });
    }
  }
  var current = select.value || "";
  var html = "<option value=''>" + esc(t("filter_all")) + "</option>";
  (categoryOptions || []).forEach(function(cat) {
    var code = cat.category_code || cat.category || "";
    if (!code) return;
    var label = currentLang === "en" ? (cat.label_en || cat.label_ja || code) : currentLang === "zh" ? (cat.label_zh || cat.label_ja || code) : (cat.label_ja || cat.label_en || code);
    html += "<option value='" + esc(code) + "'>" + esc(label) + "</option>";
  });
  select.innerHTML = html;
  select.value = current;
}

function setManufacturingCostEditControls() {
  var canEditCost = canEditManufacturingCostMgmt();
  ["btn-manufacturing-cost-save-list", "btn-manufacturing-cost-delete-list", "btn-manufacturing-cost-remove-open"].forEach(function(id) {
    var el = document.getElementById(id);
    if (el) setCspStyle(el, "display", canEditCost ? "" : "none");
  });
  var nameEl = document.getElementById("manufacturing-cost-list-name");
  if (nameEl) nameEl.disabled = !canEditCost;
}

function manufacturingCostCategoryLabel(code) {
  if (!code) return t("filter_all");
  var cat = (categoryOptions || []).find(function(row) {
    return String(row.category_code || row.category || "") === String(code);
  });
  if (!cat) return tCat(code);
  return currentLang === "en" ? (cat.label_en || cat.label_ja || code) : currentLang === "zh" ? (cat.label_zh || cat.label_ja || code) : (cat.label_ja || cat.label_en || code);
}

function manufacturingCostSelectedCategory() {
  return (document.getElementById("manufacturing-cost-category") || {}).value || "";
}

function loadManufacturingCostCategoryCoreCosts() {
  try {
    var raw = localStorage.getItem(MANUFACTURING_COST_CATEGORY_CORE_STORAGE_KEY);
    var data = raw ? JSON.parse(raw) : {};
    manufacturingCostCategoryCoreCosts = {};
    Object.keys(data || {}).forEach(function(key) {
      var n = parseInt(data[key], 10);
      if (!isNaN(n) && n >= 0) manufacturingCostCategoryCoreCosts[key] = n;
    });
  } catch (e) {
    manufacturingCostCategoryCoreCosts = {};
  }
}

function saveManufacturingCostCategoryCoreCosts() {
  try {
    localStorage.setItem(MANUFACTURING_COST_CATEGORY_CORE_STORAGE_KEY, JSON.stringify(manufacturingCostCategoryCoreCosts || {}));
  } catch (e) {}
}

function manufacturingCostProductCategory(product) {
  product = product || {};
  return String(product.category_code || product.category || "");
}

function manufacturingCostCoreCostForProduct(product, settings) {
  settings = settings || manufacturingCostSettings();
  var kind = normalizeProductKind(settings.productKind || "rebuilt");
  var productId = String(productDkdId(product) || "");
  var policyRow = manufacturingCostCorePolicyMap[productId] || null;
  var policy = coreReturnPolicyForKind(kind, policyRow ? [policyRow] : []);
  if (!policy.required) {
    return {
      amount: 0,
      category: manufacturingCostProductCategory(product),
      isCategorySpecific: false,
      isProductSpecific: !!policyRow,
      returnRequired: false,
      source: policyRow ? "product" : "kind_default"
    };
  }
  if (policyRow && policy.hasProductCharge) {
    return {
      amount: policy.charge,
      category: manufacturingCostProductCategory(product),
      isCategorySpecific: false,
      isProductSpecific: true,
      returnRequired: true,
      source: "product"
    };
  }
  var category = manufacturingCostProductCategory(product);
  var categoryCosts = settings.categoryCoreCosts || {};
  if (category && Object.prototype.hasOwnProperty.call(categoryCosts, category)) {
    var categoryCost = parseInt(categoryCosts[category], 10);
    if (!isNaN(categoryCost) && categoryCost >= 0) {
      return { amount: categoryCost, category: category, isCategorySpecific: true, isProductSpecific: false, returnRequired: true, source: "category" };
    }
  }
  return { amount: settings.coreCost || 0, category: category, isCategorySpecific: false, isProductSpecific: false, returnRequired: true, source: "default" };
}

function manufacturingCostCoreCostForCategory(category, settings) {
  settings = settings || manufacturingCostSettings();
  var categoryCosts = settings.categoryCoreCosts || {};
  if (category && Object.prototype.hasOwnProperty.call(categoryCosts, category)) {
    var n = parseInt(categoryCosts[category], 10);
    if (!isNaN(n) && n >= 0) return n;
  }
  return settings.coreCost || 0;
}

function renderManufacturingCostCategoryCoreCosts() {
  var wrap = document.getElementById("manufacturing-cost-category-core-list");
  if (!wrap) return;
  var cats = (categoryOptions || []).filter(function(cat) {
    var code = cat.category_code || cat.category || "";
    return !!code && code !== "car_air_conditioner";
  });
  if (!cats.length) {
    wrap.innerHTML = "";
    return;
  }
  var html = "";
  cats.forEach(function(cat) {
    var code = cat.category_code || cat.category || "";
    var hasValue = Object.prototype.hasOwnProperty.call(manufacturingCostCategoryCoreCosts || {}, code);
    var value = hasValue ? manufacturingCostCategoryCoreCosts[code] : "";
    html += "<div class='manufacturing-cost-category-core-row'>";
    html += "<label for='manufacturing-cost-core-" + esc(code) + "'>" + esc(manufacturingCostCategoryLabel(code)) + "</label>";
    html += "<input class='form-input' id='manufacturing-cost-core-" + esc(code) + "' type='number' min='0' step='1' inputmode='numeric' data-manufacturing-cost-category-core='" + esc(code) + "' value='" + esc(String(value)) + "' placeholder='" + esc(String(manufacturingCostNumberFromInput("manufacturing-cost-core-cost", 1500))) + "'>";
    html += "</div>";
  });
  wrap.innerHTML = html;
}

function collectManufacturingCostCategoryCoreCosts() {
  var next = {};
  if (Object.prototype.hasOwnProperty.call(manufacturingCostCategoryCoreCosts || {}, "__default")) {
    next.__default = manufacturingCostCategoryCoreCosts.__default;
  }
  document.querySelectorAll("[data-manufacturing-cost-category-core]").forEach(function(input) {
    var code = input.dataset.manufacturingCostCategoryCore || "";
    var raw = String(input.value || "").replace(/,/g, "").trim();
    if (!code || raw === "") return;
    var n = parseInt(raw, 10);
    if (!isNaN(n) && n >= 0) next[code] = n;
  });
  manufacturingCostCategoryCoreCosts = next;
  saveManufacturingCostCategoryCoreCosts();
}

function persistManufacturingCostDefaultCoreCost() {
  var n = Math.round(manufacturingCostNumberFromInput("manufacturing-cost-core-cost", 1500));
  manufacturingCostCategoryCoreCosts.__default = n;
  saveManufacturingCostCategoryCoreCosts();
  renderManufacturingCostCategoryCoreCosts();
}

function recalculateManufacturingCostCurrentRows() {
  if (!manufacturingCostRows.length) return;
  var products = manufacturingCostRows.map(function(row) { return row.product; }).filter(Boolean);
  manufacturingCostRows = manufacturingCostBuildRows(products, manufacturingCostSettings(), { snapshotMap: manufacturingCostListItemSnapshotMap });
  renderManufacturingCostRows();
}

function openManufacturingCostCategoryCoreSettings() {
  renderManufacturingCostCategoryCoreCosts();
  var overlay = document.getElementById("manufacturing-cost-category-core-overlay");
  if (overlay) overlay.classList.add("show");
}

function closeManufacturingCostCategoryCoreSettings() {
  var overlay = document.getElementById("manufacturing-cost-category-core-overlay");
  if (overlay) overlay.classList.remove("show");
}

function setManufacturingCostListStatus(message, isError) {
  var el = document.getElementById("manufacturing-cost-list-status");
  if (!el) return;
  el.textContent = message || "";
  setCspStyle(el, "color", isError ? "#d33" : "#64748b");
}

function renderManufacturingCostSavedListOptions() {
  var select = document.getElementById("manufacturing-cost-saved-list");
  if (!select) return;
  var currentCategory = manufacturingCostSelectedCategory();
  var rows = (manufacturingCostSavedLists || []).filter(function(row) {
    return !currentCategory || row.category_code === currentCategory;
  });
  var html = "<option value=''>" + esc(t("manufacturing_cost_saved_list_empty")) + "</option>";
  rows.forEach(function(row) {
    var label = (currentCategory ? "" : manufacturingCostCategoryLabel(row.category_code) + " / ") + row.list_name;
    html += "<option value='" + esc(String(row.id)) + "'>" + esc(label) + "</option>";
  });
  select.innerHTML = html;
  if (manufacturingCostActiveListId && rows.some(function(row) { return String(row.id) === String(manufacturingCostActiveListId); })) {
    select.value = String(manufacturingCostActiveListId);
  } else {
    select.value = "";
    manufacturingCostActiveListId = null;
  }
}

async function loadManufacturingCostSavedLists() {
  var r = await sb.from("manufacturing_cost_lists")
    .select("*")
    .eq("is_active", true)
    .order("category_code", { ascending: true })
    .order("list_name", { ascending: true });
  if (r.error) {
    console.warn("manufacturing cost lists lookup failed", r.error);
    manufacturingCostSavedLists = [];
    setManufacturingCostListStatus(r.error.message || t("msg_part_err"), true);
    return;
  }
  manufacturingCostSavedLists = r.data || [];
}

async function refreshManufacturingCostSavedLists() {
  await loadManufacturingCostSavedLists();
  renderManufacturingCostSavedListOptions();
}

function selectedManufacturingCostList() {
  var id = (document.getElementById("manufacturing-cost-saved-list") || {}).value || "";
  if (!id) return null;
  return (manufacturingCostSavedLists || []).find(function(row) {
    return String(row.id) === String(id);
  }) || null;
}

function resetManufacturingCostWorkingList() {
  manufacturingCostActiveListId = null;
  manufacturingCostListItemSnapshotMap = null;
  var savedEl = document.getElementById("manufacturing-cost-saved-list");
  var nameEl = document.getElementById("manufacturing-cost-list-name");
  var queryEl = document.getElementById("manufacturing-cost-query");
  if (savedEl) savedEl.value = "";
  if (nameEl) nameEl.value = "";
  if (queryEl) queryEl.value = "";
  setManufacturingCostListStatus("", false);
  renderManufacturingCostCandidateEmpty("");
  renderManufacturingCostEmpty();
  if (queryEl) queryEl.focus();
}

function clearManufacturingCostQueryInput() {
  var queryEl = document.getElementById("manufacturing-cost-query");
  if (queryEl) {
    queryEl.value = "";
    queryEl.focus();
  }
  renderManufacturingCostCandidateEmpty("");
  setManufacturingCostListStatus("", false);
}

function manufacturingCostTokens(value) {
  var text = normalizeAsciiWidth(String(value || "")).trim();
  if (!text) return [];
  var seen = {};
  var out = [];
  text.split(/[\s,\u3001\uFF0C]+/).forEach(function(token) {
    token = token.trim();
    if (!token) return;
    var key = normalizePartQuery(token);
    if (!key || seen[key]) return;
    seen[key] = true;
    out.push(token);
  });
  return out;
}

function manufacturingCostNumberFromInput(id, fallback) {
  var el = document.getElementById(id);
  var n = el ? parseFloat(String(el.value || "").replace(/,/g, "")) : NaN;
  if (isNaN(n) || n < 0) n = fallback || 0;
  return n;
}

function manufacturingCostSettings() {
  var defaultCoreCost = Object.prototype.hasOwnProperty.call(manufacturingCostCategoryCoreCosts || {}, "__default")
    ? manufacturingCostCategoryCoreCosts.__default
    : 1500;
  return {
    productKind: normalizeProductKind((document.getElementById("manufacturing-cost-kind") || {}).value || "rebuilt"),
    coreCost: Math.round(manufacturingCostNumberFromInput("manufacturing-cost-core-cost", defaultCoreCost)),
    categoryCoreCosts: Object.assign({}, manufacturingCostCategoryCoreCosts || {}),
    laborRate: manufacturingCostNumberFromInput("manufacturing-cost-labor-rate", 0),
    laborAmount: Math.round(manufacturingCostNumberFromInput("manufacturing-cost-labor-amount", MANUFACTURING_COST_DEFAULT_LABOR_AMOUNT_JPY)),
    sellingExpense: Math.round(manufacturingCostNumberFromInput("manufacturing-cost-selling-expense", MANUFACTURING_COST_DEFAULT_SELLING_EXPENSE_JPY))
  };
}

function manufacturingCostParseQty(value) {
  var text = String(value == null ? "" : value).replace(/[^\d.]/g, "");
  var n = parseFloat(text);
  if (isNaN(n) || n <= 0) return 1;
  return n;
}

function manufacturingCostParseRate(value) {
  if (value === null || value === undefined || String(value).trim() === "") return 100;
  var text = String(value).replace(/[^\d.]/g, "");
  var n = parseFloat(text);
  if (isNaN(n)) return 100;
  if (n < 0) return 0;
  if (n > 100) return 100;
  return n;
}

function manufacturingCostYen(value) {
  return "\u00a5" + formatYen(Math.round(value || 0));
}

function manufacturingCostPercent(value) {
  var n = parseFloat(value);
  if (isNaN(n)) return "-";
  return String(n).replace(/\.0+$/, "") + "%";
}

function manufacturingCostComponentCalc(row) {
  row = row || {};
  var unitRaw = row.unit_price_jpy;
  var hasUnit = !(unitRaw === null || unitRaw === undefined || unitRaw === "");
  var unit = hasUnit ? parseInt(unitRaw, 10) : 0;
  if (isNaN(unit)) {
    hasUnit = false;
    unit = 0;
  }
  var qty = manufacturingCostParseQty(row.quantity);
  var rate = manufacturingCostParseRate(row.replacement_rate);
  return {
    unit: unit,
    hasUnit: hasUnit,
    qty: qty,
    rate: rate,
    amount: hasUnit ? Math.round(unit * qty * rate / 100) : 0
  };
}

function manufacturingCostComponentInputState(row) {
  row = row || {};
  var calc = manufacturingCostComponentCalc(row);
  var quantityText = String(row.quantity == null ? "" : row.quantity).trim();
  var quantityNumber = parseFloat(quantityText.replace(/[^\d.]/g, ""));
  var rateText = String(row.replacement_rate == null ? "" : row.replacement_rate).trim();
  var rateNumber = parseFloat(rateText.replace(/[^\d.]/g, ""));
  return {
    hasUnit: calc.hasUnit,
    hasQuantity: quantityText !== "" && !isNaN(quantityNumber) && quantityNumber > 0,
    hasReplacementRate: rateText !== "" && !isNaN(rateNumber) && rateNumber >= 0 && rateNumber <= 100
  };
}

function manufacturingCostComponentComparisonKey(row) {
  row = row || {};
  function compact(value) {
    return String(value || "").toUpperCase().replace(/[\s\u3000\-_/・･]/g, "");
  }
  return [
    compact(row.component_manufacturer),
    compact(row.component_manufacturer_part_number),
    compact(row.component_genuine_part_number),
    compact(row.component_name || row.component_part_name)
  ].join("|");
}

function manufacturingCostMatchingCurrentComponents(snapshot, currentComponents) {
  var candidates = [];
  if (snapshot && snapshot.id != null && snapshot.id !== "") {
    candidates = (currentComponents || []).filter(function(current) {
      return current && current.id != null && String(current.id) === String(snapshot.id);
    });
  }
  if (!candidates.length) {
    var key = manufacturingCostComponentComparisonKey(snapshot);
    if (key.replace(/\|/g, "")) {
      candidates = (currentComponents || []).filter(function(current) {
        return manufacturingCostComponentComparisonKey(current) === key;
      });
    }
  }
  return candidates;
}

function manufacturingCostSnapshotUnitPriceDiffers(snapshotComponents, currentComponents) {
  snapshotComponents = snapshotComponents || [];
  currentComponents = currentComponents || [];
  if (!snapshotComponents.length || !currentComponents.length) return false;
  return snapshotComponents.some(function(snapshot) {
    var candidates = manufacturingCostMatchingCurrentComponents(snapshot, currentComponents);
    if (!candidates.length) return false;
    var savedCalc = manufacturingCostComponentCalc(snapshot);
    var currentWithUnit = candidates.filter(function(current) {
      return manufacturingCostComponentCalc(current).hasUnit;
    });
    if (!currentWithUnit.length) return false;
    return !currentWithUnit.some(function(current) {
      var currentCalc = manufacturingCostComponentCalc(current);
      return savedCalc.hasUnit && savedCalc.unit === currentCalc.unit;
    });
  });
}

function manufacturingCostRowWithCurrentUnitPrices(row, settings) {
  row = row || {};
  var savedComponents = row.components || [];
  var hasSnapshot = savedComponents.some(function(component) { return !!(component && component.is_cost_snapshot); });
  var currentComponents = manufacturingCostComponentMap[String(row.productId || "")] || [];
  if (!hasSnapshot || !currentComponents.length) return { row: row, updatedCount: 0 };
  var updatedCount = 0;
  var nextComponents = savedComponents.map(function(snapshot) {
    var candidates = manufacturingCostMatchingCurrentComponents(snapshot, currentComponents);
    var current = candidates.find(function(candidate) {
      return manufacturingCostComponentCalc(candidate).hasUnit;
    });
    if (!current) return snapshot;
    var savedCalc = manufacturingCostComponentCalc(snapshot);
    var currentCalc = manufacturingCostComponentCalc(current);
    if (savedCalc.hasUnit && savedCalc.unit === currentCalc.unit) return snapshot;
    updatedCount += 1;
    return Object.assign({}, snapshot, { unit_price_jpy: currentCalc.unit });
  });
  if (!updatedCount) return { row: row, updatedCount: 0 };
  var partsCost = nextComponents.reduce(function(total, component) {
    return total + manufacturingCostComponentCalc(component).amount;
  }, 0);
  var missingUnitCount = 0;
  var missingQuantityCount = 0;
  var missingReplacementRateCount = 0;
  currentComponents.forEach(function(component) {
    var inputState = manufacturingCostComponentInputState(component);
    if (!inputState.hasUnit) missingUnitCount += 1;
    if (!inputState.hasQuantity) missingQuantityCount += 1;
    if (!inputState.hasReplacementRate) missingReplacementRateCount += 1;
  });
  var coreInfo = manufacturingCostCoreCostForProduct(row.product, settings);
  var laborRateCost = Math.round((partsCost + coreInfo.amount) * settings.laborRate / 100);
  var laborCost = laborRateCost + settings.laborAmount;
  var sellingExpense = Math.round(settings.sellingExpense == null ? MANUFACTURING_COST_DEFAULT_SELLING_EXPENSE_JPY : settings.sellingExpense);
  return {
    row: Object.assign({}, row, {
      components: nextComponents,
      partsCost: partsCost,
      coreCost: coreInfo.amount,
      coreCostCategory: coreInfo.category,
      coreCostCategorySpecific: coreInfo.isCategorySpecific,
      coreCostProductSpecific: coreInfo.isProductSpecific,
      coreCostSource: coreInfo.source,
      coreReturnRequired: coreInfo.returnRequired,
      laborRateCost: laborRateCost,
      laborAmount: settings.laborAmount,
      laborCost: laborCost,
      sellingExpense: sellingExpense,
      totalCost: partsCost + coreInfo.amount + laborCost + sellingExpense,
      missingUnitCount: missingUnitCount,
      missingQuantityCount: missingQuantityCount,
      missingReplacementRateCount: missingReplacementRateCount,
      savedSnapshotUnitPriceDiffers: false
    }),
    updatedCount: updatedCount
  };
}

function manufacturingCostSnapshotNumber(value, fallback) {
  var n = parseInt(value, 10);
  return isNaN(n) ? (fallback || 0) : n;
}

function manufacturingCostComponentSnapshot(component) {
  component = component || {};
  var calc = manufacturingCostComponentCalc(component);
  return {
    id: component.id || null,
    component_manufacturer: component.component_manufacturer || null,
    component_manufacturer_part_number: component.component_manufacturer_part_number || null,
    component_genuine_part_number: component.component_genuine_part_number || null,
    component_name: component.component_name || component.component_part_name || null,
    quantity: calc.qty,
    unit_price_jpy: calc.hasUnit ? calc.unit : null,
    replacement_rate: calc.rate,
    subtotal_jpy: calc.amount,
    procurement_category: component.procurement_category || null
  };
}

function manufacturingCostRowComponentSnapshots(row) {
  return ((row && row.components) || []).map(manufacturingCostComponentSnapshot);
}

function manufacturingCostSnapshotComponents(item) {
  if (!item) return [];
  var raw = item.components_snapshot;
  if (!raw) return [];
  if (typeof raw === "string") {
    try { raw = JSON.parse(raw); } catch (e) { raw = []; }
  }
  if (!Array.isArray(raw)) return [];
  return raw.map(function(component) {
    component = component || {};
    return {
      id: component.id || null,
      component_manufacturer: component.component_manufacturer || null,
      component_manufacturer_part_number: component.component_manufacturer_part_number || null,
      component_genuine_part_number: component.component_genuine_part_number || null,
      component_name: component.component_name || component.component_part_name || null,
      component_part_name: component.component_name || component.component_part_name || null,
      quantity: component.quantity,
      unit_price_jpy: component.unit_price_jpy,
      replacement_rate: component.replacement_rate,
      procurement_category: component.procurement_category || null,
      is_cost_snapshot: true
    };
  });
}

function manufacturingCostBuildSnapshotMap(items) {
  var map = {};
  (items || []).forEach(function(item) {
    if (!item || !item.dkd_shohin_id) return;
    map[String(item.dkd_shohin_id)] = item;
  });
  return map;
}

function manufacturingCostProductTitle(product) {
  product = product || {};
  return product.genuine_part_number || product.genuine_part_number_2 || product.manufacturer_part_number || ("DKD " + (product.dkd_shohin_id || "-"));
}

function manufacturingCostCurrentProductIdMap() {
  var map = {};
  (manufacturingCostRows || []).forEach(function(row) {
    if (row && row.productId) map[String(row.productId)] = true;
  });
  return map;
}

async function loadManufacturingCostCandidateStatuses(products) {
  var rows = products || [];
  var statusMap = {};
  if (!rows.length) {
    manufacturingCostCandidateStatusMap = statusMap;
    return statusMap;
  }
  var results = await Promise.all([
    fetchProductVariantSummaryMap(rows),
    fetchProductionPartRegistrationCountMap(rows)
  ]);
  var variantMap = results[0] || {};
  var registrationCounts = results[1] || {};
  var byKind = registrationCounts.byKind || {};
  rows.forEach(function(product) {
    var key = String(productDkdId(product) || "");
    if (!key) return;
    var kindCounts = byKind[key] || {};
    statusMap[key] = {
      hasCatalog: !!(product.has_catalog_source || product.has_catalog_spec || productKindSummaryHasKind(variantMap[key], "catalog_spec")),
      rebuiltComponentCount: parseInt(kindCounts.rebuilt || 0, 10) || 0
    };
  });
  manufacturingCostCandidateStatusMap = statusMap;
  return statusMap;
}

function renderManufacturingCostCandidateStatusLabels(product) {
  var key = String(productDkdId(product) || "");
  var status = manufacturingCostCandidateStatusMap[key] || { hasCatalog: false, rebuiltComponentCount: 0 };
  var rebuiltCount = parseInt(status.rebuiltComponentCount || 0, 10) || 0;
  var html = "";
  if (status.hasCatalog) {
    html += "<span class='badge-catalog'>" + esc(t("product_kind_catalog_spec")) + "</span>";
  }
  if (rebuiltCount > 0) {
    html += "<span class='badge-component' title='" + esc(productKindLabel("rebuilt") + " " + t("product_kind_component_count")) + "'>&#x1F9E9; " + esc(String(rebuiltCount)) + "</span>";
  }
  return html;
}

function renderManufacturingCostCandidates(products, mode) {
  manufacturingCostCandidateRows = products || [];
  manufacturingCostCandidateMode = mode || "";
  var wrap = document.getElementById("manufacturing-cost-candidates");
  if (!wrap) return;
  if (!manufacturingCostCandidateRows.length) {
    renderManufacturingCostCandidateEmpty(t("no_results"));
    return;
  }
  var checkedDefault = mode === "category" || manufacturingCostCandidateRows.length === 1;
  var currentIds = manufacturingCostCurrentProductIdMap();
  var html = "<div class='manufacturing-cost-candidate-panel'>";
  html += "<div class='manufacturing-cost-section-head'>";
  html += "<div><div class='manufacturing-cost-section-title'><span class='manufacturing-cost-section-badge candidate'>" + esc(t("manufacturing_cost_candidate_badge")) + "</span><strong>" + esc(t("manufacturing_cost_candidate_title")) + "</strong><span>" + esc(tf("manufacturing_cost_candidate_count", { n: manufacturingCostCandidateRows.length })) + "</span></div>";
  html += "<div class='manufacturing-cost-section-note'>" + esc(t("manufacturing_cost_candidate_note")) + "</div></div>";
  html += "<div class='manufacturing-cost-candidate-actions'>";
  html += "<button class='btn-secondary' type='button' data-cost-select-all='1'>" + esc(t("manufacturing_cost_select_all")) + "</button>";
  html += "<button class='btn-secondary' type='button' data-cost-clear-selection='1'>" + esc(t("manufacturing_cost_clear_selection")) + "</button>";
  html += "<button class='btn-primary' type='button' data-cost-calc-selected='1'>" + esc(t("manufacturing_cost_calc_selected")) + "</button>";
  html += "</div></div>";
  html += "<div class='manufacturing-cost-candidate-list'>";
  manufacturingCostCandidateRows.forEach(function(product) {
    var id = productDkdId(product);
    var cat = product.category_code || product.category || "";
    var isAdded = !!currentIds[String(id || "")];
    var statusLabels = renderManufacturingCostCandidateStatusLabels(product);
    var checked = checkedDefault ? " checked" : "";
    if (isAdded) checked = "";
    html += "<label class='manufacturing-cost-candidate-row" + (isAdded ? " added" : "") + "'>";
    html += "<input type='checkbox' data-cost-candidate-check='1' value='" + esc(String(id || "")) + "'" + checked + (isAdded ? " disabled data-cost-candidate-added='1'" : "") + ">";
    html += "<span class='manufacturing-cost-candidate-info'><span class='manufacturing-cost-candidate-main'>" + esc(manufacturingCostProductTitle(product)) + "</span>";
    html += "<span class='manufacturing-cost-candidate-sub'>" + esc([product.manufacturer_part_number, product.genuine_part_number_2, product.manufacturer, "DKD " + (id || "-")].filter(Boolean).join(" / ")) + "</span>";
    if (statusLabels) html += "<span class='manufacturing-cost-candidate-data-labels'>" + statusLabels + "</span>";
    html += "</span>";
    html += "<span class='manufacturing-cost-candidate-side'><span class='manufacturing-cost-candidate-kind'>" + esc(tCat(cat)) + "</span>";
    if (isAdded) html += "<span class='manufacturing-cost-candidate-added'>" + esc(t("manufacturing_cost_already_added")) + "</span>";
    html += "</span>";
    html += "</label>";
  });
  html += "</div></div>";
  wrap.innerHTML = html;
}

function selectedManufacturingCostCandidateProducts(options) {
  options = options || {};
  var selected = {};
  document.querySelectorAll("#manufacturing-cost-candidates [data-cost-candidate-check]:checked").forEach(function(el) {
    if (!options.includeAdded && el.dataset.costCandidateAdded === "1") return;
    selected[String(el.value || "")] = true;
  });
  return (manufacturingCostCandidateRows || []).filter(function(product) {
    return selected[String(productDkdId(product) || "")];
  });
}

function selectedManufacturingCostDuplicateCandidateProducts() {
  var currentIds = manufacturingCostCurrentProductIdMap();
  return selectedManufacturingCostCandidateProducts({ includeAdded: true }).filter(function(product) {
    return !!currentIds[String(productDkdId(product) || "")];
  });
}

function setManufacturingCostCandidateChecks(checked) {
  document.querySelectorAll("#manufacturing-cost-candidates [data-cost-candidate-check]").forEach(function(el) {
    if (el.dataset.costCandidateAdded === "1") {
      el.checked = false;
      return;
    }
    el.checked = !!checked;
  });
}

function mergeManufacturingCostProducts(addProducts) {
  var merged = [];
  var seen = {};
  function add(product) {
    var id = productDkdId(product);
    if (!id || seen[String(id)]) return;
    seen[String(id)] = true;
    merged.push(product);
  }
  (manufacturingCostRows || []).forEach(function(row) {
    if (row && row.product) add(row.product);
  });
  (addProducts || []).forEach(add);
  return merged;
}

async function fetchManufacturingCostProducts(tokens, category) {
  var rows = [];
  var seen = {};
  function addRows(list) {
    normalizeCoreProductFastRows(list || []).forEach(function(row) {
      var id = productDkdId(row);
      if (!id || seen[id]) return;
      seen[id] = true;
      rows.push(row);
    });
  }
  if (tokens.length) {
    for (var i = 0; i < tokens.length && rows.length < 200; i++) {
      var r = await fetchCoreProductMasterMatches(tokens[i], category || null, 60);
      if (r.error) return r;
      addRows(r.data || []);
    }
  } else if (category) {
    var cr = await fetchCategoryProducts(category, 200);
    if (cr.error) return cr;
    addRows(cr.data || []);
  }
  rows = filterVisibleProducts(rows).slice(0, 200);
  return { data: rows, error: null };
}

async function fetchManufacturingCostProductsByIds(ids) {
  ids = Array.from(new Set((ids || []).map(function(id) { return parseInt(id, 10); }).filter(function(id) { return !isNaN(id); })));
  if (!ids.length) return { data: [], error: null };
  var byId = {};
  for (var i = 0; i < ids.length; i += 120) {
    var chunk = ids.slice(i, i + 120);
    var r = await sb.from("core_products")
      .select(CORE_PRODUCT_FAST_SELECT)
      .in("dkd_shohin_id", chunk)
      .limit(chunk.length);
    if (r.error) return r;
    normalizeCoreProductFastRows(r.data || []).forEach(function(row) {
      byId[String(productDkdId(row))] = row;
    });
  }
  return {
    data: ids.map(function(id) { return byId[String(id)]; }).filter(Boolean),
    error: null
  };
}

async function loadManufacturingCostComponents(products, productKind) {
  manufacturingCostComponentMap = {};
  var ids = (products || []).map(function(p) { return productDkdId(p); }).filter(Boolean);
  ids = Array.from(new Set(ids.map(function(id) { return parseInt(id, 10); }))).filter(function(id) { return !isNaN(id); });
  for (var i = 0; i < ids.length; i += 120) {
    var chunk = ids.slice(i, i + 120);
    var r = await sb.from("assembly_component_usage_details")
      .select("id,dkd_shohin_id,product_kind,product_variant_id,component_manufacturer,component_manufacturer_part_number,component_genuine_part_number,component_name,component_part_name,quantity,unit_price_jpy,replacement_rate,procurement_category,is_catalog_evidence")
      .in("dkd_shohin_id", chunk)
      .eq("product_kind", productKind)
      .eq("is_catalog_evidence", false)
      .limit(10000);
    if (r.error) return r;
    (r.data || []).forEach(function(row) {
      var key = String(row.dkd_shohin_id || "");
      if (!key) return;
      if (!manufacturingCostComponentMap[key]) manufacturingCostComponentMap[key] = [];
      manufacturingCostComponentMap[key].push(row);
    });
  }
  return { data: manufacturingCostComponentMap, error: null };
}

async function loadManufacturingCostCorePolicies(products, productKind) {
  manufacturingCostCorePolicyMap = {};
  var ids = (products || []).map(function(product) { return productDkdId(product); }).filter(Boolean);
  ids = Array.from(new Set(ids.map(function(id) { return parseInt(id, 10); }))).filter(function(id) { return !isNaN(id); });
  productKind = normalizeProductKind(productKind || "rebuilt");
  for (var i = 0; i < ids.length; i += 200) {
    var chunk = ids.slice(i, i + 200);
    var r = await sb.from("core_product_variants")
      .select("dkd_shohin_id,product_kind,core_return_required,core_charge_jpy,is_active")
      .in("dkd_shohin_id", chunk)
      .eq("product_kind", productKind)
      .eq("is_active", true);
    if (r.error) return r;
    (r.data || []).forEach(function(row) {
      var key = String(row.dkd_shohin_id || "");
      if (!key) return;
      var current = manufacturingCostCorePolicyMap[key];
      if (!current || (current.core_charge_jpy == null && row.core_charge_jpy != null)) {
        manufacturingCostCorePolicyMap[key] = row;
      }
    });
  }
  return { data: manufacturingCostCorePolicyMap, error: null };
}

function manufacturingCostBuildRows(products, settings, options) {
  options = options || {};
  var snapshotMap = options.snapshotMap || null;
  return (products || []).map(function(product) {
    var id = productDkdId(product);
    var snapshotItem = snapshotMap ? snapshotMap[String(id || "")] : null;
    var snapshotComponents = manufacturingCostSnapshotComponents(snapshotItem);
    var currentComponents = manufacturingCostComponentMap[String(id || "")] || [];
    var components = snapshotComponents.length ? snapshotComponents : currentComponents;
    var validationComponents = currentComponents.length ? currentComponents : components;
    var snapshotUnitPriceDiffers = manufacturingCostSnapshotUnitPriceDiffers(snapshotComponents, currentComponents);
    var partsCost = 0;
    var missingUnitCount = 0;
    var missingQuantityCount = 0;
    var missingReplacementRateCount = 0;
    components.forEach(function(row) {
      var calc = manufacturingCostComponentCalc(row);
      partsCost += calc.amount;
    });
    validationComponents.forEach(function(row) {
      var inputState = manufacturingCostComponentInputState(row);
      if (!inputState.hasUnit) missingUnitCount += 1;
      if (!inputState.hasQuantity) missingQuantityCount += 1;
      if (!inputState.hasReplacementRate) missingReplacementRateCount += 1;
    });
    if (snapshotItem && !snapshotComponents.length && !components.length) {
      partsCost = manufacturingCostSnapshotNumber(snapshotItem.parts_cost_jpy_snapshot, partsCost);
      missingUnitCount = manufacturingCostSnapshotNumber(snapshotItem.missing_unit_count_snapshot, missingUnitCount);
    }
    var componentCount = snapshotItem && !snapshotComponents.length && !components.length
      ? manufacturingCostSnapshotNumber(snapshotItem.component_count_snapshot, components.length)
      : components.length;
    if (snapshotComponents.length) componentCount = snapshotComponents.length;
    var coreInfo = manufacturingCostCoreCostForProduct(product, settings);
    var coreCost = coreInfo.amount;
    var laborBase = partsCost + coreCost;
    var laborRateCost = Math.round(laborBase * settings.laborRate / 100);
    var laborCost = laborRateCost + settings.laborAmount;
    var sellingExpense = Math.round(settings.sellingExpense == null ? MANUFACTURING_COST_DEFAULT_SELLING_EXPENSE_JPY : settings.sellingExpense);
    return {
      product: product,
      productId: id,
      components: components,
      componentCount: componentCount,
      missingUnitCount: missingUnitCount,
      partsCost: partsCost,
      coreCost: coreCost,
      coreCostCategory: coreInfo.category,
      coreCostCategorySpecific: coreInfo.isCategorySpecific,
      coreCostProductSpecific: coreInfo.isProductSpecific,
      coreCostSource: coreInfo.source,
      coreReturnRequired: coreInfo.returnRequired,
      laborRateCost: laborRateCost,
      laborAmount: settings.laborAmount,
      laborCost: laborCost,
      sellingExpense: sellingExpense,
      totalCost: partsCost + coreCost + laborCost + sellingExpense,
      savedSnapshotUnitPriceDiffers: snapshotUnitPriceDiffers,
      missingQuantityCount: missingQuantityCount,
      missingReplacementRateCount: missingReplacementRateCount
    };
  });
}

async function buildAndRenderManufacturingCostProducts(products, settings, options) {
  options = options || {};
  if (Object.prototype.hasOwnProperty.call(options, "snapshotMap")) {
    manufacturingCostListItemSnapshotMap = options.snapshotMap || null;
  }
  var loads = await Promise.all([
    loadManufacturingCostComponents(products, settings.productKind),
    loadManufacturingCostCorePolicies(products, settings.productKind)
  ]);
  loads.forEach(function(result) {
    if (result.error) throw result.error;
  });
  manufacturingCostRows = manufacturingCostBuildRows(products, settings, { snapshotMap: manufacturingCostListItemSnapshotMap });
  renderManufacturingCostRows();
}

function renderManufacturingCostSummary(rows) {
  var wrap = document.getElementById("manufacturing-cost-summary");
  if (!wrap) return;
  if (!rows || !rows.length) {
    wrap.innerHTML = "";
    return;
  }
  var parts = 0, labor = 0, selling = 0, total = 0;
  rows.forEach(function(row) {
    parts += row.partsCost || 0;
    labor += row.laborCost || 0;
    selling += row.sellingExpense || 0;
    total += row.totalCost || 0;
  });
  wrap.innerHTML =
    "<div class='manufacturing-cost-summary'>" +
      "<div class='manufacturing-cost-stat'><span>" + esc(t("manufacturing_cost_summary_products")) + "</span><b>" + esc(String(rows.length)) + "</b></div>" +
      "<div class='manufacturing-cost-stat'><span>" + esc(t("manufacturing_cost_summary_parts")) + "</span><b>" + esc(manufacturingCostYen(parts)) + "</b></div>" +
      "<div class='manufacturing-cost-stat'><span>" + esc(t("manufacturing_cost_summary_labor")) + "</span><b>" + esc(manufacturingCostYen(labor)) + "</b></div>" +
      "<div class='manufacturing-cost-stat'><span>" + esc(t("manufacturing_cost_summary_selling_expense")) + "</span><b>" + esc(manufacturingCostYen(selling)) + "</b></div>" +
      "<div class='manufacturing-cost-stat'><span>" + esc(t("manufacturing_cost_summary_total")) + "</span><b>" + esc(manufacturingCostYen(total)) + "</b></div>" +
    "</div>";
}

function renderManufacturingCostComponentDetailBody(row) {
  if (!row.components.length) return "";
  var html = "<div class='manufacturing-cost-detail-badges'>";
  html += "<span class='manufacturing-cost-detail-badge'>" + esc(tf("manufacturing_cost_component_count", { n: row.componentCount || row.components.length })) + "</span>";
  html += "<span class='manufacturing-cost-detail-badge total'>" + esc(t("manufacturing_cost_summary_parts")) + " " + esc(manufacturingCostYen(row.partsCost)) + "</span>";
  if (row.missingUnitCount) html += "<span class='manufacturing-cost-detail-badge warn'>" + esc(tf("manufacturing_cost_missing_unit", { n: row.missingUnitCount })) + "</span>";
  if (row.missingQuantityCount) html += "<span class='manufacturing-cost-detail-badge warn'>" + esc(tf("manufacturing_cost_missing_quantity", { n: row.missingQuantityCount })) + "</span>";
  if (row.missingReplacementRateCount) html += "<span class='manufacturing-cost-detail-badge warn'>" + esc(tf("manufacturing_cost_missing_replacement_rate", { n: row.missingReplacementRateCount })) + "</span>";
  if (row.savedSnapshotUnitPriceDiffers) html += "<span class='manufacturing-cost-detail-badge warn'>" + esc(t("manufacturing_cost_snapshot_unit_price_changed")) + "</span>";
  html += "</div>";
  html += "<div class='manufacturing-cost-component-list'>";
  html += "<div class='manufacturing-cost-component-header'>";
  html += "<span>" + esc(t("component_name")) + "</span>";
  html += "<span>" + esc(t("f_part_number")) + "</span>";
  html += "<span>" + esc(t("manufacturing_cost_unit_price")) + "</span>";
  html += "<span>" + esc(t("manufacturing_cost_quantity")) + "</span>";
  html += "<span>" + esc(t("manufacturing_cost_replacement_rate")) + "</span>";
  html += "<span>" + esc(t("manufacturing_cost_calculated")) + "</span>";
  html += "</div>";
  row.components.forEach(function(component) {
    var calc = manufacturingCostComponentCalc(component);
    var name = component.component_name || component.component_part_name || component.component_manufacturer_part_number || "-";
    var unitText = calc.hasUnit ? manufacturingCostYen(calc.unit) : t("manufacturing_cost_unit_price_missing");
    var partText = [component.component_manufacturer, component.component_manufacturer_part_number, component.component_genuine_part_number].filter(Boolean).join(" / ") || "-";
    html += "<div class='manufacturing-cost-component-card" + (calc.hasUnit ? "" : " missing-unit") + "'>";
    html += "<div class='manufacturing-cost-component-title'>" + esc(name) + "</div>";
    html += "<div class='manufacturing-cost-component-part'>" + esc(partText) + "</div>";
    html += "<div class='manufacturing-cost-component-cell'><b>" + esc(unitText) + "</b></div>";
    html += "<div class='manufacturing-cost-component-cell'><b>" + esc(String(calc.qty)) + "</b></div>";
    html += "<div class='manufacturing-cost-component-cell'><b>" + esc(manufacturingCostPercent(calc.rate)) + "</b></div>";
    html += "<div class='manufacturing-cost-component-cell manufacturing-cost-component-subtotal'><b>" + esc(manufacturingCostYen(calc.amount)) + "</b></div>";
    html += "</div>";
  });
  html += "</div>";
  return html;
}

function renderManufacturingCostComponentDetails(row, rowIndex) {
  if (!row.components.length) return "";
  var summaryText = tf("manufacturing_cost_component_detail_summary", {
    n: row.componentCount || row.components.length,
    amount: manufacturingCostYen(row.partsCost)
  });
  return "<details class='manufacturing-cost-details' data-manufacturing-cost-detail-index='" + esc(String(rowIndex)) + "'>" +
    "<summary>" + esc(summaryText) + "</summary>" +
    "<div class='manufacturing-cost-detail-lazy'><div class='manufacturing-cost-detail-loading'>" + esc(t("loading")) + "</div></div>" +
    "</details>";
}

function populateManufacturingCostComponentDetails(detailEl) {
  if (!detailEl || !detailEl.open || detailEl.dataset.loaded === "1") return;
  var rowIndex = parseInt(detailEl.dataset.manufacturingCostDetailIndex || "", 10);
  var row = !isNaN(rowIndex) ? manufacturingCostRows[rowIndex] : null;
  var body = detailEl.querySelector(".manufacturing-cost-detail-lazy");
  if (!body || !row) return;
  body.innerHTML = renderManufacturingCostComponentDetailBody(row);
  detailEl.dataset.loaded = "1";
}

function bindManufacturingCostComponentDetailToggles() {
  var list = document.getElementById("manufacturing-cost-list");
  if (!list) return;
  list.querySelectorAll(".manufacturing-cost-details[data-manufacturing-cost-detail-index]").forEach(function(detailEl) {
    detailEl.addEventListener("toggle", function() {
      populateManufacturingCostComponentDetails(detailEl);
    });
    populateManufacturingCostComponentDetails(detailEl);
  });
}

function setManufacturingCostTargetDeleteStatus(message, isError) {
  var el = document.getElementById("manufacturing-cost-target-delete-status");
  if (!el) return;
  el.textContent = message || "";
  el.classList.toggle("is-error", !!isError);
}

function updateManufacturingCostTargetDeleteCount() {
  var list = document.getElementById("manufacturing-cost-target-delete-list");
  var countEl = document.getElementById("manufacturing-cost-target-delete-count");
  var removeBtn = document.getElementById("btn-manufacturing-cost-remove-selected");
  if (!list) return;
  var checks = Array.from(list.querySelectorAll("[data-manufacturing-cost-delete-check]"));
  var selected = checks.filter(function(check) { return check.checked; }).length;
  if (countEl) countEl.textContent = tf("manufacturing_cost_remove_count", { selected: selected, total: checks.length });
  if (removeBtn) removeBtn.disabled = selected === 0;
}

function renderManufacturingCostTargetDeleteList() {
  var list = document.getElementById("manufacturing-cost-target-delete-list");
  var selectAllBtn = document.getElementById("btn-manufacturing-cost-remove-all");
  var clearBtn = document.getElementById("btn-manufacturing-cost-remove-clear");
  if (!list) return;
  var rows = manufacturingCostRows || [];
  if (!rows.length) {
    list.innerHTML = "<div class='empty'>" + esc(t("manufacturing_cost_remove_empty")) + "</div>";
  } else {
    list.innerHTML = rows.map(function(row) {
      var p = row.product || {};
      var sub = [p.manufacturer_part_number, p.genuine_part_number_2, p.manufacturer, tCat(p.category_code || p.category), "DKD " + (row.productId || "-")].filter(Boolean).join(" / ");
      return "<label class='manufacturing-cost-target-delete-row'>" +
        "<input type='checkbox' value='" + esc(String(row.productId || "")) + "' data-manufacturing-cost-delete-check>" +
        "<span class='manufacturing-cost-target-delete-info'><strong>" + esc(manufacturingCostProductTitle(p)) + "</strong><small>" + esc(sub) + "</small></span>" +
        "<span class='manufacturing-cost-target-delete-amount'>" + esc(manufacturingCostYen(row.totalCost)) + "</span>" +
      "</label>";
    }).join("");
  }
  if (selectAllBtn) selectAllBtn.disabled = !rows.length;
  if (clearBtn) clearBtn.disabled = !rows.length;
  updateManufacturingCostTargetDeleteCount();
}

function openManufacturingCostTargetDelete() {
  if (!canEditManufacturingCostMgmt()) { alert(t("err_perm")); return; }
  renderManufacturingCostTargetDeleteList();
  setManufacturingCostTargetDeleteStatus("", false);
  var overlay = document.getElementById("manufacturing-cost-target-delete-overlay");
  if (overlay) overlay.classList.add("show");
}

function closeManufacturingCostTargetDelete() {
  var overlay = document.getElementById("manufacturing-cost-target-delete-overlay");
  if (overlay) overlay.classList.remove("show");
}

function setManufacturingCostTargetDeleteChecks(checked) {
  var list = document.getElementById("manufacturing-cost-target-delete-list");
  if (!list) return;
  list.querySelectorAll("[data-manufacturing-cost-delete-check]").forEach(function(check) {
    check.checked = !!checked;
  });
  setManufacturingCostTargetDeleteStatus("", false);
  updateManufacturingCostTargetDeleteCount();
}

function removeSelectedManufacturingCostTargets() {
  if (!canEditManufacturingCostMgmt()) { alert(t("err_perm")); return; }
  var list = document.getElementById("manufacturing-cost-target-delete-list");
  if (!list) return;
  var selectedIds = Array.from(list.querySelectorAll("[data-manufacturing-cost-delete-check]:checked")).map(function(check) {
    return String(check.value || "");
  }).filter(Boolean);
  if (!selectedIds.length) {
    setManufacturingCostTargetDeleteStatus(t("manufacturing_cost_remove_none"), true);
    return;
  }
  if (!confirm(tf("manufacturing_cost_remove_confirm", { n: selectedIds.length }))) return;
  var selectedMap = {};
  selectedIds.forEach(function(id) { selectedMap[id] = true; });
  manufacturingCostRows = (manufacturingCostRows || []).filter(function(item) {
    return !selectedMap[String((item && item.productId) || "")];
  });
  if (manufacturingCostListItemSnapshotMap) {
    selectedIds.forEach(function(id) { delete manufacturingCostListItemSnapshotMap[id]; });
  }
  closeManufacturingCostTargetDelete();
  renderManufacturingCostRows();
  if (manufacturingCostCandidateRows.length) {
    renderManufacturingCostCandidates(manufacturingCostCandidateRows, manufacturingCostCandidateMode);
  }
  setManufacturingCostListStatus(t("manufacturing_cost_remove_target_done"), false);
}

function renderManufacturingCostRows() {
  var list = document.getElementById("manufacturing-cost-list");
  var countEl = document.getElementById("manufacturing-cost-count");
  var removeOpenBtn = document.getElementById("btn-manufacturing-cost-remove-open");
  if (removeOpenBtn) removeOpenBtn.disabled = !canEditManufacturingCostMgmt() || !manufacturingCostRows.length;
  if (!list) return;
  if (countEl) countEl.textContent = tf("manufacturing_cost_selected_count", { n: manufacturingCostRows.length || 0 });
  renderManufacturingCostSummary(manufacturingCostRows);
  if (!manufacturingCostRows.length) {
    list.innerHTML = "<div class='empty'>" + esc(t("no_results")) + "</div>";
    return;
  }
  var html = "<div class='manufacturing-cost-table-wrap'><table class='mgmt-table manufacturing-cost-table'>";
  html += "<tr><th>" + esc(t("manufacturing_cost_product")) + "</th><th>" + esc(t("manufacturing_cost_components")) + "</th><th>" + esc(t("manufacturing_cost_parts_cost")) + "</th><th>" + esc(t("manufacturing_cost_core_cost_short")) + "</th><th>" + esc(t("manufacturing_cost_labor_cost")) + "</th><th>" + esc(t("manufacturing_cost_selling_expense_cost")) + "</th><th>" + esc(t("manufacturing_cost_total")) + "</th><th>" + esc(t("manufacturing_cost_notes")) + "</th></tr>";
  manufacturingCostRows.forEach(function(row, rowIndex) {
    var p = row.product || {};
    var notes = [];
    if (!row.componentCount) notes.push(t("manufacturing_cost_no_components"));
    if (row.missingUnitCount) notes.push(tf("manufacturing_cost_missing_unit", { n: row.missingUnitCount }));
    if (row.missingQuantityCount) notes.push(tf("manufacturing_cost_missing_quantity", { n: row.missingQuantityCount }));
    if (row.missingReplacementRateCount) notes.push(tf("manufacturing_cost_missing_replacement_rate", { n: row.missingReplacementRateCount }));
    if (row.savedSnapshotUnitPriceDiffers) notes.push(t("manufacturing_cost_snapshot_unit_price_changed"));
    var coreNote = row.coreCostSource === "product"
      ? t("core_charge_product_source") + (row.coreReturnRequired === false ? " / " + t("core_return_not_required") : "")
      : row.coreCostSource === "kind_default"
        ? t("core_return_not_required")
        : row.coreCostCategorySpecific
          ? tf("manufacturing_cost_core_category_note", { category: manufacturingCostCategoryLabel(row.coreCostCategory) })
          : t("manufacturing_cost_core_default_note");
    var detailHtml = renderManufacturingCostComponentDetails(row, rowIndex);
    var productFacts = [
      [t("f_mfr_pn"), p.manufacturer_part_number],
      [t("f_genuine_pn"), p.genuine_part_number || p.genuine_part_number_2],
      [t("f_manufacturer"), p.manufacturer],
      ["DKD", row.productId]
    ].filter(function(item) { return item[1] !== null && item[1] !== undefined && item[1] !== ""; }).map(function(item) {
      return "<span><b>" + esc(item[0]) + "</b> " + esc(item[1]) + "</span>";
    }).join("");
    var productSub = [p.genuine_part_number_2, tCat(p.category_code || p.category)].filter(Boolean).join(" / ");
    html += "<tr class='manufacturing-cost-main-row'>";
    html += "<td><div class='manufacturing-cost-product-main'>" + esc(manufacturingCostProductTitle(p)) + "</div>" + (productFacts ? "<div class='manufacturing-cost-product-facts'>" + productFacts + "</div>" : "") + "<div class='manufacturing-cost-product-sub'>" + esc(productSub) + "</div></td>";
    html += "<td><div class='manufacturing-cost-money'>" + esc(String(row.componentCount || 0)) + "</div></td>";
    html += "<td><div class='manufacturing-cost-money'>" + esc(manufacturingCostYen(row.partsCost)) + "</div></td>";
    html += "<td><div class='manufacturing-cost-money'>" + esc(manufacturingCostYen(row.coreCost)) + "</div><div class='manufacturing-cost-note'>" + esc(coreNote) + "</div></td>";
    html += "<td><div class='manufacturing-cost-money'>" + esc(manufacturingCostYen(row.laborCost)) + "</div></td>";
    html += "<td><div class='manufacturing-cost-money'>" + esc(manufacturingCostYen(row.sellingExpense)) + "</div></td>";
    html += "<td><div class='manufacturing-cost-money manufacturing-cost-total'>" + esc(manufacturingCostYen(row.totalCost)) + "</div><div class='manufacturing-cost-note'>" + esc(t("manufacturing_cost_formula_note")) + "</div></td>";
    html += "<td>" + (notes.length ? "<div class='manufacturing-cost-missing'>" + esc(notes.join(" / ")) + "</div>" : "") + "</td>";
    html += "</tr>";
    if (detailHtml) html += "<tr class='manufacturing-cost-detail-row'><td colspan='8'>" + detailHtml + "</td></tr>";
  });
  html += "</table></div>";
  list.innerHTML = html;
  bindManufacturingCostComponentDetailToggles();
}

function manufacturingCostExportFileName() {
  var listName = (document.getElementById("manufacturing-cost-list-name") || {}).value || "";
  var base = listName.trim() || "manufacturing_cost";
  base = normalizeAsciiWidth(base).replace(/[\\/:*?"<>|]+/g, "_").replace(/\s+/g, "_").replace(/^_+|_+$/g, "");
  if (!base) base = "manufacturing_cost";
  var d = new Date();
  var y = String(d.getFullYear());
  var m = String(d.getMonth() + 1).padStart(2, "0");
  var day = String(d.getDate()).padStart(2, "0");
  return base + "_" + y + m + day + ".csv";
}

function exportManufacturingCostRows() {
  if (!canViewManufacturingCostMgmt()) { alert(t("err_perm")); return; }
  if (!manufacturingCostRows.length) {
    setManufacturingCostListStatus(t("manufacturing_cost_export_no_rows"), true);
    return;
  }
  var rows = [[
    "カテゴリ名",
    "純正品番",
    "メーカー品番",
    "部品原価",
    "コア代",
    "製造工賃",
    "販売費用",
    "製造原価計"
  ]];
  manufacturingCostRows.forEach(function(row) {
    var p = row.product || {};
    var category = manufacturingCostCategoryLabel(p.category_code || p.category || "");
    rows.push([
      category,
      p.genuine_part_number || p.genuine_part_number_2 || "",
      p.manufacturer_part_number || "",
      Math.round(row.partsCost || 0),
      Math.round(row.coreCost || 0),
      Math.round(row.laborCost || 0),
      Math.round(row.sellingExpense || 0),
      Math.round(row.totalCost || 0)
    ]);
  });
  var csv = rows.map(function(row) {
    return row.map(ecMallCsvCell).join(",");
  }).join("\r\n") + "\r\n";
  var blob = new Blob(["\ufeff" + csv], { type: "text/csv;charset=utf-8" });
  var url = URL.createObjectURL(blob);
  var a = document.createElement("a");
  a.href = url;
  a.download = manufacturingCostExportFileName();
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(function() { URL.revokeObjectURL(url); }, 1000);
  setManufacturingCostListStatus(tf("manufacturing_cost_export_done", { n: manufacturingCostRows.length }), false);
}

async function searchManufacturingCostCandidates() {
  if (!canViewManufacturingCostMgmt()) { alert(t("err_perm")); return; }
  var requestSeq = ++manufacturingCostCandidateRequestSeq;
  manufacturingCostActiveListId = null;
  var list = document.getElementById("manufacturing-cost-list");
  var countEl = document.getElementById("manufacturing-cost-count");
  var summaryEl = document.getElementById("manufacturing-cost-summary");
  var candidatesEl = document.getElementById("manufacturing-cost-candidates");
  var q = (document.getElementById("manufacturing-cost-query") || {}).value || "";
  var category = (document.getElementById("manufacturing-cost-category") || {}).value || "";
  var tokens = manufacturingCostTokens(q);
  var hadRows = manufacturingCostRows.length > 0;
  if (!tokens.length && !category) {
    renderManufacturingCostCandidateEmpty(t("manufacturing_cost_need_condition"));
    if (!hadRows) renderManufacturingCostEmpty();
    return;
  }
  if (candidatesEl) candidatesEl.innerHTML = "<div class='manufacturing-cost-candidate-panel'><div class='loading'>" + esc(t("loading")) + "</div></div>";
  if (list && !hadRows) list.innerHTML = "<div class='empty'>" + esc(t("manufacturing_cost_candidate_search_hint")) + "</div>";
  if (countEl && !hadRows) countEl.textContent = tf("manufacturing_cost_selected_count", { n: 0 });
  if (summaryEl && !hadRows) summaryEl.innerHTML = "";
  manufacturingCostCandidateStatusMap = {};
  try {
    var pr = await fetchManufacturingCostProducts(tokens, category);
    if (requestSeq !== manufacturingCostCandidateRequestSeq) return;
    if (pr.error) throw pr.error;
    var products = pr.data || [];
    await loadManufacturingCostCandidateStatuses(products);
    if (requestSeq !== manufacturingCostCandidateRequestSeq) return;
    renderManufacturingCostCandidates(products, tokens.length ? "query" : "category");
    if (!products.length && list && !hadRows) list.innerHTML = "<div class='empty'>" + esc(t("no_results")) + "</div>";
  } catch (e) {
    if (requestSeq !== manufacturingCostCandidateRequestSeq) return;
    console.warn("manufacturing cost candidate search failed", e);
    manufacturingCostCandidateRows = [];
    manufacturingCostCandidateStatusMap = {};
    if (countEl && !hadRows) countEl.textContent = tf("manufacturing_cost_selected_count", { n: 0 });
    if (candidatesEl) candidatesEl.innerHTML = "";
    if (list && !hadRows) list.innerHTML = "<div class='empty'>" + esc(t("msg_part_err") + ": " + ((e && e.message) || String(e))) + "</div>";
    setManufacturingCostListStatus((e && e.message) || String(e), true);
  }
}

async function calculateSelectedManufacturingCost() {
  if (!canViewManufacturingCostMgmt()) { alert(t("err_perm")); return; }
  var duplicates = selectedManufacturingCostDuplicateCandidateProducts();
  if (duplicates.length) {
    alert(t("manufacturing_cost_duplicate_selected_alert"));
    setManufacturingCostListStatus(t("manufacturing_cost_duplicate_selected_status"), true);
    renderManufacturingCostCandidates(manufacturingCostCandidateRows, manufacturingCostCandidateMode);
    return;
  }
  var products = selectedManufacturingCostCandidateProducts();
  if (!products.length) {
    setManufacturingCostListStatus(t("manufacturing_cost_no_candidate_selected"), true);
    return;
  }
  setManufacturingCostListStatus("", false);
  var list = document.getElementById("manufacturing-cost-list");
  var countEl = document.getElementById("manufacturing-cost-count");
  var summaryEl = document.getElementById("manufacturing-cost-summary");
  if (list) list.innerHTML = "<div class='loading'>" + esc(t("loading")) + "</div>";
  if (countEl) countEl.textContent = t("loading");
  if (summaryEl) summaryEl.innerHTML = "";
  try {
    await buildAndRenderManufacturingCostProducts(mergeManufacturingCostProducts(products), manufacturingCostSettings());
    renderManufacturingCostCandidates(manufacturingCostCandidateRows, manufacturingCostCandidateMode);
  } catch (e) {
    console.warn("manufacturing cost calculation failed", e);
    manufacturingCostRows = [];
    manufacturingCostComponentMap = {};
    manufacturingCostCorePolicyMap = {};
    if (countEl) countEl.textContent = "";
    if (list) list.innerHTML = "<div class='empty'>" + esc(t("msg_part_err") + ": " + ((e && e.message) || String(e))) + "</div>";
  }
}

async function calculateManufacturingCost() {
  await searchManufacturingCostCandidates();
}

async function syncManufacturingCostListItems(listId, items) {
  if (!listId || !items.length) {
    return { data: null, error: new Error(t("manufacturing_cost_list_rows_required")) };
  }
  var currentR = await sb.from("manufacturing_cost_list_items")
    .select("id,dkd_shohin_id")
    .eq("list_id", listId);
  if (currentR.error) return currentR;
  for (var i = 0; i < items.length; i += 200) {
    var upsertR = await sb.from("manufacturing_cost_list_items")
      .upsert(items.slice(i, i + 200), { onConflict: "list_id,dkd_shohin_id" });
    if (upsertR.error) return upsertR;
  }
  var keepProductIds = {};
  items.forEach(function(item) {
    keepProductIds[String(item.dkd_shohin_id)] = true;
  });
  var staleIds = (currentR.data || []).filter(function(row) {
    return !keepProductIds[String(row.dkd_shohin_id)];
  }).map(function(row) {
    return row.id;
  }).filter(Boolean);
  for (var j = 0; j < staleIds.length; j += 200) {
    var deleteR = await sb.from("manufacturing_cost_list_items")
      .delete()
      .eq("list_id", listId)
      .in("id", staleIds.slice(j, j + 200));
    if (deleteR.error) return deleteR;
  }
  return { data: items, error: null };
}

async function saveManufacturingCostList() {
  if (!canEditManufacturingCostMgmt()) { alert(t("err_perm")); return; }
  var category = manufacturingCostSelectedCategory();
  var listNameEl = document.getElementById("manufacturing-cost-list-name");
  var listName = listNameEl ? listNameEl.value.trim() : "";
  if (!listName) { setManufacturingCostListStatus(t("manufacturing_cost_list_name_required"), true); if (listNameEl) listNameEl.focus(); return; }
  var selected = selectedManufacturingCostList();
  if (!manufacturingCostRows.length) { setManufacturingCostListStatus(t("manufacturing_cost_list_rows_required"), true); return; }
  var settings = manufacturingCostSettings();
  var currentProducts = manufacturingCostRows.map(function(row) { return row.product; }).filter(Boolean);
  var currentLoads = await Promise.all([
    loadManufacturingCostComponents(currentProducts, settings.productKind),
    loadManufacturingCostCorePolicies(currentProducts, settings.productKind)
  ]);
  var currentLoadError = currentLoads.find(function(result) { return result.error; });
  if (currentLoadError) { setManufacturingCostListStatus(currentLoadError.error.message || t("msg_part_err"), true); return; }
  var updatedUnitPriceCount = 0;
  var rowsToSave = manufacturingCostRows.map(function(row) {
    var refreshed = manufacturingCostRowWithCurrentUnitPrices(row, settings);
    updatedUnitPriceCount += refreshed.updatedCount;
    return refreshed.row;
  });
  var selectedCategory = selected ? (selected.category_code || "") : "";
  var existing = selected && selected.id && selected.list_name === listName && selectedCategory === category ? selected : null;
  if (!existing) {
    var existingQuery = sb.from("manufacturing_cost_lists")
      .select("id")
      .eq("list_name", listName)
      .eq("is_active", true);
    existingQuery = category ? existingQuery.eq("category_code", category) : existingQuery.is("category_code", null);
    var existingR = await existingQuery.maybeSingle();
    if (existingR.error) { setManufacturingCostListStatus(existingR.error.message || t("msg_part_err"), true); return; }
    existing = existingR.data || null;
  }
  var payload = {
    list_name: listName,
    category_code: category || null,
    product_kind: settings.productKind,
    core_cost_jpy: manufacturingCostCoreCostForCategory(category, settings),
    labor_rate_percent: settings.laborRate,
    labor_amount_jpy: settings.laborAmount,
    selling_expense_jpy: settings.sellingExpense,
    updated_by: currentUser ? currentUser.id : null,
    updated_at: new Date().toISOString()
  };
  var saveR;
  if (existing && existing.id) {
    saveR = await sb.from("manufacturing_cost_lists").update(payload).eq("id", existing.id).select("*").single();
  } else {
    payload.created_by = currentUser ? currentUser.id : null;
    saveR = await sb.from("manufacturing_cost_lists").insert(payload).select("*").single();
  }
  if (saveR.error) { setManufacturingCostListStatus(saveR.error.message || t("msg_part_err"), true); return; }
  var listId = saveR.data.id;
  var items = rowsToSave.map(function(row, idx) {
    var p = row.product || {};
    return {
      list_id: listId,
      dkd_shohin_id: row.productId,
      sort_order: idx + 1,
      part_number_snapshot: p.manufacturer_part_number || null,
      genuine_part_number_snapshot: p.genuine_part_number || null,
      manufacturer_snapshot: p.manufacturer || null,
      category_code_snapshot: p.category_code || p.category || category,
      component_count_snapshot: row.componentCount || 0,
      missing_unit_count_snapshot: row.missingUnitCount || 0,
      parts_cost_jpy_snapshot: Math.round(row.partsCost || 0),
      core_cost_jpy_snapshot: Math.round(row.coreCost || 0),
      labor_cost_jpy_snapshot: Math.round(row.laborCost || 0),
      selling_expense_jpy_snapshot: Math.round(row.sellingExpense || 0),
      total_cost_jpy_snapshot: Math.round(row.totalCost || 0),
      components_snapshot: manufacturingCostRowComponentSnapshots(row)
    };
  }).filter(function(row) { return !!row.dkd_shohin_id; });
  if (items.length !== rowsToSave.length) { setManufacturingCostListStatus(t("manufacturing_cost_list_rows_required"), true); return; }
  var syncR = await syncManufacturingCostListItems(listId, items);
  if (syncR.error) { setManufacturingCostListStatus(syncR.error.message || t("msg_part_err"), true); return; }
  manufacturingCostActiveListId = listId;
  manufacturingCostRows = rowsToSave;
  manufacturingCostListItemSnapshotMap = manufacturingCostBuildSnapshotMap(items);
  await refreshManufacturingCostSavedLists();
  renderManufacturingCostRows();
  setManufacturingCostListStatus(updatedUnitPriceCount
    ? tf("manufacturing_cost_list_saved_current_prices", { n: updatedUnitPriceCount })
    : t("manufacturing_cost_list_saved"), false);
}

async function loadManufacturingCostList() {
  if (!canViewManufacturingCostMgmt()) { alert(t("err_perm")); return; }
  var selected = selectedManufacturingCostList();
  if (!selected) { setManufacturingCostListStatus(t("manufacturing_cost_list_select_required"), true); return; }
  manufacturingCostActiveListId = selected.id;
  var categoryEl = document.getElementById("manufacturing-cost-category");
  var kindEl = document.getElementById("manufacturing-cost-kind");
  var nameEl = document.getElementById("manufacturing-cost-list-name");
  var queryEl = document.getElementById("manufacturing-cost-query");
  if (categoryEl) categoryEl.value = selected.category_code || "";
  if (kindEl) kindEl.value = selected.product_kind || "rebuilt";
  if (nameEl) nameEl.value = selected.list_name || "";
  if (queryEl) queryEl.value = "";
  var coreEl = document.getElementById("manufacturing-cost-core-cost");
  var rateEl = document.getElementById("manufacturing-cost-labor-rate");
  var amountEl = document.getElementById("manufacturing-cost-labor-amount");
  var sellingEl = document.getElementById("manufacturing-cost-selling-expense");
  if (coreEl) coreEl.value = selected.core_cost_jpy == null ? 1500 : selected.core_cost_jpy;
  if (selected.category_code && selected.core_cost_jpy != null) {
    manufacturingCostCategoryCoreCosts[selected.category_code] = parseInt(selected.core_cost_jpy, 10) || 0;
    saveManufacturingCostCategoryCoreCosts();
    renderManufacturingCostCategoryCoreCosts();
  }
  if (rateEl) rateEl.value = selected.labor_rate_percent == null ? 0 : selected.labor_rate_percent;
  if (amountEl) amountEl.value = selected.labor_amount_jpy == null ? MANUFACTURING_COST_DEFAULT_LABOR_AMOUNT_JPY : selected.labor_amount_jpy;
  if (sellingEl) sellingEl.value = selected.selling_expense_jpy == null ? MANUFACTURING_COST_DEFAULT_SELLING_EXPENSE_JPY : selected.selling_expense_jpy;
  await refreshManufacturingCostSavedLists();
  renderManufacturingCostCandidateEmpty("");
  var list = document.getElementById("manufacturing-cost-list");
  var countEl = document.getElementById("manufacturing-cost-count");
  var summaryEl = document.getElementById("manufacturing-cost-summary");
  if (list) list.innerHTML = "<div class='loading'>" + esc(t("loading")) + "</div>";
  if (countEl) countEl.textContent = t("loading");
  if (summaryEl) summaryEl.innerHTML = "";
  try {
    var itemsR = await sb.from("manufacturing_cost_list_items")
      .select("*")
      .eq("list_id", selected.id)
      .order("sort_order", { ascending: true });
    if (itemsR.error) throw itemsR.error;
    var itemRows = itemsR.data || [];
    if (!itemRows.length) throw new Error(t("manufacturing_cost_list_rows_required"));
    var ids = itemRows.map(function(row) { return row.dkd_shohin_id; });
    var snapshotMap = manufacturingCostBuildSnapshotMap(itemRows);
    var productR = await fetchManufacturingCostProductsByIds(ids);
    if (productR.error) throw productR.error;
    await buildAndRenderManufacturingCostProducts(productR.data || [], manufacturingCostSettings(), { snapshotMap: snapshotMap });
    setManufacturingCostListStatus(t("manufacturing_cost_list_loaded"), false);
  } catch (e) {
    console.warn("manufacturing cost list load failed", e);
    manufacturingCostRows = [];
    manufacturingCostComponentMap = {};
    manufacturingCostCorePolicyMap = {};
    if (countEl) countEl.textContent = "";
    if (list) list.innerHTML = "<div class='empty'>" + esc(t("msg_part_err") + ": " + ((e && e.message) || String(e))) + "</div>";
    setManufacturingCostListStatus((e && e.message) || String(e), true);
  }
}

async function deleteManufacturingCostList() {
  if (!canEditManufacturingCostMgmt()) { alert(t("err_perm")); return; }
  var selected = selectedManufacturingCostList();
  if (!selected) { setManufacturingCostListStatus(t("manufacturing_cost_list_select_required"), true); return; }
  if (!confirm(t("manufacturing_cost_list_delete_confirm"))) return;
  var r = await sb.from("manufacturing_cost_lists")
    .update({ is_active: false, updated_by: currentUser ? currentUser.id : null, updated_at: new Date().toISOString() })
    .eq("id", selected.id);
  if (r.error) { setManufacturingCostListStatus(r.error.message || t("msg_part_err"), true); return; }
  manufacturingCostActiveListId = null;
  await refreshManufacturingCostSavedLists();
  setManufacturingCostListStatus(t("manufacturing_cost_list_deleted"), false);
}

