async function enterFinishedLabelMgmt(options) {
  if (!canViewFinishedLabelMgmt()) { alert(t("err_perm")); return; }
  showScreen("finished-label-mgmt");
  renderFinishedLabelCategoryOptions();
  renderFinishedLabelEmpty();
  await loadFinishedLabelTemplates();
  setFinishedLabelPrintMode(options && options.mode ? options.mode : "");
  if (options && options.product) {
    if (!finishedLabelPrintMode) setFinishedLabelPrintMode("product");
    await selectFinishedLabelProduct(options.product, options.instruction || null);
  }
}

function setFinishedLabelPrintMode(mode) {
  mode = mode === "box" ? "box" : (mode === "product" ? "product" : "");
  var previousMode = finishedLabelPrintMode;
  finishedLabelPrintMode = mode;
  if (!mode || (previousMode && previousMode !== mode)) {
    finishedLabelLastIssuedRecord = null;
    finishedLabelSelectedHistoryId = null;
    var productPrint = document.getElementById("btn-finished-label-preview");
    var boxPrint = document.getElementById("btn-finished-box-label-preview");
    if (productPrint) productPrint.disabled = true;
    if (boxPrint) boxPrint.disabled = true;
    renderFinishedLabelIssuedResult(null);
  }
  var hub = document.getElementById("finished-label-mode-hub");
  var workspace = document.getElementById("finished-label-workspace");
  if (hub) hub.hidden = !!mode;
  if (workspace) {
    workspace.hidden = !mode;
    workspace.classList.toggle("is-product-mode", mode === "product");
    workspace.classList.toggle("is-box-mode", mode === "box");
  }
  document.querySelectorAll("[data-finished-label-product-only]").forEach(function(el) {
    el.hidden = mode !== "product";
  });
  document.querySelectorAll("[data-finished-label-box-only]").forEach(function(el) {
    el.hidden = mode !== "box";
  });
  var title = document.getElementById("finished-label-screen-title");
  var badge = document.getElementById("finished-label-mode-badge");
  var searchTitle = document.getElementById("finished-label-product-search-title");
  var searchHint = document.getElementById("finished-label-search-hint");
  var editorTitle = document.getElementById("finished-label-editor-title");
  if (!mode) {
    if (title) title.textContent = t("finished_label_screen_title");
    return;
  }
  var isBox = mode === "box";
  if (title) title.textContent = t(isBox ? "finished_box_label_screen_title" : "finished_label_product_screen_title");
  if (badge) badge.textContent = t(isBox ? "finished_box_label_badge" : "finished_label_product_badge");
  if (searchTitle) searchTitle.textContent = t(isBox ? "finished_box_label_product_search" : "finished_label_product_search");
  if (searchHint) searchHint.textContent = t(isBox ? "finished_box_label_search_hint" : "finished_label_search_hint");
  if (editorTitle) editorTitle.textContent = t(isBox ? "finished_box_label_issue_form" : "finished_label_issue_form");
  renderFinishedLabelHistory();
  renderFinishedLabelIssuedResult(finishedLabelLastIssuedRecord);
}

function renderFinishedLabelEmpty() {
  finishedLabelProducts = [];
  finishedLabelProductReadinessMap = {};
  finishedLabelBoxReadinessMap = {};
  finishedLabelVisibleLimit = FINISHED_LABEL_PAGE_STEP;
  finishedLabelSearchRequestSeq += 1;
  finishedLabelInstructionMap = {};
  finishedLabelSelectedProduct = null;
  finishedLabelSelectedInstruction = null;
  finishedLabelVariants = [];
  finishedLabelHistoryRows = [];
  finishedLabelLastIssuedRecord = null;
  finishedLabelSelectedHistoryId = null;
  finishedLabelComponentCandidates = [];
  finishedLabelSelectedComponentIds = {};
  finishedLabelComponentLoadSeq += 1;
  var results = document.getElementById("finished-label-results");
  var count = document.getElementById("finished-label-search-count");
  var loadMore = document.getElementById("btn-finished-label-load-more");
  var history = document.getElementById("finished-label-history-list");
  if (count) count.textContent = "";
  if (loadMore) loadMore.hidden = true;
  if (results) results.innerHTML = "<div class='empty'>" + esc(t(finishedLabelPrintMode === "box" ? "finished_box_label_search_hint" : "finished_label_search_hint")) + "</div>";
  if (history) history.innerHTML = "<div class='empty'>" + esc(t("finished_label_select_product")) + "</div>";
  renderFinishedLabelSelectedSummary(null);
  renderFinishedLabelVariantOptions([]);
  resetFinishedLabelForm();
  renderFinishedLabelComponents();
  renderFinishedLabelIssuedResult(null);
}

function renderFinishedLabelCategoryOptions(selected) {
  var select = document.getElementById("finished-label-product-category");
  if (!select) return;
  selected = selected || select.value || "オルタネータ";
  select.innerHTML = FINISHED_LABEL_CATEGORIES.map(function(row) {
    return "<option value='" + esc(row[0]) + "'" + (row[0] === selected ? " selected" : "") + ">" + esc(tCat(row[0])) + "</option>";
  }).join("");
}

function finishedLabelCategoryForProduct(p) {
  var code = String((p && (p.category_code || p.category)) || "").toLowerCase();
  var label = String(productCategoryLabel(p) || "").toLowerCase();
  if (code.indexOf("starter") >= 0 || label.indexOf("スタータ") >= 0 || label.indexOf("starter") >= 0) return "スタータ";
  if (code.indexOf("ac") >= 0 || code.indexOf("compressor") >= 0 || label.indexOf("コンプレッサ") >= 0) return "ACコンプレッサ";
  if (code.indexOf("distributor") >= 0 || label.indexOf("ディストリ") >= 0) return "ディストリビュータ";
  if (code.indexOf("alternator") >= 0 || label.indexOf("オルタ") >= 0 || label.indexOf("alternator") >= 0) return "オルタネータ";
  return "その他";
}

async function loadFinishedLabelTemplates() {
  var r = await sb.from("finished_label_part_templates")
    .select("id,product_kind,part_type,default_maker,default_part_number,sort_order,is_active")
    .eq("is_active", true)
    .order("product_kind", { ascending: true })
    .order("sort_order", { ascending: true });
  if (r.error) {
    console.warn("finished label template lookup failed", r.error);
    finishedLabelTemplates = [];
    return;
  }
  finishedLabelTemplates = r.data || [];
}

function finishedLabelTemplatesForCategory(category) {
  var rows = (finishedLabelTemplates || []).filter(function(row) {
    return row.product_kind === category;
  });
  if (rows.length) return rows;
  return [{ part_type: "備考", default_maker: "", default_part_number: "", sort_order: 10 }];
}

function normalizeFinishedLabelSearchValue(value) {
  return normalizeAsciiWidth(value)
    .replace(/[\u2010-\u2015\u2212\u30FC\uFF0D]/g, "-")
    .toUpperCase()
    .replace(/[^0-9A-Z-]/g, "");
}

function normalizeFinishedLabelSearchInput(input) {
  if (!input) return "";
  var normalized = normalizeFinishedLabelSearchValue(input.value);
  if (input.value === normalized) return normalized;
  var cursor = input.selectionStart;
  input.value = normalized;
  if (typeof cursor === "number" && typeof input.setSelectionRange === "function") {
    cursor = Math.min(cursor, normalized.length);
    input.setSelectionRange(cursor, cursor);
  }
  return normalized;
}

function finishedLabelAsciiKeyFromEvent(event) {
  if (!event || event.ctrlKey || event.metaKey || event.altKey) return "";
  var code = String(event.code || "");
  if (/^Key[A-Z]$/.test(code)) return code.slice(3);
  if (/^Digit[0-9]$/.test(code)) return code.slice(5);
  if (/^Numpad[0-9]$/.test(code)) return code.slice(6);
  if (code === "Minus" || code === "NumpadSubtract") return "-";
  return "";
}

function insertFinishedLabelAsciiKey(input, value) {
  if (!input || !value) return;
  var start = typeof input.selectionStart === "number" ? input.selectionStart : input.value.length;
  var end = typeof input.selectionEnd === "number" ? input.selectionEnd : start;
  if (typeof input.setRangeText === "function") {
    input.setRangeText(value, start, end, "end");
    return;
  }
  input.value = input.value.slice(0, start) + value + input.value.slice(end);
  if (typeof input.setSelectionRange === "function") {
    var nextCursor = start + value.length;
    input.setSelectionRange(nextCursor, nextCursor);
  }
}

function captureFinishedLabelSearchInputState(input) {
  if (!input) return { value: "", start: 0, end: 0 };
  var value = String(input.value || "");
  var start = typeof input.selectionStart === "number" ? input.selectionStart : value.length;
  var end = typeof input.selectionEnd === "number" ? input.selectionEnd : start;
  return { value: value, start: start, end: end };
}

function restoreFinishedLabelSearchInputState(input, state) {
  if (!input || !state) return;
  input.value = String(state.value || "");
  if (typeof input.setSelectionRange === "function") {
    var start = Math.min(Number(state.start) || 0, input.value.length);
    var end = Math.min(Number(state.end) || start, input.value.length);
    input.setSelectionRange(start, end);
  }
}

function isFinishedLabelSearchCompositionFollowup(event, composing) {
  if (!event) return false;
  var inputType = String(event.inputType || "");
  return !!composing || !!event.isComposing || inputType === "insertCompositionText" || inputType === "insertText";
}

async function loadFinishedLabelProductReadiness(products) {
  var readinessMap = {};
  var ids = Array.from(new Set((products || []).map(function(product) {
    return parseInt(productDkdId(product), 10);
  }).filter(function(id) {
    return !isNaN(id);
  })));
  if (!ids.length) return readinessMap;

  var requests = await Promise.all([
    fetchProductionPartRegistrationCountMap(products),
    sb.from("core_product_variants")
      .select("dkd_shohin_id,product_kind")
      .in("dkd_shohin_id", ids)
      .in("product_kind", ["rebuilt", "aftermarket_new"])
      .eq("is_active", true)
      .limit(Math.max(ids.length * 3, 100))
  ]);
  var componentCounts = requests[0] && requests[0].byKind || {};
  var variantResult = requests[1] || {};
  ids.forEach(function(id) {
    var key = String(id);
    var counts = componentCounts[key] || {};
    readinessMap[key] = {
      rebuiltComponents: parseInt(counts.rebuilt || 0, 10) || 0,
      aftermarketNewComponents: parseInt(counts.aftermarket_new || 0, 10) || 0,
      hasRebuiltVariant: false,
      hasAftermarketNewVariant: false
    };
  });
  if (variantResult.error) {
    console.warn("finished label product-kind readiness lookup failed", variantResult.error);
    return readinessMap;
  }
  (variantResult.data || []).forEach(function(row) {
    var readiness = readinessMap[String(row.dkd_shohin_id || "")];
    if (!readiness) return;
    var kind = normalizeProductKind(row.product_kind);
    if (kind === "rebuilt") readiness.hasRebuiltVariant = true;
    if (kind === "aftermarket_new") readiness.hasAftermarketNewVariant = true;
  });
  return readinessMap;
}

async function loadFinishedBoxLabelProductReadiness(products) {
  var ids = Array.from(new Set((products || []).map(function(product) {
    return parseInt(productDkdId(product), 10);
  }).filter(function(id) {
    return !isNaN(id);
  })));
  if (!ids.length) return {};
  var result = await sb.from("finished_label_issues")
    .select("id,dkd_shohin_id,issue_code,quantity,issued_at")
    .in("dkd_shohin_id", ids)
    .order("issued_at", { ascending: false })
    .limit(1000);
  if (result.error) {
    console.warn("finished box label readiness lookup failed", result.error);
    return {};
  }
  var readinessMap = {};
  ids.forEach(function(id) {
    readinessMap[String(id)] = { issueCount: 0, latestIssuedAt: "", latestIssueCode: "", totalUnits: 0 };
  });
  (result.data || []).forEach(function(row) {
    var readiness = readinessMap[String(row.dkd_shohin_id || "")];
    if (!readiness) return;
    readiness.issueCount += 1;
    readiness.totalUnits += parseInt(row.quantity || 0, 10) || 0;
    if (!readiness.latestIssuedAt || String(row.issued_at || "") > readiness.latestIssuedAt) {
      readiness.latestIssuedAt = row.issued_at || "";
      readiness.latestIssueCode = row.issue_code || "";
    }
  });
  return readinessMap;
}

function finishedLabelProductPriority(product) {
  if (finishedLabelPrintMode === "box") {
    var boxReadiness = finishedLabelBoxReadinessMap[String(productDkdId(product) || "")];
    if (!boxReadiness) return 2;
    return Number(boxReadiness.issueCount) > 0 ? 0 : 1;
  }
  var readiness = finishedLabelProductReadinessMap[String(productDkdId(product) || "")] || {};
  var rebuiltComponents = parseInt(readiness.rebuiltComponents || 0, 10) || 0;
  var aftermarketNewComponents = parseInt(readiness.aftermarketNewComponents || 0, 10) || 0;
  var hasBothComponents = rebuiltComponents > 0 && aftermarketNewComponents > 0;
  var hasBothVariants = !!readiness.hasRebuiltVariant && !!readiness.hasAftermarketNewVariant;
  var hasComponents = rebuiltComponents + aftermarketNewComponents > 0;
  if (hasBothComponents) return 0;
  if (hasBothVariants && hasComponents) return 1;
  if (hasComponents) return 2;
  if (hasBothVariants) return 3;
  return 4;
}

function sortFinishedLabelProducts(products) {
  return (products || []).map(function(product, index) {
    return { product: product, index: index };
  }).sort(function(a, b) {
    var priorityDiff = finishedLabelProductPriority(a.product) - finishedLabelProductPriority(b.product);
    if (priorityDiff) return priorityDiff;
    if (finishedLabelPrintMode === "box") {
      var aBox = finishedLabelBoxReadinessMap[String(productDkdId(a.product) || "")] || {};
      var bBox = finishedLabelBoxReadinessMap[String(productDkdId(b.product) || "")] || {};
      var latestDiff = String(bBox.latestIssuedAt || "").localeCompare(String(aBox.latestIssuedAt || ""));
      if (latestDiff) return latestDiff;
    }
    var aInstruction = finishedLabelInstructionMap[String(productDkdId(a.product))] || {};
    var bInstruction = finishedLabelInstructionMap[String(productDkdId(b.product))] || {};
    var aRank = parseInt(aInstruction.priority_rank, 10);
    var bRank = parseInt(bInstruction.priority_rank, 10);
    aRank = isNaN(aRank) ? Number.MAX_SAFE_INTEGER : aRank;
    bRank = isNaN(bRank) ? Number.MAX_SAFE_INTEGER : bRank;
    return aRank === bRank ? a.index - b.index : aRank - bRank;
  }).map(function(entry) {
    return entry.product;
  });
}

async function searchFinishedLabelProducts() {
  if (!canViewFinishedLabelMgmt()) return;
  var requestSeq = ++finishedLabelSearchRequestSeq;
  finishedLabelVisibleLimit = FINISHED_LABEL_PAGE_STEP;
  finishedLabelProductReadinessMap = {};
  finishedLabelBoxReadinessMap = {};
  var qEl = document.getElementById("finished-label-search");
  var q = normalizeFinishedLabelSearchInput(qEl);
  var results = document.getElementById("finished-label-results");
  var count = document.getElementById("finished-label-search-count");
  var loadMore = document.getElementById("btn-finished-label-load-more");
  if (results) results.innerHTML = "<div class='loading'>" + esc(t("loading")) + "</div>";
  if (count) count.textContent = t("loading");
  if (loadMore) loadMore.hidden = true;

  var rows = [];
  finishedLabelInstructionMap = {};
  if (q) {
    var pr = await fetchCoreProductMasterMatches(q, null, 80);
    if (pr.error) {
      if (results) results.innerHTML = "<div class='empty'>" + esc(pr.error.message || t("msg_part_err")) + "</div>";
      if (count) count.textContent = "";
      return;
    }
    rows = normalizeCoreProductFastRows(pr.data || []);
  } else if (finishedLabelPrintMode === "box") {
    rows = await fetchFinishedBoxLabelProducts();
  } else {
    rows = await fetchFinishedLabelProductionProducts();
  }
  if (requestSeq !== finishedLabelSearchRequestSeq) return;
  var visibleProducts = filterVisibleProducts(rows);
  var readinessMap = {};
  try {
    readinessMap = finishedLabelPrintMode === "box"
      ? await loadFinishedBoxLabelProductReadiness(visibleProducts)
      : await loadFinishedLabelProductReadiness(visibleProducts);
  } catch (error) {
    console.warn("finished label readiness ranking failed", error);
  }
  if (requestSeq !== finishedLabelSearchRequestSeq) return;
  if (finishedLabelPrintMode === "box") finishedLabelBoxReadinessMap = readinessMap;
  else finishedLabelProductReadinessMap = readinessMap;
  finishedLabelProducts = sortFinishedLabelProducts(visibleProducts);
  renderFinishedLabelResults();
}

async function fetchFinishedBoxLabelProducts() {
  var issueResult = await sb.from("finished_label_issues")
    .select("dkd_shohin_id,issued_at")
    .order("issued_at", { ascending: false })
    .limit(300);
  if (issueResult.error) {
    console.warn("finished box label recent issue lookup failed", issueResult.error);
    return [];
  }
  var ids = [];
  (issueResult.data || []).forEach(function(row) {
    var id = parseInt(row.dkd_shohin_id, 10);
    if (!isNaN(id) && ids.indexOf(id) < 0 && ids.length < 60) ids.push(id);
  });
  if (!ids.length) return [];
  var productResult = await sb.from("core_products")
    .select(CORE_PRODUCT_FAST_SELECT)
    .in("dkd_shohin_id", ids)
    .limit(ids.length);
  if (productResult.error) {
    console.warn("finished box label product lookup failed", productResult.error);
    return [];
  }
  var productMap = {};
  normalizeCoreProductFastRows(productResult.data || []).forEach(function(product) {
    productMap[String(productDkdId(product))] = product;
  });
  return ids.map(function(id) { return productMap[String(id)]; }).filter(Boolean);
}

async function fetchFinishedLabelProductionProducts() {
  var instR = await sb.from("production_instruction_candidates")
    .select("*")
    .order("priority_rank", { ascending: true })
    .limit(60);
  if (instR.error) {
    console.warn("finished label production lookup failed", instR.error);
    return [];
  }
  var ids = [];
  (instR.data || []).forEach(function(row) {
    var id = parseInt(row.dkd_shohin_id, 10);
    if (!isNaN(id) && ids.indexOf(id) < 0) ids.push(id);
    if (!isNaN(id)) finishedLabelInstructionMap[String(id)] = row;
  });
  if (!ids.length) return [];
  var productR = await sb.from("core_products")
    .select(CORE_PRODUCT_FAST_SELECT)
    .in("dkd_shohin_id", ids)
    .limit(ids.length);
  if (productR.error) {
    console.warn("finished label product lookup failed", productR.error);
    return normalizeCoreProductFastRows(instR.data || []);
  }
  var productMap = {};
  normalizeCoreProductFastRows(productR.data || []).forEach(function(p) {
    productMap[String(productDkdId(p))] = p;
  });
  return ids.map(function(id) {
    var p = productMap[String(id)] || {};
    var inst = finishedLabelInstructionMap[String(id)] || {};
    return Object.assign({}, inst, p, { dkd_shohin_id: id });
  });
}

function renderFinishedLabelResults() {
  var results = document.getElementById("finished-label-results");
  var count = document.getElementById("finished-label-search-count");
  var loadMore = document.getElementById("btn-finished-label-load-more");
  var visibleProducts = finishedLabelProducts.slice(0, finishedLabelVisibleLimit);
  if (count) count.textContent = tf("finished_label_count_summary", { shown: visibleProducts.length, total: finishedLabelProducts.length });
  if (loadMore) loadMore.hidden = visibleProducts.length >= finishedLabelProducts.length;
  if (!results) return;
  if (!finishedLabelProducts.length) {
    results.innerHTML = "<div class='empty'>" + esc(t("no_results")) + "</div>";
    return;
  }
  var selectedId = productDkdId(finishedLabelSelectedProduct);
  var html = "";
  visibleProducts.forEach(function(p) {
    var dkdId = productDkdId(p);
    var inst = finishedLabelInstructionMap[String(dkdId)] || null;
    var readiness = finishedLabelProductReadinessMap[String(dkdId || "")] || {};
    var boxReadiness = finishedLabelBoxReadinessMap[String(dkdId || "")] || null;
    var hasBothComponentKinds = Number(readiness.rebuiltComponents) > 0 && Number(readiness.aftermarketNewComponents) > 0;
    var hasBoxHistory = !!boxReadiness && Number(boxReadiness.issueCount) > 0;
    var active = selectedId && String(selectedId) === String(dkdId) ? " active" : "";
    var title = p.gltek_part_number || p.genuine_part_number || p.manufacturer_part_number || p.daiko_part_number || ("DKD " + dkdId);
    html += "<button type='button' class='finished-label-result" + active + ((finishedLabelPrintMode === "box" ? hasBoxHistory : hasBothComponentKinds) ? " priority" : "") + "' data-finished-label-dkd='" + esc(String(dkdId || "")) + "'>";
    html += "<div class='finished-label-result-title'>" + esc(title || "-") + "</div>";
    if (finishedLabelPrintMode === "box" && boxReadiness) {
      var boxStatus = hasBoxHistory
        ? tf("finished_box_label_ready_summary", { n: boxReadiness.issueCount, date: formatDateTime(boxReadiness.latestIssuedAt) })
        : t("finished_box_label_no_history");
      html += "<div class='finished-label-result-priority" + (hasBoxHistory ? "" : " unavailable") + "'>" + esc(boxStatus) + "</div>";
    } else if (hasBothComponentKinds) {
      html += "<div class='finished-label-result-priority'>" + esc(t("finished_label_priority_both_kinds")) + "</div>";
    }
    html += "<div class='finished-label-result-sub'>" + esc([productCategoryLabel(p), p.manufacturer, p.manufacturer_part_number].filter(Boolean).join(" / ")) + "</div>";
    html += "<div class='finished-label-result-sub'>" + esc(inst ? ("#" + (inst.priority_rank || "-") + " / " + (inst.source_year || "-")) : ("DKD " + (dkdId || "-"))) + "</div>";
    html += "</button>";
  });
  results.innerHTML = html;
  results.querySelectorAll("[data-finished-label-dkd]").forEach(function(btn) {
    btn.addEventListener("click", function() {
      var id = btn.dataset.finishedLabelDkd;
      var p = finishedLabelProducts.find(function(row) { return String(productDkdId(row)) === String(id); });
      selectFinishedLabelProduct(p, finishedLabelInstructionMap[String(id)] || null);
    });
  });
}

function showMoreFinishedLabelProducts() {
  if (finishedLabelVisibleLimit >= finishedLabelProducts.length) return;
  finishedLabelVisibleLimit = Math.min(finishedLabelVisibleLimit + FINISHED_LABEL_PAGE_STEP, finishedLabelProducts.length);
  renderFinishedLabelResults();
}

async function selectFinishedLabelProduct(product, instruction) {
  if (!product) return;
  var dkdId = productDkdId(product);
  if (!dkdId) return;
  var full = product;
  var r = await sb.from("core_products").select(CORE_PRODUCT_FAST_SELECT).eq("dkd_shohin_id", dkdId).maybeSingle();
  if (!r.error && r.data) full = Object.assign({}, product, normalizeCoreProductFastRows([r.data])[0]);
  finishedLabelSelectedProduct = full;
  finishedLabelSelectedInstruction = instruction || finishedLabelInstructionMap[String(dkdId)] || null;
  renderFinishedLabelResults();
  renderFinishedLabelSelectedSummary(full);
  resetFinishedLabelForm(full, finishedLabelSelectedInstruction);
  await loadFinishedLabelVariants(dkdId);
  renderFinishedLabelVariantOptions(finishedLabelVariants);
  renderFinishedLabelCategoryOptions(finishedLabelCategoryForProduct(full));
  if (finishedLabelPrintMode === "product") await loadFinishedLabelComponentCandidates({ resetDefaults: true });
  else renderFinishedLabelComponents();
  updateFinishedLabelQrPayload();
  await loadFinishedLabelHistory();
}

function renderFinishedLabelSelectedSummary(product) {
  var wrap = document.getElementById("finished-label-selected-summary");
  if (!wrap) return;
  var cells = [
    [t("finished_label_g_part_number"), product && product.gltek_part_number],
    [t("f_genuine_pn"), product && product.genuine_part_number],
    [t("f_mfr_pn"), product && product.manufacturer_part_number],
    [t("f_manufacturer"), product && product.manufacturer],
    [t("product_kind_section"), product && product.default_product_kind ? productKindLabel(product.default_product_kind) : "-"]
  ];
  wrap.innerHTML = cells.map(function(row) {
    return "<div class='finished-label-selected-cell'><div class='finished-label-selected-label'>" + esc(row[0]) + "</div><div class='finished-label-selected-value'>" + esc(row[1] || "-") + "</div></div>";
  }).join("");
}

function resetFinishedLabelForm(product, instruction) {
  finishedLabelLastIssuedRecord = null;
  finishedLabelSelectedHistoryId = null;
  setFinishedLabelValue("finished-label-issue-code", t("finished_label_issue_pending"));
  setFinishedLabelValue("finished-label-instruction-id", instruction && instruction.id ? String(instruction.id) : "");
  setFinishedLabelValue("finished-label-quantity", instruction && instruction.merged_source_count ? String(instruction.merged_source_count) : "1");
  setFinishedLabelValue("finished-label-print-count", "1");
  setFinishedLabelValue("finished-label-assembly-staff", "");
  setFinishedLabelValue("finished-label-inspection-staff", "");
  setFinishedLabelValue("finished-label-shelf-no", "");
  setFinishedLabelValue("finished-label-memo", product && product.notes_jp ? String(product.notes_jp).slice(0, 120) : "");
  setFinishedLabelValue("finished-label-qr-payload", t("finished_label_code_pending"));
  renderFinishedLabelIssuedResult(null);
  var preview = document.getElementById("btn-finished-label-preview");
  if (preview) preview.disabled = true;
  var boxPreview = document.getElementById("btn-finished-box-label-preview");
  if (boxPreview) {
    boxPreview.disabled = true;
    boxPreview.textContent = t("finished_box_label_preview");
  }
  var save = document.getElementById("btn-finished-label-save");
  if (save) save.disabled = !product || !product.gltek_part_number;
  renderFinishedLabelLayoutPreview();
  renderFinishedBoxLabelLayoutPreview();
}

function setFinishedLabelValue(id, value) {
  var el = document.getElementById(id);
  if (el) el.value = value == null ? "" : String(value);
}

function finishedLabelValue(id) {
  var el = document.getElementById(id);
  return el ? el.value.trim() : "";
}

async function loadFinishedLabelVariants(dkdId) {
  finishedLabelVariants = [];
  var r = await sb.from("core_product_variants")
    .select("product_variant_id,dkd_shohin_id,product_kind,display_label,stock_qty,stock_location,is_active")
    .eq("dkd_shohin_id", dkdId)
    .eq("is_active", true)
    .order("product_variant_id", { ascending: true });
  if (r.error) {
    console.warn("finished label variants lookup failed", r.error);
    return;
  }
  finishedLabelVariants = r.data || [];
}

function renderFinishedLabelVariantOptions(rows) {
  var select = document.getElementById("finished-label-variant-kind");
  if (!select) return;
  rows = rows || [];
  if (!rows.length) {
    var kind = finishedLabelSelectedProduct && finishedLabelSelectedProduct.default_product_kind || "rebuilt";
    select.innerHTML = "<option value=''>" + esc(productKindLabel(kind)) + "</option>";
    return;
  }
  select.innerHTML = rows.map(function(row) {
    var stock = row.stock_qty == null ? "0" : row.stock_qty;
    var label = tf("finished_label_variant_stock", { kind: productKindLabel(row.product_kind), n: stock });
    if (row.display_label) label += " / " + row.display_label;
    return "<option value='" + esc(String(row.product_variant_id)) + "'>" + esc(label) + "</option>";
  }).join("");
}

function selectedFinishedLabelVariant() {
  var select = document.getElementById("finished-label-variant-kind");
  var id = select ? parseInt(select.value, 10) : NaN;
  if (!isNaN(id)) {
    return finishedLabelVariants.find(function(row) { return parseInt(row.product_variant_id, 10) === id; }) || null;
  }
  return null;
}

function applyFinishedLabelTemplate() {
  if (!finishedLabelSelectedProduct) {
    finishedLabelSelectedComponentIds = {};
    renderFinishedLabelComponents();
    return;
  }
  finishedLabelSelectedComponentIds = {};
  (finishedLabelComponentCandidates || []).forEach(function(row) {
    if (Number(row.replacement_rate) === 100) {
      finishedLabelSelectedComponentIds[String(row.id)] = true;
    }
  });
  renderFinishedLabelComponents();
  updateFinishedLabelQrPayload();
}

function finishedLabelComponentName(row) {
  return String((row && (row.component_name || row.component_part_name)) || "").trim() || t("finished_label_component_uncategorized");
}

function finishedLabelComponentPartNumber(row) {
  return String((row && (row.component_manufacturer_part_number || row.component_genuine_part_number)) || "").trim() || "-";
}

function finishedLabelComponentSort(a, b) {
  var aDefault = Number(a && a.replacement_rate) === 100 ? 0 : 1;
  var bDefault = Number(b && b.replacement_rate) === 100 ? 0 : 1;
  if (aDefault !== bDefault) return aDefault - bDefault;
  var aPosition = String((a && a.component_position) || "");
  var bPosition = String((b && b.component_position) || "");
  if (aPosition !== bPosition) return aPosition.localeCompare(bPosition, "ja");
  return finishedLabelComponentName(a).localeCompare(finishedLabelComponentName(b), "ja");
}

async function loadFinishedLabelComponentCandidates(options) {
  options = options || {};
  var seq = ++finishedLabelComponentLoadSeq;
  var product = finishedLabelSelectedProduct;
  var variant = selectedFinishedLabelVariant();
  if (!product || !variant || !variant.product_variant_id) {
    finishedLabelComponentCandidates = [];
    finishedLabelSelectedComponentIds = {};
    renderFinishedLabelComponents();
    return;
  }
  var body = document.getElementById("finished-label-component-body");
  if (body) body.innerHTML = "<tr><td colspan='7' class='finished-label-component-empty'>" + esc(t("loading")) + "</td></tr>";
  var previous = Object.assign({}, finishedLabelSelectedComponentIds || {});
  var query = sb.from("assembly_component_usage_details")
    .select("id,dkd_component_id,dkd_shohin_id,product_kind,product_variant_id,component_name,component_part_name,component_manufacturer,component_manufacturer_part_number,component_genuine_part_number,quantity,replacement_rate,procurement_category,manufacturing_memo,component_position,is_catalog_evidence")
    .eq("dkd_shohin_id", productDkdId(product))
    .eq("product_kind", normalizeProductKind(variant.product_kind))
    .or("product_variant_id.is.null,product_variant_id.eq." + String(variant.product_variant_id))
    .limit(1000);
  var r = await query;
  if (seq !== finishedLabelComponentLoadSeq) return;
  if (r.error) {
    console.warn("finished label component lookup failed", r.error);
    finishedLabelComponentCandidates = [];
    finishedLabelSelectedComponentIds = {};
    renderFinishedLabelComponents(r.error.message || t("msg_part_err"));
    return;
  }
  var seen = {};
  finishedLabelComponentCandidates = (r.data || []).filter(function(row) {
    var key = String(row.id || "");
    if (!key || seen[key]) return false;
    seen[key] = true;
    return true;
  }).sort(finishedLabelComponentSort);
  finishedLabelSelectedComponentIds = {};
  finishedLabelComponentCandidates.forEach(function(row) {
    var key = String(row.id);
    if (options.resetDefaults) {
      if (Number(row.replacement_rate) === 100) finishedLabelSelectedComponentIds[key] = true;
    } else if (previous[key] || String(options.includeUsageId || "") === key || Number(row.replacement_rate) === 100) {
      finishedLabelSelectedComponentIds[key] = true;
    }
  });
  renderFinishedLabelComponents();
  updateFinishedLabelQrPayload();
}

function renderFinishedLabelComponents(errorMessage) {
  var body = document.getElementById("finished-label-component-body");
  if (!body) return;
  var selectedRows = (finishedLabelComponentCandidates || []).filter(function(row) {
    return !!finishedLabelSelectedComponentIds[String(row.id)];
  }).sort(finishedLabelComponentSort);
  var availableRows = (finishedLabelComponentCandidates || []).filter(function(row) {
    return !finishedLabelSelectedComponentIds[String(row.id)];
  });
  var picker = document.getElementById("finished-label-component-add-select");
  var addBtn = document.getElementById("btn-finished-label-component-add");
  var count = document.getElementById("finished-label-component-count");
  if (picker) {
    picker.innerHTML = "<option value=''>" + esc(t(availableRows.length ? "finished_label_component_picker_prompt" : "finished_label_component_picker_empty")) + "</option>" + availableRows.map(function(row) {
      var text = [finishedLabelComponentName(row), row.component_manufacturer, finishedLabelComponentPartNumber(row), row.replacement_rate == null ? "" : (t("finished_label_usage_rate") + " " + row.replacement_rate + "%")].filter(Boolean).join(" / ");
      return "<option value='" + esc(String(row.id)) + "'>" + esc(text) + "</option>";
    }).join("");
    picker.disabled = !availableRows.length;
  }
  if (addBtn) addBtn.disabled = !availableRows.length;
  if (count) count.textContent = tf("finished_label_component_selected_count", { selected: selectedRows.length, total: finishedLabelComponentCandidates.length });
  if (errorMessage) {
    body.innerHTML = "<tr><td colspan='7' class='finished-label-component-empty'>" + esc(errorMessage) + "</td></tr>";
    return;
  }
  if (!finishedLabelSelectedProduct) {
    body.innerHTML = "<tr><td colspan='7' class='finished-label-component-empty'>" + esc(t("finished_label_component_select_first")) + "</td></tr>";
    return;
  }
  if (!selectedRows.length) {
    body.innerHTML = "<tr><td colspan='7' class='finished-label-component-empty'>" + esc(t("finished_label_component_default_empty")) + "</td></tr>";
    return;
  }
  body.innerHTML = selectedRows.map(function(row, idx) {
    var rate = row.replacement_rate == null ? t("finished_label_rate_unset") : (String(row.replacement_rate) + "%");
    var defaultClass = Number(row.replacement_rate) === 100 ? " default" : "";
    var genuine = row.component_genuine_part_number ? tf("finished_label_genuine_prefix", { number: row.component_genuine_part_number }) : "";
    var memo = row.manufacturing_memo || row.procurement_category || "";
    return "<tr data-finished-label-component-row='" + esc(String(row.id)) + "'>" +
      "<td>" + (idx + 1) + "</td>" +
      "<td><span class='finished-label-component-name'>" + esc(finishedLabelComponentName(row)) + "</span><span class='finished-label-component-sub'>" + esc([row.component_position, memo].filter(Boolean).join(" / ")) + "</span></td>" +
      "<td>" + esc(row.component_manufacturer || "-") + "</td>" +
      "<td><span class='finished-label-component-part'>" + esc(finishedLabelComponentPartNumber(row)) + "</span><span class='finished-label-component-sub'>" + esc(genuine) + "</span></td>" +
      "<td><span class='finished-label-component-rate" + defaultClass + "'>" + esc(rate) + "</span></td>" +
      "<td>" + esc(row.quantity || "1") + "</td>" +
      "<td><button class='btn-sm-edit production-action-secondary' type='button' data-finished-label-component-remove='" + esc(String(row.id)) + "'>" + esc(t("finished_label_component_remove")) + "</button></td>" +
    "</tr>";
  }).join("");
  body.querySelectorAll("[data-finished-label-component-remove]").forEach(function(btn) {
    btn.addEventListener("click", function() {
      delete finishedLabelSelectedComponentIds[String(btn.dataset.finishedLabelComponentRemove)];
      renderFinishedLabelComponents();
      updateFinishedLabelQrPayload();
    });
  });
}

function readFinishedLabelComponents() {
  return (finishedLabelComponentCandidates || []).filter(function(row) {
    return !!finishedLabelSelectedComponentIds[String(row.id)];
  }).sort(finishedLabelComponentSort).map(function(row, idx) {
    return {
      no: idx + 1,
      usageId: row.id,
      componentId: row.dkd_component_id,
      type: finishedLabelComponentName(row),
      maker: row.component_manufacturer || "",
      partNo: row.component_manufacturer_part_number || row.component_genuine_part_number || "",
      genuinePartNo: row.component_genuine_part_number || "",
      quantity: row.quantity || "1",
      usageRate: row.replacement_rate,
      procurementCategory: row.procurement_category || "",
      memo: row.manufacturing_memo || ""
    };
  });
}

function addFinishedLabelSelectedComponent() {
  var picker = document.getElementById("finished-label-component-add-select");
  var usageId = picker ? String(picker.value || "") : "";
  if (!usageId) return;
  var belongsToSelectedProduct = (finishedLabelComponentCandidates || []).some(function(row) {
    return String(row.id) === usageId;
  });
  if (!belongsToSelectedProduct) return;
  finishedLabelSelectedComponentIds[usageId] = true;
  renderFinishedLabelComponents();
  updateFinishedLabelQrPayload();
}

async function openFinishedLabelComponentRegistration() {
  if (!finishedLabelSelectedProduct) { alert(t("finished_label_no_product")); return; }
  var variant = selectedFinishedLabelVariant();
  if (!variant || !variant.product_variant_id) { alert(t("finished_label_variant_required")); return; }
  currentProduct = finishedLabelSelectedProduct;
  currentProductVariants = finishedLabelVariants.slice();
  currentSelectedProductKind = normalizeProductKind(variant.product_kind);
  currentSelectedComponentVariantId = String(variant.product_variant_id);
  componentReturnScreen = "finished-label-mgmt";
  assemblyComponentRows = finishedLabelComponentCandidates.slice();
  await openComponentAddForm();
  setComponentAddValue("component-add-replacement-rate", "100");
}

function readFinishedLabelRecord() {
  var p = finishedLabelSelectedProduct;
  if (!p) throw new Error(t("finished_label_no_product"));
  if (!p.gltek_part_number) throw new Error(t("finished_label_g_part_number_required"));
  var variant = selectedFinishedLabelVariant();
  if (!variant || !variant.product_variant_id) throw new Error(t("finished_label_variant_required"));
  var instIdText = finishedLabelValue("finished-label-instruction-id");
  var instructionId = instIdText ? parseInt(instIdText, 10) : null;
  if (instIdText && (!Number.isInteger(instructionId) || instructionId < 1)) {
    throw new Error(t("finished_label_instruction_id") + " is invalid");
  }
  var qty = Number(finishedLabelValue("finished-label-quantity"));
  if (!Number.isInteger(qty) || qty < 1 || qty > 100) {
    throw new Error(t("finished_label_quantity_invalid"));
  }
  return {
    issueCode: "",
    productionInstructionId: instructionId,
    dkdShohinId: productDkdId(p),
    productVariantId: variant.product_variant_id,
    productKind: normalizeProductKind(variant.product_kind),
    productCategory: finishedLabelValue("finished-label-product-category") || finishedLabelCategoryForProduct(p),
    productNo: p.gltek_part_number || p.manufacturer_part_number || p.genuine_part_number || p.daiko_part_number || "",
    gltekPartNumber: p.gltek_part_number || "",
    genuinePartNumber: p.genuine_part_number || "",
    genuinePartNumber2: p.genuine_part_number_2 || "",
    manufacturerPartNumber: p.manufacturer_part_number || "",
    manufacturer: p.manufacturer || "",
    daikoPartNumber: p.daiko_part_number || "",
    vehicleManufacturer: p.vehicle_manufacturer || "",
    nominalVoltage: specNumberText(p.nominal_voltage_v, "V"),
    nominalOutput: finishedLabelOutputText(p),
    nominalSpec: p.spec || p.nominal_raw_spec || "",
    quantity: Math.max(1, qty),
    assemblyStaff: finishedLabelValue("finished-label-assembly-staff"),
    inspectionStaff: finishedLabelValue("finished-label-inspection-staff"),
    shelfNo: finishedLabelValue("finished-label-shelf-no"),
    memo: finishedLabelValue("finished-label-memo"),
    printCount: 1,
    issuedAt: null,
    units: [],
    components: readFinishedLabelComponents()
  };
}

function finishedLabelOutputText(p) {
  if (!p) return "";
  if (p.nominal_current_a) return specNumberText(p.nominal_current_a, "A");
  if (p.nominal_power_kw) return specNumberText(p.nominal_power_kw, "kW");
  if (p.nominal_power_w) return specNumberText(p.nominal_power_w, "W");
  if (p.nominal_gas_type) return String(p.nominal_gas_type);
  return "";
}

function updateFinishedLabelQrPayload() {
  if (finishedLabelLastIssuedRecord && finishedLabelLastIssuedRecord.units.length) {
    var units = finishedLabelLastIssuedRecord.units;
    var value = units[0].manufacturing_serial;
    if (units.length > 1) value += " ～ " + units[units.length - 1].manufacturing_serial;
    setFinishedLabelValue("finished-label-qr-payload", value);
    renderFinishedLabelLayoutPreview();
    renderFinishedBoxLabelLayoutPreview();
    return;
  }
  setFinishedLabelValue("finished-label-qr-payload", t("finished_label_code_pending"));
  renderFinishedLabelLayoutPreview();
  renderFinishedBoxLabelLayoutPreview();
}

function finishedLabelPreviewProductNo() {
  var product = finishedLabelSelectedProduct || {};
  return product.gltek_part_number || t("finished_label_g_number_missing_value");
}

function finishedLabelPreviewSerial() {
  if (finishedLabelLastIssuedRecord && Array.isArray(finishedLabelLastIssuedRecord.units) && finishedLabelLastIssuedRecord.units.length) {
    return finishedLabelLastIssuedRecord.units[0].manufacturing_serial || "M2026-0000123";
  }
  return "M" + new Date().getFullYear() + "-0000123";
}

function buildFinishedLabelMarkup(serial, productNo) {
  productNo = String(productNo || "-");
  var productLength = Array.from(productNo).length;
  var productSizeClass = productLength > 18 ? " long" : (productLength > 14 ? " compact" : "");
  var qrDataUrl = finishedProductSerialQrDataUrl(serial);
  return "<section class='serial-label'>" +
    "<div class='serial-label-head'><strong>GLTEK</strong><span>PRODUCT ID</span></div>" +
    "<div class='serial-label-body'><img class='serial-label-qr' src='" + esc(qrDataUrl) + "' alt='" + esc(serial) + "'>" +
    "<div class='serial-label-copy'>" +
    "<div class='serial-label-field-name'>GLTEK PART NO.</div>" +
    "<div class='serial-label-product" + productSizeClass + "'>" + esc(productNo) + "</div>" +
    "<div class='serial-label-rule'></div>" +
    "<div class='serial-label-field-name'>MFG SERIAL / S/N</div>" +
    "<div class='serial-label-number'>" + esc(serial) + "</div>" +
    "</div></div></section>";
}

function renderFinishedLabelLayoutPreview() {
  var host = document.getElementById("finished-label-layout-preview");
  if (!host) return;
  var serial = finishedLabelPreviewSerial();
  try {
    host.innerHTML = buildFinishedLabelMarkup(serial, finishedLabelPreviewProductNo());
  } catch (e) {
    host.innerHTML = "<div class='finished-label-layout-error'>QR preview unavailable</div>";
  }
  var qrValue = document.getElementById("finished-label-layout-qr-value");
  if (qrValue) qrValue.textContent = serial;
}

function finishedProductPartBarcodeDataUrl(partNumber) {
  partNumber = String(partNumber || "").trim();
  if (!partNumber || typeof JsBarcode !== "function") throw new Error("Code 128 barcode library is unavailable");
  var canvas = document.createElement("canvas");
  JsBarcode(canvas, partNumber, {
    format: "CODE128",
    displayValue: false,
    margin: 8,
    width: 2,
    height: 96,
    background: "#ffffff",
    lineColor: "#000000"
  });
  return canvas.toDataURL("image/png");
}

function finishedBoxLabelPreviewRecord() {
  if (finishedLabelPrintMode === "box" && finishedLabelLastIssuedRecord && Array.isArray(finishedLabelLastIssuedRecord.units) && finishedLabelLastIssuedRecord.units.length) {
    return finishedLabelLastIssuedRecord;
  }
  var product = finishedLabelSelectedProduct || {};
  var variant = selectedFinishedLabelVariant();
  return {
    productNo: finishedLabelPreviewProductNo(),
    gltekPartNumber: product.gltek_part_number || "",
    genuinePartNumber: product.genuine_part_number || "",
    genuinePartNumber2: product.genuine_part_number_2 || "",
    manufacturerPartNumber: product.manufacturer_part_number || "",
    manufacturer: product.manufacturer || "",
    productCategory: finishedLabelValue("finished-label-product-category") || finishedLabelCategoryForProduct(product),
    productKind: variant && variant.product_kind || product.default_product_kind || "",
    nominalVoltage: specNumberText(product.nominal_voltage_v, "V"),
    nominalOutput: finishedLabelOutputText(product),
    nominalSpec: product.spec || product.nominal_raw_spec || "",
    units: [{ manufacturing_serial: finishedLabelPreviewSerial() }]
  };
}

function finishedBoxLabelProductNo(record, unit) {
  record = record || {};
  unit = unit || {};
  return String(unit.gltek_part_number || record.gltekPartNumber || unit.product_no || record.productNo || record.manufacturerPartNumber || record.genuinePartNumber || "-");
}

function buildFinishedBoxLabelMarkup(record, unit) {
  record = record || {};
  unit = unit || {};
  var serial = unit.manufacturing_serial || "-";
  var productNo = finishedBoxLabelProductNo(record, unit);
  var productLength = Array.from(productNo).length;
  var productSizeClass = productLength > 24 ? " long" : (productLength > 18 ? " compact" : "");
  var manufacturer = unit.manufacturer || record.manufacturer || "";
  var manufacturerPartNumber = unit.manufacturer_part_number || record.manufacturerPartNumber || "";
  var manufacturerLine = [manufacturer, manufacturerPartNumber].filter(Boolean).join(" / ") || "-";
  var genuineLine = [unit.genuine_part_number || record.genuinePartNumber, record.genuinePartNumber2].filter(Boolean).join(" / ") || "-";
  var specification = [record.nominalVoltage, record.nominalOutput, record.nominalSpec].filter(Boolean).join(" / ") || "-";
  var category = record.productCategory ? tCat(record.productCategory) : "-";
  var productKind = record.productKind ? productKindLabel(record.productKind) : "-";
  var barcodeDataUrl = finishedProductPartBarcodeDataUrl(productNo);
  var qrDataUrl = finishedProductSerialQrDataUrl(serial);
  return "<section class='box-product-label'>" +
    "<div class='box-product-label-head'><strong>GLTEK</strong><span>BOX LABEL</span><em>" + esc(category) + "</em></div>" +
    "<div class='box-product-label-number'><span>GLTEK PART NO.</span><strong class='box-product-label-part" + productSizeClass + "'>" + esc(productNo) + "</strong></div>" +
    "<div class='box-product-label-barcode'><img src='" + esc(barcodeDataUrl) + "' alt='Code 128 " + esc(productNo) + "'><strong>" + esc(productNo) + "</strong></div>" +
    "<div class='box-product-label-lower'><div class='box-product-label-details'>" +
    "<div><span>MANUFACTURER / MFR PART NO.</span><strong>" + esc(manufacturerLine) + "</strong></div>" +
    "<div><span>GENUINE PART NO.</span><strong>" + esc(genuineLine) + "</strong></div>" +
    "<div><span>SPECIFICATION</span><strong>" + esc(specification) + "</strong></div>" +
    "<div><span>PRODUCT TYPE</span><strong>" + esc(productKind) + "</strong></div>" +
    "</div><div class='box-product-label-serial'><img src='" + esc(qrDataUrl) + "' alt='" + esc(serial) + "'><span>MFG SERIAL / S/N</span><strong>" + esc(serial) + "</strong></div></div>" +
    "</section>";
}

function renderFinishedBoxLabelLayoutPreview() {
  var host = document.getElementById("finished-box-label-layout-preview");
  if (!host) return;
  var record = finishedBoxLabelPreviewRecord();
  var unit = record.units[0];
  try {
    host.innerHTML = buildFinishedBoxLabelMarkup(record, unit);
  } catch (e) {
    host.innerHTML = "<div class='finished-label-layout-error'>Barcode preview unavailable</div>";
  }
  var barcodeValue = document.getElementById("finished-box-label-barcode-value");
  if (barcodeValue) barcodeValue.textContent = finishedBoxLabelProductNo(record, unit);
  var qrValue = document.getElementById("finished-box-label-qr-value");
  if (qrValue) qrValue.textContent = unit.manufacturing_serial;
}

async function saveFinishedLabelIssue() {
  if (!canEditFinishedLabelMgmt()) { alert(t("err_perm")); return; }
  var btn = document.getElementById("btn-finished-label-save");
  if (btn) btn.disabled = true;
  var printWindow = null;
  try {
    var record = readFinishedLabelRecord();
    printWindow = window.open("", "_blank");
    if (printWindow) {
      printWindow.document.write("<!doctype html><meta charset='utf-8'><title>D-CATS</title><p>" + esc(t("finished_label_issuing")) + "</p>");
    }
    var r = await sb.rpc("issue_finished_product_serials", {
      target_dkd_shohin_id: record.dkdShohinId,
      target_product_variant_id: record.productVariantId,
      target_quantity: record.quantity,
      target_production_instruction_id: record.productionInstructionId || null,
      target_product_category: record.productCategory,
      target_assembly_staff: record.assemblyStaff || null,
      target_inspection_staff: record.inspectionStaff || null,
      target_shelf_no: record.shelfNo || null,
      target_memo: record.memo || null,
      target_components: record.components
    });
    if (r.error) throw r.error;
    var issued = r.data || {};
    record.issueCode = issued.issue_code || "";
    record.issueId = issued.issue_id || null;
    record.issuedAt = issued.issued_at ? new Date(issued.issued_at) : new Date();
    record.quantity = Number(issued.quantity) || record.quantity;
    record.stockQtyAfter = Number(issued.stock_qty_after);
    record.units = Array.isArray(issued.units) ? issued.units : [];
    if (!record.units.length) throw new Error("Manufacturing serial response was empty");
    finishedLabelLastIssuedRecord = record;
    setFinishedLabelValue("finished-label-issue-code", record.issueCode);
    updateFinishedLabelQrPayload();
    renderFinishedLabelIssuedResult(record);
    var preview = document.getElementById("btn-finished-label-preview");
    if (preview) preview.disabled = false;
    var boxPreview = document.getElementById("btn-finished-box-label-preview");
    if (boxPreview) boxPreview.disabled = true;
    await writeLog("insert", "finished_product_units", record.issueId, record.issueCode, null, {
      issue_code: record.issueCode,
      quantity: record.quantity,
      first_serial: issued.first_serial,
      last_serial: issued.last_serial,
      stock_qty_after: issued.stock_qty_after
    });
    if (printWindow) openFinishedLabelPrintPreview(record, printWindow);
    else alert(t("finished_label_popup_blocked"));
    alert(t("finished_label_saved"));
    await loadFinishedLabelHistory();
  } catch (e) {
    if (printWindow && !printWindow.closed) printWindow.close();
    alert(t("msg_save_err") + ": " + (e.message || e));
  } finally {
    if (btn) btn.disabled = false;
  }
}

function renderFinishedLabelIssuedResult(record) {
  var host = document.getElementById("finished-label-issued-result");
  if (!host) return;
  if (!record || !Array.isArray(record.units) || !record.units.length) {
    host.innerHTML = "";
    host.classList.remove("show");
    setFinishedBoxLabelPrintButton(null);
    return;
  }
  var serials = record.units.map(function(unit) {
    return "<span class='finished-label-serial-chip'>" + esc(unit.manufacturing_serial || "") + "</span>";
  }).join("");
  var stockText = Number.isFinite(record.stockQtyAfter)
    ? tf("finished_label_stock_after", { n: record.stockQtyAfter })
    : "";
  var isBox = finishedLabelPrintMode === "box";
  var sourceRow = record.sourceHistoryRow || null;
  var actionHtml = isBox
    ? "<span class='finished-box-label-print-status " + (sourceRow && sourceRow.boxLabelPrinted ? "reprint" : "initial") + "'>" + esc(t(sourceRow && sourceRow.boxLabelPrinted ? "finished_box_label_reprint_status" : "finished_box_label_initial_status")) + "</span>"
    : "<button class='btn-sm-edit production-action-secondary' id='btn-finished-label-issued-print'>" + esc(t("finished_label_preview")) + "</button>";
  host.innerHTML = "<div class='finished-label-issued-head'><div><strong>" + esc(t(isBox ? "finished_box_label_selected_serials" : "finished_label_serial_result")) + "</strong><span>" + esc(record.issueCode || "") + "</span></div><div class='finished-label-issued-actions'>" + actionHtml + "</div></div>" +
    "<div class='finished-label-issued-meta'>" + esc([tf("finished_label_history_units", { n: record.quantity }), stockText].filter(Boolean).join(" / ")) + "</div>" +
    "<div class='finished-label-serial-list'>" + serials + "</div>";
  host.classList.add("show");
  var btn = document.getElementById("btn-finished-label-issued-print");
  if (btn) btn.addEventListener("click", function() { openFinishedLabelPrintPreview(record); });
  if (isBox) setFinishedBoxLabelPrintButton(sourceRow);
}

function setFinishedBoxLabelPrintButton(row) {
  var button = document.getElementById("btn-finished-box-label-preview");
  if (!button) return;
  var units = row && Array.isArray(row.finishedUnits) ? row.finishedUnits : [];
  var blocked = !!(row && (row.boxPrintAuditUnavailable || row.boxLabelPartiallyPrinted));
  button.disabled = !row || !units.length || blocked;
  button.textContent = t(row && row.boxLabelPrinted ? "finished_label_reprint" : "finished_box_label_preview");
  button.title = row && row.boxLabelPartiallyPrinted ? t("finished_box_label_partial_print") : "";
}

function selectFinishedBoxLabelHistory(row, options) {
  options = options || {};
  if (!row || !Array.isArray(row.finishedUnits) || !row.finishedUnits.length) {
    finishedLabelSelectedHistoryId = null;
    finishedLabelLastIssuedRecord = null;
    renderFinishedLabelIssuedResult(null);
    renderFinishedBoxLabelLayoutPreview();
    if (!options.skipHistoryRender) renderFinishedLabelHistory();
    return;
  }
  finishedLabelSelectedHistoryId = row.id;
  var record = finishedLabelRecordFromHistory(row);
  record.sourceHistoryRow = row;
  finishedLabelLastIssuedRecord = record;
  updateFinishedLabelQrPayload();
  renderFinishedLabelIssuedResult(record);
  if (!options.skipHistoryRender) renderFinishedLabelHistory();
}

async function loadFinishedLabelHistory() {
  var list = document.getElementById("finished-label-history-list");
  if (!list) return;
  if (!finishedLabelSelectedProduct) {
    finishedLabelSelectedHistoryId = null;
    finishedLabelLastIssuedRecord = null;
    renderFinishedLabelIssuedResult(null);
    list.innerHTML = "<div class='empty'>" + esc(t("finished_label_select_product")) + "</div>";
    return;
  }
  list.innerHTML = "<div class='loading'>" + esc(t("loading")) + "</div>";
  var dkdId = productDkdId(finishedLabelSelectedProduct);
  var r = await sb.from("finished_label_issues")
    .select("*")
    .eq("dkd_shohin_id", dkdId)
    .order("issued_at", { ascending: false })
    .limit(30);
  if (r.error) {
    finishedLabelSelectedHistoryId = null;
    finishedLabelLastIssuedRecord = null;
    renderFinishedLabelIssuedResult(null);
    list.innerHTML = "<div class='empty'>" + esc(r.error.message) + "</div>";
    return;
  }
  finishedLabelHistoryRows = r.data || [];
  var issueIds = finishedLabelHistoryRows.map(function(row) { return row.id; });
  if (issueIds.length) {
    var unitsResult = await sb.from("finished_product_units")
      .select("id,manufacturing_serial,finished_label_issue_id,status,product_no,gltek_part_number,genuine_part_number,manufacturer_part_number,manufacturer,product_category,product_kind")
      .in("finished_label_issue_id", issueIds)
      .order("manufacturing_serial", { ascending: true });
    if (unitsResult.error) {
      list.innerHTML = "<div class='empty'>" + esc(unitsResult.error.message) + "</div>";
      return;
    }
    var byIssue = {};
    (unitsResult.data || []).forEach(function(unit) {
      var key = String(unit.finished_label_issue_id);
      if (!byIssue[key]) byIssue[key] = [];
      byIssue[key].push(unit);
    });
    finishedLabelHistoryRows.forEach(function(row) {
      row.finishedUnits = byIssue[String(row.id)] || [];
    });
    var unitIds = (unitsResult.data || []).map(function(unit) { return unit.id; });
    if (unitIds.length) {
      var printResult = await sb.from("finished_product_label_prints")
        .select("finished_product_unit_id,print_event_type,label_target,requested_at")
        .in("finished_product_unit_id", unitIds)
        .eq("label_target", "box");
      if (printResult.error) {
        console.warn("box label print history lookup failed", printResult.error);
        finishedLabelHistoryRows.forEach(function(row) { row.boxPrintAuditUnavailable = true; });
      } else {
        var boxInitialUnitIds = {};
        (printResult.data || []).forEach(function(printRow) {
          if (printRow.print_event_type === "initial") boxInitialUnitIds[String(printRow.finished_product_unit_id)] = true;
        });
        finishedLabelHistoryRows.forEach(function(row) {
          var units = row.finishedUnits || [];
          row.boxLabelPrinted = !!units.length && units.every(function(unit) {
            return !!boxInitialUnitIds[String(unit.id)];
          });
          row.boxLabelPartiallyPrinted = !row.boxLabelPrinted && units.some(function(unit) {
            return !!boxInitialUnitIds[String(unit.id)];
          });
        });
      }
    }
  }
  if (finishedLabelPrintMode === "box") {
    var selectedRow = finishedLabelHistoryRows.find(function(row) {
      return String(row.id) === String(finishedLabelSelectedHistoryId || "") && Array.isArray(row.finishedUnits) && row.finishedUnits.length;
    }) || finishedLabelHistoryRows.find(function(row) {
      return Array.isArray(row.finishedUnits) && row.finishedUnits.length;
    });
    if (selectedRow) selectFinishedBoxLabelHistory(selectedRow, { skipHistoryRender: true });
    else selectFinishedBoxLabelHistory(null, { skipHistoryRender: true });
  }
  renderFinishedLabelHistory();
}

function renderFinishedLabelHistory() {
  var list = document.getElementById("finished-label-history-list");
  if (!list) return;
  if (!finishedLabelHistoryRows.length) {
    list.innerHTML = "<div class='empty'>" + esc(t("finished_label_history_empty")) + "</div>";
    return;
  }
  var html = "";
  finishedLabelHistoryRows.forEach(function(row) {
    var comps = Array.isArray(row.components_json) ? row.components_json.length : 0;
    var units = Array.isArray(row.finishedUnits) ? row.finishedUnits : [];
    var serialText = units.length ? units[0].manufacturing_serial : "-";
    if (units.length > 1) serialText += " ～ " + units[units.length - 1].manufacturing_serial;
    var actionHtml = "";
    if (finishedLabelPrintMode === "box") {
      var selected = String(row.id) === String(finishedLabelSelectedHistoryId || "");
      var boxActionLabel = t(selected ? "finished_box_label_history_selected" : "finished_box_label_history_select");
      var boxActionTitle = row.boxLabelPartiallyPrinted ? t("finished_box_label_partial_print") : "";
      var statusKey = row.boxLabelPrinted ? "finished_box_label_reprint_status" : "finished_box_label_initial_status";
      actionHtml = "<span class='finished-box-label-print-status " + (row.boxLabelPrinted ? "reprint" : "initial") + "'>" + esc(t(statusKey)) + "</span>" +
        "<button class='btn-sm-edit production-action-secondary' data-finished-box-label-history-select='" + esc(String(row.id)) + "'" + (units.length ? "" : " disabled") + (boxActionTitle ? " title='" + esc(boxActionTitle) + "'" : "") + ">" + esc(boxActionLabel) + "</button>";
    } else {
      actionHtml = "<button class='btn-sm-edit production-action-secondary' data-finished-label-history-preview='" + esc(String(row.id)) + "'" + (units.length ? "" : " disabled") + ">" + esc(t("finished_product_label_reprint")) + "</button>";
    }
    html += "<div class='finished-label-history-row" + (finishedLabelPrintMode === "box" && String(row.id) === String(finishedLabelSelectedHistoryId || "") ? " active" : "") + "'>";
    html += "<div class='finished-label-history-main'><span>" + esc(row.issue_code || "-") + "</span><div class='finished-label-history-actions'>" + actionHtml + "</div></div>";
    html += "<div class='finished-label-history-serial'>" + esc(serialText) + "</div>";
    html += "<div class='finished-label-history-sub'>" + esc([formatDateTime(row.issued_at), row.product_category ? tCat(row.product_category) : "", productKindLabel(row.product_kind), tf("finished_label_history_units", { n: row.quantity }), tf("finished_label_history_parts", { n: comps })].filter(Boolean).join(" / ")) + "</div>";
    html += "</div>";
  });
  list.innerHTML = html;
  list.querySelectorAll("[data-finished-label-history-preview]").forEach(function(btn) {
    btn.addEventListener("click", function() {
      var row = finishedLabelHistoryRows.find(function(x) { return String(x.id) === String(btn.dataset.finishedLabelHistoryPreview); });
      if (row) reprintFinishedLabelIssue(row, "product");
    });
  });
  list.querySelectorAll("[data-finished-box-label-history-select]").forEach(function(btn) {
    btn.addEventListener("click", function() {
      var row = finishedLabelHistoryRows.find(function(x) { return String(x.id) === String(btn.dataset.finishedBoxLabelHistorySelect); });
      if (row) selectFinishedBoxLabelHistory(row);
    });
  });
}

function finishedLabelRecordFromHistory(row, issued) {
  issued = issued || {};
  var units = Array.isArray(issued.units) ? issued.units : (row.finishedUnits || []);
  return {
    issueCode: row.issue_code,
    issueId: row.id,
    productionInstructionId: row.production_instruction_id,
    dkdShohinId: row.dkd_shohin_id,
    productVariantId: row.product_variant_id,
    productKind: row.product_kind,
    productCategory: row.product_category,
    productNo: row.product_no,
    gltekPartNumber: row.gltek_part_number || "",
    genuinePartNumber: row.genuine_part_number,
    genuinePartNumber2: row.genuine_part_number_2,
    manufacturerPartNumber: row.manufacturer_part_number,
    manufacturer: row.manufacturer,
    daikoPartNumber: row.daiko_part_number,
    vehicleManufacturer: row.vehicle_manufacturer,
    nominalVoltage: row.nominal_voltage,
    nominalOutput: row.nominal_output,
    nominalSpec: row.nominal_spec,
    quantity: Number(issued.quantity) || row.quantity,
    assemblyStaff: row.assembly_staff,
    inspectionStaff: row.inspection_staff,
    shelfNo: row.shelf_no,
    memo: row.memo,
    printCount: 1,
    issuedAt: row.issued_at ? new Date(row.issued_at) : new Date(),
    units: units,
    components: Array.isArray(row.components_json) ? row.components_json : []
  };
}

async function reprintFinishedLabelIssue(row, labelType) {
  labelType = labelType === "box" ? "box" : "product";
  var reason = window.prompt(t("finished_label_reprint_reason"), t("finished_label_reprint_default_reason"));
  if (reason === null) return;
  reason = String(reason || "").trim();
  if (!reason) { alert(t("finished_label_reprint_reason")); return; }
  var printWindow = window.open("", "_blank");
  if (printWindow) {
    printWindow.document.write("<!doctype html><meta charset='utf-8'><title>D-CATS</title><p>" + esc(t("finished_label_reprint_recording")) + "</p>");
  }
  try {
    var result = await sb.rpc("record_finished_product_label_print", {
      target_finished_label_issue_id: row.id,
      target_label_target: labelType === "box" ? "box" : "finished_product",
      target_print_event_type: "reprint",
      target_reason: reason
    });
    if (result.error) throw result.error;
    var record = finishedLabelRecordFromHistory(row, result.data || {});
    record.sourceHistoryRow = row;
    await writeLog("insert", "finished_product_label_prints", row.id, row.issue_code, null, {
      event_type: labelType === "box" ? "box_label_reprint" : "product_label_reprint",
      label_size: labelType === "box" ? "80x60" : "45x20",
      reason: reason,
      quantity: record.units.length,
      copies_per_unit: 1
    });
    if (printWindow) {
      if (labelType === "box") openFinishedBoxLabelPrintPreview(record, printWindow);
      else openFinishedLabelPrintPreview(record, printWindow);
    }
    else alert(t("finished_label_popup_blocked"));
  } catch (e) {
    if (printWindow && !printWindow.closed) printWindow.close();
    alert(t("msg_save_err") + ": " + (e.message || e));
  }
}

async function printFinishedBoxLabelIssue(row) {
  if (!row || !Array.isArray(row.finishedUnits) || !row.finishedUnits.length) return;
  var eventType = row.boxLabelPrinted ? "reprint" : "initial";
  var reason = null;
  if (eventType === "reprint") {
    reason = window.prompt(t("finished_label_reprint_reason"), t("finished_label_reprint_default_reason"));
    if (reason === null) return;
    reason = String(reason || "").trim();
    if (!reason) { alert(t("finished_label_reprint_reason")); return; }
  }
  var boxPreview = document.getElementById("btn-finished-box-label-preview");
  if (boxPreview) boxPreview.disabled = true;
  var printWindow = window.open("", "_blank");
  if (printWindow) {
    printWindow.document.write("<!doctype html><meta charset='utf-8'><title>D-CATS</title><p>" + esc(t("finished_box_label_print_recording")) + "</p>");
  }
  try {
    var result = await sb.rpc("record_finished_product_label_print", {
      target_finished_label_issue_id: row.id,
      target_label_target: "box",
      target_print_event_type: eventType,
      target_reason: reason
    });
    if (result.error) throw result.error;
    var record = finishedLabelRecordFromHistory(row, result.data || {});
    record.sourceHistoryRow = row;
    finishedLabelLastIssuedRecord = record;
    finishedLabelSelectedHistoryId = row.id;
    row.boxLabelPrinted = true;
    renderFinishedLabelIssuedResult(record);
    await writeLog("insert", "finished_product_label_prints", row.id, row.issue_code, null, {
      event_type: eventType === "initial" ? "box_label_initial" : "box_label_reprint",
      label_size: "80x60",
      reason: reason,
      quantity: record.units.length,
      copies_per_unit: 1
    });
    if (printWindow) openFinishedBoxLabelPrintPreview(record, printWindow);
    else alert(t("finished_label_popup_blocked"));
    renderFinishedLabelHistory();
  } catch (e) {
    if (printWindow && !printWindow.closed) printWindow.close();
    alert(t("msg_save_err") + ": " + (e.message || e));
  } finally {
    setFinishedBoxLabelPrintButton(row);
  }
}

function previewCurrentFinishedLabel() {
  if (!finishedLabelLastIssuedRecord) return;
  openFinishedLabelPrintPreview(finishedLabelLastIssuedRecord);
}

function previewCurrentFinishedBoxLabel() {
  if (!finishedLabelLastIssuedRecord || !finishedLabelLastIssuedRecord.sourceHistoryRow) {
    alert(t("finished_box_label_select_history"));
    return;
  }
  printFinishedBoxLabelIssue(finishedLabelLastIssuedRecord.sourceHistoryRow);
}

function finishedProductSerialQrDataUrl(serial) {
  if (!serial || typeof QRCode !== "function") throw new Error("QR code library is unavailable");
  var host = document.createElement("div");
  new QRCode(host, {
    text: serial,
    width: 240,
    height: 240,
    correctLevel: QRCode.CorrectLevel.M
  });
  var canvas = host.querySelector("canvas");
  if (canvas && typeof canvas.toDataURL === "function") return canvas.toDataURL("image/png");
  var image = host.querySelector("img");
  if (image && image.src) return image.src;
  throw new Error("QR code generation failed");
}

function openFinishedLabelPrintPreview(record, existingWindow) {
  var win = existingWindow || window.open("", "_blank");
  if (!win) {
    alert(t("finished_label_popup_blocked"));
    return false;
  }
  try {
    win.document.open();
    win.document.write(buildFinishedLabelPrintHtml(record));
    win.document.close();
    var printBtn = win.document.getElementById("dcats-print-now");
    if (printBtn) printBtn.addEventListener("click", function() { win.print(); });
    return true;
  } catch (e) {
    if (!win.closed) win.close();
    alert(e.message || e);
    return false;
  }
}

function buildFinishedLabelPrintHtml(record) {
  var units = Array.isArray(record.units) ? record.units : [];
  if (!units.length) throw new Error("No manufacturing serials to print");
  var labels = [];
  units.forEach(function(unit) {
    var serial = unit.manufacturing_serial || "";
    var productNo = unit.gltek_part_number || unit.product_no || record.gltekPartNumber || record.productNo || record.manufacturerPartNumber || record.genuinePartNumber || "-";
    labels.push(buildFinishedLabelMarkup(serial, productNo));
  });
  return "<!doctype html><html lang='" + esc(currentLang) + "'><head><meta charset='utf-8'><title>D-CATS " + esc(record.issueCode || "") + "</title>" +
    "<link rel='stylesheet' href='print.css?dcats_version=" + encodeURIComponent(APP_VERSION) + "'>" +
    "</head><body><div class='toolbar'><button id='dcats-print-now' type='button'>" + esc(t("btn_print")) + "</button><span>" + esc(tf("finished_label_print_setup", { n: units.length })) + "</span></div><main class='serial-labels'>" + labels.join("") + "</main></body></html>";
}

function openFinishedBoxLabelPrintPreview(record, existingWindow) {
  var win = existingWindow || window.open("", "_blank");
  if (!win) {
    alert(t("finished_label_popup_blocked"));
    return false;
  }
  try {
    win.document.open();
    win.document.write(buildFinishedBoxLabelPrintHtml(record));
    win.document.close();
    var printBtn = win.document.getElementById("dcats-print-now");
    if (printBtn) printBtn.addEventListener("click", function() { win.print(); });
    return true;
  } catch (e) {
    if (!win.closed) win.close();
    alert(e.message || e);
    return false;
  }
}

function buildFinishedBoxLabelPrintHtml(record) {
  var units = Array.isArray(record.units) ? record.units : [];
  if (!units.length) throw new Error("No manufacturing serials to print");
  var labels = units.map(function(unit) {
    return buildFinishedBoxLabelMarkup(record, unit);
  });
  return "<!doctype html><html lang='" + esc(currentLang) + "'><head><meta charset='utf-8'><title>D-CATS BOX " + esc(record.issueCode || "") + "</title>" +
    "<link rel='stylesheet' href='box-label-print.css?dcats_version=" + encodeURIComponent(APP_VERSION) + "'>" +
    "</head><body><div class='toolbar'><button id='dcats-print-now' type='button'>" + esc(t("btn_print")) + "</button><span>" + esc(tf("finished_box_label_print_setup", { n: units.length })) + "</span></div><main class='box-product-labels'>" + labels.join("") + "</main></body></html>";
}

// =============================================
// 完品出荷・保証管理
// =============================================
function finishedShipmentTodayValue() {
  var now = new Date();
  var local = new Date(now.getTime() - now.getTimezoneOffset() * 60000);
  return local.toISOString().slice(0, 10);
}

function normalizeFinishedShipmentSerial(value) {
  return normalizeAsciiWidth(String(value || "")).trim().toUpperCase();
}

function setFinishedShipmentMessage(id, message, isError) {
  var el = document.getElementById(id);
  if (!el) return;
  el.textContent = message || "";
  el.className = "finished-shipment-message" + (message ? " show" : "") + (isError ? " error" : " success");
}

function finishedShipmentWarrantyState(expiresOn) {
  if (!expiresOn) return { active: false, label: "-" };
  var active = finishedShipmentTodayValue() <= String(expiresOn).slice(0, 10);
  return {
    active: active,
    label: t(active ? "finished_shipping_warranty_active" : "finished_shipping_warranty_expired")
  };
}

async function enterFinishedProductShipping() {
  if (!canManageFinishedProductShipping()) { alert(t("err_perm")); return; }
  showScreen("finished-product-shipping");
  finishedShipmentUnits = [];
  setFinishedShipmentMessage("finished-shipment-scan-message", "", false);
  setFinishedShipmentMessage("finished-shipment-save-message", "", false);
  var lookup = document.getElementById("finished-shipment-lookup");
  if (lookup) lookup.innerHTML = "";
  var shippedOn = document.getElementById("finished-shipment-shipped-on");
  if (shippedOn) shippedOn.value = finishedShipmentTodayValue();
  renderFinishedShipmentUnits();
  await Promise.all([loadFinishedShipmentCustomers(), loadFinishedShipmentHistory()]);
  var input = document.getElementById("finished-shipment-serial-input");
  if (input) input.focus();
}

async function loadFinishedShipmentCustomers() {
  var select = document.getElementById("finished-shipment-customer");
  if (select) select.innerHTML = "<option value=''>" + esc(t("loading")) + "</option>";
  var r = await sb.from("sales_customers")
    .select("id,source_customer_code,customer_name,customer_kana")
    .eq("is_active", true)
    .order("customer_kana", { ascending: true })
    .order("customer_name", { ascending: true })
    .limit(2000);
  if (r.error) {
    finishedShipmentCustomers = [];
    if (select) select.innerHTML = "<option value=''>" + esc(r.error.message || t("msg_part_err")) + "</option>";
    return;
  }
  finishedShipmentCustomers = r.data || [];
  if (!select) return;
  select.innerHTML = "<option value=''>-</option>" + finishedShipmentCustomers.map(function(row) {
    var label = [row.source_customer_code, row.customer_name].filter(Boolean).join(" / ");
    return "<option value='" + esc(String(row.id)) + "'>" + esc(label || ("ID " + row.id)) + "</option>";
  }).join("");
}

function renderFinishedShipmentUnits() {
  var body = document.getElementById("finished-shipment-unit-body");
  var count = document.getElementById("finished-shipment-unit-count");
  if (count) count.textContent = String(finishedShipmentUnits.length);
  if (!body) return;
  if (!finishedShipmentUnits.length) {
    body.innerHTML = "<tr><td colspan='4' class='empty'>" + esc(t("finished_shipping_no_units")) + "</td></tr>";
    return;
  }
  body.innerHTML = finishedShipmentUnits.map(function(unit) {
    var productNo = unit.gltek_part_number || unit.product_no || unit.manufacturer_part_number || unit.genuine_part_number || "-";
    return "<tr>" +
      "<td><strong class='finished-shipment-serial'>" + esc(unit.manufacturing_serial) + "</strong></td>" +
      "<td>" + esc(productNo) + "</td>" +
      "<td>" + esc(unit.manufacturer || "-") + "</td>" +
      "<td><button type='button' class='btn-sm-edit production-action-secondary' data-finished-shipment-remove='" + esc(String(unit.id)) + "'>×</button></td>" +
      "</tr>";
  }).join("");
  body.querySelectorAll("[data-finished-shipment-remove]").forEach(function(btn) {
    btn.addEventListener("click", function() {
      finishedShipmentUnits = finishedShipmentUnits.filter(function(unit) {
        return String(unit.id) !== String(btn.dataset.finishedShipmentRemove);
      });
      renderFinishedShipmentUnits();
    });
  });
}

async function loadFinishedShipmentForUnit(unitId) {
  var itemR = await sb.from("finished_product_shipment_items")
    .select("shipment_id")
    .eq("finished_product_unit_id", unitId)
    .order("shipment_id", { ascending: false })
    .limit(20);
  if (itemR.error || !(itemR.data || []).length) return null;
  var shipmentIds = itemR.data.map(function(row) { return row.shipment_id; });
  var shipmentR = await sb.from("finished_product_shipments")
    .select("id,shipment_code,customer_code_snapshot,customer_name_snapshot,shipped_on,external_order_number,carrier_name,tracking_number,warranty_months,warranty_expires_on,status,cancelled_at,cancellation_reason,created_at")
    .in("id", shipmentIds)
    .order("created_at", { ascending: false })
    .limit(20);
  if (shipmentR.error) return null;
  var rows = shipmentR.data || [];
  return rows.find(function(row) { return row.status === "shipped"; }) || rows[0] || null;
}

async function renderFinishedShipmentLookup(unit) {
  var wrap = document.getElementById("finished-shipment-lookup");
  if (!wrap) return;
  if (!unit) { wrap.innerHTML = ""; return; }
  var shipment = await loadFinishedShipmentForUnit(unit.id);
  var productNo = unit.gltek_part_number || unit.product_no || unit.manufacturer_part_number || unit.genuine_part_number || "-";
  var html = "<div class='finished-shipment-lookup-head'><strong>" + esc(unit.manufacturing_serial) + "</strong><span class='finished-shipment-status " + esc(unit.status || "") + "'>" + esc(t(unit.status === "available" ? "finished_shipping_available" : "finished_shipping_shipped")) + "</span></div>";
  html += "<div class='finished-shipment-lookup-sub'>" + esc([productNo, unit.manufacturer].filter(Boolean).join(" / ")) + "</div>";
  if (shipment) {
    var warranty = finishedShipmentWarrantyState(shipment.warranty_expires_on);
    html += "<div class='finished-shipment-lookup-grid'>" +
      "<div><span>" + esc(t("finished_shipping_customer")) + "</span><strong>" + esc(shipment.customer_name_snapshot || "-") + "</strong></div>" +
      "<div><span>" + esc(t("finished_shipping_shipped_on")) + "</span><strong>" + esc(shipment.shipped_on || "-") + "</strong></div>" +
      "<div><span>" + esc(t("finished_shipping_tracking")) + "</span><strong>" + esc(shipment.tracking_number || "-") + "</strong></div>" +
      "<div><span>" + esc(warranty.label) + "</span><strong class='" + (warranty.active ? "warranty-active" : "warranty-expired") + "'>" + esc(shipment.warranty_expires_on || "-") + "</strong></div>" +
      "</div>";
  }
  wrap.innerHTML = html;
}

async function addFinishedShipmentSerial() {
  if (!canManageFinishedProductShipping()) return;
  var input = document.getElementById("finished-shipment-serial-input");
  var serial = normalizeFinishedShipmentSerial(input ? input.value : "");
  setFinishedShipmentMessage("finished-shipment-scan-message", "", false);
  if (!/^M[0-9]{4}-[0-9]{7}$/.test(serial)) {
    setFinishedShipmentMessage("finished-shipment-scan-message", t("finished_shipping_serial_invalid"), true);
    if (input) input.select();
    return;
  }
  if (finishedShipmentUnits.some(function(unit) { return unit.manufacturing_serial === serial; })) {
    setFinishedShipmentMessage("finished-shipment-scan-message", t("finished_shipping_serial_duplicate"), true);
    if (input) input.select();
    return;
  }
  var r = await sb.from("finished_product_units")
    .select("id,manufacturing_serial,dkd_shohin_id,product_variant_id,product_kind,product_category,product_no,gltek_part_number,genuine_part_number,manufacturer_part_number,manufacturer,status,manufactured_at")
    .eq("manufacturing_serial", serial)
    .maybeSingle();
  if (r.error || !r.data) {
    setFinishedShipmentMessage("finished-shipment-scan-message", t("finished_shipping_serial_not_found"), true);
    if (input) input.select();
    return;
  }
  await renderFinishedShipmentLookup(r.data);
  if (r.data.status !== "available") {
    setFinishedShipmentMessage("finished-shipment-scan-message", t("finished_shipping_serial_unavailable"), true);
    if (input) input.select();
    return;
  }
  finishedShipmentUnits.push(r.data);
  renderFinishedShipmentUnits();
  setFinishedShipmentMessage("finished-shipment-scan-message", t("finished_shipping_available"), false);
  if (input) { input.value = ""; input.focus(); }
}

function clearFinishedShipmentUnits() {
  finishedShipmentUnits = [];
  renderFinishedShipmentUnits();
  setFinishedShipmentMessage("finished-shipment-scan-message", "", false);
  var lookup = document.getElementById("finished-shipment-lookup");
  if (lookup) lookup.innerHTML = "";
}

async function saveFinishedProductShipment() {
  if (!canManageFinishedProductShipping() || finishedShipmentSaving) return;
  var customerId = parseInt((document.getElementById("finished-shipment-customer") || {}).value, 10);
  var shippedOn = ((document.getElementById("finished-shipment-shipped-on") || {}).value || "").trim();
  var warrantyMonths = parseInt((document.getElementById("finished-shipment-warranty-months") || {}).value, 10);
  if (!finishedShipmentUnits.length) { setFinishedShipmentMessage("finished-shipment-save-message", t("finished_shipping_serial_required"), true); return; }
  if (isNaN(customerId)) { setFinishedShipmentMessage("finished-shipment-save-message", t("finished_shipping_customer_required"), true); return; }
  if (!/^\d{4}-\d{2}-\d{2}$/.test(shippedOn)) { setFinishedShipmentMessage("finished-shipment-save-message", t("finished_shipping_date_required"), true); return; }
  if (isNaN(warrantyMonths) || warrantyMonths < 1 || warrantyMonths > 120) { setFinishedShipmentMessage("finished-shipment-save-message", t("finished_shipping_warranty_months"), true); return; }

  finishedShipmentSaving = true;
  var button = document.getElementById("btn-finished-shipment-save");
  if (button) button.disabled = true;
  setFinishedShipmentMessage("finished-shipment-save-message", t("loading"), false);
  try {
    var r = await sb.rpc("ship_finished_product_units", {
      target_manufacturing_serials: finishedShipmentUnits.map(function(unit) { return unit.manufacturing_serial; }),
      target_sales_customer_id: customerId,
      target_shipped_on: shippedOn,
      target_external_order_number: ((document.getElementById("finished-shipment-order-number") || {}).value || "").trim() || null,
      target_carrier_name: ((document.getElementById("finished-shipment-carrier") || {}).value || "").trim() || null,
      target_tracking_number: ((document.getElementById("finished-shipment-tracking") || {}).value || "").trim() || null,
      target_warranty_months: warrantyMonths,
      target_note: ((document.getElementById("finished-shipment-note") || {}).value || "").trim() || null
    });
    if (r.error) throw r.error;
    var result = r.data || {};
    clearFinishedShipmentUnits();
    setFinishedShipmentMessage("finished-shipment-save-message", t("finished_shipping_saved") + " " + (result.shipment_code || ""), false);
    await loadFinishedShipmentHistory();
  } catch (e) {
    console.warn("finished-product shipment save failed", e);
    setFinishedShipmentMessage("finished-shipment-save-message", (e && e.message) || t("msg_part_err"), true);
  } finally {
    finishedShipmentSaving = false;
    if (button) button.disabled = false;
  }
}

async function loadFinishedShipmentHistory() {
  var wrap = document.getElementById("finished-shipment-history");
  if (wrap) wrap.innerHTML = "<div class='loading'>" + esc(t("loading")) + "</div>";
  var shipmentR = await sb.from("finished_product_shipments")
    .select("id,shipment_code,sales_customer_id,customer_code_snapshot,customer_name_snapshot,shipped_on,external_order_number,carrier_name,tracking_number,warranty_months,warranty_expires_on,note,status,created_at,cancelled_at,cancellation_reason")
    .order("created_at", { ascending: false })
    .limit(50);
  if (shipmentR.error) {
    finishedShipmentHistoryRows = [];
    if (wrap) wrap.innerHTML = "<div class='empty'>" + esc(shipmentR.error.message || t("msg_part_err")) + "</div>";
    return;
  }
  var shipments = shipmentR.data || [];
  if (!shipments.length) {
    finishedShipmentHistoryRows = [];
    renderFinishedShipmentHistory();
    return;
  }
  var ids = shipments.map(function(row) { return row.id; });
  var itemR = await sb.from("finished_product_shipment_items")
    .select("shipment_id,finished_product_unit_id")
    .in("shipment_id", ids);
  if (itemR.error) {
    if (wrap) wrap.innerHTML = "<div class='empty'>" + esc(itemR.error.message || t("msg_part_err")) + "</div>";
    return;
  }
  var unitIds = Array.from(new Set((itemR.data || []).map(function(row) { return row.finished_product_unit_id; })));
  var units = [];
  if (unitIds.length) {
    var unitR = await sb.from("finished_product_units")
      .select("id,manufacturing_serial,product_no,gltek_part_number,genuine_part_number,manufacturer_part_number,manufacturer,status")
      .in("id", unitIds);
    if (unitR.error) {
      if (wrap) wrap.innerHTML = "<div class='empty'>" + esc(unitR.error.message || t("msg_part_err")) + "</div>";
      return;
    }
    units = unitR.data || [];
  }
  var unitMap = {};
  units.forEach(function(unit) { unitMap[String(unit.id)] = unit; });
  var itemMap = {};
  (itemR.data || []).forEach(function(item) {
    var key = String(item.shipment_id);
    if (!itemMap[key]) itemMap[key] = [];
    if (unitMap[String(item.finished_product_unit_id)]) itemMap[key].push(unitMap[String(item.finished_product_unit_id)]);
  });
  finishedShipmentHistoryRows = shipments.map(function(row) {
    return Object.assign({}, row, { units: itemMap[String(row.id)] || [] });
  });
  renderFinishedShipmentHistory();
}

function renderFinishedShipmentHistory() {
  var wrap = document.getElementById("finished-shipment-history");
  if (!wrap) return;
  if (!finishedShipmentHistoryRows.length) {
    wrap.innerHTML = "<div class='empty'>" + esc(t("finished_shipping_history_empty")) + "</div>";
    return;
  }
  wrap.innerHTML = finishedShipmentHistoryRows.map(function(row) {
    var active = row.status === "shipped";
    var warranty = finishedShipmentWarrantyState(row.warranty_expires_on);
    var serials = (row.units || []).map(function(unit) { return unit.manufacturing_serial; });
    var meta = [row.shipped_on, row.carrier_name, row.tracking_number, row.external_order_number].filter(Boolean).join(" / ");
    var html = "<article class='finished-shipment-history-row'>";
    html += "<div class='finished-shipment-history-head'><div><strong>" + esc(row.shipment_code || ("S" + row.id)) + "</strong><span>" + esc(row.customer_name_snapshot || "-") + "</span></div>";
    html += "<span class='finished-shipment-status " + esc(row.status || "") + "'>" + esc(t(active ? "finished_shipping_shipped" : "finished_shipping_cancelled_status")) + "</span></div>";
    html += "<div class='finished-shipment-history-meta'>" + esc(meta || "-") + "</div>";
    html += "<div class='finished-shipment-warranty " + (warranty.active && active ? "active" : "expired") + "'>" + esc(warranty.label + " / " + (row.warranty_expires_on || "-")) + "</div>";
    html += "<div class='finished-label-serial-list'>" + serials.map(function(serial) { return "<span class='finished-label-serial-chip'>" + esc(serial) + "</span>"; }).join("") + "</div>";
    if (active) html += "<div class='finished-shipment-history-actions'><button type='button' class='btn-sm-edit production-action-secondary' data-finished-shipment-cancel='" + esc(String(row.id)) + "'>" + esc(t("finished_shipping_cancel")) + "</button></div>";
    if (!active && row.cancellation_reason) html += "<div class='finished-shipment-history-meta'>" + esc(row.cancellation_reason) + "</div>";
    html += "</article>";
    return html;
  }).join("");
  wrap.querySelectorAll("[data-finished-shipment-cancel]").forEach(function(btn) {
    btn.addEventListener("click", function() { cancelFinishedProductShipment(parseInt(btn.dataset.finishedShipmentCancel, 10)); });
  });
}

async function cancelFinishedProductShipment(shipmentId) {
  if (!canManageFinishedProductShipping() || !shipmentId) return;
  var reason = prompt(t("finished_shipping_cancel_reason"));
  if (reason == null) return;
  reason = reason.trim();
  if (!reason) { alert(t("finished_shipping_cancel_reason")); return; }
  var r = await sb.rpc("cancel_finished_product_shipment", {
    target_shipment_id: shipmentId,
    target_reason: reason
  });
  if (r.error) { alert(r.error.message || t("msg_part_err")); return; }
  setFinishedShipmentMessage("finished-shipment-save-message", t("finished_shipping_cancelled"), false);
  await loadFinishedShipmentHistory();
}

