// カテゴリマスタから販売管理のカテゴリ選択肢を生成
function renderCategoryChips() {
  var select = document.getElementById("search-category-filter");
  if (!select) return;

  var cats = categoryOptions.length ? categoryOptions : [];
  if (!cats.length) {
    var seen = {};
    allProducts.forEach(function(p) {
      var catKey = p.category_code || p.category;
      if (catKey && !seen[catKey]) {
        seen[catKey] = true;
        cats.push({
          category_code: catKey,
          label_ja: p.category_ja || p.category,
          label_en: p.category_en || p.category,
          label_zh: p.category_zh || p.category
        });
      }
    });
  }
  select.innerHTML = "";
  var allOption = document.createElement("option");
  allOption.value = "all";
  allOption.textContent = t("filter_all");
  select.appendChild(allOption);
  cats.forEach(function(cat) {
    var catCode = cat.category_code || cat.category;
    if (!catCode) return;
    var option = document.createElement("option");
    option.value = "cat:" + catCode;
    option.textContent = categoryOptionLabel(cat);
    select.appendChild(option);
  });
  if (typeof syncSearchFilterControls === "function") syncSearchFilterControls();
}

function esc(s) {
  if (s == null) return "";
  return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
}

function safeHttpsUrl(raw, allowedHosts) {
  try {
    var u = new URL(String(raw || ""), location.href);
    if (u.protocol !== "https:") return "";
    if (allowedHosts && allowedHosts.length) {
      var ok = allowedHosts.some(function(host) {
        return u.hostname === host || u.hostname.endsWith("." + host);
      });
      if (!ok) return "";
    }
    return u.toString();
  } catch (e) {
    return "";
  }
}

var PRODUCT_IMAGE_BUCKET = "product-images";
var PRODUCT_IMAGE_SIGNED_URL_TTL_SECONDS = 15 * 60;
var PRODUCT_IMAGE_SIGNED_URL_CACHE_MARGIN_MS = 60 * 1000;
var PRODUCT_IMAGE_BLANK_SRC = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///ywAAAAAAQABAAACAUwAOw==";
var signedProductImageUrlCache = {};
var signedProductImageUrlPending = {};
var signedProductImageHydrationScheduled = false;

function productImageStoragePathFromUrl(raw) {
  try {
    var u = new URL(String(raw || ""));
    var supa = new URL(SUPABASE_URL);
    if (u.origin !== supa.origin) return "";
    var prefixes = [
      "/storage/v1/object/public/" + PRODUCT_IMAGE_BUCKET + "/",
      "/storage/v1/render/image/public/" + PRODUCT_IMAGE_BUCKET + "/",
      "/storage/v1/object/sign/" + PRODUCT_IMAGE_BUCKET + "/",
      "/storage/v1/render/image/sign/" + PRODUCT_IMAGE_BUCKET + "/",
      "/storage/v1/object/authenticated/" + PRODUCT_IMAGE_BUCKET + "/",
      "/storage/v1/render/image/authenticated/" + PRODUCT_IMAGE_BUCKET + "/"
    ];
    for (var i = 0; i < prefixes.length; i++) {
      var prefix = prefixes[i];
      if (u.pathname.indexOf(prefix) === 0) {
        var path = u.pathname.slice(prefix.length);
        try { return decodeURIComponent(path); } catch (e) { return path; }
      }
    }
  } catch (e) {}
  return "";
}

function productImageStoragePath(source) {
  if (!source) return "";
  if (typeof source === "object") {
    var objectPath = String(source.storage_path || "").trim();
    if (objectPath) return objectPath.replace(/^\/+/, "");
    return productImageStoragePathFromUrl(source.image_url || source.thumbnail_image_url || "");
  }
  var raw = String(source || "").trim();
  if (!raw) return "";
  if (raw.indexOf("://") < 0 && raw.indexOf("data:") !== 0 && raw.indexOf("/") >= 0) {
    return raw.replace(/^\/+/, "").replace(new RegExp("^" + PRODUCT_IMAGE_BUCKET + "/"), "");
  }
  return productImageStoragePathFromUrl(raw);
}

function safeSupabaseImageUrl(raw) {
  try {
    var u = new URL(String(raw || ""));
    var supa = new URL(SUPABASE_URL);
    var okPath = productImageStoragePathFromUrl(u.toString()) !== "";
    if (u.origin !== supa.origin || !okPath) return "";
    return u.toString();
  } catch (e) {
    return "";
  }
}

function buildSupabaseThumbUrl(url, width, height, resize) {
  var raw = safeSupabaseImageUrl(url);
  if (!raw) return "";
  var pairs = [
    ["/storage/v1/object/public/", "/storage/v1/render/image/public/"],
    ["/storage/v1/object/sign/", "/storage/v1/render/image/sign/"],
    ["/storage/v1/object/authenticated/", "/storage/v1/render/image/authenticated/"]
  ];
  var transformed = "";
  for (var i = 0; i < pairs.length; i++) {
    if (raw.indexOf(pairs[i][0]) >= 0) {
      transformed = raw.replace(pairs[i][0], pairs[i][1]);
      break;
    }
    if (raw.indexOf(pairs[i][1]) >= 0) {
      transformed = raw;
      break;
    }
  }
  if (!transformed) return "";
  try {
    var u = new URL(transformed);
    u.searchParams.set("width", String(width || 96));
    u.searchParams.set("height", String(height || width || 96));
    u.searchParams.set("resize", resize || "contain");
    u.searchParams.set("quality", "55");
    return u.toString();
  } catch (e) {
    var joiner = transformed.indexOf("?") >= 0 ? "&" : "?";
    return transformed + joiner + "width=" + encodeURIComponent(String(width || 96)) +
      "&height=" + encodeURIComponent(String(height || width || 96)) +
      "&resize=" + encodeURIComponent(resize || "contain") +
      "&quality=55";
  }
}

function signedProductImageOptions(options) {
  options = options || {};
  var width = parseInt(options.width || 0, 10) || 0;
  var height = parseInt(options.height || options.width || 0, 10) || 0;
  return {
    width: width,
    height: height,
    resize: options.resize || "contain"
  };
}

function signedProductImageCacheKey(path, options) {
  var opt = signedProductImageOptions(options);
  return [path, opt.width, opt.height, opt.resize].join("|");
}

function cachedSignedProductImageUrl(path, options) {
  var entry = signedProductImageUrlCache[signedProductImageCacheKey(path, options)];
  if (!entry || !entry.url) return "";
  if (entry.expiresAt <= Date.now() + PRODUCT_IMAGE_SIGNED_URL_CACHE_MARGIN_MS) return "";
  return entry.url;
}

function signProductImageUrl(path, options) {
  path = String(path || "").replace(/^\/+/, "");
  if (!path) return Promise.resolve("");
  var key = signedProductImageCacheKey(path, options);
  var cached = cachedSignedProductImageUrl(path, options);
  if (cached) return Promise.resolve(cached);
  if (signedProductImageUrlPending[key]) return signedProductImageUrlPending[key];
  var opt = signedProductImageOptions(options);
  var apiOptions = {};
  if (opt.width || opt.height) {
    apiOptions.transform = {
      width: opt.width || undefined,
      height: opt.height || opt.width || undefined,
      resize: opt.resize || "contain"
    };
  }
  signedProductImageUrlPending[key] = sb.storage
    .from(PRODUCT_IMAGE_BUCKET)
    .createSignedUrl(path, PRODUCT_IMAGE_SIGNED_URL_TTL_SECONDS, apiOptions.transform ? apiOptions : undefined)
    .then(function(result) {
      if (result.error) throw result.error;
      var signedUrl = result.data && (result.data.signedUrl || result.data.signedURL || result.data.publicUrl) || "";
      if (signedUrl) {
        signedProductImageUrlCache[key] = {
          url: signedUrl,
          expiresAt: Date.now() + PRODUCT_IMAGE_SIGNED_URL_TTL_SECONDS * 1000
        };
      }
      return signedUrl;
    })
    .catch(function(e) {
      console.warn("product image signed URL failed", e);
      return "";
    })
    .finally(function() {
      delete signedProductImageUrlPending[key];
    });
  return signedProductImageUrlPending[key];
}

function productImageFallbackUrl(source, options) {
  var raw = typeof source === "object" ? (source.image_url || source.thumbnail_image_url || "") : source;
  var original = safeSupabaseImageUrl(raw);
  if (!original) return "";
  return buildSupabaseThumbUrl(original, options.width || 96, options.height || options.width || 96, options.resize || "contain") || original;
}

function signedProductImageDatasetAttrs(path, options) {
  if (!path) return "";
  var opt = signedProductImageOptions(options);
  return " data-product-image-path='" + esc(path) + "'" +
    " data-product-image-width='" + esc(String(opt.width || "")) + "'" +
    " data-product-image-height='" + esc(String(opt.height || "")) + "'" +
    " data-product-image-resize='" + esc(opt.resize || "contain") + "'";
}

function thumbImgHtml(source, options) {
  options = options || {};
  var path = productImageStoragePath(source);
  var fallback = productImageFallbackUrl(source, options);
  var signed = path ? cachedSignedProductImageUrl(path, options) : "";
  var src = signed || fallback || PRODUCT_IMAGE_BLANK_SRC;
  var loading = options.loading || "lazy";
  var decoding = options.decoding || "async";
  var fetchPriority = options.fetchPriority ? " fetchpriority='" + esc(options.fetchPriority) + "'" : "";
  var cls = options.className ? " class='" + esc(options.className) + "'" : "";
  if (path) scheduleSignedProductImageHydration();
  return "<img" + cls + " src='" + esc(src) + "' data-original-src='" + esc(fallback || signed || "") + "'" +
    signedProductImageDatasetAttrs(path, options) +
    " loading='" + esc(loading) + "' decoding='" + esc(decoding) + "'" + fetchPriority + " alt=''>";
}

function signedProductImageOptionsFromDataset(img) {
  return {
    width: parseInt(img.dataset.productImageWidth || "0", 10) || 0,
    height: parseInt(img.dataset.productImageHeight || "0", 10) || 0,
    resize: img.dataset.productImageResize || "contain"
  };
}

function setSignedProductImageElementSource(img, source, options) {
  if (!img) return;
  options = options || {};
  var path = productImageStoragePath(source);
  var fallback = productImageFallbackUrl(source, options);
  if (!path) {
    img.removeAttribute("data-product-image-path");
    img.src = fallback || "";
    img.dataset.originalSrc = fallback || "";
    return;
  }
  var opt = signedProductImageOptions(options);
  img.dataset.productImagePath = path;
  img.dataset.productImageWidth = String(opt.width || "");
  img.dataset.productImageHeight = String(opt.height || "");
  img.dataset.productImageResize = opt.resize || "contain";
  img.dataset.originalSrc = fallback || "";
  img.src = cachedSignedProductImageUrl(path, opt) || fallback || PRODUCT_IMAGE_BLANK_SRC;
  hydrateSignedProductImageElement(img);
}

function hydrateSignedProductImageElement(img) {
  if (!img || !img.dataset || !img.dataset.productImagePath) return;
  var path = img.dataset.productImagePath;
  var options = signedProductImageOptionsFromDataset(img);
  var cached = cachedSignedProductImageUrl(path, options);
  if (cached) {
    img.src = cached;
    img.dataset.originalSrc = cached;
    return;
  }
  signProductImageUrl(path, options).then(function(url) {
    if (!url || !img.dataset || img.dataset.productImagePath !== path) return;
    var latest = signedProductImageOptionsFromDataset(img);
    if (signedProductImageCacheKey(path, latest) !== signedProductImageCacheKey(path, options)) return;
    img.src = url;
    img.dataset.originalSrc = url;
  });
}

function hydrateSignedProductImages(root) {
  var scope = root || document;
  if (!scope.querySelectorAll) return;
  scope.querySelectorAll("img[data-product-image-path]").forEach(function(img) {
    hydrateSignedProductImageElement(img);
  });
}

function scheduleSignedProductImageHydration() {
  if (signedProductImageHydrationScheduled) return;
  signedProductImageHydrationScheduled = true;
  setTimeout(function() {
    signedProductImageHydrationScheduled = false;
    hydrateSignedProductImages(document);
  }, 0);
}

document.addEventListener("error", function(event) {
  var img = event.target;
  if (!img || img.tagName !== "IMG" || !img.dataset || !img.dataset.originalSrc) return;
  if (img.dataset.productImagePath && img.dataset.thumbFallbackDone !== "1") {
    img.dataset.thumbFallbackDone = "1";
    var options = signedProductImageOptionsFromDataset(img);
    delete options.width;
    delete options.height;
    signProductImageUrl(img.dataset.productImagePath, options).then(function(url) {
      if (url) img.src = url;
    });
    return;
  }
  if (img.dataset.thumbFallbackDone === "1" || img.src === img.dataset.originalSrc) return;
  img.dataset.thumbFallbackDone = "1";
  img.src = img.dataset.originalSrc;
}, true);

var preloadedThumbUrls = {};
function preloadThumbImage(source, options) {
  options = options || {};
  var path = productImageStoragePath(source);
  if (path) {
    signProductImageUrl(path, options).then(function(src) {
      if (!src || preloadedThumbUrls[src]) return;
      preloadedThumbUrls[src] = true;
      var img = new Image();
      img.decoding = "async";
      img.src = src;
    });
    return;
  }
  var src = productImageFallbackUrl(source, options);
  if (src && !preloadedThumbUrls[src]) {
    preloadedThumbUrls[src] = true;
    var fallbackImg = new Image();
    fallbackImg.decoding = "async";
    fallbackImg.src = src;
  }
}

function preloadProductSearchThumbnails(products) {
  (products || []).slice(0, productSearchLimit || SEARCH_INITIAL_LIMIT).forEach(function(p) {
    var thumb = getProductImageThumbnail(p);
    if (thumb) preloadThumbImage(thumb, { width: 112, height: 112, resize: "contain" });
  });
}

function preloadCurrentImageThumbnails(images) {
  (images || []).forEach(function(img) {
    if (img && (img.storage_path || img.image_url)) preloadThumbImage(img, { width: 240, height: 240, resize: "contain" });
  });
}

// カテゴリ名を現在の言語で表示する
// "alternator" / "Large Alternator" → キー "cat_Alternator" → 翻訳辞書を引く
function categoryTranslationSource(category) {
  var raw = String(category || "").trim();
  if (!raw) return "";
  var nativeMap = {
    "オルタネータ": "Alternator",
    "オルタネーター": "Alternator",
    "スタータ": "Starter",
    "スターター": "Starter",
    "ディストリビュータ": "Distributor",
    "大型オルタネータ": "Large Alternator",
    "大型オルタネーター": "Large Alternator",
    "ACコンプレッサ": "AC Compressor",
    "ACコンプレッサー": "AC Compressor",
    "スタータジェネレータ": "Starter Generator",
    "スタータージェネレータ": "Starter Generator",
    "新品大型スタータ": "New Large Starter",
    "新品大型スターター": "New Large Starter",
    "大型スタータ": "Large Starter",
    "大型スターター": "Large Starter",
    "スロットルボディ": "Throttle Body",
    "ブロアモーター": "Blower Motor",
    "ブロワモーター": "Blower Motor"
  };
  if (nativeMap[raw]) return nativeMap[raw];
  var code = raw.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
  var map = {
    alternator: "Alternator",
    starter: "Starter",
    distributor: "Distributor",
    large_alternator: "Large Alternator",
    large_starter: "Large Starter",
    new_large_starter: "New Large Starter",
    starter_generator: "Starter Generator",
    ac_compressor: "AC Compressor",
    throttle_body: "Throttle Body",
    blower_motor: "Blower Motor"
  };
  return map[code] || raw;
}
function tCat(category) {
  if (!category) return "-";
  var source = categoryTranslationSource(category);
  var key = "cat_" + source.replace(/ /g, "_");
  var val = t(key);
  // 翻訳辞書にキーがない場合はそのまま返す
  return val === key ? source : val;
}
function categoryOptionLabel(cat) {
  if (!cat) return "-";
  var code = cat.category_code || cat.category || cat.label_en || cat.label_ja || "";
  var rawCode = String(code || "").trim().toLowerCase();
  var label = "";
  if (currentLang === "ja") label = cat.label_ja || "";
  if (currentLang === "zh") label = cat.label_zh || "";
  if (currentLang === "en") label = cat.label_en || "";
  if (label && label.trim().toLowerCase() !== rawCode) return label;
  return tCat(code);
}
function productCategoryLabel(p) {
  if (!p) return "-";
  var code = p.category_code || p.category || "";
  var rawCode = String(code || "").trim().toLowerCase();
  var label = "";
  if (currentLang === "ja") label = p.category_ja || "";
  if (currentLang === "zh") label = p.category_zh || "";
  if (currentLang === "en") label = p.category_en || "";
  if (label && label.trim().toLowerCase() !== rawCode) return label;
  return tCat(code || label);
}
function refreshCategorySelectLabels() {
  document.querySelectorAll("#pf-category option").forEach(function(opt) {
    opt.textContent = tCat(opt.value);
  });
}
function getProductEngine(p) {
  return p.engine || p.engine_model || p.engine_type || p.engine_code || "";
}
function normalizeAsciiWidth(value) {
  if (value === null || value === undefined) return "";
  return String(value)
    .replace(/[\uFF01-\uFF5E]/g, function(ch) {
      return String.fromCharCode(ch.charCodeAt(0) - 0xFEE0);
    })
    .replace(/\u3000/g, " ");
}

function norm(s) {
  if (s == null) return "";
  return normalizeAsciiWidth(s)
    .toUpperCase()
    .replace(/[\u2010-\u2015\u2212\u30FC\uFF0D]/g, "-")
    .replace(/[-\s]/g, "")
    .replace(/^([AM])0+([0-9])T/, "$1$2T")
    .toLowerCase();
}
function isPC() { return window.innerWidth >= 768; }

function delay(ms) {
  return new Promise(function(resolve) { setTimeout(resolve, ms); });
}

function normalizedStartsWith(value, query) {
  return !!query && norm(value).indexOf(query) === 0;
}

function normalizedContains(value, query) {
  return !!query && norm(value).indexOf(query) >= 0;
}

function productHasSlPart(p, slNums) {
  return !!(
    (slNums && slNums.length > 0) ||
    productSlPresence(p)
  );
}

function applyCachedSearchAuxiliaryMaps(products) {
  var changed = false;
  (products || []).forEach(function(p) {
    productImageCacheKeys(p).forEach(function(cacheKey) {
      if (Object.prototype.hasOwnProperty.call(imageCountCache, cacheKey) && !Object.prototype.hasOwnProperty.call(imageCountMap, cacheKey)) {
        imageCountMap[cacheKey] = imageCountCache[cacheKey];
        changed = true;
      }
      if (Object.prototype.hasOwnProperty.call(imageThumbnailCache, cacheKey) && !Object.prototype.hasOwnProperty.call(imageThumbnailMap, cacheKey)) {
        imageThumbnailMap[cacheKey] = imageThumbnailCache[cacheKey];
        changed = true;
      }
      if (Object.prototype.hasOwnProperty.call(productionImageCountCache, cacheKey) && !Object.prototype.hasOwnProperty.call(productionImageCountMap, cacheKey)) {
        productionImageCountMap[cacheKey] = productionImageCountCache[cacheKey];
        changed = true;
      }
    });
    productSlCacheKeys(p).forEach(function(key) {
      if (Object.prototype.hasOwnProperty.call(slPresenceCache, key) && !Object.prototype.hasOwnProperty.call(slPresenceMap, key)) {
        slPresenceMap[key] = slPresenceCache[key];
        changed = true;
      }
      if (Object.prototype.hasOwnProperty.call(slPartsCache, key) && !Object.prototype.hasOwnProperty.call(slPartsMap, key)) {
        slPartsMap[key] = slPartsCache[key];
        changed = true;
      }
    });
    var dkdKey = productDkdId(p);
    if (dkdKey && Object.prototype.hasOwnProperty.call(productVariantSummaryCache, dkdKey) && !Object.prototype.hasOwnProperty.call(productVariantSummaryMap, dkdKey)) {
      productVariantSummaryMap[dkdKey] = productVariantSummaryCache[dkdKey];
      changed = true;
    }
  });
  return changed;
}

function productSearchCardDkdIds(products) {
  var seen = {};
  var ids = [];
  (products || []).forEach(function(p) {
    var id = parseInt(p && (p.dkd_shohin_id || p.id), 10);
    if (isNaN(id) || seen[id]) return;
    seen[id] = true;
    ids.push(id);
  });
  return ids;
}

function normalizeProductKind(kind) {
  kind = String(kind || "").trim().toLowerCase();
  if (kind === "aftermarket" || kind === "aftermarket-new" || kind === "aftermarket new") return "aftermarket_new";
  if (kind === "used-core" || kind === "used core" || kind === "core") return "used_core";
  if (kind === "catalog" || kind === "catalog-spec" || kind === "catalog spec" || kind === "catalog_spec") return "catalog_spec";
  if (kind === "rebuilt" || kind === "rebuild") return "rebuilt";
  return kind || "rebuilt";
}

function productKindLabel(kind) {
  kind = normalizeProductKind(kind);
  if (kind === "rebuilt") return t("product_kind_rebuilt");
  if (kind === "aftermarket_new") return t("product_kind_aftermarket_new");
  if (kind === "used_core") return t("product_kind_used_core");
  if (kind === "catalog_spec") return t("product_kind_catalog_spec");
  return t("product_kind_other");
}

function productKindClass(kind) {
  kind = normalizeProductKind(kind);
  if (kind === "rebuilt" || kind === "aftermarket_new" || kind === "used_core" || kind === "catalog_spec") return kind;
  return "other";
}

function coreReturnRequiredDefault(kind) {
  return normalizeProductKind(kind) === "rebuilt";
}

function coreReturnPolicyForKind(kind, rows) {
  kind = normalizeProductKind(kind || "rebuilt");
  var matches = (rows || []).filter(function(row) {
    return normalizeProductKind(row && row.product_kind) === kind;
  });
  var row = matches.find(function(item) {
    return item && item.core_charge_jpy !== null && item.core_charge_jpy !== undefined && item.core_charge_jpy !== "";
  }) || matches[0] || null;
  var required = row && typeof row.core_return_required === "boolean"
    ? row.core_return_required
    : coreReturnRequiredDefault(kind);
  var charge = row && row.core_charge_jpy !== null && row.core_charge_jpy !== undefined && row.core_charge_jpy !== ""
    ? parseInt(row.core_charge_jpy, 10)
    : null;
  if (charge !== null && (isNaN(charge) || charge < 0)) charge = null;
  return {
    kind: kind,
    row: row,
    required: required,
    charge: charge,
    hasProductCharge: charge !== null
  };
}

function coreReturnChargeText(policy) {
  if (!policy || !policy.required) return "¥0";
  return policy.hasProductCharge ? "¥" + formatYen(policy.charge) : t("core_charge_unset");
}

function renderCoreReturnPolicyHtml(kind, rows, options) {
  options = options || {};
  var policy = coreReturnPolicyForKind(kind, rows);
  var stateClass = policy.required ? "required" : "not-required";
  var stateText = policy.required ? t("core_return_required") : t("core_return_not_required");
  var chargeHtml = options.showCharge === false
    ? ""
    : "<div class='core-return-policy-item'><span>" + esc(t("core_charge_short")) + "</span><strong class='core-charge-value" + (policy.required && !policy.hasProductCharge ? " unset" : "") + "'>" + esc(coreReturnChargeText(policy)) + "</strong></div>";
  return "<div class='core-return-policy-panel" + (options.compact ? " compact" : "") + (options.vertical ? " vertical" : "") + "'>" +
    (options.showTitle === false ? "" : "<div class='detail-block-title'>" + esc(t("core_return_policy")) + "</div>") +
    "<div class='core-return-policy-grid'>" +
      "<div class='core-return-policy-item'><span>" + esc(t("core_return_required_label")) + "</span><strong class='core-return-badge " + stateClass + "'>" + esc(stateText) + "</strong></div>" +
      chargeHtml +
    "</div></div>";
}

function imageProductKindOptions() {
  return ["rebuilt", "aftermarket_new"];
}

function imageKindSelectHtml(id, selected) {
  selected = normalizeProductKind(selected || "rebuilt");
  var cls = productKindClass(selected);
  var html = "<select id='" + esc(id) + "' class='product-kind-select " + esc(cls) + "'>";
  imageProductKindOptions().forEach(function(kind) {
    html += "<option class='" + productKindClass(kind) + "' value='" + esc(kind) + "'" + (kind === selected ? " selected" : "") + ">" + esc(productKindLabel(kind)) + "</option>";
  });
  html += "</select>";
  return html;
}

function imageKindFilterSelectHtml(id, selected) {
  selected = selected ? normalizeProductKind(selected) : "";
  var cls = selected ? productKindClass(selected) : "other";
  var html = "<select id='" + esc(id) + "' class='product-kind-select " + esc(cls) + "'>";
  html += "<option value=''>" + esc(t("image_edit_filter_all")) + "</option>";
  imageProductKindOptions().forEach(function(kind) {
    html += "<option class='" + productKindClass(kind) + "' value='" + esc(kind) + "'" + (kind === selected ? " selected" : "") + ">" + esc(productKindLabel(kind)) + "</option>";
  });
  html += "</select>";
  return html;
}

function setProductKindSelectClass(select) {
  if (!select) return;
  var cls = select.value ? productKindClass(select.value) : "other";
  select.className = "product-kind-select " + cls;
}

function productDisplayKindAllowed(kind) {
  kind = normalizeProductKind(kind);
  return kind === "rebuilt" || kind === "aftermarket_new" || (kind === "catalog_spec" && canSeeCatalogSpec());
}

function productKindSortValue(kind) {
  kind = normalizeProductKind(kind);
  if (kind === "catalog_spec") return 5;
  if (kind === "rebuilt") return 10;
  if (kind === "aftermarket_new") return 20;
  if (kind === "used_core") return 30;
  return 90;
}

function createProductVariantSummary() {
  return { rows: [], kinds: {} };
}

function addProductVariantSummaryRow(summary, row) {
  if (!summary) return summary;
  row = row || {};
  var kind = normalizeProductKind(row.product_kind || row.default_product_kind || "rebuilt");
  if (!productDisplayKindAllowed(kind)) return summary;
  if (!summary.kinds[kind]) {
    summary.kinds[kind] = { kind: kind, count: 0, stockQty: 0, stockKnown: false, slCount: 0 };
  }
  var meta = summary.kinds[kind];
  meta.count += 1;
  if (row.stock_qty !== null && row.stock_qty !== undefined && row.stock_qty !== "") {
    var qty = parseFloat(row.stock_qty);
    if (!isNaN(qty)) {
      meta.stockQty += qty;
      meta.stockKnown = true;
    }
  }
  if (row.sl_part_id) meta.slCount += 1;
  summary.rows.push({
    product_variant_id: row.product_variant_id || null,
    dkd_shohin_id: row.dkd_shohin_id || null,
    product_kind: kind,
    stock_qty: row.stock_qty,
    sl_part_id: row.sl_part_id || null,
    display_label: row.display_label || "",
    stock_location: row.stock_location || "",
    stock_note: row.stock_note || "",
    core_return_required: typeof row.core_return_required === "boolean" ? row.core_return_required : coreReturnRequiredDefault(kind),
    core_charge_jpy: row.core_charge_jpy === null || row.core_charge_jpy === undefined || row.core_charge_jpy === "" ? null : parseInt(row.core_charge_jpy, 10)
  });
  return summary;
}

function cloneProductVariantSummary(summary) {
  var copy = createProductVariantSummary();
  (summary && summary.rows || []).forEach(function(row) {
    addProductVariantSummaryRow(copy, row);
  });
  return copy;
}

function productKindSummaryForProduct(p) {
  var dkdKey = productDkdId(p);
  var cached = dkdKey ? (productVariantSummaryMap[dkdKey] || productVariantSummaryCache[dkdKey]) : null;
  var summary = cloneProductVariantSummary(cached);
  if (p && (p.has_catalog_spec || p.has_catalog_source) && canSeeCatalogSpec() && !summary.kinds.catalog_spec) {
    addProductVariantSummaryRow(summary, {
      dkd_shohin_id: dkdKey || null,
      product_kind: "catalog_spec",
      display_label: "Catalog Spec"
    });
  }
  var defaultKind = normalizeProductKind(p && p.default_product_kind || "rebuilt");
  if (!productDisplayKindAllowed(defaultKind)) defaultKind = "rebuilt";
  if (!summary.kinds[defaultKind]) {
    addProductVariantSummaryRow(summary, { product_kind: defaultKind });
  }
  return summary;
}

function productKindSummaryHasKind(summary, kind) {
  kind = normalizeProductKind(kind);
  return !!(summary && summary.kinds && summary.kinds[kind]);
}

function renderProductKindPill(kind, meta, options) {
  options = options || {};
  meta = meta || {};
  var extra = "";
  if (options.detail && meta.stockKnown) {
    extra += "<span class='product-kind-stock'>" + esc(t("product_kind_stock")) + " " + esc(String(meta.stockQty)) + "</span>";
  }
  if (options.detail && meta.slCount > 0) {
    extra += "<span class='product-kind-stock'>" + esc(t("product_kind_sl")) + " " + esc(String(meta.slCount)) + "</span>";
  }
  return "<span class='product-kind-pill " + productKindClass(kind) + "'>" + esc(productKindLabel(kind)) + extra + "</span>";
}

function renderProductKindPills(summary, options) {
  options = options || {};
  var kinds = Object.keys((summary && summary.kinds) || {}).sort(function(a, b) {
    return productKindSortValue(a) - productKindSortValue(b);
  });
  if (options.compact) {
    var compactSlots = ["rebuilt", "aftermarket_new"];
    var compactHtml = "<div class='product-kind-list compact'>";
    compactSlots.forEach(function(kind) {
      var hasKind = productKindSummaryHasKind(summary, kind);
      compactHtml += "<span class='product-kind-slot" + (hasKind ? "" : " slot-empty") + "'>" +
        (hasKind ? renderProductKindPill(kind, summary.kinds[kind] || {}, options) : "&nbsp;") +
        "</span>";
    });
    compactHtml += "</div>";
    return compactHtml;
  }
  if (!kinds.length) {
    return "<div class='product-kind-list" + (options.compact ? " compact" : "") + "'><span class='product-kind-pill other'>" + esc(t("product_kind_none")) + "</span></div>";
  }
  var html = "<div class='product-kind-list" + (options.compact ? " compact" : "") + "'>";
  kinds.forEach(function(kind) {
    html += renderProductKindPill(kind, summary.kinds[kind] || {}, options);
  });
  html += "</div>";
  return html;
}

function renderBadgeSlotHtml(key, html) {
  return "<span class='badge-slot badge-slot-" + esc(key || "item") + (html ? "" : " slot-empty") + "'>" + (html || "&nbsp;") + "</span>";
}

function renderResultBadgeSlots(options) {
  options = options || {};
  var cls = options.className || "badges";
  var imageCount = parseInt(options.imageCount || 0, 10);
  if (isNaN(imageCount)) imageCount = 0;
  var catalogHtml = options.hasCatalogSpec ? "<span class='badge-catalog'>" + esc(t("product_kind_catalog_spec")) + "</span>" : "";
  var slHtml = options.hasSL ? "<span class='badge-sl'>SL</span>" : "";
  var kikanHtml = options.hasKikan ? "<span class='badge-kikan' title='" + esc(t("kikan_section")) + "'>&#x1F504;</span>" : "";
  var imageHtml = "";
  if (imageCount > 0) {
    imageHtml = "<span class='badge-img'>&#x1F4F7;" + esc(String(imageCount)) + "</span>";
  } else if (options.showEmptyImageBadge) {
    imageHtml = "<span class='badge-img no-image'>&#x1F5BC; " + esc(t("image_none_short")) + "</span>";
  }
  if (options.hideWhenEmpty && !catalogHtml && !slHtml && !kikanHtml && !imageHtml) return "";
  return "<div class='" + esc(cls) + " badge-slot-list'>" +
    renderBadgeSlotHtml("catalog", catalogHtml) +
    renderBadgeSlotHtml("sl", slHtml) +
    renderBadgeSlotHtml("kikan", kikanHtml) +
    renderBadgeSlotHtml("image", imageHtml) +
    "</div>";
}

function productKindSelectLabel(kind, summary) {
  kind = normalizeProductKind(kind);
  return productKindLabel(kind);
}

function productKindRowsForCurrent() {
  var dkdId = currentProduct ? productDkdId(currentProduct) : null;
  var rows = (currentProductVariants || []).filter(function(row) {
    return !dkdId || !row.dkd_shohin_id || String(row.dkd_shohin_id) === String(dkdId);
  }).filter(function(row) {
    return productDisplayKindAllowed(row.product_kind || row.default_product_kind || "rebuilt");
  }).slice();
  var defaultKind = normalizeProductKind((currentProduct && currentProduct.default_product_kind) || "rebuilt");
  if (!productDisplayKindAllowed(defaultKind)) defaultKind = "rebuilt";
  if (!rows.length && dkdId) {
    rows.push({
      product_variant_id: null,
      dkd_shohin_id: dkdId,
      product_kind: defaultKind,
      stock_qty: null,
      stock_location: "",
      stock_note: "",
      sl_part_id: null,
      is_active: true
    });
  }
  rows.sort(function(a, b) {
    var ak = normalizeProductKind(a.product_kind);
    var bk = normalizeProductKind(b.product_kind);
    if (ak !== bk) return productKindSortValue(ak) - productKindSortValue(bk);
    if (!!a.sl_part_id !== !!b.sl_part_id) return a.sl_part_id ? 1 : -1;
    return (parseInt(a.product_variant_id || 0, 10) || 0) - (parseInt(b.product_variant_id || 0, 10) || 0);
  });
  return rows;
}

function currentProductKindOptions(summary) {
  var map = {};
  map.rebuilt = true;
  map.aftermarket_new = true;
  Object.keys((summary && summary.kinds) || {}).forEach(function(kind) {
    map[normalizeProductKind(kind)] = true;
  });
  productKindRowsForCurrent().forEach(function(row) {
    map[normalizeProductKind(row.product_kind)] = true;
  });
  var defaultKind = normalizeProductKind((currentProduct && currentProduct.default_product_kind) || "rebuilt");
  if (!productDisplayKindAllowed(defaultKind)) defaultKind = "rebuilt";
  map[defaultKind] = true;
  return Object.keys(map).sort(function(a, b) {
    return productKindSortValue(a) - productKindSortValue(b);
  });
}

function selectedProductKind() {
  var kind = normalizeProductKind(currentSelectedProductKind || (currentProduct && currentProduct.default_product_kind) || "rebuilt");
  return productDisplayKindAllowed(kind) ? kind : "rebuilt";
}

function selectedProductVariantId() {
  var kind = selectedProductKind();
  var rows = productKindRowsForCurrent().filter(function(row) {
    return normalizeProductKind(row.product_kind) === kind && row.product_variant_id;
  });
  rows.sort(function(a, b) {
    if (!!a.sl_part_id !== !!b.sl_part_id) return a.sl_part_id ? 1 : -1;
    return (parseInt(a.product_variant_id || 0, 10) || 0) - (parseInt(b.product_variant_id || 0, 10) || 0);
  });
  return rows.length ? rows[0].product_variant_id : null;
}

function componentProductKindOptions() {
  var map = { rebuilt: true, aftermarket_new: true };
  if (canSeeCatalogSpec()) {
    currentProductKindOptions(productKindSummaryForProduct(currentProduct)).forEach(function(kind) {
      if (normalizeProductKind(kind) === "catalog_spec") map.catalog_spec = true;
    });
  }
  return Object.keys(map).sort(function(a, b) {
    return productKindSortValue(a) - productKindSortValue(b);
  });
}

function componentVariantRowsForKind(kind) {
  var dkdId = currentProduct ? productDkdId(currentProduct) : null;
  kind = normalizeProductKind(kind || selectedProductKind());
  return (currentProductVariants || []).filter(function(row) {
    if (!row.product_variant_id) return false;
    if (dkdId && row.dkd_shohin_id && String(row.dkd_shohin_id) !== String(dkdId)) return false;
    return normalizeProductKind(row.product_kind) === kind && productDisplayKindAllowed(kind);
  }).slice().sort(function(a, b) {
    if (!!a.sl_part_id !== !!b.sl_part_id) return a.sl_part_id ? 1 : -1;
    return (parseInt(a.product_variant_id || 0, 10) || 0) - (parseInt(b.product_variant_id || 0, 10) || 0);
  });
}

function componentVariantLabel(row) {
  if (!row) return t("component_variant_auto");
  var kind = productKindLabel(row.product_kind || selectedProductKind());
  var labels = [];
  if (row.display_label) labels.push(row.display_label);
  if (row.sl_part_id) labels.push(t("product_kind_sl") + " " + row.sl_part_id);
  if (row.stock_location) labels.push(row.stock_location);
  if (productKindStockKindAllowed(row.product_kind)) {
    labels.push(t("product_kind_stock_qty") + " " + (row.stock_qty === null || row.stock_qty === undefined || row.stock_qty === "" ? "0" : row.stock_qty));
  }
  return kind + (labels.length ? " / " + labels.join(" / ") : " #" + String(row.product_variant_id || ""));
}

function componentTargetVariantText() {
  var selectedId = selectedComponentVariantId();
  if (!selectedId) return t("component_variant_auto");
  var row = componentVariantRowsForKind(selectedProductKind()).find(function(v) {
    return parseInt(v.product_variant_id, 10) === selectedId;
  });
  if (!row) return t("component_variant_auto");
  var labels = [];
  if (row.display_label) labels.push(row.display_label);
  if (row.sl_part_id) labels.push(t("product_kind_sl") + " " + row.sl_part_id);
  if (row.stock_location) labels.push(row.stock_location);
  return labels.length ? labels.join(" / ") : ("#" + String(row.product_variant_id || ""));
}

function componentTargetStockText() {
  if (!productKindStockKindAllowed(selectedProductKind())) return "-";
  var selectedId = selectedComponentVariantId();
  if (!selectedId) return "-";
  var row = componentVariantRowsForKind(selectedProductKind()).find(function(v) {
    return parseInt(v.product_variant_id, 10) === selectedId;
  });
  if (!row) return "-";
  return row.stock_qty === null || row.stock_qty === undefined || row.stock_qty === "" ? "0" : String(row.stock_qty);
}

function componentTargetSummaryHtml(componentCount) {
  var kind = selectedProductKind();
  var countText = componentCount === null || componentCount === undefined ? "-" : String(componentCount);
  return "<div class='component-target-summary'>" +
    "<div class='component-target-stat'><span>" + esc(t("component_target_kind_label")) + "</span><b>" + esc(productKindLabel(kind)) + "</b></div>" +
    "<div class='component-target-stat'><span>" + esc(t("component_target_variant_label")) + "</span><b>" + esc(componentTargetVariantText()) + "</b></div>" +
    "<div class='component-target-stat'><span>" + esc(t("product_kind_stock_qty")) + "</span><b>" + esc(componentTargetStockText()) + "</b></div>" +
    "<div class='component-target-stat'><span>" + esc(t("component_section")) + "</span><b>" + esc(countText) + "</b></div>" +
  "</div>";
}

function updateComponentTargetSummary(componentCount) {
  var el = document.getElementById("component-target-summary");
  if (el) el.innerHTML = componentTargetSummaryHtml(componentCount);
}

function componentEmptyDetailText(kind) {
  kind = normalizeProductKind(kind || selectedProductKind());
  if (currentLang === "en") {
    return kind === "rebuilt"
      ? "Catalog-derived component rows are managed here. Manual rows can be added without changing protected catalog rows."
      : "No component rows are registered for this kind. Add only the parts used for this product kind.";
  }
  if (currentLang === "zh") {
    return kind === "rebuilt"
      ? "目录来源的构成部品在这里管理。手动追加不会修改受保护的目录数据。"
      : "此区分尚未登记构成部品。请只追加该区分实际使用的部品。";
  }
  return kind === "rebuilt"
    ? "パーツカタログ由来の構成部品はここに表示します。カタログ行は保護したまま、社内入力分を追加できます。"
    : "この区分には構成部品が未登録です。この区分で実際に使用する部品だけを追加してください。";
}

function componentEmptyStateHtml() {
  var kind = selectedProductKind();
  return "<div class='component-empty-state'>" +
    "<div class='component-empty-title'>" + esc(tf("component_empty_for_kind", { kind: productKindLabel(kind) })) + "</div>" +
    "<div>" + esc(componentEmptyDetailText(kind)) + "</div>" +
  "</div>";
}

function selectedComponentVariantId() {
  var id = parseInt(currentSelectedComponentVariantId || "", 10);
  if (isNaN(id)) return null;
  var found = componentVariantRowsForKind(selectedProductKind()).some(function(row) {
    return parseInt(row.product_variant_id, 10) === id;
  });
  if (!found) {
    currentSelectedComponentVariantId = "";
    return null;
  }
  return id;
}

function componentUsageTargetLabel(row) {
  var kind = productKindLabel(row && row.product_kind ? row.product_kind : selectedProductKind());
  if (!row || !row.product_variant_id) return kind + " / " + t("component_variant_auto");
  var found = componentVariantRowsForKind(row.product_kind).find(function(v) {
    return parseInt(v.product_variant_id, 10) === parseInt(row.product_variant_id, 10);
  });
  return found ? componentVariantLabel(found) : (kind + " #" + String(row.product_variant_id));
}

function ensureSelectedProductKind(summary) {
  var options = currentProductKindOptions(summary);
  var selected = selectedProductKind();
  if (options.indexOf(selected) < 0) selected = options[0] || "rebuilt";
  currentSelectedProductKind = selected;
  return selected;
}

function renderProductKindPanelHtml(summary) {
  summary = summary || productKindSummaryForProduct(currentProduct);
  var selected = ensureSelectedProductKind(summary);
  var options = currentProductKindOptions(summary);
  var selectedMeta = summary.kinds && summary.kinds[selected] ? summary.kinds[selected] : null;
  var stockText = productKindStockKindAllowed(selected) && selectedMeta && selectedMeta.stockKnown
    ? String(selectedMeta.stockQty)
    : "-";
  var html = "<div class='product-kind-control detail-sales-kind-control'>";
  html += "<div class='detail-sales-term-row detail-sales-kind-row'>";
  html += "<div class='detail-sales-term-label'>" + esc(t("product_kind_section")) + "</div>";
  html += "<div class='detail-sales-term-value product-kind-control-row compact'>";
  html += "<select id='product-kind-select' class='product-kind-select " + productKindClass(selected) + "'>";
  options.forEach(function(kind) {
    html += "<option class='" + productKindClass(kind) + "' value='" + esc(kind) + "'" + (kind === selected ? " selected" : "") + ">" + esc(productKindSelectLabel(kind, summary)) + "</option>";
  });
  html += "</select></div></div>";
  html += "<div class='product-kind-stock-grid'><div class='product-kind-stock-row detail-sales-term-row active " + productKindClass(selected) + "' data-product-kind-row='" + esc(selected) + "'>";
  html += "<div class='product-kind-stock-label detail-sales-term-label'>" + esc(t("product_kind_stock_qty")) + "</div>";
  html += "<div class='product-kind-stock-value detail-sales-term-value'>" + esc(stockText) + "</div>";
  html += "</div></div></div>";
  return html;
}

function renderProductKindWrapForCurrent() {
  var wrap = document.getElementById("product-kind-wrap");
  if (!wrap || !currentProduct) return;
  wrap.innerHTML = renderProductKindPanelHtml(productKindSummaryForProduct(currentProduct));
  bindProductKindPanelActions();
}

function renderCoreReturnPolicyWrapForCurrent() {
  var wrap = document.getElementById("core-return-policy-wrap");
  if (!wrap) return;
  wrap.innerHTML = renderCoreReturnPolicyHtml(selectedProductKind(), productKindRowsForCurrent(), { compact: true, vertical: true, showTitle: false });
}

function bindProductKindPanelActions() {
  var select = document.getElementById("product-kind-select");
  if (select) {
    select.onchange = function() {
      currentSelectedProductKind = normalizeProductKind(select.value || "rebuilt");
      renderProductKindWrapForCurrent();
      renderCoreReturnPolicyWrapForCurrent();
      updateSalesProductStatusBadges();
      currentImages = [];
      renderImagesLoading();
      loadImages(null, detailSecondaryRequestSeq);
      if (canSeeSalesPrice()) loadDetailCustomerInfoForCurrent(detailSecondaryRequestSeq);
    };
  }
}

async function fetchProductVariantSummaryMap(products) {
  var map = {};
  var ids = productSearchCardDkdIds(products);
  if (!ids.length) return map;
  for (var i = 0; i < ids.length; i += 200) {
    var chunk = ids.slice(i, i + 200);
    var r = await sb.from("core_product_variants")
      .select("product_variant_id, dkd_shohin_id, product_kind, sl_part_id, display_label, stock_qty, stock_location, stock_note, core_return_required, core_charge_jpy, is_active")
      .eq("is_active", true)
      .in("dkd_shohin_id", chunk);
    if (r.error) {
      console.warn("product variant summary lookup failed", r.error);
      return map;
    }
    (r.data || []).forEach(function(row) {
      var key = String(row.dkd_shohin_id || "");
      if (!key) return;
      if (!map[key]) map[key] = createProductVariantSummary();
      addProductVariantSummaryRow(map[key], row);
    });
  }
  return map;
}

function productImageCacheKeys(p) {
  var keys = [];
  var dkd = productDkdId(p);
  if (dkd) keys.push("dkd:" + String(dkd));
  var legacyId = productLegacyPartId(p);
  if (legacyId) keys.push(String(legacyId));
  return keys.filter(function(key, idx, arr) { return key && arr.indexOf(key) === idx; });
}

function setProductImageCache(p, imageCount, thumbnailUrl) {
  var count = parseInt(imageCount || 0, 10) || 0;
  var thumb = thumbnailUrl || "";
  productImageCacheKeys(p).forEach(function(key) {
    imageCountMap[key] = count;
    imageCountCache[key] = count;
    imageThumbnailMap[key] = thumb;
    imageThumbnailCache[key] = thumb;
  });
}

function setProductionImageCache(p, imageCount) {
  var count = parseInt(imageCount || 0, 10) || 0;
  productImageCacheKeys(p).forEach(function(key) {
    productionImageCountMap[key] = count;
    productionImageCountCache[key] = count;
  });
}

function getProductImageCount(p) {
  var count = 0;
  productImageCacheKeys(p).forEach(function(key) {
    if (Object.prototype.hasOwnProperty.call(imageCountMap, key)) {
      count = Math.max(count, parseInt(imageCountMap[key] || 0, 10) || 0);
    }
    if (!isCustomerPortalSearchMode() && Object.prototype.hasOwnProperty.call(imageCountCache, key)) {
      count = Math.max(count, parseInt(imageCountCache[key] || 0, 10) || 0);
    }
  });
  return count;
}

function getProductionImageCount(p) {
  var count = 0;
  productImageCacheKeys(p).forEach(function(key) {
    if (Object.prototype.hasOwnProperty.call(productionImageCountMap, key)) {
      count = Math.max(count, parseInt(productionImageCountMap[key] || 0, 10) || 0);
    }
    if (Object.prototype.hasOwnProperty.call(productionImageCountCache, key)) {
      count = Math.max(count, parseInt(productionImageCountCache[key] || 0, 10) || 0);
    }
  });
  return count;
}

function getProductImageThumbnail(p) {
  var thumb = "";
  productImageCacheKeys(p).some(function(key) {
    thumb = imageThumbnailMap[key] || (!isCustomerPortalSearchMode() ? imageThumbnailCache[key] : "") || "";
    return !!thumb;
  });
  return thumb;
}

async function fetchProductImageCountMapForContext(products, context) {
  var ids = productSearchCardDkdIds(products || []);
  var result = { counts: {}, thumbnails: {} };
  if (!ids.length) return result;
  for (var i = 0; i < ids.length; i += 200) {
    var chunk = ids.slice(i, i + 200);
    var query = sb.from("core_product_images")
      .select("dkd_shohin_id,image_url,storage_path,product_kind,image_origin,show_in_sales,show_in_production,sort_order,created_at,id")
      .in("dkd_shohin_id", chunk)
      .order("sort_order")
      .order("created_at")
      .order("id");
    var r = await query;
    if (r.error && isImageVisibilitySchemaError(r.error)) {
      r = await sb.from("core_product_images")
        .select("dkd_shohin_id,image_url,storage_path,product_kind,sort_order,created_at,id")
        .in("dkd_shohin_id", chunk)
        .order("sort_order")
        .order("created_at")
        .order("id");
    }
    if (r.error) {
      console.warn("product image count lookup failed", r.error);
      continue;
    }
    (r.data || []).forEach(function(img) {
      if (!img || !img.dkd_shohin_id || !img.image_url) return;
      var kind = normalizeProductKind(img.product_kind || "rebuilt");
      if (img.product_kind && imageProductKindOptions().indexOf(kind) < 0) return;
      if (!imageContextMatches(img, context)) return;
      var key = "dkd:" + String(img.dkd_shohin_id);
      result.counts[key] = (result.counts[key] || 0) + 1;
      if (!result.thumbnails[key]) result.thumbnails[key] = img.storage_path || img.image_url;
    });
  }
  return result;
}

function applyProductImageCountMapForContext(products, imageInfo, context) {
  var counts = (imageInfo && imageInfo.counts) || {};
  var thumbs = (imageInfo && imageInfo.thumbnails) || {};
  (products || []).forEach(function(p) {
    var dkd = productDkdId(p);
    var key = dkd ? "dkd:" + String(dkd) : "";
    var count = key ? (parseInt(counts[key] || 0, 10) || 0) : 0;
    if (context === "production") {
      setProductionImageCache(p, count);
    } else {
      setProductImageCache(p, count, key ? (thumbs[key] || "") : "");
    }
  });
}

async function fetchProductSearchCardFlags(products) {
  var ids = productSearchCardDkdIds((products || []).slice(0, SEARCH_RENDER_LIMIT));
  if (!ids.length) return [];
  var r = await sb.rpc("get_product_search_card_flags", { target_dkd_ids: ids });
  if (r.error) {
    console.warn("product search card flags lookup failed", r.error);
    return [];
  }
  return r.data || [];
}

function applyProductSearchCardFlags(rows, products) {
  var byDkd = {};
  (products || []).forEach(function(p) {
    var key = String(p && (p.dkd_shohin_id || p.id || "") || "");
    if (key) byDkd[key] = p;
  });
  (rows || []).forEach(function(row) {
    var dkdKey = String(row && row.dkd_shohin_id || "");
    if (!dkdKey) return;
    var p = byDkd[dkdKey] || null;
    var hasSl = !!row.has_sl_part;
    var imageCount = parseInt(row.image_count || 0, 10) || 0;
    var thumbUrl = row.thumbnail_image_url || "";
    var hasKikan = !!row.has_kikan_compatible;
    var hasCatalogSpec = !!row.has_catalog_spec;
    if (p) {
      p.has_sl_part = hasSl || !!p.has_sl_part;
      if (hasKikan) p.has_kikan_compatible = true;
      if (hasCatalogSpec) p.has_catalog_spec = true;
      if (!isCustomerPortalSearchMode()) setProductImageCache(p, imageCount, thumbUrl);
      productSlCacheKeys(p).forEach(function(key) {
        slPresenceMap[key] = hasSl;
        slPresenceCache[key] = hasSl;
      });
    }
  });
}

function productLegacyPartIds(products) {
  var seen = {};
  var ids = [];
  (products || []).forEach(function(p) {
    var id = productLegacyPartId(p);
    if (!id || seen[id]) return;
    seen[id] = true;
    ids.push(id);
  });
  return ids;
}

async function fillProductLegacyPartIds(products) {
  var missingDkdIds = [];
  var byDkdId = {};
  (products || []).forEach(function(p) {
    if (productLegacyPartId(p)) return;
    var dkdId = p && (p.dkd_shohin_id || p.id);
    var n = parseInt(dkdId, 10);
    if (isNaN(n) || byDkdId[n]) return;
    byDkdId[n] = p;
    missingDkdIds.push(n);
  });
  if (!missingDkdIds.length) return;
  for (var i = 0; i < missingDkdIds.length; i += 200) {
    var chunk = missingDkdIds.slice(i, i + 200);
    var r = await sb.from("core_product_search_view")
      .select("dkd_shohin_id, legacy_part_id")
      .in("dkd_shohin_id", chunk);
    if (r.error) {
      console.warn("legacy part id lookup failed", r.error);
      continue;
    }
    (r.data || []).forEach(function(row) {
      var p = byDkdId[parseInt(row.dkd_shohin_id, 10)];
      var legacyId = parseInt(row.legacy_part_id, 10);
      if (p && !isNaN(legacyId)) p.legacy_part_id = legacyId;
    });
  }
}

async function fetchSlAndImageMaps(products) {
  var mapping = await fetchSlMappingMaps(products);
  if (!(mapping.slIds || []).length && !productSearchCardDkdIds(products).length) {
    mapping = await fetchLegacySlMappingMaps(products);
  }
  var detail = await fetchSlLabelAndImageMaps(mapping);
  return {
    presence: mapping.presence || {},
    labels: detail.labels || {},
    imageCounts: detail.imageCounts || {},
    thumbnails: detail.thumbnails || {}
  };
}

async function fetchSlMappingMaps(products) {
  var dkdIds = productSearchCardDkdIds(products);
  var byDkd = {};
  (products || []).forEach(function(p) {
    var dkd = productDkdId(p);
    if (dkd) byDkd[String(dkd)] = p;
  });
  var result = { presence: {}, slIdToKeys: {}, slIds: [], keys: [] };
  if (!dkdIds.length) return result;

  for (var i = 0; i < dkdIds.length; i += 200) {
    var chunk = dkdIds.slice(i, i + 200);
    var m = await sb.from("core_product_sl_links")
      .select("dkd_shohin_id, sl_part_id, status")
      .eq("status", "active")
      .in("dkd_shohin_id", chunk);
    if (m.error) {
      console.warn("SL mapping lookup failed", m.error);
      continue;
    }
    (m.data || []).forEach(function(row) {
      var dkdId = row.dkd_shohin_id;
      var slId = row.sl_part_id;
      if (!dkdId || !slId) return;
      var product = byDkd[String(dkdId)] || null;
      productSlCacheKeys(product || { dkd_shohin_id: dkdId }).forEach(function(key) {
        result.presence[key] = true;
        if (result.keys.indexOf(key) < 0) result.keys.push(key);
        if (!result.slIdToKeys[slId]) {
          result.slIdToKeys[slId] = [];
          result.slIds.push(slId);
        }
        if (result.slIdToKeys[slId].indexOf(key) < 0) result.slIdToKeys[slId].push(key);
      });
    });
  }

  return result;
}

async function fetchLegacySlMappingMaps(products) {
  await fillProductLegacyPartIds(products);
  var partIds = productLegacyPartIds(products);
  var result = { presence: {}, slIdToKeys: {}, slIds: [], keys: [] };
  if (!partIds.length) return result;

  for (var i = 0; i < partIds.length; i += 200) {
    var chunk = partIds.slice(i, i + 200);
    var m = await sb.from("part_sl_mapping")
      .select("part_id, sl_part_id")
      .in("part_id", chunk);
    if (m.error) {
      console.warn("legacy SL mapping lookup failed", m.error);
      continue;
    }
    (m.data || []).forEach(function(row) {
      var partId = row.part_id;
      var slId = row.sl_part_id;
      if (!partId || !slId) return;
      var key = String(partId);
      result.presence[key] = true;
      if (result.keys.indexOf(key) < 0) result.keys.push(key);
      if (!result.slIdToKeys[slId]) {
        result.slIdToKeys[slId] = [];
        result.slIds.push(slId);
      }
      if (result.slIdToKeys[slId].indexOf(key) < 0) result.slIdToKeys[slId].push(key);
    });
  }
  return result;
}

async function fetchSlLabelAndImageMaps(mapping) {
  var result = { labels: {}, imageCounts: {}, thumbnails: {} };
  var keys = (mapping && mapping.keys) || [];
  var slIds = (mapping && mapping.slIds) || [];
  var slIdToKeys = (mapping && mapping.slIdToKeys) || {};

  var labelPromise = Promise.resolve();
  if (canSeePurchasePrice() && slIds.length) {
    labelPromise = (async function() {
      for (var j = 0; j < slIds.length; j += 200) {
        var labelChunk = slIds.slice(j, j + 200);
        var labels = await sb.from("sl_parts")
          .select("id, supplier_pn")
          .in("id", labelChunk);
        if (labels.error) {
          console.warn("SL label lookup failed", labels.error);
          continue;
        }
        (labels.data || []).forEach(function(row) {
          if (!row.id || !row.supplier_pn) return;
          (slIdToKeys[row.id] || []).forEach(function(key) {
            if (!result.labels[key]) result.labels[key] = [];
            if (result.labels[key].indexOf(row.supplier_pn) < 0) result.labels[key].push(row.supplier_pn);
          });
        });
      }
    })();
  }

  var imagePromise = (async function() {
    var dkdIds = keys.map(function(key) {
      var m = String(key || "").match(/^dkd:(\d+)$/);
      return m ? parseInt(m[1], 10) : null;
    }).filter(function(id, idx, arr) {
      return id && arr.indexOf(id) === idx;
    });
    for (var k = 0; k < dkdIds.length; k += 200) {
      var imageChunk = dkdIds.slice(k, k + 200);
      var imgs = await sb.from("core_product_images")
        .select("dkd_shohin_id, image_url, product_kind, image_origin, show_in_sales, show_in_production")
        .in("dkd_shohin_id", imageChunk)
        .order("sort_order")
        .order("created_at")
        .order("id");
      if (imgs.error) {
        console.warn("product image lookup failed", imgs.error);
        continue;
      }
      (imgs.data || []).forEach(function(img) {
        var kind = normalizeProductKind(img.product_kind || "rebuilt");
        if (img.product_kind && imageProductKindOptions().indexOf(kind) < 0) return;
        if (!imageContextMatches(img, "sales")) return;
        var key = "dkd:" + String(img.dkd_shohin_id || "");
        if (!key) return;
        result.imageCounts[key] = (result.imageCounts[key] || 0) + 1;
        if (!result.thumbnails[key]) result.thumbnails[key] = img.image_url;
      });
    }
  })();

  await Promise.all([labelPromise, imagePromise]);
  return result;
}

function productHasCatalogData(p) {
  if (!p) return false;
  if (p.has_catalog_spec) return true;
  if (p.has_catalog_source) return true;
  return productKindSummaryHasKind(productKindSummaryForProduct(p), "catalog_spec");
}

function productRebuiltComponentCount(p) {
  var key = productDkdId(p);
  var byKind = key ? productionComponentKindCountMap[key] : null;
  if (byKind && Object.prototype.hasOwnProperty.call(byKind, "rebuilt")) {
    return parseInt(byKind.rebuilt || 0, 10) || 0;
  }
  return 0;
}

function productSearchPriorityScore(p) {
  var score = 0;
  var rebuiltCount = productRebuiltComponentCount(p);
  if (rebuiltCount > 0) score += 200000 + Math.min(rebuiltCount, 999);
  if (productHasCatalogData(p)) score += 100000;
  return score;
}

function sortProductSearchRows(rows) {
  return (rows || []).slice().sort(function(a, b) {
    var sa = productSearchPriorityScore(a);
    var sb = productSearchPriorityScore(b);
    if (sb !== sa) return sb - sa;
    var ac = productComponentCount(a);
    var bc = productComponentCount(b);
    if (bc !== ac) return bc - ac;
    return String(a.manufacturer_part_number || a.genuine_part_number || "").localeCompare(String(b.manufacturer_part_number || b.genuine_part_number || ""), "ja", { numeric: true });
  });
}

function getFiltered() {
  var q = norm(document.getElementById("q").value.trim());
  return sortProductSearchRows(allProducts.filter(function(p) {
    var slNums = slPartLabelsForProduct(p);
    var partMatch = !q || [
      p.genuine_part_number, p.genuine_part_number_2,
      p.manufacturer_part_number, p.daiko_part_number,
      p.dks_shohin_cd, p.shohin_cd, p.gltek_part_number,
      p.pulley_assy_part_number,
      p.genuine_body_part_number, p.manufacturer_body_part_number,
      p.genuine_clutch_part_number, p.manufacturer_clutch_part_number
    ].concat(slNums).some(function(v){ return normalizedStartsWith(v, q); });
    var ms = partMatch;
    var mf = currentFilter.indexOf("cat:") === 0 ? (p.category_code || p.category) === currentFilter.slice(4) : true;
    return ms && mf;
  }));
}

function mergeObjectMap(target, source) {
  target = target || {};
  Object.keys(source || {}).forEach(function(key) {
    target[key] = source[key];
  });
  return target;
}

function mergeProductSearchRows(existingRows, addedRows) {
  var rows = (existingRows || []).slice();
  var seen = {};
  rows.forEach(function(row) {
    var key = productDkdId(row);
    if (key) seen[key] = true;
  });
  (addedRows || []).forEach(function(row) {
    var key = productDkdId(row);
    if (!key || seen[key]) return;
    seen[key] = true;
    rows.push(row);
  });
  return rows;
}

async function fetchCategoryProductPage(categoryFilter, offset, pageSize) {
  if (!categoryFilter) return { data: [], error: null, count: 0 };
  offset = Math.max(parseInt(offset || 0, 10) || 0, 0);
  pageSize = Math.max(parseInt(pageSize || SEARCH_INITIAL_LIMIT, 10) || SEARCH_INITIAL_LIMIT, 1);

  async function fetchByColumn(column) {
    var query = sb.from("core_products")
      .select(CORE_PRODUCT_FAST_SELECT, { count: "exact" })
      .eq(column, categoryFilter)
      .order("manufacturer_part_number", { ascending: true, nullsFirst: false })
      .order("genuine_part_number", { ascending: true, nullsFirst: false })
      .order("dkd_shohin_id", { ascending: true })
      .range(offset, offset + pageSize - 1);
    return await query;
  }

  var byCode = await fetchByColumn("category_code");
  if (byCode.error) return byCode;
  if ((byCode.count || 0) > 0 || (byCode.data || []).length > 0) {
    byCode.data = normalizeCoreProductFastRows(byCode.data || []);
    return byCode;
  }

  var byName = await fetchByColumn("category");
  if (!byName.error) byName.data = normalizeCoreProductFastRows(byName.data || []);
  return byName;
}

async function fetchCategoryProducts(categoryFilter, maxRows) {
  return await fetchCategoryProductPage(categoryFilter, 0, maxRows || SEARCH_FETCH_LIMIT);
}

async function fetchProductionOtherCategoryProducts(maxRows) {
  maxRows = maxRows || SEARCH_FETCH_LIMIT;
  var primaryCodes = productionPrimaryCategoryCodes();
  var notInValue = "(" + primaryCodes.join(",") + ")";
  var rows = [];
  var seen = {};

  function appendRows(sourceRows) {
    normalizeCoreProductFastRows(sourceRows || []).forEach(function(row) {
      var key = productDkdId(row);
      if (!key || seen[key]) return;
      if (!productionMatchesCategoryFilter(row)) return;
      seen[key] = true;
      rows.push(row);
    });
  }

  var byCode = await sb.from("core_products")
    .select(CORE_PRODUCT_FAST_SELECT)
    .not("category_code", "in", notInValue)
    .order("manufacturer_part_number", { ascending: true })
    .limit(Math.min(maxRows * 3, SEARCH_FETCH_LIMIT));
  if (byCode.error) return byCode;
  appendRows(byCode.data);

  if (rows.length < maxRows) {
    var byNull = await sb.from("core_products")
      .select(CORE_PRODUCT_FAST_SELECT)
      .is("category_code", null)
      .order("manufacturer_part_number", { ascending: true })
      .limit(Math.min((maxRows - rows.length) * 3, SEARCH_FETCH_LIMIT));
    if (byNull.error) return byNull;
    appendRows(byNull.data);
  }

  return { data: rows.slice(0, maxRows), error: null };
}

async function fetchSlProductsFromLoadedMap(maxRows) {
  maxRows = maxRows || productSearchLimit;
  var dkdIds = Object.keys(slPresenceMap || {}).concat(Object.keys(slPartsMap || {})).map(function(key) {
    var m = String(key || "").match(/^dkd:(\d+)$/);
    return m ? parseInt(m[1], 10) : null;
  }).filter(function(id) {
    return id && !isNaN(id);
  });
  dkdIds = Array.from(new Set(dkdIds));
  if (!dkdIds.length) return { data: [], error: null };

  var rows = [];
  var seen = {};
  for (var i = 0; i < dkdIds.length && rows.length < maxRows; i += 120) {
    var chunk = dkdIds.slice(i, i + 120);
    var r = await sb.from("core_products")
      .select(CORE_PRODUCT_FAST_SELECT)
      .in("dkd_shohin_id", chunk)
      .order("manufacturer_part_number", { ascending: true })
      .order("genuine_part_number", { ascending: true })
      .limit(maxRows);
    if (r.error) return r;
    normalizeCoreProductFastRows(r.data || []).forEach(function(row) {
      var key = String(row.dkd_shohin_id || row.id || "");
      if (!key || seen[key] || rows.length >= maxRows) return;
      seen[key] = true;
      rows.push(row);
    });
  }
  return { data: rows, error: null };
}

async function fetchSlProductsFromMapping(q, maxRows) {
  maxRows = maxRows || productSearchLimit;
  var mappings = await sb.from("core_product_sl_links")
    .select("dkd_shohin_id")
    .eq("status", "active")
    .not("dkd_shohin_id", "is", null)
    .limit(1000);
  if (mappings.error) {
    console.warn("SL mapping direct lookup failed; falling back to RPC", mappings.error);
    return await fetchSlProductsViaRpc(q, maxRows);
  }

  var dkdIds = uniqueTextValues((mappings.data || []).map(function(row) {
    return String(row.dkd_shohin_id || "").trim();
  })).map(function(id) {
    return parseInt(id, 10);
  }).filter(function(id) {
    return !isNaN(id);
  });
  if (!dkdIds.length) return await fetchSlProductsViaRpc(q, maxRows);

  var rows = [];
  var seen = {};
  for (var i = 0; i < dkdIds.length; i += 200) {
    var chunk = dkdIds.slice(i, i + 200);
    var r = await sb.from("core_product_search_view")
      .select("*")
      .in("dkd_shohin_id", chunk)
      .order("manufacturer_part_number", { ascending: true })
      .order("genuine_part_number", { ascending: true });
    if (r.error) {
      console.warn("SL product direct lookup failed; falling back to RPC", r.error);
      return await fetchSlProductsViaRpc(q, maxRows);
    }
    normalizeCoreProductFastRows(r.data || []).forEach(function(row) {
      var key = String(row.dkd_shohin_id || row.id || "");
      if (!key || seen[key]) return;
      seen[key] = true;
      row.has_sl_part = true;
      rows.push(row);
    });
  }

  if (!rows.length) {
    var fallback = await fetchSlProductsViaRpc(q, maxRows);
    if (!fallback.error && (fallback.data || []).length) return fallback;
  }

  var query = norm(String(q || "").trim());
  if (query) {
    rows = rows.filter(function(p) {
      var partMatch = [
        p.genuine_part_number, p.genuine_part_number_2,
        p.manufacturer_part_number, p.daiko_part_number,
        p.pulley_assy_part_number,
        p.genuine_body_part_number, p.manufacturer_body_part_number,
        p.genuine_clutch_part_number, p.manufacturer_clutch_part_number
      ].some(function(v){ return normalizedStartsWith(v, query); });
      return partMatch;
    });
  }

  return { data: rows.slice(0, maxRows), error: null };
}

async function fetchSlProductsViaRpc(q, maxRows) {
  var r = await sb.rpc("search_core_products", {
    search_text: q || null,
    category_filter: null,
    require_sl: true,
    max_rows: maxRows || productSearchLimit
  });
  if (r.error) return r;
  r.data = normalizeCoreProductFastRows(r.data || []);
  (r.data || []).forEach(function(row) {
    row.has_sl_part = true;
  });
  return r;
}

function normalizePartQuery(q) {
  return normalizeAsciiWidth(q)
    .toUpperCase()
    .replace(/[\u2010-\u2015\u2212\u30FC\uFF0D]/g, "-")
    .replace(/[-\s]/g, "");
}

function normalizedPartKey(value) {
  return normalizeAsciiWidth(value).toUpperCase().replace(/[^0-9A-Z]/g, "");
}

function uniqueTextValues(values) {
  var seen = {};
  var out = [];
  (values || []).forEach(function(value) {
    var text = String(value || "").trim();
    if (!text || seen[text]) return;
    seen[text] = true;
    out.push(text);
  });
  return out;
}

function mitsubishiCatalogPartKeyVariants(partNumber) {
  var key = normalizedPartKey(partNumber);
  var variants = [key];
  var m = key.match(/^([A-Z])(\d{1,2})([A-Z].*)$/);
  if (m) variants.push(m[1] + m[2].padStart(3, "0") + m[3]);
  return uniqueTextValues(variants);
}

function componentAssyLookupKeys(product) {
  var key = normalizedPartKey(product && product.manufacturer_part_number);
  if (!key) return [];
  var manufacturer = String(product && product.manufacturer || "").toUpperCase();
  if (manufacturer === "MITSUBISHI") return mitsubishiCatalogPartKeyVariants(key);
  return [key];
}

function normalizeCoreProductFastRows(rows) {
  return (rows || []).map(function(row) {
    var p = Object.assign({}, row);
    p.id = p.dkd_shohin_id;
    p.shohin_cd = p.shohin_cd || p.dks_shohin_cd || "";
    p.category = p.category || p.category_code || "";
    p.category_ja = p.category_ja || "";
    p.category_en = p.category_en || "";
    p.category_zh = p.category_zh || "";
    p.dks_relation_type = p.dks_relation_type || "";
    p.dks_match_basis = p.dks_match_basis || "";
    return p;
  });
}

async function fetchSourceAliasProducts(q) {
  var normalized = normalizePartQuery(q);
  if (!normalized) return { data: [] };

  var alias = await sb.rpc("core_product_source_alias_matches", {
    normalized_q: normalized
  });
  if (alias.error || !(alias.data || []).length) return alias.error ? alias : { data: [] };

  var ids = (alias.data || []).map(function(row) {
    return row.dkd_shohin_id;
  }).filter(function(id) {
    return id !== null && id !== undefined && id !== "";
  });
  if (!ids.length) return { data: [] };

  var r = await sb.from("core_products")
    .select(CORE_PRODUCT_FAST_SELECT)
    .in("dkd_shohin_id", ids)
    .order("manufacturer_part_number")
    .order("genuine_part_number")
    .limit(productSearchLimit);
  if (!r.error) r.data = normalizeCoreProductFastRows(r.data || []);
  return r;
}

async function fetchSlPartProducts(q, categoryFilter, maxRows) {
  var raw = normalizeAsciiWidth(String(q || "").trim());
  var normalized = normalizePartQuery(raw);
  if (!raw && !normalized) return { data: [] };
  maxRows = maxRows || productSearchLimit;

  var slRows = [];
  var seenSlRow = {};
  async function appendSlRows(pattern) {
    var r = await sb.from("sl_parts")
      .select("id, supplier_pn")
      .ilike("supplier_pn", pattern)
      .limit(1000);
    if (r.error) return r;
    (r.data || []).forEach(function(row) {
      var key = String(row.id || "");
      if (!key || seenSlRow[key]) return;
      seenSlRow[key] = true;
      slRows.push(row);
    });
    return r;
  }
  var prefix = await appendSlRows(raw + "%");
  if (prefix.error) return prefix;
  if (!slRows.length && normalized && normalized.length >= 3) {
    var loosePrefix = await appendSlRows(normalized.slice(0, 3) + "%");
    if (loosePrefix.error) return loosePrefix;
  }
  if (raw.length >= 3) {
    var contains = await appendSlRows("%" + raw + "%");
    if (contains.error) return contains;
  }

  var slIds = [];
  slRows.forEach(function(row) {
    var label = row.supplier_pn || "";
    if (!label) return;
    var matched = normalizedStartsWith(label, raw) ||
      normalizedContains(label, raw) ||
      (normalized && (normalizedStartsWith(label, normalized) || normalizedContains(label, normalized)));
    if (matched && row.id) slIds.push(row.id);
  });
  slIds = Array.from(new Set(slIds));
  if (!slIds.length) return { data: [] };

  var dkdIds = [];
  var seenDkd = {};
  for (var i = 0; i < slIds.length; i += 200) {
    var slChunk = slIds.slice(i, i + 200);
    var links = await sb.from("core_product_sl_links")
      .select("dkd_shohin_id, sl_part_id")
      .eq("status", "active")
      .in("sl_part_id", slChunk);
    if (links.error) return links;
    (links.data || []).forEach(function(link) {
      var id = parseInt(link.dkd_shohin_id, 10);
      if (isNaN(id) || seenDkd[id]) return;
      seenDkd[id] = true;
      dkdIds.push(id);
    });
  }
  if (!dkdIds.length) return { data: [] };

  var rows = [];
  var seenRow = {};
  for (var j = 0; j < dkdIds.length && rows.length < maxRows; j += 200) {
    var dkdChunk = dkdIds.slice(j, j + 200);
    var query = sb.from("core_products")
      .select(CORE_PRODUCT_FAST_SELECT)
      .in("dkd_shohin_id", dkdChunk)
      .order("manufacturer_part_number", { ascending: true })
      .order("genuine_part_number", { ascending: true });
    if (categoryFilter) query = query.eq("category_code", categoryFilter);
    var r = await query;
    if (r.error) return r;
    normalizeCoreProductFastRows(r.data || []).forEach(function(row) {
      var key = String(row.dkd_shohin_id || row.id || "");
      if (!key || seenRow[key] || rows.length >= maxRows) return;
      seenRow[key] = true;
      row.has_sl_part = true;
      rows.push(row);
    });
  }
  return { data: rows, error: null };
}

async function fetchCoreProductMasterMatches(q, categoryFilter, maxRows) {
  var normalized = normalizePartQuery(q);
  var raw = String(q || "").trim();
  if (!normalized && !raw) return { data: [] };
  maxRows = maxRows || productSearchLimit;
  var normalizedFields = [
    "normalized_genuine_part_number",
    "normalized_genuine_part_number_2",
    "normalized_manufacturer_part_number",
    "normalized_pulley_assy_part_number",
    "normalized_daiko_part_number",
    "normalized_genuine_body_part_number",
    "normalized_manufacturer_body_part_number",
    "normalized_genuine_clutch_part_number",
    "normalized_manufacturer_clutch_part_number"
  ];
  var directExactFields = [
    "dks_shohin_cd",
    "gltek_part_number"
  ];

  async function runCoreProductQuery(orParts, limitMultiplier) {
    if (!orParts.length) return { data: [] };
    var coreQuery = sb.from("core_products")
      .select(CORE_PRODUCT_FAST_SELECT)
      .or(orParts.join(","))
      .order("manufacturer_part_number", { ascending: true })
      .order("genuine_part_number", { ascending: true })
      .limit(Math.max(maxRows * (limitMultiplier || 2), maxRows));
    if (categoryFilter) coreQuery = coreQuery.eq("category_code", categoryFilter);
    var result = await coreQuery;
    if (result.error) return result;
    result.data = normalizeCoreProductFastRows(result.data || []).slice(0, maxRows);
    return result;
  }

  // Equality operators remain indexable under the current RLS policies; prefix LIKE does not.
  var exactParts = normalized ? normalizedFields.map(function(column) {
    return column + ".eq." + normalized;
  }).concat(directExactFields.map(function(column) {
    return column + ".eq." + normalized;
  })) : [];
  var exact = await runCoreProductQuery(exactParts, 1);
  if (exact.error || (exact.data || []).length) return exact;

  var prefixParts = normalized ? normalizedFields.map(function(column) {
    return column + ".like." + normalized + "%";
  }) : [];

  var fast = normalized ? await sb.rpc("search_core_products_by_prefix_fast", {
    search_prefix: normalized,
    category_filter: categoryFilter || null,
    max_rows: maxRows
  }) : { data: [] };
  if (fast.error) {
    console.warn("Fast core product prefix search failed; falling back to direct lookup", fast.error);
    fast = await runCoreProductQuery(prefixParts, 2);
  } else {
    fast.data = normalizeCoreProductFastRows(fast.data || []).slice(0, maxRows);
  }
  if (fast.error || (fast.data || []).length) return fast;

  var orParts = normalized ? normalizedFields.map(function(column) {
    return column + ".ilike.%" + normalized + "%";
  }) : [];
  return await runCoreProductQuery(orParts, 2);
}

async function runProductSearch(options) {
  options = options || {};
  if (options.resetLimit) productSearchLimit = SEARCH_INITIAL_LIMIT;
  var q = document.getElementById("q").value.trim();
  if (currentFilter === "production") currentFilter = "all";
  if (q && options.resetFilter && currentFilter !== "all") {
    currentFilter = "all";
    syncSearchFilterControls();
  }
  var categoryFilter = currentFilter.indexOf("cat:") === 0 ? currentFilter.slice(4) : null;
  var categoryPageKey = !q && categoryFilter ? "category:" + categoryFilter : "";
  var appendCategoryPage = !!(categoryPageKey && options.append && productSearchPageKey === categoryPageKey);
  var categoryPageSize = 0;
  if (categoryPageKey && !appendCategoryPage) {
    productSearchFetchedCount = 0;
    productSearchTotalCount = null;
    productSearchHasMore = false;
    productSearchPageKey = categoryPageKey;
  } else if (!categoryPageKey) {
    productSearchTotalCount = null;
    productSearchHasMore = false;
    productSearchPageKey = "";
  }
  searchSlOnly = false;
  var requireSl = false;
  var list = document.getElementById("list");
  var seq = ++searchRequestSeq;
  productAuxSeq++;

  if (!q && currentFilter === "all" && !requireSl) {
    allProducts = [];
    productSearchFetchedCount = 0;
    productSearchTotalCount = null;
    productSearchHasMore = false;
    productSearchPageKey = "";
    imageCountMap = {};
    imageThumbnailMap = {};
    productionImageCountMap = {};
    slPartsMap = {};
    slPresenceMap = {};
    componentUsageCountMap = {};
    productionComponentKindCountMap = {};
    coreStockQtyMap = {};
    kikanCompatibleMap = {};
    productVariantSummaryMap = {};
    renderCategoryChips();
    closePanel();
    render();
    return;
  }

  document.getElementById("count-bar").textContent = t("loading");
  list.innerHTML = "<div class='loading'>" + t("loading") + "</div>";

  var r;
  if (!q && categoryFilter) {
    var categoryOffset = appendCategoryPage ? productSearchFetchedCount : 0;
    categoryPageSize = appendCategoryPage
      ? Math.max(productSearchLimit - productSearchFetchedCount, 1)
      : productSearchLimit;
    r = await fetchCategoryProductPage(categoryFilter, categoryOffset, categoryPageSize);
  } else if (q) {
    r = await fetchCoreProductMasterMatches(q, categoryFilter, productSearchLimit);
  } else {
    r = await sb.rpc("search_core_products", {
        search_text: q || null,
        category_filter: categoryFilter,
        require_sl: requireSl,
        max_rows: productSearchLimit
      });
  }
  if (seq !== searchRequestSeq) return;
  if (r.error) {
    console.warn("search_core_products failed", r.error);
    allProducts = [];
    productSearchFetchedCount = 0;
    productSearchTotalCount = null;
    productSearchHasMore = false;
    closePanel();
    document.getElementById("count-bar").textContent = "";
    var moreWrap = document.getElementById("load-more-wrap");
    if (moreWrap) setCspStyle(moreWrap, "display", "none");
    list.innerHTML = "<div class='empty'>" + t("no_results") + "</div>";
    return;
  }
  // Keep fallback reads sequential. Speculative requests can outlive the result and delay detail views.
  if (q && !(r.data || []).length) {
    var aliasResult = await fetchSourceAliasProducts(q);
    if (seq !== searchRequestSeq) return;
    if (!aliasResult.error && (aliasResult.data || []).length) {
      r = aliasResult;
    } else if (aliasResult.error) {
      console.warn("source alias search failed", aliasResult.error);
    }
  }
  if (q && !(r.data || []).length) {
    var slResult = await fetchSlPartProducts(q, categoryFilter, productSearchLimit);
    if (seq !== searchRequestSeq) return;
    if (!slResult.error && (slResult.data || []).length) {
      r = slResult;
    } else if (slResult.error) {
      console.warn("SL part search failed", slResult.error);
    }
  }
  var rawProducts = r.data || [];
  var auxiliaryProducts;
  if (categoryPageKey) {
    var visiblePageProducts = filterVisibleProducts(rawProducts);
    if (appendCategoryPage) {
      allProducts = mergeProductSearchRows(allProducts, visiblePageProducts);
      productSearchFetchedCount += rawProducts.length;
      auxiliaryProducts = visiblePageProducts;
    } else {
      allProducts = visiblePageProducts;
      productSearchFetchedCount = rawProducts.length;
      auxiliaryProducts = allProducts;
    }
    productSearchTotalCount = typeof r.count === "number" ? r.count : null;
    productSearchHasMore = productSearchTotalCount !== null
      ? productSearchFetchedCount < productSearchTotalCount
      : rawProducts.length >= categoryPageSize;
  } else {
    productSearchFetchedCount = rawProducts.length;
    productSearchHasMore = productSearchFetchedCount >= productSearchLimit && productSearchLimit < SEARCH_FETCH_LIMIT;
    allProducts = filterVisibleProducts(rawProducts);
    auxiliaryProducts = allProducts;
  }
  if (!appendCategoryPage) {
    imageCountMap = {};
    imageThumbnailMap = {};
    productionImageCountMap = {};
    slPartsMap = {};
    slPresenceMap = {};
    componentUsageCountMap = {};
    productionComponentKindCountMap = {};
    coreStockQtyMap = {};
    kikanCompatibleMap = {};
    productVariantSummaryMap = {};
  }
  applyCachedSearchAuxiliaryMaps(auxiliaryProducts);
  renderCategoryChips();
  render();
  if (!options.preserveSelection) {
    syncFirstSearchResultDetail();
  }
  if (options.logActivity) {
    logUserActivity("search", {
      screen: "search",
      action: "product_search",
      target_type: "search",
      target_desc: q || categoryFilter || currentFilter || "-",
      metadata: {
        query: q || "",
        filter: currentFilter,
        category_filter: categoryFilter,
        result_count: allProducts.length,
        limit: productSearchLimit,
        source: options.source || null
      },
      throttleKey: "product:" + (q || "") + ":" + currentFilter + ":" + productSearchLimit,
      throttleMs: 3000
    });
  }
  scheduleProductSearchEnrichment(seq, auxiliaryProducts.slice(), {
    append: appendCategoryPage,
    preserveSelection: !!options.preserveSelection
  });
}

function waitForProductSearchEnrichmentDelay(ms) {
  return new Promise(function(resolve) { setTimeout(resolve, ms); });
}

function isProductSearchEnrichmentStale(seq, auxSeq) {
  return seq !== searchRequestSeq || auxSeq !== productAuxSeq || !isScreenActive("search");
}

async function waitForProductSearchDetailLoads(seq, auxSeq) {
  for (var attempt = 0; attempt < 3; attempt++) {
    if (isProductSearchEnrichmentStale(seq, auxSeq)) return false;
    var detailSeq = detailSecondaryRequestSeq;
    var detailPromise = productSearchDetailReadyPromise;
    await detailPromise;
    await waitForProductSearchEnrichmentDelay(300);
    if (isProductSearchEnrichmentStale(seq, auxSeq)) return false;
    if (detailSeq === detailSecondaryRequestSeq && detailPromise === productSearchDetailReadyPromise) return true;
  }
  return false;
}

function scheduleProductSearchEnrichment(seq, products, options) {
  var auxSeq = productAuxSeq;
  runDeferredProductSearchEnrichment(seq, auxSeq, products, options).catch(function(error) {
    console.warn("deferred product search enrichment failed", error);
  });
}

async function runDeferredProductSearchEnrichment(seq, auxSeq, products, options) {
  options = options || {};
  var lookupProducts = (products || []).slice(0, SEARCH_RENDER_LIMIT);
  if (!lookupProducts.length) return;
  if (!await waitForProductSearchDetailLoads(seq, auxSeq)) return;

  var cardFlags = await fetchProductSearchCardFlags(lookupProducts);
  if (isProductSearchEnrichmentStale(seq, auxSeq)) return;
  applyProductSearchCardFlags(cardFlags, lookupProducts);
  render();

  if (!await waitForProductSearchDetailLoads(seq, auxSeq)) return;
  var salesImageInfo = await fetchProductImageCountMapForContext(lookupProducts, "sales");
  if (isProductSearchEnrichmentStale(seq, auxSeq)) return;
  applyProductImageCountMapForContext(lookupProducts, salesImageInfo, "sales");
  preloadProductSearchThumbnails(lookupProducts);
  render();

  if (!await waitForProductSearchDetailLoads(seq, auxSeq)) return;
  await loadProductSearchAuxiliaryData(seq, lookupProducts, { append: !!options.append });
}

async function fetchComponentUsageCountMap(products) {
  var map = {};
  var ids = (products || []).map(function(p) {
    return productDkdId(p);
  }).filter(function(id) {
    return id !== null && id !== undefined && id !== "";
  });
  var uniqueIds = Array.from(new Set(ids.map(function(id) { return parseInt(id, 10); }))).filter(function(id) {
    return !isNaN(id);
  });
  if (!uniqueIds.length) return map;
  for (var i = 0; i < uniqueIds.length; i += 200) {
    var chunk = uniqueIds.slice(i, i + 200);
    var r = await sb.from("parallel_component_search_targets")
      .select("dkd_shohin_id, component_usage_count")
      .in("dkd_shohin_id", chunk)
      .gt("component_usage_count", 0);
    if (r.error) {
      console.warn("component usage count lookup failed", r.error);
      return map;
    }
    (r.data || []).forEach(function(row) {
      map[String(row.dkd_shohin_id)] = parseInt(row.component_usage_count || 0, 10);
    });
  }
  var fallbackMap = await fetchMitsubishiComponentUsageCountFallback(products, map);
  Object.keys(fallbackMap).forEach(function(key) {
    if (!map[key]) map[key] = fallbackMap[key];
  });
  return map;
}

async function fetchMitsubishiComponentUsageCountFallback(products, baseMap) {
  var map = {};
  var keyToProductIds = {};
  var lookupKeys = [];
  (products || []).forEach(function(p) {
    var manufacturer = String(p && p.manufacturer || "").toUpperCase();
    if (manufacturer !== "MITSUBISHI") return;
    var id = productDkdId(p);
    if (!id || (baseMap && baseMap[id] > 0)) return;
    componentAssyLookupKeys(p).forEach(function(key) {
      if (!key) return;
      if (!keyToProductIds[key]) {
        keyToProductIds[key] = [];
        lookupKeys.push(key);
      }
      keyToProductIds[key].push(id);
    });
  });
  lookupKeys = uniqueTextValues(lookupKeys);
  if (!lookupKeys.length) return map;
  var countByKey = {};
  for (var i = 0; i < lookupKeys.length; i += 60) {
    var chunk = lookupKeys.slice(i, i + 60);
    var r = await sb.from("assembly_component_usage_details")
      .select("normalized_assy_manufacturer_part_number")
      .eq("assy_manufacturer", "MITSUBISHI")
      .in("normalized_assy_manufacturer_part_number", chunk);
    if (r.error) {
      console.warn("mitsubishi component count fallback failed", r.error);
      return map;
    }
    (r.data || []).forEach(function(row) {
      var key = String(row.normalized_assy_manufacturer_part_number || "");
      countByKey[key] = (countByKey[key] || 0) + 1;
    });
  }
  Object.keys(countByKey).forEach(function(key) {
    (keyToProductIds[key] || []).forEach(function(id) {
      map[id] = Math.max(map[id] || 0, countByKey[key] || 0);
    });
  });
  return map;
}

async function fetchCoreStockQtyMap(products) {
  var map = {};
  var ids = (products || []).map(function(p) {
    return productDkdId(p);
  }).filter(function(id) {
    return id !== null && id !== undefined && id !== "";
  });
  var uniqueIds = Array.from(new Set(ids.map(function(id) { return parseInt(id, 10); }))).filter(function(id) {
    return !isNaN(id);
  });
  if (!uniqueIds.length) return map;
  for (var i = 0; i < uniqueIds.length; i += 200) {
    var chunk = uniqueIds.slice(i, i + 200);
    var r = await sb.from("production_core_list_entries")
      .select("dkd_shohin_id, quantity")
      .in("dkd_shohin_id", chunk);
    if (r.error) {
      console.warn("core stock count lookup failed", r.error);
      return map;
    }
    (r.data || []).forEach(function(row) {
      var key = String(row.dkd_shohin_id);
      map[key] = (map[key] || 0) + (parseInt(row.quantity || 0, 10) || 0);
    });
  }
  return map;
}

async function fetchKikanCompatibleMap(products, isStale) {
  var map = {};
  var rows = (products || []).slice(0, KIKAN_FLAG_LOOKUP_LIMIT);
  if (isStale && isStale()) return map;
  for (var i = 0; i < rows.length; i += 4) {
    if (isStale && isStale()) return map;
    var chunk = rows.slice(i, i + 4);
    var results = await Promise.all(chunk.map(hasDisplayableKikanCompatibleParts));
    if (isStale && isStale()) return map;
    chunk.forEach(function(p, idx) {
      var key = productKikanKey(p);
      kikanCompatibleFlagCache[key] = !!results[idx];
      if (results[idx]) {
        map[key] = true;
        p.has_kikan_compatible = true;
      } else {
        delete kikanCompatibleMap[key];
        p.has_kikan_compatible = false;
      }
    });
  }
  return map;
}

async function enrichProductsWithKikanFlags(products) {
  var rows = (products || []).slice(0, KIKAN_FLAG_LOOKUP_LIMIT);
  var map = {};
  rows.forEach(function(p) {
    p.has_kikan_compatible = false;
  });
  var rpcResult = await fetchKikanRpcFlagMap(rows);
  if (rpcResult && rpcResult.ok) {
    map = rpcResult.map || {};
  } else {
    map = await fetchKikanCompatibleMap(rows);
  }
  rows.forEach(function(p) {
    var key = productKikanKey(p);
    p.has_kikan_compatible = !!map[key];
  });
  return map;
}

async function fetchKikanRpcFlagMap(products) {
  var map = {};
  var payload = (products || []).slice(0, KIKAN_FLAG_LOOKUP_LIMIT).map(function(p) {
    return {
      dkd_shohin_id: productDkdId(p) || null,
      manufacturer: p.manufacturer || null,
      manufacturer_part_number: p.manufacturer_part_number || null,
      genuine_part_number: p.genuine_part_number || null
    };
  }).filter(function(p) {
    return p.dkd_shohin_id !== null && p.dkd_shohin_id !== undefined && p.dkd_shohin_id !== "";
  });
  if (!payload.length) return { ok: true, map: map };
  var r = await sb.rpc("get_kikan_compatible_flags", {
    target_products: payload
  });
  if (r.error) {
    console.warn("get_kikan_compatible_flags failed", r.error);
    return { ok: false, map: map };
  }
  (r.data || []).forEach(function(row) {
    var key = "dkd:" + String(row.dkd_shohin_id || "");
    if (row.has_compatible) {
      kikanCompatibleFlagCache[key] = true;
      map[key] = true;
    }
  });
  return { ok: true, map: map };
}

async function fetchKikanGroupMemberFlagMap(products) {
  var map = {};
  var ids = (products || []).map(function(p) {
    return parseInt(productDkdId(p), 10);
  }).filter(function(id) {
    return !isNaN(id);
  });
  var uniqueIds = Array.from(new Set(ids));
  if (!uniqueIds.length) return map;
  var first = await sb.from("kikan_group_members")
    .select("kikan_group_id, dkd_gokan_id")
    .in("dkd_gokan_id", uniqueIds);
  if (first.error) {
    console.warn("kikan group flag lookup failed", first.error);
    return map;
  }
  var groupIds = Array.from(new Set((first.data || []).map(function(row) {
    return row.kikan_group_id;
  }).filter(function(id) {
    return id !== null && id !== undefined && id !== "";
  })));
  if (!groupIds.length) return map;
  var second = await sb.from("kikan_group_members")
    .select("kikan_group_id, dkd_gokan_id")
    .in("kikan_group_id", groupIds);
  if (second.error) {
    console.warn("kikan group member count lookup failed", second.error);
    return map;
  }
  var membersByGroup = {};
  (second.data || []).forEach(function(row) {
    var gid = String(row.kikan_group_id);
    if (!membersByGroup[gid]) membersByGroup[gid] = {};
    membersByGroup[gid][String(row.dkd_gokan_id)] = true;
  });
  (first.data || []).forEach(function(row) {
    var gid = String(row.kikan_group_id);
    var target = String(row.dkd_gokan_id);
    var members = Object.keys(membersByGroup[gid] || {});
    if (members.some(function(memberId) { return memberId !== target; })) {
      map["dkd:" + target] = true;
    }
  });
  return map;
}

async function loadProductSearchAuxiliaryData(seq, products, options) {
  options = options || {};
  var auxSeq = productAuxSeq;
  var lookupProducts = (products || []).slice(0, SEARCH_RENDER_LIMIT);
  function isStale() {
    return seq !== searchRequestSeq || auxSeq !== productAuxSeq;
  }
  var shouldLoadKikanFlags = customerCanShowCompatibleParts();
  var fast = await Promise.all([
    canSeeComponentInfo() ? fetchComponentUsageCountMap(lookupProducts) : Promise.resolve({}),
    canSeeCoreStockInfo() ? fetchCoreStockQtyMap(lookupProducts) : Promise.resolve({}),
    fetchProductVariantSummaryMap(lookupProducts),
    canSeeComponentInfo() ? fetchProductionPartRegistrationCountMap(lookupProducts) : Promise.resolve({ total: {}, byKind: {} }),
    shouldLoadKikanFlags ? fetchKikanCompatibleMap(lookupProducts, isStale) : Promise.resolve({})
  ]);
  if (isStale()) return;
  var nextComponentCounts = fast[0] || {};
  var nextCoreStock = fast[1] || {};
  var nextVariantSummary = fast[2] || {};
  var productionCounts = fast[3] || {};
  if (options.append) {
    componentUsageCountMap = mergeObjectMap(componentUsageCountMap, nextComponentCounts);
    coreStockQtyMap = mergeObjectMap(coreStockQtyMap, nextCoreStock);
    productVariantSummaryMap = mergeObjectMap(productVariantSummaryMap, nextVariantSummary);
    productionComponentKindCountMap = mergeObjectMap(productionComponentKindCountMap, productionCounts.byKind || {});
  } else {
    componentUsageCountMap = nextComponentCounts;
    coreStockQtyMap = nextCoreStock;
    productVariantSummaryMap = nextVariantSummary;
    productionComponentKindCountMap = productionCounts.byKind || {};
  }
  var kikanFlags = fast[4] || {};
  Object.keys(kikanFlags).forEach(function(key) {
    if (kikanFlags[key]) kikanCompatibleMap[key] = true;
  });
  Object.keys(productVariantSummaryMap).forEach(function(key) {
    productVariantSummaryCache[key] = productVariantSummaryMap[key];
  });
  lookupProducts.forEach(function(p) {
    var key = String(p && (p.dkd_shohin_id || p.id || "") || "");
    if (key && Object.prototype.hasOwnProperty.call(componentUsageCountMap, key)) {
      p.component_count = componentUsageCountMap[key];
    }
    if (shouldLoadKikanFlags) {
      var kikanKey = productKikanKey(p);
      var hasKikan = !!kikanFlags[kikanKey];
      p.has_kikan_compatible = hasKikan;
      if (hasKikan) {
        kikanCompatibleMap[kikanKey] = true;
      } else {
        delete kikanCompatibleMap[kikanKey];
      }
    }
  });
  render();
}

function productDkdId(p) {
  return String(p && (p.dkd_shohin_id || p.id || p.dkd_gokan_id || "") || "");
}

function productKikanKey(p) {
  return "dkd:" + productDkdId(p);
}

function hasProductKikanCompatible(p) {
  var key = productKikanKey(p);
  return !!(p && p.has_kikan_compatible) ||
    !!kikanCompatibleMap[key] ||
    !!kikanCompatibleFlagCache[key];
}

function productComponentCount(p) {
  var key = String(p && (p.dkd_shohin_id || p.id || "") || "");
  if (key && Object.prototype.hasOwnProperty.call(componentUsageCountMap, key)) {
    return parseInt(componentUsageCountMap[key] || 0, 10) || 0;
  }
  return parseInt(p && (p.component_usage_count || p.component_count || p.component_count_total || 0), 10) || 0;
}

async function loadComponentUsageCounts(products) {
  componentUsageCountMap = {};
  var ids = (products || []).map(function(p) {
    return p.dkd_shohin_id || p.id;
  }).filter(function(id) {
    return id !== null && id !== undefined && id !== "";
  });
  if (!ids.length) return;

  var uniqueIds = Array.from(new Set(ids.map(function(id) { return parseInt(id, 10); }))).filter(function(id) {
    return !isNaN(id);
  });
  if (!uniqueIds.length) return;

  for (var i = 0; i < uniqueIds.length; i += 200) {
    var chunk = uniqueIds.slice(i, i + 200);
    var r = await sb.from("parallel_component_search_targets")
      .select("dkd_shohin_id, component_usage_count")
      .in("dkd_shohin_id", chunk)
      .gt("component_usage_count", 0);
    if (r.error) {
      console.warn("component usage count lookup failed", r.error);
      return;
    }
    (r.data || []).forEach(function(row) {
      componentUsageCountMap[String(row.dkd_shohin_id)] = parseInt(row.component_usage_count || 0, 10);
    });
  }
}

async function loadCoreStockQtyCounts(products) {
  coreStockQtyMap = {};
  var ids = (products || []).map(function(p) {
    return p.dkd_shohin_id || p.id;
  }).filter(function(id) {
    return id !== null && id !== undefined && id !== "";
  });
  var uniqueIds = Array.from(new Set(ids.map(function(id) { return parseInt(id, 10); }))).filter(function(id) {
    return !isNaN(id);
  });
  if (!uniqueIds.length) return;
  for (var i = 0; i < uniqueIds.length; i += 200) {
    var chunk = uniqueIds.slice(i, i + 200);
    var r = await sb.from("production_core_list_entries")
      .select("dkd_shohin_id, quantity")
      .in("dkd_shohin_id", chunk);
    if (r.error) {
      console.warn("core stock count lookup failed", r.error);
      return;
    }
    (r.data || []).forEach(function(row) {
      var key = String(row.dkd_shohin_id);
      coreStockQtyMap[key] = (coreStockQtyMap[key] || 0) + (parseInt(row.quantity || 0, 10) || 0);
    });
  }
}

async function loadKikanCompatibleFlags(products) {
  kikanCompatibleMap = {};
  var rows = products || [];
  for (var i = 0; i < rows.length; i += 8) {
    var chunk = rows.slice(i, i + 8);
    var results = await Promise.all(chunk.map(hasDisplayableKikanCompatibleParts));
    chunk.forEach(function(p, idx) {
      if (results[idx]) kikanCompatibleMap[productKikanKey(p)] = true;
    });
  }
}

async function hasDisplayableKikanCompatibleParts(product) {
  var targetId = parseInt(product && (product.dkd_shohin_id || product.id), 10);
  if (isNaN(targetId)) return false;
  var r = await sb.rpc("get_kikan_compatible_parts", {
    target_dkd_shohin_id: targetId,
    target_manufacturer: product ? (product.manufacturer || null) : null,
    target_manufacturer_part_number: product ? (product.manufacturer_part_number || null) : null,
    target_genuine_part_number: product ? (product.genuine_part_number || null) : null
  });
  if (r.error) {
    console.warn("get_kikan_compatible_parts flag lookup failed", r.error);
    return false;
  }

  var parts_list = r.data || [];
  if (product && (product.category_code || product.category)) {
    var currentCategory = product.category_code || product.category;
    parts_list = parts_list.filter(function(p) {
      var cat = p.category_code || p.category || "";
      return !cat || cat === currentCategory || cat === "unclassified_assy" || cat === "other_assy";
    });
  }

  parts_list = filterVisibleProducts(parts_list);
  parts_list = parts_list.filter(function(p) {
    if (String(p.dkd_shohin_id) === String(targetId)) return false;
    return true;
  });
  return parts_list.length > 0;
}

function render() {
  var q    = document.getElementById("q").value.trim();
  var list = document.getElementById("list");
  var moreWrap = document.getElementById("load-more-wrap");
  if (!q && currentFilter === "all" && !searchSlOnly) {
    document.getElementById("count-bar").textContent = t("hint_search");
    list.innerHTML = "<div class='empty'>" + t("hint_search") + "</div>";
    if (moreWrap) setCspStyle(moreWrap, "display", "none");
    return;
  }
  var items = getFiltered();
  if (items.length === 0) {
    list.innerHTML = "<div class='empty'>" + t("no_results") + "</div>";
    if (moreWrap) setCspStyle(moreWrap, "display", productSearchHasMore ? "block" : "none");
    return;
  }
  var visibleItems = items;
  var countText = productSearchTotalCount !== null
    ? tf("search_count_loaded", { loaded: items.length, total: productSearchTotalCount })
    : items.length + " 件表示";
  if (productSearchTotalCount === null && productSearchFetchedCount >= productSearchLimit) {
    countText += " - " + productSearchLimit + " 件まで取得";
    if (productSearchLimit >= SEARCH_FETCH_LIMIT) {
      countText += "。品番で絞り込んでください";
    }
  }
  document.getElementById("count-bar").textContent = countText;
  if (moreWrap) setCspStyle(moreWrap, "display", productSearchHasMore ? "block" : "none");
  var html = "";
  visibleItems.forEach(function(p, idx) {
    var cnt   = getProductImageCount(p);
    var slNums = slPartLabelsForProduct(p);
    var hasSL  = productHasSlPart(p, slNums);
    var hasKikan = hasProductKikanCompatible(p);
    var kindSummary = productKindSummaryForProduct(p);
    var hasCatalogSpec = productHasCatalogData(p);
    var sel   = (currentProduct && currentProduct.id===p.id) ? " selected" : "";
    html += "<div class='card"+sel+"' data-id='"+p.id+"' data-result-index='"+idx+"'><div class='card-top'>";
    html += "<div class='card-media'>";
    html += "<div class='card-thumb card-thumb-icon " + (cnt > 0 ? "has-image" : "no-image") + "'>&#x1F5BC;<span>" + esc(cnt > 0 ? t("image_has") : t("image_none_short")) + "</span></div>";
    if (hasCatalogSpec) html += "<div class='card-media-catalog'><span class='badge-catalog'>" + esc(t("product_kind_catalog_spec")) + "</span></div>";
    html += "</div>";
    html += "<div class='card-left'>";
    html += "<div class='card-pn card-pn-primary'>"+esc(p.genuine_part_number||p.manufacturer_part_number||"-")+"</div>";
    html += "<div class='card-name'>"+esc(productCategoryLabel(p))+"</div>";
    if (p.genuine_part_number_2) html += "<div class='card-sub'>純正2: "+esc(p.genuine_part_number_2)+"</div>";
    html += renderProductKindPills(kindSummary, { compact: true });
    html += renderResultBadgeSlots({
      className: "badges card-badges-inline",
      hasCatalogSpec: false,
      hasSL: hasSL,
      hasKikan: hasKikan,
      imageCount: cnt,
      hideWhenEmpty: true
    });
    if (p.manufacturer || p.manufacturer_part_number) {
      html += "<div class='card-mfr'>";
      if (p.manufacturer) html += esc(p.manufacturer);
      if (p.manufacturer && p.manufacturer_part_number) html += " / ";
      if (p.manufacturer_part_number) html += "<span data-dcats-inline-style='s-7b8c3df56487'>"+esc(p.manufacturer_part_number)+"</span>";
      html += "</div>";
    }
    if (hasSL && slNums.length) html += "<div class='card-sl'>SL: "+esc(slNums[0])+(slNums.length>1?" 他":"")+"</div>";
    html += "</div>";
    html += "</div></div>";
  });
  list.innerHTML = html;
}

// =============================================
// 詳細パネル
// =============================================
function focusSearchResultIndex(index) {
  if (index === null || index === undefined || index < 0) return;
  requestAnimationFrame(function() {
    var card = document.querySelector("#list .card[data-result-index='" + index + "']");
    if (!card) return;
    card.setAttribute("tabindex", "-1");
    card.scrollIntoView({ behavior: "smooth", block: "start", inline: "nearest" });
    try { card.focus({ preventScroll: true }); } catch (e) { card.focus(); }
  });
}

function focusProductionResultIndex(index) {
  if (index === null || index === undefined || index < 0) return;
  requestAnimationFrame(function() {
    var card = document.querySelector("#production-list [data-production-index='" + index + "']");
    if (!card) return;
    card.setAttribute("tabindex", "-1");
    card.scrollIntoView({ behavior: "smooth", block: "start", inline: "nearest" });
    try { card.focus({ preventScroll: true }); } catch (e) { card.focus(); }
  });
}

function syncFirstSearchResultDetail() {
  var first = getFiltered()[0] || null;
  if (!first) {
    closePanel();
    return;
  }
  var id = parseInt(productDkdId(first), 10);
  if (isNaN(id)) {
    closePanel();
    return;
  }
  openPanel(id, { showMobileOverlay: false, autoSelect: true });
}

function openPanel(id, options) {
  options = options || {};
  if (!canViewProductInfo()) {
    if (!options.autoSelect) showPermissionDenied("open_product_detail", "core_product_search_view", id);
    closePanel();
    return;
  }
  currentProduct = null;
  currentCoreDkdShohinId = null;
  currentProductSpecs = [];
  currentProductNominalSpec = null;
  currentProductVariants = [];
  for (var i=0;i<allProducts.length;i++) {
    if (parseInt(productDkdId(allProducts[i]), 10) === id) {
      currentProduct = allProducts[i];
      currentProduct.id = currentProduct.id || id;
      break;
    }
  }
  if (!currentProduct) return;
  if (!options.autoSelect) logProductDetailOpen("search", currentProduct);
  setCspStyle(document.getElementById("panel-welcome"), "display", "none");
  setCspStyle(document.getElementById("panel-inner"), "display", "grid");
  setCspStyle(document.getElementById("panel-footer"), "display", canManageUsedCoreImages() ? "block" : "none");
  document.getElementById("panel-topbar-title").textContent = productCategoryLabel(currentProduct) || "-";
  configureSalesProductAddButton();
  if (!isPC() && options.showMobileOverlay !== false) { document.getElementById("overlay").classList.add("show"); document.getElementById("panel").classList.add("show"); }
  renderPanelStatic();
  document.querySelectorAll(".card").forEach(function(c){ c.classList.toggle("selected", parseInt(c.dataset.id,10)===id); });
}

async function openProductByDkdId(dkdId) {
  var id = parseInt(dkdId, 10);
  if (isNaN(id)) return;
  var found = allProducts.some(function(p) { return parseInt(productDkdId(p), 10) === id; });
  if (!found) {
    var r = await sb.from("core_product_search_view").select("*").eq("dkd_shohin_id", id).maybeSingle();
    if (!r.error && r.data) allProducts.push(normalizeCoreProductFastRows([r.data])[0]);
  }
  openPanel(id);
}

function productionSearchTermForRow(row, id) {
  return row.manufacturer_part_number || row.genuine_part_number || row.genuine_part_number_2 || row.core_part_number || String(id || "");
}

async function openProductionProductByDkdId(dkdId, options) {
  options = options || {};
  var id = parseInt(dkdId, 10);
  if (isNaN(id)) return;
  var row = (productionRows || []).find(function(p) { return parseInt(productDkdId(p), 10) === id; }) || null;
  if (!row) {
    var r = await sb.from("core_product_search_view").select("*").eq("dkd_shohin_id", id).maybeSingle();
    if (r.error || !r.data) {
      alert(t("no_results"));
      return;
    }
    row = normalizeCoreProductFastRows([r.data])[0];
  }
  applyCachedSearchAuxiliaryMaps([row]);
  row = enrichProductionProduct(row);
  var replaced = false;
  productionRows = (productionRows || []).map(function(p) {
    if (parseInt(productDkdId(p), 10) === id) {
      replaced = true;
      return row;
    }
    return p;
  });
  if (!replaced) productionRows.unshift(row);
  currentProductionRow = row;
  if (options.syncSearch !== false) {
    productionFilter = "all";
    productionCategoryFilter = "all";
    var qEl = document.getElementById("production-q");
    if (qEl) qEl.value = productionSearchTermForRow(row, id);
    renderProductionFilterChips();
    renderProductionCategoryFilterOptions();
  }
  showScreen("production-search");
  updateAllHeaders();
  renderProductionList();
  var selectedIndex = productionFilteredRows.findIndex(function(p) { return parseInt(productDkdId(p), 10) === id; });
  await renderProductionDetail(row);
  if (selectedIndex >= 0) focusProductionResultIndex(selectedIndex);
  logProductDetailOpen("production-search", row);
}

async function openProductionCompatibleProduct(dkdId) {
  await openProductionProductByDkdId(dkdId);
}

