function componentReverseCatalogAssyKey(row) {
  var manufacturerPartKey = normalizedPartKey(row && row.assy_manufacturer_part_number);
  if (!manufacturerPartKey) return "row|" + String((row && row.id) || "");
  return normalizedPartKey(row && row.assy_manufacturer) + "|" + manufacturerPartKey;
}

function componentReverseHasCatalogAssyNumbers(row) {
  return !!normalizedPartKey(row && row.assy_manufacturer_part_number) &&
    !!normalizedPartKey(row && row.assy_genuine_part_number);
}

function componentReversePreferCatalogAssyRows(rows) {
  var groups = {};
  var groupOrder = [];
  (rows || []).forEach(function(row) {
    var key = componentReverseCatalogAssyKey(row);
    if (!groups[key]) {
      groups[key] = [];
      groupOrder.push(key);
    }
    groups[key].push(row);
  });
  return groupOrder.reduce(function(out, key) {
    var group = groups[key];
    var completeRows = group.filter(componentReverseHasCatalogAssyNumbers);
    return out.concat(completeRows.length ? completeRows : group);
  }, []);
}

async function loadComponentReverseUsageRows(componentIds, scope, selectColumns) {
  if (scope !== "catalog_spec") {
    var scopedQuery = sb.from("assembly_component_usage_details")
      .select(selectColumns)
      .in("dkd_component_id", componentIds)
      .limit(300);
    if (scope !== "all") scopedQuery = scopedQuery.eq("product_kind", scope);
    return await scopedQuery;
  }

  var rows = [];
  for (var from = 0; from < COMPONENT_REVERSE_CATALOG_SOURCE_LIMIT; from += COMPONENT_REVERSE_PAGE_SIZE) {
    var to = Math.min(from + COMPONENT_REVERSE_PAGE_SIZE - 1, COMPONENT_REVERSE_CATALOG_SOURCE_LIMIT - 1);
    var page = await sb.from("assembly_component_usage_details")
      .select(selectColumns)
      .in("dkd_component_id", componentIds)
      .eq("product_kind", "catalog_spec")
      .order("id", { ascending: true })
      .range(from, to);
    if (page.error) return page;
    var pageRows = page.data || [];
    rows = rows.concat(pageRows);
    if (pageRows.length < COMPONENT_REVERSE_PAGE_SIZE) break;
  }
  return { data: componentReversePreferCatalogAssyRows(rows), error: null };
}

async function loadComponentReverseVehicleApplicationRows(rows, field, rowField, makerGroup) {
  var keys = uniqueTextValues((rows || []).map(function(row) {
    return normalizedPartKey(row && row[rowField]);
  }).filter(Boolean));
  if (!keys.length || !makerGroup) return [];

  async function loadChunk(chunk) {
    var loaded = [];
    for (var from = 0; from < COMPONENT_REVERSE_VEHICLE_SOURCE_LIMIT; from += COMPONENT_REVERSE_PAGE_SIZE) {
      var to = Math.min(from + COMPONENT_REVERSE_PAGE_SIZE - 1, COMPONENT_REVERSE_VEHICLE_SOURCE_LIMIT - 1);
      var page = await sb.from("catalog_vehicle_applications")
        .select("id,normalized_manufacturer_part_number,normalized_genuine_part_number,vehicle_manufacturer")
        .in("vehicle_manufacturer", makerGroup.aliases)
        .in(field, chunk)
        .order("id", { ascending: true })
        .range(from, to);
      if (page.error) throw page.error;
      var pageRows = page.data || [];
      loaded = loaded.concat(pageRows);
      if (pageRows.length < COMPONENT_REVERSE_PAGE_SIZE) break;
    }
    return loaded;
  }

  var chunks = chunkArray(keys, COMPONENT_REVERSE_VEHICLE_CHUNK_SIZE);
  var rowsById = {};
  for (var i = 0; i < chunks.length; i += COMPONENT_REVERSE_VEHICLE_CHUNK_CONCURRENCY) {
    var batch = chunks.slice(i, i + COMPONENT_REVERSE_VEHICLE_CHUNK_CONCURRENCY);
    var batchRows = await Promise.all(batch.map(loadChunk));
    batchRows.forEach(function(loaded) {
      loaded.forEach(function(row) {
        var key = String(row.id || "") || [
          row.normalized_manufacturer_part_number || "",
          row.normalized_genuine_part_number || "",
          row.vehicle_manufacturer || ""
        ].join("|");
        rowsById[key] = row;
      });
    });
  }
  return Object.keys(rowsById).map(function(key) { return rowsById[key]; });
}

function componentReverseVehicleAssyPairKey(manufacturerPartNumber, genuinePartNumber) {
  return normalizedPartKey(manufacturerPartNumber) + "|" + normalizedPartKey(genuinePartNumber);
}

function componentReverseAddVehicleMaker(map, key, maker) {
  if (!key || !maker) return;
  if (!map[key]) map[key] = [];
  if (map[key].indexOf(maker) < 0) map[key].push(maker);
}

function componentReverseRowsForVehicleApplications(rows, applications) {
  var pairMap = {};
  var manufacturerMap = {};
  var genuineMap = {};
  (applications || []).forEach(function(application) {
    var manufacturerKey = String(application.normalized_manufacturer_part_number || "");
    var genuineKey = String(application.normalized_genuine_part_number || "");
    var maker = String(application.vehicle_manufacturer || "").trim();
    if (manufacturerKey && genuineKey) {
      componentReverseAddVehicleMaker(pairMap, manufacturerKey + "|" + genuineKey, maker);
    }
    componentReverseAddVehicleMaker(manufacturerMap, manufacturerKey, maker);
    componentReverseAddVehicleMaker(genuineMap, genuineKey, maker);
  });
  return (rows || []).reduce(function(out, row) {
    var manufacturerKey = normalizedPartKey(row && row.assy_manufacturer_part_number);
    var genuineKey = normalizedPartKey(row && row.assy_genuine_part_number);
    var makers = manufacturerKey && genuineKey
      ? (pairMap[componentReverseVehicleAssyPairKey(manufacturerKey, genuineKey)] || [])
      : manufacturerKey
        ? (manufacturerMap[manufacturerKey] || [])
        : (genuineMap[genuineKey] || []);
    if (!makers.length) return out;
    out.push(Object.assign({}, row, { component_reverse_vehicle_makers: makers }));
    return out;
  }, []);
}

async function filterComponentReverseRowsByVehicleMaker(rows, makerGroup) {
  if (!makerGroup || !rows || !rows.length) return rows || [];
  var genuineOnlyRows = rows.filter(function(row) {
    return !normalizedPartKey(row && row.assy_manufacturer_part_number) &&
      !!normalizedPartKey(row && row.assy_genuine_part_number);
  });
  var applicationGroups = await Promise.all([
    loadComponentReverseVehicleApplicationRows(rows, "normalized_manufacturer_part_number", "assy_manufacturer_part_number", makerGroup),
    loadComponentReverseVehicleApplicationRows(genuineOnlyRows, "normalized_genuine_part_number", "assy_genuine_part_number", makerGroup)
  ]);
  return componentReverseRowsForVehicleApplications(rows, applicationGroups[0].concat(applicationGroups[1]));
}

function componentReverseKindLabel(row) {
  if (row && row.is_catalog_evidence) return productKindLabel("catalog_spec");
  return productKindLabel((row && row.product_kind) || "rebuilt");
}

function renderComponentReverseLookupRows(rows) {
  var result = document.getElementById("component-reverse-result");
  if (!result) return;
  if (!rows || !rows.length) {
    result.innerHTML = "<div class='component-empty'>" + esc(t("component_reverse_no_results")) + "</div>";
    return;
  }
  var html = "<div class='component-reverse-list'>";
  rows.forEach(function(row) {
    html += "<div class='component-reverse-row'>";
    html += "<div>";
    html += "<div class='component-reverse-label'>" + esc(t("f_mfr_assy_pn")) + "</div>";
    html += "<div class='component-reverse-assy'>" + esc(row.assy_manufacturer_part_number || "-") + "</div>";
    html += "<div class='component-reverse-label'>" + esc(t("f_genuine_assy_pn")) + "</div>";
    html += "<div class='component-reverse-assy component-reverse-assy-genuine'>" + esc(row.assy_genuine_part_number || "-") + "</div>";
    html += "<div class='component-reverse-sub'>" + esc(t("f_manufacturer")) + ": " + esc(row.assy_manufacturer || "-") + " / " + esc(t("product_kind_section")) + ": " + esc(componentReverseKindLabel(row)) + "</div>";
    if (row.component_reverse_vehicle_makers && row.component_reverse_vehicle_makers.length) {
      html += "<div class='component-reverse-sub'>" + esc(t("f_vehicle_mfr")) + ": " + esc(row.component_reverse_vehicle_makers.map(vehicleMakerLabel).join(" / ")) + "</div>";
    }
    html += "</div>";
    html += "<div>";
    html += "<div class='component-reverse-label'>" + esc(t("component_reverse_component")) + "</div>";
    html += "<div class='component-reverse-part'>" + esc(row.component_name || row.component_part_name || "-") + "</div>";
    html += "<div class='component-reverse-sub'>" + esc(t("f_mfr_pn")) + ": " + esc(row.component_manufacturer_part_number || "-") + "</div>";
    html += "<div class='component-reverse-sub'>" + esc(t("f_genuine_pn")) + ": " + esc(row.component_genuine_part_number || "-") + "</div>";
    html += "<div class='component-reverse-sub'>" + esc(row.component_manufacturer || "") + "</div>";
    html += "</div>";
    html += "<div class='component-reverse-meta'>";
    html += "<div class='component-reverse-meta-item'><div class='component-reverse-label'>" + esc(t("component_position")) + "</div><div class='component-reverse-main'>" + esc(row.component_position || row.source_code || "-") + "</div></div>";
    html += "<div class='component-reverse-meta-item'><div class='component-reverse-label'>" + esc(t("component_interchange")) + "</div><div class='component-reverse-main'>" + esc(formatComponentInterchange(row)) + "</div></div>";
    html += "<div class='component-reverse-meta-item'><div class='component-reverse-label'>" + esc(t("component_start_period")) + "</div><div class='component-reverse-main'>" + esc(row.effective_start || row.start_period || "-") + "</div></div>";
    html += "<div class='component-reverse-meta-item'><div class='component-reverse-label'>" + esc(t("component_end_period")) + "</div><div class='component-reverse-main'>" + esc(row.effective_end || row.end_period || "-") + "</div></div>";
    html += "</div>";
    html += "<div class='component-reverse-action'><button class='btn-sm-edit production-action-secondary' data-component-reverse-open-assy='" + esc(String(row.dkd_shohin_id || "")) + "'>" + esc(t("component_reverse_open_assy")) + "</button></div>";
    html += "</div>";
  });
  html += "</div>";
  result.innerHTML = html;
  result.querySelectorAll("[data-component-reverse-open-assy]").forEach(function(btn) {
    btn.addEventListener("click", function() {
      openComponentReverseAssy(btn.dataset.componentReverseOpenAssy);
    });
  });
}

async function runComponentReverseLookup() {
  var mfrEl = document.getElementById("component-reverse-mfr-pn");
  var genuineEl = document.getElementById("component-reverse-genuine-pn");
  if (mfrEl) normalizeComponentPartNumberElement(mfrEl);
  if (genuineEl) normalizeComponentPartNumberElement(genuineEl);
  var values = [
    componentReverseValue("component-reverse-mfr-pn"),
    componentReverseValue("component-reverse-genuine-pn")
  ];
  var keys = componentReverseSearchKeys();
  var result = document.getElementById("component-reverse-result");
  var button = document.getElementById("btn-component-reverse-search");
  if (!keys.length) {
    setComponentReverseStatus(t("component_reverse_no_query"), true);
    if (result) result.innerHTML = "<div class='component-empty'>" + esc(t("component_reverse_no_query")) + "</div>";
    return;
  }
  if (button) {
    button.disabled = true;
    button.textContent = t("loading");
  }
  setComponentReverseStatus(t("component_reverse_searching"), false);
  if (result) result.innerHTML = "<div class='component-empty'>" + esc(t("loading")) + "</div>";
  var selectColumns = "id, dkd_component_id, dkd_shohin_id, product_kind, product_variant_id, assy_manufacturer, assy_manufacturer_part_number, assy_genuine_part_number, component_manufacturer, component_manufacturer_part_number, component_genuine_part_number, component_name, component_part_name, quantity, unit_price_jpy, interchange_code, effective_start, effective_end, component_position, source_code, is_catalog_evidence";
  var r = { data: [], error: null };
  try {
    var componentIds = await loadComponentReverseComponentIds(keys);
    if (componentIds.length) {
      var scope = componentReverseScopeValue();
      r = await loadComponentReverseUsageRows(componentIds, scope, selectColumns);
    }
  } catch (e) {
    r = { data: [], error: e };
  }
  if (r.error) {
    if (button) {
      button.disabled = false;
      button.textContent = t("component_reverse_search");
    }
    console.warn("component reverse lookup failed", r.error);
    setComponentReverseStatus(t("msg_kikan_err") + ": " + r.error.message, true);
    if (result) result.innerHTML = "<div class='component-empty'>" + esc(t("component_reverse_no_results")) + "</div>";
    return;
  }
  var partName = componentReverseValue("component-reverse-part-name");
  var rows = componentReverseDedupRows(r.data || []).filter(function(row) {
    return componentReverseNameMatches(row, partName);
  });
  try {
    rows = await filterComponentReverseRowsByVehicleMaker(rows, componentReverseVehicleMakerGroup());
  } catch (e) {
    if (button) {
      button.disabled = false;
      button.textContent = t("component_reverse_search");
    }
    console.warn("component reverse vehicle maker lookup failed", e);
    setComponentReverseStatus(t("msg_kikan_err") + ": " + (e.message || String(e)), true);
    if (result) result.innerHTML = "<div class='component-empty'>" + esc(t("component_reverse_no_results")) + "</div>";
    return;
  }
  rows.sort(function(a, b) {
    var scoreDiff = componentReverseMatchScore(b, values) - componentReverseMatchScore(a, values);
    if (scoreDiff) return scoreDiff;
    var assyA = String(a.assy_manufacturer_part_number || "");
    var assyB = String(b.assy_manufacturer_part_number || "");
    if (assyA !== assyB) return assyA.localeCompare(assyB, "ja", { numeric: true });
    return String(a.component_position || "").localeCompare(String(b.component_position || ""), "ja", { numeric: true });
  });
  rows = rows.slice(0, COMPONENT_REVERSE_RESULT_LIMIT);
  if (button) {
    button.disabled = false;
    button.textContent = t("component_reverse_search");
  }
  setComponentReverseStatus(tf("component_reverse_count", { n: rows.length }), false);
  renderComponentReverseLookupRows(rows);
}

async function openComponentReverseAssy(dkdId) {
  var id = parseInt(dkdId, 10);
  if (isNaN(id)) return;
  closeComponentReverseLookup();
  if (componentReturnScreen === "production-search" || isScreenActive("production-search")) {
    await openProductionProductByDkdId(id);
    return;
  }
  showScreen("search");
  updateAllHeaders();
  await openProductByDkdId(id);
}

