  html += "<div id='component-target-summary'>" + componentTargetSummaryHtml(null) + "</div>";
  html += "<div class='component-target-controls'>";
  html += "<div class='component-target-field'><label for='component-product-kind-select'>" + esc(t("component_target_kind_label")) + "</label>";
