function bindComponentKindSelector() {
  var select = document.getElementById("component-product-kind-select");
  var variantSelect = document.getElementById("component-product-variant-select");
  if (select) {
    select.onchange = function() {
      currentSelectedProductKind = normalizeProductKind(select.value || "rebuilt");
      currentSelectedComponentVariantId = "";
      renderComponentAddPanel();
      updateComponentsContextHeader();
      loadAssemblyComponentsForCurrent();
    };
  }
  if (variantSelect) {
    variantSelect.onchange = function() {
      currentSelectedComponentVariantId = variantSelect.value || "";
      renderComponentAddPanel();
      updateComponentsContextHeader();
      loadAssemblyComponentsForCurrent();
    };
  }
}

function renderComponentAddPanel() {
  var wrap = document.getElementById("component-add-wrap");
  if (!wrap) return;
  var html = renderComponentKindSelectorHtml();
  if (selectedProductKind() === "catalog_spec") {
    wrap.innerHTML = "<div class='component-catalog-head-layout'><div class='component-catalog-target'>" + html + "</div><div class='component-illustration-slot' id='component-illustration-slot'>" + renderComponentIllustrationPanelHtml() + "</div></div>";
    bindComponentKindSelector();
    bindCatalogIllustrationInteractions(wrap);
    return;
  }
  if (!canManageComponentsInCurrentContext()) {
    wrap.innerHTML = html;
    bindComponentKindSelector();
    return;
  }
  html += "<div class='component-add-panel component-add-compact'>";
  html += "<div><div class='component-add-title'>" + esc(t("component_add_title")) + "</div>";
  html += "<div class='component-add-current'>" + esc(productKindLabel(selectedProductKind()) + " / " + componentTargetVariantText()) + "</div></div>";
  html += "<button class='btn-primary' id='btn-component-add-open' type='button'>+ " + esc(t("component_add_open")) + "</button>";
  html += "</div>";
  wrap.innerHTML = html;
  bindComponentKindSelector();
  var openBtn = document.getElementById("btn-component-add-open");
  if (openBtn) openBtn.addEventListener("click", openComponentAddForm);
}

function closeComponentAddForm() {
  var overlay = document.getElementById("component-add-overlay");
  if (overlay) overlay.classList.remove("show");
}

function cancelComponentAddForm() {
  if (confirm(t("component_add_cancel_confirm"))) closeComponentAddForm();
}

async function openComponentAddForm() {
  if (!currentProduct) return;
  if (!canManageComponentsInCurrentContext()) { alert(t("err_perm")); return; }
  if (selectedProductKind() === "catalog_spec") { alert(t("component_catalog_locked_save")); return; }
  var productKeyAtOpen = productDkdId(currentProduct) + "|" + componentCatalogCategoryCode(currentProduct) + "|" + selectedProductKind();
  componentCatalogNameCandidates = [];
  componentCatalogNameCandidateLabelMap = {};
  componentCatalogNameCandidateKindMap = {};
  componentCatalogNameCandidateMetaMap = {};
  componentCatalogNameCandidateMasterMap = {};
  clearComponentAddForm();
  var manufacturer = document.getElementById("component-add-mfr");
  if (manufacturer) manufacturer.value = "";
  renderComponentAddNameOptions();
  var title = document.getElementById("component-add-modal-title");
  if (title) title.textContent = tf("component_add_title_for_kind", { kind: productKindLabel(selectedProductKind()) });
  var help = document.getElementById("component-add-modal-help");
  if (help) help.textContent = selectedProductSub() + " / " + componentTargetVariantText();
  var err = document.getElementById("component-add-error");
  if (err) err.textContent = "";
  var btn = document.getElementById("btn-component-add");
  if (btn) { btn.disabled = false; btn.textContent = t("component_add"); }
  var overlay = document.getElementById("component-add-overlay");
  if (overlay) overlay.classList.add("show");
  var name = document.getElementById("component-add-name");
  if (name) name.focus();
  loadComponentCatalogNameCandidatesForCurrent().then(function() {
    var overlayNow = document.getElementById("component-add-overlay");
    if (!overlayNow || !overlayNow.classList.contains("show")) return;
    if (!currentProduct || productKeyAtOpen !== productDkdId(currentProduct) + "|" + componentCatalogCategoryCode(currentProduct) + "|" + selectedProductKind()) return;
    renderComponentAddNameOptions(componentAddValue("component-add-name"));
  }).catch(function(err) {
    console.warn("component name candidates load failed", err);
  });
}

function componentAddValue(id) {
  var el = document.getElementById(id);
  return el ? el.value.trim() : "";
}

function setComponentAddValue(id, value) {
  var el = document.getElementById(id);
  if (el && el.tagName === "SELECT" && value && !Array.prototype.some.call(el.options || [], function(opt) { return opt.value === value; })) {
    var opt = document.createElement("option");
    opt.value = value;
    opt.textContent = value;
    opt.dataset.unapproved = "1";
    el.insertBefore(opt, el.firstChild ? el.firstChild.nextSibling : null);
  }
  if (el) el.value = value || "";
}

function normalizeComponentPartNumberInput(value) {
  return normalizeAsciiWidth(value)
    .trim()
    .toUpperCase()
    .replace(/[\u2010-\u2015\u2212\u30FC\uFF0D]/g, "-")
    .replace(/[\u3002\uFF0E]/g, ".")
    .replace(/[\u3001\uFF0C]/g, ",");
}

function normalizedComponentPartKey(value) {
  return normalizeComponentPartNumberInput(value).replace(/[-,\s]/g, "");
}

function normalizeComponentManufacturerInput(value) {
  return normalizeAsciiWidth(value).trim().toUpperCase();
}

function normalizeComponentPartNumberElement(el) {
  if (!el) return "";
  var value = normalizeComponentPartNumberInput(el.value);
  if (el.value !== value) el.value = value;
  return value;
}

function bindComponentPartNumberInputEvents(el, onStateChange, onCommit) {
  if (!el) return;
  var composing = false;
  var normalizeTimer = null;
  function clearNormalizeTimer() {
    if (normalizeTimer === null) return;
    clearTimeout(normalizeTimer);
    normalizeTimer = null;
  }
  function updateState() {
    if (typeof onStateChange === "function") onStateChange();
  }
  function commitValue() {
    clearNormalizeTimer();
    normalizeComponentPartNumberElement(el);
    updateState();
    if (typeof onCommit === "function") onCommit();
  }
  el.addEventListener("compositionstart", function() {
    clearNormalizeTimer();
    composing = true;
  });
  el.addEventListener("compositionend", function() {
    composing = false;
    clearNormalizeTimer();
    normalizeTimer = setTimeout(function() {
      normalizeTimer = null;
      if (composing) return;
      normalizeComponentPartNumberElement(el);
      updateState();
    }, 0);
  });
  el.addEventListener("input", function(event) {
    if (composing || (event && event.isComposing)) return;
    updateState();
  });
  el.addEventListener("change", commitValue);
  el.addEventListener("blur", commitValue);
}

function componentPartNumberSpec(kind) {
  return kind === "genuine"
    ? { required: false, label: t("f_genuine_pn") }
    : { required: true, label: t("f_mfr_pn") };
}

function componentPartNumberValidation(value, kind) {
  var spec = componentPartNumberSpec(kind);
  var normalized = normalizeComponentPartNumberInput(value);
  var errors = [];
  var warnings = [];
  if (!normalized) {
    if (spec.required) errors.push(t("component_mfr_pn_required"));
    return { value: normalized, errors: errors, warnings: warnings };
  }
  var validPattern = kind === "manufacturer" ? /^[A-Z0-9.,-]+$/ : /^[A-Z0-9-]+$/;
  if (!validPattern.test(normalized)) {
    errors.push(tf(kind === "manufacturer" ? "component_mfr_part_number_invalid_chars" : "component_part_number_invalid_chars", { field: spec.label }));
  }
  return { value: normalized, errors: errors, warnings: warnings };
}

function setComponentPartNumberInputState(el, result) {
  if (!el || !result) return;
  el.classList.toggle("component-part-number-invalid", result.errors.length > 0);
  el.classList.toggle("component-part-number-warning", result.errors.length === 0 && result.warnings.length > 0);
  el.title = result.errors.concat(result.warnings).join("\n");
}

function validateComponentPartNumberInputs(manufacturerPartNumber, genuinePartNumber, manufacturer, excludeUsageId) {
  var mfr = componentPartNumberValidation(manufacturerPartNumber, "manufacturer");
  var genuine = componentPartNumberValidation(genuinePartNumber, "genuine");
  var errors = mfr.errors.concat(genuine.errors);
  var warnings = mfr.warnings.concat(genuine.warnings);
  var makerKey = normalizeComponentManufacturerInput(manufacturer || "UNKNOWN");
  var partKey = normalizedComponentPartKey(mfr.value);
  if (partKey) {
    (assemblyComponentRows || []).forEach(function(row) {
      if (excludeUsageId && String(row.id) === String(excludeUsageId)) return;
      var rowMakerKey = normalizeComponentManufacturerInput(row.component_manufacturer || "UNKNOWN");
      var rowPartKey = normalizedComponentPartKey(row.component_manufacturer_part_number);
      if (rowMakerKey === makerKey && rowPartKey === partKey) {
        warnings.push(tf("component_part_number_duplicate_warning", {
          value: [makerKey, mfr.value].filter(Boolean).join(" / ")
        }));
      }
    });
  }
  return {
    manufacturerPartNumber: mfr.value,
    genuinePartNumber: genuine.value,
    errors: errors,
    warnings: warnings
  };
}

function confirmComponentPartNumberWarnings(warnings) {
  if (!warnings || !warnings.length) return true;
  var unique = uniqueTextValues(warnings);
  return confirm(tf("component_part_number_confirm", { messages: unique.join("\n") }));
}

function setComponentAddPartNumberWarning(errors, warnings) {
  var box = document.getElementById("component-add-part-number-warning");
  if (!box) return;
  var messages = (errors || []).concat(warnings || []);
  box.textContent = uniqueTextValues(messages).join("\n");
  box.classList.toggle("show", messages.length > 0);
  box.classList.toggle("error", (errors || []).length > 0);
}

function updateComponentAddPartNumberInputState() {
  var mfrEl = document.getElementById("component-add-mfr-pn");
  var genuineEl = document.getElementById("component-add-genuine-pn");
  var mfr = componentPartNumberValidation(mfrEl ? mfrEl.value : "", "manufacturer");
  var genuine = componentPartNumberValidation(genuineEl ? genuineEl.value : "", "genuine");
  setComponentPartNumberInputState(mfrEl, mfr);
  setComponentPartNumberInputState(genuineEl, genuine);
  setComponentAddPartNumberWarning(mfr.errors.concat(genuine.errors), mfr.warnings.concat(genuine.warnings));
}

function updateComponentEditPartNumberInputStates(tr) {
  if (!tr) return;
  var mfrEl = tr.querySelector("[data-component-edit-field='component_manufacturer_part_number']");
  var genuineEl = tr.querySelector("[data-component-edit-field='component_genuine_part_number']");
  setComponentPartNumberInputState(mfrEl, componentPartNumberValidation(mfrEl ? mfrEl.value : "", "manufacturer"));
  setComponentPartNumberInputState(genuineEl, componentPartNumberValidation(genuineEl ? genuineEl.value : "", "genuine"));
}

function componentPartRowMatchScore(row, mfrKey, genuineKey) {
  var rowMfrKey = normalizedPartKey(row.normalized_manufacturer_part_number || row.manufacturer_part_number);
  var rowGenuineKey = normalizedPartKey(row.normalized_genuine_part_number || row.genuine_part_number);
  var score = 0;
  if (mfrKey && rowMfrKey === mfrKey) score += 20;
  if (genuineKey && rowGenuineKey === genuineKey) score += 20;
  if (mfrKey && rowGenuineKey === mfrKey) score += 14;
  if (genuineKey && rowMfrKey === genuineKey) score += 14;
  if (mfrKey && genuineKey && rowMfrKey === mfrKey && rowGenuineKey === genuineKey) score += 40;
  if (mfrKey && genuineKey && rowMfrKey === genuineKey && rowGenuineKey === mfrKey) score += 24;
  if (row.manufacturer_part_number) score += 3;
  if (row.genuine_part_number) score += 2;
  if (row.manufacturer) score += 1;
  return score;
}

function componentPartLookupCandidateFromProduct(row, mfrKey, genuineKey) {
  if (!row) return null;
  var g1 = normalizedPartKey(row.normalized_genuine_part_number || row.genuine_part_number);
  var g2 = normalizedPartKey(row.normalized_genuine_part_number_2 || row.genuine_part_number_2);
  var useGenuine2 = !!(g2 && ((mfrKey && g2 === mfrKey) || (genuineKey && g2 === genuineKey)));
  return {
    manufacturer: row.manufacturer || "",
    manufacturer_part_number: row.manufacturer_part_number || "",
    genuine_part_number: useGenuine2 ? (row.genuine_part_number_2 || row.genuine_part_number || "") : (row.genuine_part_number || row.genuine_part_number_2 || ""),
    part_name: "",
    normalized_manufacturer_part_number: row.normalized_manufacturer_part_number || normalizedPartKey(row.manufacturer_part_number),
    normalized_genuine_part_number: useGenuine2 ? g2 : (g1 || g2)
  };
}

async function lookupCoreProductPartNumberPair(mfrKey, genuineKey) {
  var keys = [];
  if (mfrKey) keys.push(mfrKey);
  if (genuineKey && keys.indexOf(genuineKey) < 0) keys.push(genuineKey);
  if (!keys.length) return null;
  var filters = [];
  keys.forEach(function(key) {
    filters.push("normalized_manufacturer_part_number.eq." + key);
    filters.push("normalized_genuine_part_number.eq." + key);
    filters.push("normalized_genuine_part_number_2.eq." + key);
  });
  var r = await sb.from("core_products")
    .select("manufacturer,manufacturer_part_number,genuine_part_number,genuine_part_number_2,category,normalized_manufacturer_part_number,normalized_genuine_part_number,normalized_genuine_part_number_2")
    .or(filters.join(","))
    .limit(30);
  if (r.error) {
    console.warn("core product part number lookup failed", r.error);
    return null;
  }
  var best = null;
  var bestScore = 0;
  (r.data || []).forEach(function(row) {
    var candidate = componentPartLookupCandidateFromProduct(row, mfrKey, genuineKey);
    var score = componentPartRowMatchScore(candidate, mfrKey, genuineKey);
    if (score > bestScore) {
      best = candidate;
      bestScore = score;
    }
  });
  return best;
}

async function lookupComponentPartNumberPair(mfrValue, genuineValue) {
  if (/[.,]/.test(String(mfrValue || ""))) return null;
  var mfrKey = normalizedPartKey(mfrValue);
  var genuineKey = normalizedPartKey(genuineValue);
  var keys = [];
  if (mfrKey) keys.push(mfrKey);
  if (genuineKey && keys.indexOf(genuineKey) < 0) keys.push(genuineKey);
  if (!keys.length) return null;
  var filters = [];
  keys.forEach(function(key) {
    filters.push("normalized_manufacturer_part_number.eq." + key);
    filters.push("normalized_genuine_part_number.eq." + key);
  });
  var r = await sb.from("component_parts")
    .select("manufacturer,manufacturer_part_number,genuine_part_number,part_name,normalized_manufacturer_part_number,normalized_genuine_part_number")
    .or(filters.join(","))
    .limit(30);
  if (r.error) {
    console.warn("component part number lookup failed", r.error);
    return lookupCoreProductPartNumberPair(mfrKey, genuineKey);
  }
  var best = null;
  var bestScore = 0;
  (r.data || []).forEach(function(row) {
    var score = componentPartRowMatchScore(row, mfrKey, genuineKey);
    var bestHasMfrPart = best && best.manufacturer_part_number;
    var bestHasGenuinePart = best && best.genuine_part_number;
    if (
      score > bestScore ||
      (score === bestScore && row.manufacturer_part_number && !bestHasMfrPart) ||
      (score === bestScore && row.genuine_part_number && !bestHasGenuinePart)
    ) {
      best = row;
      bestScore = score;
    }
  });
  var bestMfrKey = best ? normalizedPartKey(best.normalized_manufacturer_part_number || best.manufacturer_part_number) : "";
  var bestGenuineKey = best ? normalizedPartKey(best.normalized_genuine_part_number || best.genuine_part_number) : "";
  var shouldUseProductFallback = !best || !best.manufacturer_part_number || (mfrKey && bestMfrKey === mfrKey && bestGenuineKey === mfrKey);
  if (shouldUseProductFallback) {
    var productBest = await lookupCoreProductPartNumberPair(mfrKey, genuineKey);
    if (productBest && (!best || componentPartRowMatchScore(productBest, mfrKey, genuineKey) >= bestScore)) {
      best = productBest;
    }
  }
  return best;
}

async function reconcileComponentAddPartNumbers() {
  var seq = ++componentAddPartNumberLookupSeq;
  if (!isCurrentCategoryAssyComponentName(componentAddValue("component-add-name"))) return null;
  var mfrPn = componentAddValue("component-add-mfr-pn");
  var genuinePn = componentAddValue("component-add-genuine-pn");
  if (!mfrPn && !genuinePn) return null;
  var row = await lookupComponentPartNumberPair(mfrPn, genuinePn);
  if (seq !== componentAddPartNumberLookupSeq || !row) return row;
  if (row.manufacturer) setComponentAddValue("component-add-mfr", row.manufacturer);
  if (row.manufacturer_part_number) setComponentAddValue("component-add-mfr-pn", row.manufacturer_part_number);
  if (row.genuine_part_number) setComponentAddValue("component-add-genuine-pn", row.genuine_part_number);
  var currentName = componentAddValue("component-add-name");
  if (!currentName && row.part_name) setComponentAddValue("component-add-name", row.part_name);
  renderComponentAddNameOptions(componentAddValue("component-add-name"));
  updateComponentAddPartNumberInputState();
  return row;
}

function clearComponentAddForm() {
  ["component-add-mfr","component-add-mfr-pn","component-add-genuine-pn","component-add-name","component-add-position","component-add-unit-price","component-add-replacement-rate","component-add-interchange","component-add-procurement-category","component-add-start","component-add-end","component-add-manufacturing-memo"].forEach(function(id) {
    var el = document.getElementById(id);
    if (el) {
      el.value = "";
      el.classList.remove("component-part-number-invalid", "component-part-number-warning");
      el.title = "";
    }
  });
  var qty = document.getElementById("component-add-qty");
  if (qty) qty.value = "1";
  setComponentAddPartNumberWarning([], []);
}

function nullableDigitsFromInput(id) {
  var el = document.getElementById(id);
  var v = el ? el.value.trim() : "";
  if (!v) return null;
  if (!/^\d+$/.test(v)) return NaN;
  return parseInt(v, 10);
}

function normalizeComponentReplacementRateElement(setDefault) {
  var el = document.getElementById("component-add-replacement-rate");
  if (!el) return null;
  var value = String(el.value || "").trim();
  if (!value) {
    if (setDefault) {
      el.value = "100";
      return 100;
    }
    return null;
  }
  if (!/^\d+$/.test(value)) return NaN;
  var num = parseInt(value, 10);
  if (num > 100) num = 100;
  if (num < 0) num = 0;
  if (String(num) !== value) el.value = String(num);
  return num;
}

function applyComponentProcurementRateDefault() {
  var procurement = document.getElementById("component-add-procurement-category");
  var rate = document.getElementById("component-add-replacement-rate");
  if (!procurement || !rate) return;
  if (procurement.value === "新品交換") rate.value = "100";
}

async function addAssemblyComponentForCurrent() {
  if (!currentProduct) return;
  if (!canManageComponentsInCurrentContext()) { alert(t("err_perm")); return; }
  if (selectedProductKind() === "catalog_spec") { alert(t("component_catalog_locked_save")); return; }
  var err = document.getElementById("component-add-error");
  if (err) err.textContent = "";
  var dkdId = await resolveCurrentCoreDkdShohinId();
  var targetManufacturer = normalizeComponentManufacturerInput(currentProduct.manufacturer) || "UNKNOWN";
  var targetManufacturerPartNumber = normalizeComponentPartNumberInput(currentProduct.manufacturer_part_number || "");
  if (!targetManufacturerPartNumber) {
    if (err) err.textContent = t("component_assy_mfr_pn_required");
    else alert(t("component_assy_mfr_pn_required"));
    return;
  }
  normalizeComponentPartNumberElement(document.getElementById("component-add-mfr-pn"));
  normalizeComponentPartNumberElement(document.getElementById("component-add-genuine-pn"));
  var preAddMfrCheck = componentPartNumberValidation(componentAddValue("component-add-mfr-pn"), "manufacturer");
  var preAddGenuineCheck = componentPartNumberValidation(componentAddValue("component-add-genuine-pn"), "genuine");
  var preAddErrors = preAddMfrCheck.errors.concat(preAddGenuineCheck.errors).filter(function(msg) {
    return msg !== t("component_mfr_pn_required");
  });
  if (preAddErrors.length) {
    updateComponentAddPartNumberInputState();
    if (err) err.textContent = uniqueTextValues(preAddErrors).join("\n");
    else alert(uniqueTextValues(preAddErrors).join("\n"));
    return;
  }
  await reconcileComponentAddPartNumbers();
  normalizeComponentPartNumberElement(document.getElementById("component-add-mfr-pn"));
  normalizeComponentPartNumberElement(document.getElementById("component-add-genuine-pn"));
  var componentMfr = normalizeComponentManufacturerInput(componentAddValue("component-add-mfr")) || "UNKNOWN";
  setComponentAddValue("component-add-mfr", componentMfr);
  var addPartCheck = validateComponentPartNumberInputs(
    componentAddValue("component-add-mfr-pn"),
    componentAddValue("component-add-genuine-pn"),
    componentMfr,
    null
  );
  setComponentAddValue("component-add-mfr-pn", addPartCheck.manufacturerPartNumber);
  setComponentAddValue("component-add-genuine-pn", addPartCheck.genuinePartNumber);
  updateComponentAddPartNumberInputState();
  if (addPartCheck.errors.length) {
    if (err) err.textContent = uniqueTextValues(addPartCheck.errors).join("\n");
    else alert(uniqueTextValues(addPartCheck.errors).join("\n"));
    return;
  }
  if (!confirmComponentPartNumberWarnings(addPartCheck.warnings)) return;
  var componentPartName = canonicalComponentNameForStorage(componentAddValue("component-add-name"));
  setComponentAddValue("component-add-name", componentPartName);
  var componentNameError = componentNameMasterValidationMessage(componentPartName);
  if (componentNameError) {
    if (err) err.textContent = componentNameError;
    else alert(componentNameError);
    return;
  }
  var componentMfrPn = addPartCheck.manufacturerPartNumber;
  if (!componentMfrPn) {
    if (err) err.textContent = t("component_mfr_pn_required");
    else alert(t("component_mfr_pn_required"));
    return;
  }
  applyComponentProcurementRateDefault();
  var replacementRate = normalizeComponentReplacementRateElement(false);
  if (isNaN(replacementRate)) {
    if (err) err.textContent = t("component_replacement_rate_digits");
    else alert(t("component_replacement_rate_digits"));
    return;
  }
  if (replacementRate != null && (replacementRate < 0 || replacementRate > 100)) {
    if (err) err.textContent = t("component_replacement_rate_range");
    else alert(t("component_replacement_rate_range"));
    return;
  }
  var payload = {
    target_dkd_shohin_id: dkdId || null,
    target_manufacturer: targetManufacturer,
    target_manufacturer_part_number: targetManufacturerPartNumber,
    target_genuine_part_number: currentProduct.genuine_part_number || null,
    target_product_kind: selectedProductKind(),
    target_product_variant_id: selectedComponentVariantId(),
    component_manufacturer: componentMfr,
    component_manufacturer_part_number: componentMfrPn,
    component_genuine_part_number: addPartCheck.genuinePartNumber || null,
    component_part_name: componentPartName,
    component_position: componentAddValue("component-add-position") || null,
    component_quantity: componentAddValue("component-add-qty") || "1",
    component_unit_price_jpy: nullableIntFromInput("component-add-unit-price"),
    component_replacement_rate: replacementRate,
    component_manufacturing_memo: componentAddValue("component-add-manufacturing-memo") || null,
    component_interchange_code: componentAddValue("component-add-interchange") || null,
    component_procurement_category: componentAddValue("component-add-procurement-category") || null,
    component_effective_start: componentAddValue("component-add-start") || null,
    component_effective_end: componentAddValue("component-add-end") || null
  };
  var addBtn = document.getElementById("btn-component-add");
  if (addBtn) { addBtn.disabled = true; addBtn.textContent = t("component_add_loading"); }
  var r = await sb.rpc("add_manual_assembly_component", payload);
  if (addBtn) { addBtn.disabled = false; addBtn.textContent = t("component_add"); }
  if (r.error) {
    if (err) err.textContent = t("component_add_failed") + ": " + r.error.message;
    else alert(t("component_add_failed") + ": " + r.error.message);
    return;
  }
  await writeLog("insert", "assembly_component_usages", r.data || dkdId, componentMfrPn, null, payload);
  recordComponentNameCandidateUsageForCurrent(componentPartName);
  clearComponentAddForm();
  closeComponentAddForm();
  if (typeof componentReturnScreen !== "undefined" && componentReturnScreen === "finished-label-mgmt") {
    await loadFinishedLabelComponentCandidates({ includeUsageId: r.data });
    return;
  }
  await loadAssemblyComponentsForCurrent();
}

function componentEditInput(row, field, value) {
  var partNumberField = field === "component_manufacturer_part_number" || field === "component_genuine_part_number";
  var attrs = partNumberField ? " class='component-part-number-edit' inputmode='latin' autocomplete='off' autocapitalize='characters' spellcheck='false'" : "";
  return "<input data-component-edit-field='" + esc(field) + "'" + attrs + " value='" + esc(value || "") + "'>";
}

function componentEditNameInput(row) {
  var value = row.component_name || row.component_part_name || "";
  return "<select data-component-edit-field='component_part_name'>" + componentNameSelectOptionsHtml(value, { baseRow: row }) + "</select><button class='btn-sm-edit production-action-secondary' data-component-name-edit-request='1' type='button'>" + esc(t("component_name_request_open")) + "</button>";
}

function componentProcurementCategoryLabel(value) {
  var keyMap = {
    "部品どり": "component_procurement_parts_donor",
    "自コア再利用": "component_procurement_reuse_core",
    "新品交換": "component_procurement_new_replacement"
  };
  var key = keyMap[String(value || "")];
  return key ? t(key) : (value || "-");
}

function componentProcurementOptionsHtml(value) {
  var current = String(value || "");
  var options = ["", "部品どり", "自コア再利用", "新品交換"];
  return options.map(function(option) {
    var label = option ? componentProcurementCategoryLabel(option) : "-";
    return "<option value='" + esc(option) + "'" + (option === current ? " selected" : "") + ">" + esc(label) + "</option>";
  }).join("");
}

function componentEditProcurementSelect(value) {
  return "<select data-component-edit-field='procurement_category'>" + componentProcurementOptionsHtml(value) + "</select>";
}

function isCatalogComponentRow(row) {
  if (!row) return false;
  if (row.is_catalog_evidence === true) return true;
  var sourceCode = String(row.source_code || "").toLowerCase();
  var sourceTable = String(row.source_table || "").toLowerCase();
  return sourceCode.indexOf("catalog") === 0 || sourceTable.indexOf("catalog") >= 0;
}

function startComponentEdit(usageId) {
  if (!canManageComponentsInCurrentContext()) { alert(t("err_perm")); return; }
  var row = assemblyComponentRows.find(function(r) { return String(r.id) === String(usageId); });
  if (isCatalogComponentRow(row)) {
    alert(t("component_catalog_locked_edit"));
    return;
  }
  editingComponentUsageId = String(usageId);
  componentCatalogNameCandidates = [];
  componentCatalogNameCandidateLabelMap = {};
  componentCatalogNameCandidateKindMap = {};
  componentCatalogNameCandidateMetaMap = {};
  componentCatalogNameCandidateMasterMap = {};
  renderAssemblyComponentRows();
  refreshComponentEditNameCandidates(String(usageId));
}

async function refreshComponentEditNameCandidates(usageId) {
  await loadComponentCatalogNameCandidatesForCurrent();
  if (String(editingComponentUsageId || "") !== String(usageId || "")) return;
  var tr = document.querySelector("[data-component-edit-row='" + String(usageId) + "']");
  var payload = tr ? componentEditPayloadFromRow(tr) : {};
  var editingRow = assemblyComponentRows.find(function(row) { return String(row.id) === String(usageId); }) || null;
  var editingName = payload.component_part_name || (editingRow ? (editingRow.component_name || editingRow.component_part_name || "") : "");
  var list = document.getElementById("component-edit-name-list");
  if (list) list.innerHTML = componentNameOptionsHtml(editingName, { baseRow: editingRow });
  var select = tr ? tr.querySelector("[data-component-edit-field='component_part_name']") : null;
  if (select) setComponentNameSelectOptions(select, editingName, { baseRow: editingRow });
}

function cancelComponentEdit() {
  editingComponentUsageId = null;
  renderAssemblyComponentRows();
}

function componentEditPayloadFromRow(tr) {
  var payload = {};
  tr.querySelectorAll("[data-component-edit-field]").forEach(function(el) {
    payload[el.dataset.componentEditField] = el.value.trim();
  });
  return payload;
}

function componentIsNumericRecordId(value) {
  return /^\d+$/.test(String(value || ""));
}

async function resolveManualComponentUsageId(row, usageId) {
  if (componentIsNumericRecordId(usageId)) return String(usageId);
  if (row && componentIsNumericRecordId(row.id)) return String(row.id);
  if (!row || !row.dkd_component_id) return "";
  var dkdId = await resolveCurrentCoreDkdShohinId();
  if (!dkdId) return "";
  var query = sb.from("assembly_component_usages")
    .select("id")
    .eq("dkd_shohin_id", dkdId)
    .eq("component_id", row.dkd_component_id)
    .eq("is_catalog_evidence", false)
    .eq("product_kind", row.product_kind || selectedProductKind())
    .limit(2);
  if (row.product_variant_id) query = query.eq("product_variant_id", row.product_variant_id);
  var r = await query;
  if (r.error || !r.data || r.data.length !== 1) return "";
  row.id = r.data[0].id;
  return String(r.data[0].id);
}

function setComponentEditFieldValue(tr, field, value) {
  var el = tr ? tr.querySelector("[data-component-edit-field='" + field + "']") : null;
  if (el) el.value = value || "";
}

async function reconcileComponentEditPartNumbers(usageId) {
  var seq = ++componentEditPartNumberLookupSeq;
  var tr = document.querySelector("[data-component-edit-row='" + String(usageId) + "']");
  if (!tr) return null;
  var payload = componentEditPayloadFromRow(tr);
  if (!isCurrentCategoryAssyComponentName(payload.component_part_name)) return null;
  var row = await lookupComponentPartNumberPair(payload.component_manufacturer_part_number, payload.component_genuine_part_number);
  if (seq !== componentEditPartNumberLookupSeq || !row) return row;
  if (row.manufacturer) setComponentEditFieldValue(tr, "component_manufacturer", row.manufacturer);
  if (row.manufacturer_part_number) setComponentEditFieldValue(tr, "component_manufacturer_part_number", row.manufacturer_part_number);
  if (row.genuine_part_number) setComponentEditFieldValue(tr, "component_genuine_part_number", row.genuine_part_number);
  if (!payload.component_part_name && row.part_name) setComponentEditFieldValue(tr, "component_part_name", row.part_name);
  updateComponentEditPartNumberInputStates(tr);
  return row;
}

async function saveComponentEdit(usageId) {
  if (!canManageComponentsInCurrentContext()) { alert(t("err_perm")); return; }
  var row = assemblyComponentRows.find(function(r) { return String(r.id) === String(usageId); });
  if (!row) return;
  if (isCatalogComponentRow(row)) {
    alert(t("component_catalog_locked_save"));
    editingComponentUsageId = null;
    renderAssemblyComponentRows();
    return;
  }
  var resolvedUsageId = await resolveManualComponentUsageId(row, usageId);
  if (!resolvedUsageId) {
    alert("構成部品の使用レコードIDを確認できませんでした。画面を更新して再度お試しください。");
    return;
  }
  var guardR = await sb.from("assembly_component_usages")
    .select("id,is_catalog_evidence")
    .eq("id", resolvedUsageId)
    .maybeSingle();
  if (guardR.error) {
    alert("構成部品の確認に失敗しました: " + guardR.error.message);
    return;
  }
  if (!guardR.data || guardR.data.is_catalog_evidence === true) {
    alert(t("component_catalog_locked_save"));
    editingComponentUsageId = null;
    await loadAssemblyComponentsForCurrent();
    return;
  }
  var tr = document.querySelector("[data-component-edit-row='" + String(usageId) + "']");
  if (!tr) return;
  normalizeComponentPartNumberElement(tr.querySelector("[data-component-edit-field='component_manufacturer_part_number']"));
  normalizeComponentPartNumberElement(tr.querySelector("[data-component-edit-field='component_genuine_part_number']"));
  var preEditPayload = componentEditPayloadFromRow(tr);
  var preEditMfrCheck = componentPartNumberValidation(preEditPayload.component_manufacturer_part_number, "manufacturer");
  var preEditGenuineCheck = componentPartNumberValidation(preEditPayload.component_genuine_part_number, "genuine");
  var preEditErrors = preEditMfrCheck.errors.concat(preEditGenuineCheck.errors).filter(function(msg) {
    return msg !== t("component_mfr_pn_required");
  });
  if (preEditErrors.length) {
    updateComponentEditPartNumberInputStates(tr);
    alert(uniqueTextValues(preEditErrors).join("\n"));
    return;
  }
  await reconcileComponentEditPartNumbers(usageId);
  normalizeComponentPartNumberElement(tr.querySelector("[data-component-edit-field='component_manufacturer_part_number']"));
  normalizeComponentPartNumberElement(tr.querySelector("[data-component-edit-field='component_genuine_part_number']"));
  var payload = componentEditPayloadFromRow(tr);
  var editPartCheck = validateComponentPartNumberInputs(
    payload.component_manufacturer_part_number,
    payload.component_genuine_part_number,
    payload.component_manufacturer || "UNKNOWN",
    usageId
  );
  setComponentEditFieldValue(tr, "component_manufacturer_part_number", editPartCheck.manufacturerPartNumber);
  setComponentEditFieldValue(tr, "component_genuine_part_number", editPartCheck.genuinePartNumber);
  updateComponentEditPartNumberInputStates(tr);
  if (editPartCheck.errors.length) {
    alert(uniqueTextValues(editPartCheck.errors).join("\n"));
    return;
  }
  if (!confirmComponentPartNumberWarnings(editPartCheck.warnings)) return;
  payload = componentEditPayloadFromRow(tr);
  payload.component_part_name = canonicalComponentNameForStorage(payload.component_part_name);
  setComponentEditFieldValue(tr, "component_part_name", payload.component_part_name);
  var editNameError = componentNameMasterValidationMessage(payload.component_part_name);
  if (editNameError) {
    alert(editNameError);
    return;
  }
  var editReplacementRate = String(payload.replacement_rate || "").trim();
  if (editReplacementRate && !/^\d+$/.test(editReplacementRate)) {
    alert(t("component_replacement_rate_digits"));
    return;
  }
  var btn = tr.querySelector("[data-component-save]");
  if (btn) { btn.disabled = true; btn.textContent = t("component_save_loading"); }

  var partUpdate = {
    manufacturer: payload.component_manufacturer || "UNKNOWN",
    manufacturer_part_number: payload.component_manufacturer_part_number,
    genuine_part_number: payload.component_genuine_part_number || null,
    part_name: payload.component_part_name || null,
    updated_by: currentUser ? currentUser.id : null,
    updated_at: new Date().toISOString()
  };
  var usageUpdate = {
    component_position: payload.component_position || null,
    component_name: payload.component_part_name || null,
    quantity: payload.quantity || "1",
    unit_price_jpy: nullableIntFromValue(payload.unit_price_jpy),
    replacement_rate: editReplacementRate ? parseInt(editReplacementRate, 10) : null,
    manufacturing_memo: payload.manufacturing_memo || null,
    procurement_category: payload.procurement_category || null,
    interchange_code: payload.component_interchange_code || null,
    effective_start: payload.effective_start || null,
    effective_end: payload.effective_end || null,
    updated_at: new Date().toISOString()
  };

  var countResult = await sb.from("assembly_component_usages")
    .select("id", { count: "exact", head: true })
    .eq("component_id", row.dkd_component_id);
  if (countResult.error) {
    if (btn) { btn.disabled = false; btn.textContent = t("component_save"); }
    alert("構成部品の使用状況確認に失敗しました: " + countResult.error.message);
    return;
  }
  if ((countResult.count || 0) > 1) {
    var insertPayload = {
      manufacturer: partUpdate.manufacturer,
      manufacturer_part_number: partUpdate.manufacturer_part_number,
      genuine_part_number: partUpdate.genuine_part_number,
      part_name: partUpdate.part_name,
      has_catalog_source: false,
      note: "manual D-CATS component edit clone from " + String(row.dkd_component_id || ""),
      created_by: currentUser ? currentUser.id : null,
      updated_by: currentUser ? currentUser.id : null
    };
    var ins = await sb.from("component_parts").insert(insertPayload).select("dkd_component_id").single();
    if (ins.error) {
      if (btn) { btn.disabled = false; btn.textContent = t("component_save"); }
      alert("構成部品マスタの複製に失敗しました: " + ins.error.message);
      return;
    }
    usageUpdate.component_id = ins.data.dkd_component_id;
  } else {
    var partR = await sb.from("component_parts").update(partUpdate).eq("dkd_component_id", row.dkd_component_id);
    if (partR.error) {
      if (btn) { btn.disabled = false; btn.textContent = t("component_save"); }
      alert("構成部品マスタの更新に失敗しました: " + partR.error.message);
      return;
    }
  }
  var usageR = await sb.from("assembly_component_usages").update(usageUpdate).eq("id", resolvedUsageId).eq("is_catalog_evidence", false);
  if (btn) { btn.disabled = false; btn.textContent = t("component_save"); }
  if (usageR.error) {
    alert("構成部品の更新に失敗しました: " + usageR.error.message);
    return;
  }
  await writeLog("update", "assembly_component_usages", resolvedUsageId, payload.component_manufacturer_part_number, row, payload);
  recordComponentNameCandidateUsageForCurrent(payload.component_part_name);
  editingComponentUsageId = null;
  await loadAssemblyComponentsForCurrent();
}

async function deleteComponentUsage(usageId) {
  if (!canManageComponentsInCurrentContext()) { alert(t("err_perm")); return; }
  var row = assemblyComponentRows.find(function(r) { return String(r.id) === String(usageId); });
  if (!row) return;
  if (isCatalogComponentRow(row)) {
    alert(t("component_catalog_locked_save"));
    editingComponentUsageId = null;
    renderAssemblyComponentRows();
    return;
  }
  if (!confirm(t("component_delete_confirm"))) return;
  var resolvedUsageId = await resolveManualComponentUsageId(row, usageId);
  if (!resolvedUsageId) {
    alert(t("component_delete_failed") + ": 構成部品の使用レコードIDを確認できませんでした。画面を更新して再度お試しください。");
    return;
  }
  var guardR = await sb.from("assembly_component_usages")
    .select("*")
    .eq("id", resolvedUsageId)
    .maybeSingle();
  if (guardR.error) {
    alert(t("component_delete_failed") + ": " + guardR.error.message);
    return;
  }
  if (!guardR.data || guardR.data.is_catalog_evidence === true) {
    alert(t("component_catalog_locked_save"));
    editingComponentUsageId = null;
    await loadAssemblyComponentsForCurrent();
    return;
  }
  var delR = await sb.from("assembly_component_usages")
    .delete()
    .eq("id", resolvedUsageId)
    .eq("is_catalog_evidence", false);
  if (delR.error) {
    alert(t("component_delete_failed") + ": " + delR.error.message);
    return;
  }
  await writeLog("delete", "assembly_component_usages", resolvedUsageId, componentActivityDesc(guardR.data || row), guardR.data, null);
  editingComponentUsageId = null;
  await loadAssemblyComponentsForCurrent();
}

function componentAlternativeBaseText(row) {
  if (!row) return "-";
  return [
    row.component_position || row.source_code || "",
    row.component_name || row.component_part_name || "",
    row.component_manufacturer_part_number || "",
    row.component_genuine_part_number || ""
  ].filter(Boolean).join(" / ") || "-";
}

function alternativesForComponent(row) {
  if (!row || row.dkd_component_id == null) return [];
  if (row._ui_alternatives && row._ui_alternatives.length) return row._ui_alternatives;
  return componentAlternativeMap[String(row.dkd_component_id)] || [];
}

function componentTreeKey(row) {
  if (!row) return "";
  if (row.dkd_component_id != null) return "component:" + String(row.dkd_component_id);
  return [
    "row",
    row.component_manufacturer || "",
    row.component_manufacturer_part_number || "",
    row.component_genuine_part_number || "",
    row.component_position || ""
  ].join("|");
}

function parseComponentAlternativesJson(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value;
  if (typeof value === "string") {
    try {
      var parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }
  return [];
}

function normalizeComponentAlternativeForUi(alt) {
  alt = alt || {};
  var supplierRows = [];
  if (alt.preferred_supplier_name || alt.preferred_reference_price != null) {
    supplierRows.push({
      supplier_name: alt.preferred_supplier_name || "",
      reference_price: alt.preferred_reference_price,
      currency: alt.preferred_currency || "JPY",
      status: "active",
      is_preferred: true
    });
  }
  return {
    id: alt.alternative_id || alt.id || "",
    catalog_component_id: alt.catalog_component_id || null,
    product_variant_id: alt.product_variant_id || null,
    component_position: alt.component_position || null,
    relation_type: alt.relation_type || "alternative",
    priority: alt.priority || 100,
    status: alt.status || "active",
    note: alt.note || "",
    internal_component_part_id: alt.internal_component_part_id || null,
    internal_component_parts: {
      id: alt.internal_component_part_id || null,
      manufacturer: alt.manufacturer || "",
      part_number: alt.part_number || "",
      part_name: alt.part_name || "",
      note: alt.note || "",
      status: "active"
    },
    internal_component_suppliers: supplierRows
  };
}

function componentTreeRowCatalogEvidence(row) {
  if (!row) return false;
  if (row.is_catalog_evidence === true) return true;
  if (row.is_catalog_evidence === false) return false;
  if (String(row.product_kind || "") === "catalog_spec") return true;
  return String(row.catalog_match_basis || "").indexOf("catalog_") === 0;
}

function normalizeComponentTreeRow(row, parentRow) {
  row = row || {};
  var alternatives = parseComponentAlternativesJson(row.alternatives).map(normalizeComponentAlternativeForUi);
  var dkdComponentId = row.dkd_component_id || row.component_id || null;
  var usageId = row.id || row.usage_id || row.assembly_component_usage_id || null;
  return Object.assign({}, row, {
    id: usageId || (dkdComponentId ? ("component:" + String(dkdComponentId)) : componentTreeKey(row)),
    dkd_component_id: dkdComponentId,
    component_position: row.component_position || row.figure_number || "",
    component_name: row.component_name || row.component_part_name || "",
    component_part_name: row.component_part_name || row.component_name || "",
    component_manufacturer: row.component_manufacturer || row.manufacturer || "",
    component_manufacturer_part_number: row.component_manufacturer_part_number || row.manufacturer_part_number || "",
    component_genuine_part_number: row.component_genuine_part_number || row.genuine_part_number || "",
    quantity: row.quantity || "1",
    unit_price_jpy: row.unit_price_jpy != null ? row.unit_price_jpy : row.component_unit_price_jpy,
    replacement_rate: row.replacement_rate != null ? row.replacement_rate : row.component_replacement_rate,
    manufacturing_memo: row.manufacturing_memo != null ? row.manufacturing_memo : row.component_manufacturing_memo,
    procurement_category: row.procurement_category != null ? row.procurement_category : row.component_procurement_category,
    component_interchange_code: row.component_interchange_code || row.interchange_code || "",
    source_code: row.source_code || "",
    is_catalog_evidence: componentTreeRowCatalogEvidence(row),
    has_child_catalog_components: !!(row.has_child_catalog_components || parseInt(row.child_catalog_component_count || 0, 10) > 0),
    child_catalog_component_count: parseInt(row.child_catalog_component_count || 0, 10) || 0,
    alternative_count: parseInt(row.alternative_count || alternatives.length || 0, 10) || 0,
    _ui_alternatives: alternatives,
    _ui_parent_component_key: parentRow ? componentTreeKey(parentRow) : "",
    _ui_is_child_component: !!parentRow
  });
}

function componentCurrentProductGenuineKeys() {
  return uniqueTextValues([
    normalizedPartKey(currentProduct && currentProduct.genuine_part_number),
    normalizedPartKey(currentProduct && currentProduct.genuine_part_number_2)
  ].filter(Boolean));
}

function componentIsCurrentProductSelfReference(row) {
  if (!row || !currentProduct) return false;
  var productMfrKey = normalizedPartKey(currentProduct.manufacturer_part_number);
  var rowMfrKey = normalizedPartKey(row.component_manufacturer_part_number);
  if (!productMfrKey || !rowMfrKey || productMfrKey !== rowMfrKey) return false;
  var productGenuineKeys = componentCurrentProductGenuineKeys();
  var rowGenuineKey = normalizedPartKey(row.component_genuine_part_number);
  if (!productGenuineKeys.length) return true;
  return !!rowGenuineKey && productGenuineKeys.indexOf(rowGenuineKey) >= 0;
}

function componentRowChildCount(row) {
  return parseInt(row && row.child_catalog_component_count || 0, 10) || 0;
}

function componentHasChildRows(row) {
  return !!(row && !componentIsCurrentProductSelfReference(row) && (row.has_child_catalog_components || componentRowChildCount(row) > 0));
}

async function hydrateComponentChildCounts(rows) {
  rows = Array.isArray(rows) ? rows : [];
  var targets = rows.filter(function(row) {
    return row && !componentIsCurrentProductSelfReference(row) && !componentHasChildRows(row) && row.component_manufacturer_part_number;
  });
  await Promise.all(targets.map(async function(row) {
    var r = await sb.rpc("get_catalog_assembly_component_count", {
      target_manufacturer: row.component_manufacturer || (currentProduct && currentProduct.manufacturer) || null,
      target_manufacturer_part_number: row.component_manufacturer_part_number || null,
      target_genuine_part_number: row.component_genuine_part_number || null
    });
    if (r.error) {
      console.warn("get_catalog_assembly_component_count failed", r.error);
      return;
    }
    var count = parseInt(Array.isArray(r.data) ? r.data[0] : r.data, 10) || 0;
    row.child_catalog_component_count = count;
    row.has_child_catalog_components = count > 0;
  }));
  return rows;
}

function componentChildToggleHtml(row) {
  if (!componentHasChildRows(row)) return "";
  var key = componentTreeKey(row);
  var expanded = !!componentExpandedChildMap[key];
  var loading = !!componentChildLoadingMap[key];
  var count = componentRowChildCount(row);
  var symbol = loading ? "..." : (expanded ? "-" : "+");
  return "<button class='component-tree-toggle" + (loading ? " loading" : "") + "' type='button' data-component-child-toggle='" + esc(key) + "'>" + esc(symbol) + "</button>" +
    "<span class='component-tree-count'>" + esc(String(count)) + "</span>";
}

function componentAlternativeCountHtml(row) {
  var count = alternativesForComponent(row).length || parseInt(row && row.alternative_count || 0, 10) || 0;
  return "<span class='component-alt-badge" + (count ? " has-alt" : "") + "'>" + esc(String(count)) + "</span>";
}

function componentSourceBadgeHtml(row) {
  if (!isCatalogComponentRow(row)) return "";
  return "<span class='component-source-badge'>" + esc(t("component_catalog")) + "</span>";
}

function componentIllustrationPublicUrl(row) {
  if (!row || !row.image_bucket || !row.image_path) return "";
  return row.signed_image_url || "";
}

async function signComponentIllustrationRows(rows) {
  return Promise.all((rows || []).map(async function(row) {
    if (!row || !row.image_bucket || !row.image_path) return row;
    var result = await sb.storage
      .from(row.image_bucket)
      .createSignedUrl(row.image_path, PRODUCT_IMAGE_SIGNED_URL_TTL_SECONDS);
    if (result.error) throw result.error;
    var signedUrl = result.data && (
      result.data.signedUrl || result.data.signedURL || result.data.publicUrl
    ) || "";
    if (!signedUrl) throw new Error("Catalog illustration signed URL is empty");
    return Object.assign({}, row, { signed_image_url: signedUrl });
  }));
}

function componentIllustrationPoints(row) {
  var points = row && row.points;
  if (typeof points === "string") {
    try {
      points = JSON.parse(points);
    } catch (e) {
      points = [];
    }
  }
  return Array.isArray(points) ? points : [];
}

function componentIllustrationPointLabel(point) {
  var label = String((point && point.component_position) || "").trim();
  return label || "*";
}

function componentIllustrationPointTitle(point) {
  if (!point) return "";
  return [
    point.component_position,
    point.component_name,
    point.component_manufacturer_part_number,
    point.component_genuine_part_number
  ].filter(function(value) { return value != null && String(value).trim() !== ""; }).join(" / ");
}

function componentIllustrationPointSvg(point, index, imageWidth, imageHeight) {
  var x = Number(point && point.x_px);
  var y = Number(point && point.y_px);
  if (!isFinite(x) || !isFinite(y)) return "";
  x = Math.max(0, Math.min(imageWidth, x));
  y = Math.max(0, Math.min(imageHeight, y));
  var markerScale = Math.max(1, Math.min(imageWidth / 615, imageHeight / 487));
  var markerRadius = 7 * markerScale;
  var labelOffset = 4 * markerScale;
  var labelSize = 10 * markerScale;
  var label = componentIllustrationPointLabel(point);
  var title = componentIllustrationPointTitle(point);
  return "<g class='catalog-illustration-point' data-catalog-point='" + esc(String(index)) + "'>"
    + "<title>" + esc(title || label) + "</title>"
    + "<circle cx='" + esc(String(x)) + "' cy='" + esc(String(y)) + "' r='" + esc(String(markerRadius)) + "'></circle>"
    + "<text x='" + esc(String(x)) + "' y='" + esc(String(y + labelOffset)) + "' font-size='" + esc(String(labelSize)) + "'>" + esc(label) + "</text>"
    + "</g>";
}

function componentIllustrationDimensions(row) {
  var width = Number(row && row.image_width);
  var height = Number(row && row.image_height);
  return {
    width: isFinite(width) && width > 0 ? width : 615,
    height: isFinite(height) && height > 0 ? height : 487
  };
}

function renderComponentIllustrationPanelHtml() {
  if (selectedProductKind() !== "catalog_spec") return "";
  if (componentIllustrationLoading) {
    return "<div class='catalog-illustration-panel'><div class='catalog-illustration-head'><div class='catalog-illustration-title'>カタログ図</div></div><div class='component-empty'>" + t("loading") + "</div></div>";
  }
  if (componentIllustrationError) {
    return "<div class='catalog-illustration-panel catalog-illustration-error'><div class='catalog-illustration-head'><div class='catalog-illustration-title'>カタログ図</div><button class='catalog-illustration-tool' type='button' data-catalog-retry title='再読み込み' aria-label='カタログ図を再読み込み'>↻</button></div><div>" + esc(componentIllustrationError) + "</div></div>";
  }
  var rows = componentIllustrationRows || [];
  if (!rows.length) {
    return "<div class='catalog-illustration-panel catalog-illustration-empty'><div class='catalog-illustration-head'><div class='catalog-illustration-title'>カタログ図</div></div><div class='component-empty'>カタログ図は登録されていません</div></div>";
  }
  var html = "<div class='catalog-illustration-panel'>";
  html += "<div class='catalog-illustration-head'><div class='catalog-illustration-title'>カタログ図</div><div class='catalog-illustration-meta'>" + esc(String(rows.length)) + "枚</div></div>";
  html += "<div class='catalog-illustration-list'>";
  rows.forEach(function(row) {
    var url = componentIllustrationPublicUrl(row);
    if (!url) return;
    var points = componentIllustrationPoints(row);
    var dimensions = componentIllustrationDimensions(row);
    var imageLabel = row.model_id || row.assy_manufacturer_part_number || "catalog illustration";
    var imageClass = "catalog-illustration-image";
    if (String(row.source_code || "").toLowerCase() === "catalog_denso") {
      imageClass += " catalog-illustration-image-denso";
    }
    html += "<div class='catalog-illustration-card'>";
    html += "<div class='catalog-illustration-card-head'><div class='catalog-illustration-card-label'><div class='component-pn'>" + esc(imageLabel) + "</div><div class='component-sub'>" + esc(row.source_html || row.catalog_match_basis || "") + "</div></div>";
    html += "<div class='catalog-illustration-actions'>";
    html += "<button class='catalog-illustration-tool' type='button' data-catalog-action='zoom-out' title='縮小' aria-label='縮小'>−</button>";
    html += "<span class='catalog-illustration-zoom' data-catalog-zoom-label>100%</span>";
    html += "<button class='catalog-illustration-tool' type='button' data-catalog-action='zoom-in' title='拡大' aria-label='拡大'>＋</button>";
    html += "<button class='catalog-illustration-tool' type='button' data-catalog-action='reset' title='全体表示' aria-label='全体表示'>↺</button>";
    html += "</div></div>";
    html += "<div class='catalog-illustration-frame' data-catalog-viewport data-catalog-width='" + esc(String(dimensions.width)) + "' data-catalog-height='" + esc(String(dimensions.height)) + "' tabindex='0' aria-label='" + esc(imageLabel) + "'>";
    html += "<svg class='catalog-illustration-canvas' data-catalog-canvas viewBox='0 0 " + esc(String(dimensions.width)) + " " + esc(String(dimensions.height)) + "' preserveAspectRatio='xMidYMid meet' role='img' aria-label='" + esc(imageLabel) + "'>";
    html += "<image class='" + esc(imageClass) + "' href='" + esc(url) + "' x='0' y='0' width='" + esc(String(dimensions.width)) + "' height='" + esc(String(dimensions.height)) + "' preserveAspectRatio='xMidYMid meet'></image>";
    points.forEach(function(point, index) {
      html += componentIllustrationPointSvg(point, index, dimensions.width, dimensions.height);
    });
    html += "</svg>";
    html += "</div>";
    html += "</div>";
  });
  html += "</div></div>";
  return html;
}

function catalogIllustrationViewBox(svg) {
  var values = String(svg && svg.getAttribute("viewBox") || "").trim().split(/\s+/).map(Number);
  if (values.length !== 4 || values.some(function(value) { return !isFinite(value); })) return null;
  return { x: values[0], y: values[1], width: values[2], height: values[3] };
}

function setCatalogIllustrationViewBox(viewport, x, y, width, height) {
  var svg = viewport && viewport.querySelector("[data-catalog-canvas]");
  if (!svg) return;
  var baseWidth = Number(viewport.dataset.catalogWidth) || 615;
  var baseHeight = Number(viewport.dataset.catalogHeight) || 487;
  var minWidth = baseWidth / 6;
  var minHeight = baseHeight / 6;
  width = Math.max(minWidth, Math.min(baseWidth, width));
  height = Math.max(minHeight, Math.min(baseHeight, height));
  x = Math.max(0, Math.min(baseWidth - width, x));
  y = Math.max(0, Math.min(baseHeight - height, y));
  svg.setAttribute("viewBox", [x, y, width, height].join(" "));
  var label = viewport.closest(".catalog-illustration-card");
  label = label && label.querySelector("[data-catalog-zoom-label]");
  if (label) label.textContent = String(Math.round((baseWidth / width) * 100)) + "%";
}

function zoomCatalogIllustration(viewport, multiplier, clientX, clientY) {
  var svg = viewport && viewport.querySelector("[data-catalog-canvas]");
  var current = catalogIllustrationViewBox(svg);
  if (!current) return;
  var baseWidth = Number(viewport.dataset.catalogWidth) || 615;
  var baseHeight = Number(viewport.dataset.catalogHeight) || 487;
  var currentScale = baseWidth / current.width;
  var nextScale = Math.max(1, Math.min(6, currentScale * multiplier));
  var nextWidth = baseWidth / nextScale;
  var nextHeight = baseHeight / nextScale;
  var rect = viewport.getBoundingClientRect();
  var ratioX = clientX == null || !rect.width ? 0.5 : Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
  var ratioY = clientY == null || !rect.height ? 0.5 : Math.max(0, Math.min(1, (clientY - rect.top) / rect.height));
  var anchorX = current.x + current.width * ratioX;
  var anchorY = current.y + current.height * ratioY;
  setCatalogIllustrationViewBox(
    viewport,
    anchorX - nextWidth * ratioX,
    anchorY - nextHeight * ratioY,
    nextWidth,
    nextHeight
  );
}

function resetCatalogIllustration(viewport) {
  var baseWidth = Number(viewport && viewport.dataset.catalogWidth) || 615;
  var baseHeight = Number(viewport && viewport.dataset.catalogHeight) || 487;
  setCatalogIllustrationViewBox(viewport, 0, 0, baseWidth, baseHeight);
}

function bindCatalogIllustrationInteractions(root) {
  root = root || document;
  root.querySelectorAll("[data-catalog-viewport]").forEach(function(viewport) {
    if (viewport.dataset.catalogBound === "1") return;
    viewport.dataset.catalogBound = "1";
    var drag = null;

    viewport.addEventListener("wheel", function(event) {
      event.preventDefault();
      zoomCatalogIllustration(viewport, event.deltaY < 0 ? 1.2 : (1 / 1.2), event.clientX, event.clientY);
    }, { passive: false });

    viewport.addEventListener("pointerdown", function(event) {
      if (event.button !== 0) return;
      var current = catalogIllustrationViewBox(viewport.querySelector("[data-catalog-canvas]"));
      if (!current) return;
      drag = { pointerId: event.pointerId, x: event.clientX, y: event.clientY, viewBox: current };
      viewport.setPointerCapture(event.pointerId);
      viewport.classList.add("is-dragging");
    });

    viewport.addEventListener("pointermove", function(event) {
      if (!drag || drag.pointerId !== event.pointerId) return;
      var rect = viewport.getBoundingClientRect();
      if (!rect.width || !rect.height) return;
      setCatalogIllustrationViewBox(
        viewport,
        drag.viewBox.x - ((event.clientX - drag.x) * drag.viewBox.width / rect.width),
        drag.viewBox.y - ((event.clientY - drag.y) * drag.viewBox.height / rect.height),
        drag.viewBox.width,
        drag.viewBox.height
      );
    });

    var finishDrag = function(event) {
      if (!drag || (event && drag.pointerId !== event.pointerId)) return;
      drag = null;
      viewport.classList.remove("is-dragging");
    };
    viewport.addEventListener("pointerup", finishDrag);
    viewport.addEventListener("pointercancel", finishDrag);
    viewport.addEventListener("lostpointercapture", finishDrag);
    viewport.addEventListener("dblclick", function() { resetCatalogIllustration(viewport); });
    viewport.addEventListener("keydown", function(event) {
      if (event.key === "+" || event.key === "=") {
        event.preventDefault();
        zoomCatalogIllustration(viewport, 1.2);
      } else if (event.key === "-") {
        event.preventDefault();
        zoomCatalogIllustration(viewport, 1 / 1.2);
      } else if (event.key === "0") {
        event.preventDefault();
        resetCatalogIllustration(viewport);
      } else if (["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].indexOf(event.key) >= 0) {
        var current = catalogIllustrationViewBox(viewport.querySelector("[data-catalog-canvas]"));
        if (!current) return;
        event.preventDefault();
        var dx = event.key === "ArrowLeft" ? -current.width * 0.08 : event.key === "ArrowRight" ? current.width * 0.08 : 0;
        var dy = event.key === "ArrowUp" ? -current.height * 0.08 : event.key === "ArrowDown" ? current.height * 0.08 : 0;
        setCatalogIllustrationViewBox(viewport, current.x + dx, current.y + dy, current.width, current.height);
      }
    });
  });

  root.querySelectorAll("[data-catalog-action]").forEach(function(button) {
    button.addEventListener("click", function() {
      var card = button.closest(".catalog-illustration-card");
      var viewport = card && card.querySelector("[data-catalog-viewport]");
      if (!viewport) return;
      if (button.dataset.catalogAction === "zoom-in") zoomCatalogIllustration(viewport, 1.2);
      if (button.dataset.catalogAction === "zoom-out") zoomCatalogIllustration(viewport, 1 / 1.2);
      if (button.dataset.catalogAction === "reset") resetCatalogIllustration(viewport);
    });
  });

  root.querySelectorAll("[data-catalog-retry]").forEach(function(button) {
    button.addEventListener("click", retryCatalogIllustrationLoad);
  });
}

function renderComponentIllustrationSlot() {
  var slot = document.getElementById("component-illustration-slot");
  if (!slot) return;
  slot.innerHTML = renderComponentIllustrationPanelHtml();
  bindCatalogIllustrationInteractions(slot);
}

async function retryCatalogIllustrationLoad() {
  var dkdId = await resolveCurrentCoreDkdShohinId();
  if (!dkdId) return;
  await loadCatalogIllustrationsForCurrent(dkdId, selectedProductKind());
  renderComponentIllustrationSlot();
}

async function loadCatalogIllustrationsForCurrent(dkdId, selectedKind) {
  var requestId = ++componentIllustrationRequestId;
  componentIllustrationRows = [];
  componentIllustrationLoading = false;
  componentIllustrationError = "";
  if (selectedKind !== "catalog_spec" || !dkdId) return;
  componentIllustrationLoading = true;
  renderComponentIllustrationSlot();
  try {
    var r = await sb.rpc("get_catalog_illustration_for_product", {
      target_dkd_shohin_id: dkdId,
      target_product_kind: selectedKind
    });
    if (r.error) {
      if (requestId !== componentIllustrationRequestId) return;
      componentIllustrationLoading = false;
      componentIllustrationError = "カタログ図を読み込めませんでした: " + (r.error.message || r.error.details || r.error.code || "");
      console.warn("get_catalog_illustration_for_product failed", r.error);
      renderComponentIllustrationSlot();
      return;
    }
    var signedRows = await signComponentIllustrationRows(r.data || []);
    if (requestId !== componentIllustrationRequestId) return;
    componentIllustrationLoading = false;
    componentIllustrationRows = signedRows;
    renderComponentIllustrationSlot();
  } catch (e) {
    if (requestId !== componentIllustrationRequestId) return;
    componentIllustrationLoading = false;
    componentIllustrationError = "カタログ図を読み込めませんでした";
    console.warn("get_catalog_illustration_for_product failed", e);
    renderComponentIllustrationSlot();
  }
}

async function loadComponentChildRows(row) {
  if (!row || !componentHasChildRows(row)) return [];
  var key = componentTreeKey(row);
  if (componentChildRowsMap[key] && componentChildRowsMap[key].length) return componentChildRowsMap[key];
  delete componentChildMessageMap[key];
  componentChildLoadingMap[key] = true;
  renderAssemblyComponentRows();
  var r = await sb.rpc("get_catalog_component_children_for_ui", {
    target_manufacturer: row.component_manufacturer || null,
    target_manufacturer_part_number: row.component_manufacturer_part_number || null,
    target_genuine_part_number: row.component_genuine_part_number || null,
    target_product_variant_id: selectedProductKind() === "catalog_spec" ? null : selectedComponentVariantId(),
    max_rows: 500
  });
  componentChildLoadingMap[key] = false;
  var childRows = [];
  var childError = r.error || null;
  if (r.error) {
    console.warn("get_catalog_component_children_for_ui failed", r.error);
  } else {
    childRows = (r.data || []).map(function(child) {
      return normalizeComponentTreeRow(child, row);
    });
  }
  if (!childRows.length && componentRowChildCount(row) > 0) {
    var fallback = await sb.rpc("get_catalog_assembly_components_by_part", {
      target_manufacturer: row.component_manufacturer || null,
      target_manufacturer_part_number: row.component_manufacturer_part_number || null,
      target_genuine_part_number: row.component_genuine_part_number || null,
      max_rows: 500
    });
    if (fallback.error) {
      console.warn("get_catalog_assembly_components_by_part failed", fallback.error);
      childError = childError || fallback.error;
    } else {
      childRows = (fallback.data || []).map(function(child) {
        return normalizeComponentTreeRow(child, row);
      });
      childError = null;
    }
  }
  componentChildRowsMap[key] = childRows;
  if (!childRows.length) {
    componentChildMessageMap[key] = {
      type: childError ? "error" : "empty",
      message: childError ? (t("component_child_load_failed") + ": " + (childError.message || childError.details || childError.code || "")) : t("component_child_empty")
    };
  }
  return componentChildRowsMap[key];
}

async function toggleComponentChildRows(key) {
  var row = (assemblyComponentRows || []).find(function(candidate) {
    return componentTreeKey(candidate) === key;
  });
  if (!row) return;
  if (componentExpandedChildMap[key]) {
    delete componentExpandedChildMap[key];
    renderAssemblyComponentRows();
    return;
  }
  componentExpandedChildMap[key] = true;
  try {
    await loadComponentChildRows(row);
  } catch (e) {
    componentChildLoadingMap[key] = false;
    console.warn("component child load failed", e);
    alert(t("component_child_load_failed") + ": " + (e && e.message ? e.message : e));
  }
  renderAssemblyComponentRows();
}

function componentNameMojibakeScore(text) {
  text = String(text || "");
  var matches = text.match(/[�ÃÂãâ繧繝縺譁莨]/g);
  return matches ? matches.length : 0;
}

function tryRepairLatin1Utf8Mojibake(text) {
  text = String(text || "");
  if (!/[ÃÂãâ]/.test(text) || typeof TextDecoder === "undefined") return text;
  try {
    var bytes = new Uint8Array(text.split("").map(function(ch) { return ch.charCodeAt(0) & 0xff; }));
    var repaired = new TextDecoder("utf-8").decode(bytes);
    if (repaired && componentNameMojibakeScore(repaired) < componentNameMojibakeScore(text)) return repaired;
  } catch (e) {}
  return text;
}

function normalizeComponentNameText(value) {
  var text = String(value || "").trim();
  if (!text) return "";
  text = tryRepairLatin1Utf8Mojibake(text);
  if (typeof text.normalize === "function") text = text.normalize("NFKC");
  text = text
    .replace(/[\u2010-\u2015\u2212\uFF0D]/g, "-")
    .replace(/\s+/g, " ")
    .trim();
  if (!text || componentNameMojibakeScore(text) > 0) return "";
  return text;
}

function componentNameCanonicalJaMap() {
  return {
    "ASSY": "アッセンブリ",
    "BEARING, BALL": "ベアリング,ボール",
    "BOLT": "ボルト",
    "BOLT, THROUGH": "ボルト,スルー",
    "BOLT, W/WASHER": "ボルト,W/ワッシャ",
    "BUSH, BEARING": "ブッシュ",
    "BUSHING": "ブッシュ",
    "CAP, PULLEY": "キャップ,プーリ",
    "CLIP, CORD": "クリップ,ワイヤ",
    "COVER, BEARING": "カバー,ベアリング",
    "COVER, END, RR": "カバー,リヤ エンド",
    "FRAME ASSY, DRIVE END": "フレームS/A,ドライブエンド",
    "FRAME ASSY, END, RR": "フレームS/A,リヤエンド",
    "FRAME, DRIVE END": "フレーム,ドライブ エンド",
    "HOLDER SUB-ASSY, BRUSH": "ホルダS/A,ブラシ",
    "HOLDER, W/RECTIFIER": "ホルダS/A,レクチファイヤ",
    "INSULATION BUSH, TERMINAL": "ブッシュ,ターミナル",
    "NUT": "ナット",
    "PLATE, RETAINER": "プレート,リテーナ",
    "PULLEY": "プーリ",
    "PULLEY ASSY": "プーリAY",
    "REGULATOR ASSY, GENERATOR": "レギュレータAY",
    "ROTER SUB-ASSY": "ロータS/A",
    "ROTOR ASSY": "ロータAY",
    "ROTOR SUB-ASSY": "ロータS/A",
    "SCREW": "スクリュ",
    "SCREW, W/WASHER": "スクリュ,W/ワッシャ",
    "STATOR ASSY": "ステータ"
  };
}

function canonicalComponentNameForStorage(value) {
  var text = normalizeComponentNameText(value);
  if (isComponentNameOptionGroupValue(text)) return "";
  if (!text) return "";
  return componentNameCanonicalJaMap()[text.toUpperCase()] || componentDisplayNameToCanonicalName(text) || text;
}

function componentNameDuplicateKey(value) {
  if (isComponentNameOptionGroupValue(value)) return "";
  return normalizeComponentNameText(value)
    .replace(/[ァぁ]/g, "ア")
    .replace(/[ィぃ]/g, "イ")
    .replace(/[ゥぅ]/g, "ウ")
    .replace(/[ェぇ]/g, "エ")
    .replace(/[ォぉ]/g, "オ")
    .replace(/[ャゃ]/g, "ヤ")
    .replace(/[ュゅ]/g, "ユ")
    .replace(/[ョょ]/g, "ヨ")
    .replace(/[ッっ]/g, "ツ")
    .toUpperCase();
}

function addComponentNameCandidate(list, seen, value) {
  var text = canonicalComponentNameForStorage(value);
  if (!text) return;
  var key = componentNameDuplicateKey(text);
  if (seen[key]) return;
  seen[key] = true;
  list.push(text);
}

function mergeComponentNameCandidates(list, seen, values) {
  (values || []).forEach(function(value) {
    addComponentNameCandidate(list, seen, value);
  });
}

function componentAlternativeNameCandidates(baseRow, selectedName) {
  var list = [];
  var seen = {};
  addComponentNameCandidate(list, seen, baseRow && (baseRow.component_name || baseRow.component_part_name));
  (assemblyComponentRows || []).forEach(function(row) {
    addComponentNameCandidate(list, seen, row.component_name || row.component_part_name);
  });
  (componentAlternativeRows || []).forEach(function(alt) {
    var part = alt.internal_component_parts || {};
    addComponentNameCandidate(list, seen, part.part_name);
  });
  (componentCatalogNameCandidates || []).forEach(function(name) {
    addComponentNameCandidate(list, seen, name);
  });
  appendComponentNameDefaultCandidates(list, seen, componentCatalogCategoryCode(currentProduct));
  addComponentNameCandidate(list, seen, selectedName);
  return list;
}

function componentCatalogCategoryCode(product) {
  var raw = String((product && (product.category_code || product.category)) || "").trim();
  var key = raw.toLowerCase().replace(/[_\s-]+/g, "_");
  if (key === "starter" || key === "alternator" || key === "ac_compressor" || key === "distributor" || key === "starter_generator" || key === "dc_motor") return key;
  var source = categoryTranslationSource(raw).toLowerCase();
  if (source.indexOf("ac compressor") >= 0) return "ac_compressor";
  if (source.indexOf("starter generator") >= 0) return "starter_generator";
  if (source.indexOf("alternator") >= 0) return "alternator";
  if (source.indexOf("starter") >= 0) return "starter";
  if (source.indexOf("distributor") >= 0) return "distributor";
  if (source.indexOf("dc motor") >= 0) return "dc_motor";
  if (raw.indexOf("コンプレッサ") >= 0) return "ac_compressor";
  if (raw.indexOf("オルタ") >= 0) return "alternator";
  if (raw.indexOf("スタータ") >= 0) return raw.indexOf("ジェネレータ") >= 0 ? "starter_generator" : "starter";
  if (raw.indexOf("ディストリ") >= 0) return "distributor";
  return key || "";
}

function componentAssyNameCandidatesForCategory(category) {
  category = String(category || "").toLowerCase();
  if (category === "ac_compressor") {
    return [
      "コンプレッサ",
      "コンプレッサAY",
      "コンプレッサASSY",
      "コンプレッサAY,W/クラッチ",
      "コンプレッサASSY,W/クラッチ",
      "コンプレッサAY,W/プーリ"
    ];
  }
  if (category === "alternator") {
    return [
      "オルタネータ",
      "オルタネータAY",
      "オルタネータASSY",
      "オルタネータAY,W/レギュレータ",
      "オルタネータASSY,W/レギュレータ",
      "オルタネータ,W/レギュレータ",
      "オルタネータ,W/VPレギュレータ",
      "オルタネータAY,W/Vポンプ",
      "オルタネータASSY,W/Vポンプ"
    ];
  }
  if (category === "starter") {
    return [
      "スタータ",
      "スタータAY",
      "スタータASSY"
    ];
  }
  if (category === "starter_generator") {
    return [
      "スタータジェネレータ",
      "スタータジェネレータAY",
      "スタータジェネレータASSY"
    ];
  }
  if (category === "distributor") {
    return [
      "ディストリビュータ",
      "ディストリビュータAY",
      "ディストリビュータASSY"
    ];
  }
  if (category === "dc_motor") {
    return [
      "モータ",
      "モータAY",
      "モータASSY"
    ];
  }
  return [];
}

function isCurrentCategoryAssyComponentName(value) {
  var text = normalizeComponentNameText(value);
  if (!text) return false;
  var normalizedKeys = [componentNameDuplicateKey(text)];
  var canonical = canonicalComponentNameForStorage(text);
  if (canonical) normalizedKeys.push(componentNameDuplicateKey(canonical));
  normalizedKeys = uniqueTextValues(normalizedKeys).filter(Boolean);
  var candidates = componentAssyNameCandidatesForCategory(componentCatalogCategoryCode(currentProduct));
  return candidates.some(function(name) {
    var candidateKeys = [componentNameDuplicateKey(name)];
    var translated = componentNameTranslationLabel(name);
    if (translated) candidateKeys.push(componentNameDuplicateKey(translated));
    candidateKeys = uniqueTextValues(candidateKeys).filter(Boolean);
    return candidateKeys.some(function(candidateKey) {
      return normalizedKeys.indexOf(candidateKey) >= 0;
    });
  });
}

