function appendComponentNameDefaultCandidates(list, seen, category) {
  componentNameDefaultCandidatesForCategory(category).forEach(function(name) {
    addComponentNameCandidate(list, seen, name);
  });
}

function componentNameCandidateLabelKey(value) {
  return componentNameDuplicateKey(value);
}

function addComponentNameCandidateLabel(labelMap, candidateName, displayName) {
  var value = normalizeComponentNameText(candidateName);
  var label = normalizeComponentNameText(displayName);
  if (!value || !label || value === label) return;
  labelMap[componentNameCandidateLabelKey(value)] = label;
}

function lookupComponentNameTranslation(dict, name) {
  var key = componentNameCandidateLabelKey(name);
  if (!key) return "";
  var normalizedName = normalizeComponentNameText(name);
  if (dict[normalizedName]) return dict[normalizedName];
  for (var sourceName in dict) {
    if (componentNameCandidateLabelKey(sourceName) === key) return dict[sourceName];
  }
  return "";
}

