function salesPricingCurrentProductKind() {
  var select = document.getElementById("sales-product-kind");
  return normalizeProductKind((select && select.value) || currentSalesPricingProductKind || "rebuilt");
}

function salesPricingProductVariantIdForKind(kind) {
  var targetKind = normalizeProductKind(kind || "rebuilt");
  var rows = productKindRowsForCurrent().filter(function(row) {
    return normalizeProductKind(row.product_kind) === targetKind && row.product_variant_id;
  });
  rows.sort(function(a, b) {
    if (!!a.sl_part_id !== !!b.sl_part_id) return a.sl_part_id ? 1 : -1;
    return (parseInt(a.product_variant_id || 0, 10) || 0) - (parseInt(b.product_variant_id || 0, 10) || 0);
  });
  return rows.length ? rows[0].product_variant_id : null;
}

function applySalesPricingRowToForm(row) {
  currentSalesPricingRow = row || null;
  document.getElementById("sales-base-price").value = currentSalesPricingRow ? currentSalesPricingRow.base_price_jpy : ((currentProduct && currentProduct.price_jpy) || "");
  document.getElementById("sales-price-basis").value = currentSalesPricingRow ? (currentSalesPricingRow.price_basis || "manual") : "manual";
  document.getElementById("sales-effective-start").value = currentSalesPricingRow ? (currentSalesPricingRow.effective_start || salesPricingTodayIso()) : salesPricingTodayIso();
  document.getElementById("sales-basis-note").value = currentSalesPricingRow ? (currentSalesPricingRow.basis_note || "") : "";
  renderSalesRankPreview();
}

async function loadSalesPricingCurrentBaseRow() {
  if (!currentSalesPricingDkdId) return;
  var kind = salesPricingCurrentProductKind();
  currentSalesPricingProductKind = kind;
  var currentR = await sb.from("product_base_prices")
    .select("id,dkd_shohin_id,product_kind,product_variant_id,base_price_jpy,tax_included,price_basis,basis_note,effective_start,effective_end,is_current,created_at,updated_at")
    .eq("dkd_shohin_id", currentSalesPricingDkdId)
    .eq("product_kind", kind)
    .eq("is_current", true)
    .maybeSingle();
  if (currentR.error) throw currentR.error;
  applySalesPricingRowToForm(currentR.data || null);
}

async function openSalesPricingForCurrent() {
  if (!currentProduct) return;
  if (!canViewSalesPricing()) { alert(t("err_perm")); return; }
  var overlay = document.getElementById("sales-pricing-overlay");
  var errEl = document.getElementById("sales-pricing-error");
  if (errEl) errEl.textContent = "";
  overlay.classList.add("show");
  document.getElementById("sales-pricing-product").textContent = t("loading");
  document.getElementById("sales-rank-preview").innerHTML = "<div class='component-empty'>" + esc(t("loading")) + "</div>";
  currentSalesPricingDksReference = { loading: true };
  currentSalesPricingManufacturingCost = null;
  renderSalesBasePriceGuidance();
  renderSalesPricingManufacturingCostMini();
  var saveBtn = document.getElementById("btn-sales-pricing-save");
  if (saveBtn) setCspStyle(saveBtn, "display", canEditBasePrice() ? "" : "none");
  var rankSaveBtn = document.getElementById("btn-sales-rank-save");
  if (rankSaveBtn) setCspStyle(rankSaveBtn, "display", canManageSalesPricing() ? "" : "none");
  setSalesPricingBaseFieldsVisible(canViewBasePrice());
  ["sales-base-price","sales-price-basis","sales-effective-start","sales-basis-note"].forEach(function(id) {
    var el = document.getElementById(id);
    if (el) el.disabled = !canEditBasePrice();
  });
  try {
    var dkdId = await resolveCurrentCoreDkdShohinId();
    currentSalesPricingDkdId = dkdId;
    await ensureProductVariantsForCurrentDkd(dkdId);
    currentSalesPricingProductKind = ensureSelectedProductKind(productKindSummaryForProduct(currentProduct));
    fillSalesPricingProductKindSelect(currentSalesPricingProductKind);
    document.getElementById("sales-pricing-product").textContent = salesPricingProductText(currentProduct, dkdId);
    if (!dkdId) throw new Error(t("sales_no_product_id"));
    var ranksR = await sb.from("sales_price_ranks")
      .select("rank_code,rank_name,rate_multiplier,amount_adjustment_jpy,rounding_unit_jpy,rounding_method,is_active,display_order")
      .eq("is_active", true)
      .order("display_order", { ascending: true })
      .order("rank_code", { ascending: true });
    if (ranksR.error) throw ranksR.error;
    var customersR = await sb.from("sales_customers")
      .select("price_rank_code")
      .eq("source_code", "hanbaiou")
      .eq("is_active", true);
    if (customersR.error) throw customersR.error;
    salesPricingRanks = ranksR.data || [];
    salesPricingCustomerCounts = salesPricingRankCountMap(customersR.data || []);
    await loadSalesPricingCurrentBaseRow();
    await loadSalesPricingCurrentManufacturingCost();
    var kindSelect = document.getElementById("sales-product-kind");
    if (kindSelect) {
      kindSelect.onchange = async function() {
        var err = document.getElementById("sales-pricing-error");
        if (err) err.textContent = "";
        try {
          currentSalesPricingProductKind = salesPricingCurrentProductKind();
          await loadSalesPricingCurrentBaseRow();
          await loadSalesPricingCurrentManufacturingCost();
        } catch (e) {
          console.warn("sales pricing kind switch failed", e);
          if (err) err.textContent = (e && e.message) || String(e);
        }
      };
    }
    currentSalesPricingDksReference = await fetchSalesPricingDksReference(dkdId);
    renderSalesBasePriceGuidance();
    renderSalesRankPreview();
  } catch (e) {
    console.warn("open sales pricing failed", e);
    currentSalesPricingDksReference = null;
    currentSalesPricingManufacturingCost = null;
    renderSalesBasePriceGuidance();
    renderSalesPricingManufacturingCostMini();
    if (errEl) errEl.textContent = (e && e.message) || String(e);
  }
}

async function saveSalesPricing() {
  var errEl = document.getElementById("sales-pricing-error");
  if (errEl) errEl.textContent = "";
  if (!canEditBasePrice()) { if (errEl) errEl.textContent = t("err_perm"); return; }
  var dkdId = currentSalesPricingDkdId;
  if (!dkdId) { if (errEl) errEl.textContent = t("sales_no_product_id"); return; }
  var productKind = salesPricingCurrentProductKind();
  var productVariantId = salesPricingProductVariantIdForKind(productKind);
  var base = parseInt(document.getElementById("sales-base-price").value, 10);
  if (isNaN(base) || base < 0) { if (errEl) errEl.textContent = t("sales_base_price_required"); return; }
  var payload = {
    dkd_shohin_id: dkdId,
    product_kind: productKind,
    product_variant_id: productVariantId,
    base_price_jpy: base,
    tax_included: false,
    price_basis: document.getElementById("sales-price-basis").value || "manual",
    basis_note: document.getElementById("sales-basis-note").value.trim() || null,
    effective_start: document.getElementById("sales-effective-start").value || salesPricingTodayIso(),
    is_current: true,
    created_by: currentUser ? currentUser.id : null,
    updated_by: currentUser ? currentUser.id : null
  };
  try {
    var oldRow = currentSalesPricingRow ? JSON.parse(JSON.stringify(currentSalesPricingRow)) : null;
    var closePayload = { is_current: false, updated_by: currentUser ? currentUser.id : null, updated_at: new Date().toISOString() };
    if (!oldRow || !oldRow.effective_start || payload.effective_start >= oldRow.effective_start) closePayload.effective_end = payload.effective_start;
    var upd = await sb.from("product_base_prices")
      .update(closePayload)
      .eq("dkd_shohin_id", dkdId)
      .eq("product_kind", productKind)
      .eq("is_current", true);
    if (upd.error) throw upd.error;
    var ins = await sb.from("product_base_prices").insert(payload).select("*").single();
    if (ins.error) throw ins.error;
    currentSalesPricingRow = ins.data;
    await sb.from("product_base_price_history").insert({
      base_price_id: ins.data.id,
      dkd_shohin_id: dkdId,
      product_kind: productKind,
      product_variant_id: productVariantId,
      old_base_price_jpy: oldRow ? oldRow.base_price_jpy : null,
      new_base_price_jpy: ins.data.base_price_jpy,
      old_payload: oldRow || null,
      new_payload: ins.data,
      changed_by: currentUser ? currentUser.id : null,
      change_note: payload.basis_note
    });
    var gltekAutoIssueOutcome = await ensureGltekPartNumberIssuedForDkdId(dkdId, { context: "sales_pricing", product: currentProduct });
    if (productKind === "rebuilt") salesPricingMgmtPriceMap[String(dkdId)] = ins.data;
    renderSalesPricingMgmt();
    if (productKindStockRows.length) {
      if (ins.data.product_variant_id) productKindStockPriceMap[productKindStockVariantMetaKey(ins.data.product_variant_id)] = ins.data;
      if (!ins.data.product_variant_id) productKindStockPriceMap[productKindStockPriceKey(dkdId, productKind)] = ins.data;
      renderProductKindStockMgmt();
    }
    closeSalesPricingOverlay();
    if (gltekAutoIssueOutcome && gltekAutoIssueOutcome.error) {
      alert(gltekAutoIssueFailureText("sales_pricing", gltekAutoIssueOutcome.error));
    }
  } catch (e) {
    console.warn("save sales pricing failed", e);
    if (errEl) errEl.textContent = t("msg_save_err") + ": " + ((e && e.message) || String(e));
  }
}

async function enterSalesPricingMgmt() {
  if (!canViewSalesPricing()) { alert(t("err_perm")); return; }
  showScreen("sales-pricing-mgmt");
  updateAllHeaders();
  var q = document.getElementById("sales-pricing-mgmt-search");
  if (q) q.focus();
  renderSalesPricingMgmt();
}

async function loadSalesPricingMgmt() {
  if (!canViewSalesPricing()) { alert(t("err_perm")); return; }
  var q = (document.getElementById("sales-pricing-mgmt-search") || {}).value || "";
  q = q.trim();
  var list = document.getElementById("sales-pricing-mgmt-list");
  var countEl = document.getElementById("sales-pricing-mgmt-count");
  if (!q) {
    salesPricingMgmtRows = [];
    salesPricingMgmtPriceMap = {};
    salesPricingMgmtManufacturingCostMap = {};
    if (countEl) countEl.textContent = "";
    if (list) list.innerHTML = "<div class='empty'>" + esc(t("sales_pricing_mgmt_hint")) + "</div>";
    return;
  }
  if (list) list.innerHTML = "<div class='loading'>" + esc(t("loading")) + "</div>";
  var numericDkd = /^\d+$/.test(q) ? parseInt(q, 10) : null;
  var r = numericDkd !== null
    ? await sb.from("core_products").select(CORE_PRODUCT_FAST_SELECT).eq("dkd_shohin_id", numericDkd).limit(1)
    : { data: [] };
  if (!r.error && !(r.data || []).length) {
    r = await fetchCoreProductMasterMatches(q, null, 100);
  }
  if (r.error) {
    if (list) list.innerHTML = "<div class='empty'>" + esc(r.error.message || t("msg_kikan_err")) + "</div>";
    return;
  }
  var rows = r.data || [];
  if (!rows.length) {
    var aliasResult = await fetchSourceAliasProducts(q);
    if (aliasResult.error) {
      console.warn("sales pricing alias search failed", aliasResult.error);
    } else {
      rows = aliasResult.data || [];
    }
  }
  salesPricingMgmtRows = filterVisibleProducts(normalizeCoreProductFastRows(rows)).slice(0, 100);
  var ids = salesPricingMgmtRows.map(function(row){ return row.dkd_shohin_id; }).filter(Boolean);
  salesPricingMgmtPriceMap = {};
  salesPricingMgmtManufacturingCostMap = {};
  if (ids.length) {
    var pr = await sb.from("product_base_prices")
      .select("id,dkd_shohin_id,base_price_jpy,price_basis,basis_note,effective_start,is_current")
      .in("dkd_shohin_id", ids)
      .eq("product_kind", "rebuilt")
      .eq("is_current", true);
    (pr.data || []).forEach(function(row) {
      salesPricingMgmtPriceMap[String(row.dkd_shohin_id)] = row;
    });
    salesPricingMgmtManufacturingCostMap = await fetchSalesPricingManufacturingCostMap(ids, "rebuilt");
  }
  renderSalesPricingMgmt();
}

function renderSalesPricingMgmt() {
  var list = document.getElementById("sales-pricing-mgmt-list");
  var countEl = document.getElementById("sales-pricing-mgmt-count");
  if (!list) return;
  if (countEl) countEl.textContent = salesPricingMgmtRows.length ? (salesPricingMgmtRows.length + " 件") : "";
  if (!salesPricingMgmtRows.length) {
    list.innerHTML = "<div class='empty'>" + esc(t("sales_pricing_mgmt_hint")) + "</div>";
    return;
  }
  var showBasePrice = canViewBasePrice();
  var showManufacturingCost = canViewManufacturingCostMgmt();
  var html = "<table class='mgmt-table'><tr><th>DKD</th><th>" + esc(t("f_genuine_pn")) + "</th><th>" + esc(t("f_mfr_pn")) + "</th><th>" + esc(t("f_manufacturer")) + "</th><th>" + esc(t("sales_price_section")) + "</th>";
  if (showManufacturingCost) html += "<th>" + esc(t("sales_manufacturing_cost")) + "</th>";
  if (showBasePrice) html += "<th>" + esc(t("sales_base_price")) + "</th>";
  html += "<th></th></tr>";
  salesPricingMgmtRows.forEach(function(row) {
    var price = salesPricingMgmtPriceMap[String(row.dkd_shohin_id)] || null;
    var manufacturingCost = salesPricingMgmtManufacturingCostMap[String(row.dkd_shohin_id)] || null;
    var priceText = price ? ("JPY " + formatYen(price.base_price_jpy)) : "-";
    html += "<tr>";
    html += "<td><div class='mgmt-pn'>" + esc(String(row.dkd_shohin_id || "-")) + "</div><div class='mgmt-sub'>" + esc(tCat(row.category_code || row.category) || "") + "</div></td>";
    html += "<td><div class='mgmt-pn'>" + esc(row.genuine_part_number || "-") + "</div><div class='mgmt-sub'>" + esc(row.genuine_part_number_2 || "") + "</div></td>";
    html += "<td><div class='mgmt-pn'>" + esc(row.manufacturer_part_number || "-") + "</div></td>";
    html += "<td><div class='mgmt-sub'>" + esc(row.manufacturer || "-") + "</div></td>";
    html += "<td><div class='price-value' data-dcats-inline-style='s-1024138906a0'>" + esc(priceText) + "</div></td>";
    if (showManufacturingCost) html += "<td>" + salesPricingManufacturingCostCellHtml(manufacturingCost) + "</td>";
    if (showBasePrice) html += "<td><div class='price-value'>" + esc(priceText) + "</div><div class='mgmt-sub'>" + esc(price ? ([price.price_basis, price.effective_start].filter(Boolean).join(" / ")) : "") + "</div></td>";
    html += "<td><button class='btn-sm-edit' data-sales-price-dkd='" + esc(String(row.dkd_shohin_id || "")) + "'>" + esc(t("sales_pricing_title")) + "</button></td>";
    html += "</tr>";
  });
  html += "</table>";
  list.innerHTML = html;
  list.querySelectorAll("[data-sales-price-dkd]").forEach(function(btn) {
    btn.addEventListener("click", function() {
      openSalesPricingMgmtRow(btn.dataset.salesPriceDkd);
    });
  });
}

async function openSalesPricingMgmtRow(dkdId) {
  var row = salesPricingMgmtRows.find(function(p){ return String(p.dkd_shohin_id) === String(dkdId); });
  if (!row) return;
  currentProduct = row;
  currentCoreDkdShohinId = row.dkd_shohin_id || null;
  await openSalesPricingForCurrent();
}

