// =============================================
// パスワード強度チェック
// =============================================
function checkPasswordStrength(password, fillId, labelId) {
  var fill  = document.getElementById(fillId);
  var label = document.getElementById(labelId);
  if (!fill || !label) return;

  if (!password) {
    setCspStyle(fill, "width", "0%");
    setCspStyle(fill, "background", "#eee");
    label.textContent = "";
    return;
  }

  var score = 0;
  var hints = [];

  // 長さチェック
  if (password.length >= 8)  score++;
  if (password.length >= 12) score++;
  else if (password.length < 8) hints.push("8文字以上 / 8+ chars");

  // 文字種チェック
  if (/[a-z]/.test(password)) score++;
  else hints.push("小文字 / lowercase");
  if (/[A-Z]/.test(password)) score++;
  else hints.push("大文字 / uppercase");
  if (/[0-9]/.test(password)) score++;
  else hints.push("数字 / number");
  if (/[^a-zA-Z0-9]/.test(password)) score++;
  else hints.push("記号 / symbol");

  var levels = [
    { max: 1, label: "弱い / Weak",        color: "#e24b4a", width: "20%" },
    { max: 2, label: "やや弱い / Fair",     color: "#f5a623", width: "40%" },
    { max: 3, label: "普通 / Moderate",     color: "#f5a623", width: "60%" },
    { max: 4, label: "強い / Strong",       color: "#27ae60", width: "80%" },
    { max: 99, label: "非常に強い / Very strong", color: "#1a8c3e", width: "100%" }
  ];

  var level = levels.find(function(l) { return score <= l.max; }) || levels[levels.length-1];
  setCspStyle(fill, "width", level.width);
  setCspStyle(fill, "background", level.color);
  setCspStyle(label, "color", level.color);
  label.textContent  = level.label + (hints.length > 0 ? "  (" + hints.slice(0,2).join(", ") + ")" : "");
}

// 申請画面のパスワード強度チェック
