document.addEventListener("keydown", function(e){
  if(!document.getElementById("fullscreen").classList.contains("show")) return;
  if(e.key==="ArrowLeft"&&fsIndex>0){fsIndex--;renderFullscreen();}
  var list = fullscreenImageList();
  if(e.key==="ArrowRight"&&fsIndex<list.length-1){fsIndex++;renderFullscreen();}
  if(e.key==="Escape") closeFullscreen();
});

